        state.serialize_field("extractor_set", self.0.extractor_set())?;
        state.serialize_field("profile", self.0.profile())?;
        state.serialize_field("rule", self.0.rule())?;
        state.serialize_field("snapshot", self.0.snapshot())?;
        state.end()
