impl From<RawArtifactSourceV4> for ArtifactSourceV4 {
    fn from(raw: RawArtifactSourceV4) -> Self {
        match raw {
            RawArtifactSourceV4::RunGenesis { run_id } => Self::RunGenesis { run_id: run_id.0 },
            RawArtifactSourceV4::SnapshotIngest {
                adapter_id,
                run_id,
                snapshot_id,
            } => Self::SnapshotIngest {
                adapter_id: adapter_id.0,
                run_id: run_id.0,
                snapshot_id: snapshot_id.0,
            },
            RawArtifactSourceV4::ReviewerExecution {
                execution_id,
                reviewer_id,
                run_id,
            } => Self::ReviewerExecution {
                execution_id: execution_id.0,
                reviewer_id: reviewer_id.0,
                run_id: run_id.0,
            },
            RawArtifactSourceV4::VerifierArtifact {
                claim_id,
                descriptor_id,
                procedure_version,
                role,
                run_id,
            } => Self::VerifierArtifact {
                claim_id: claim_id.0,
                descriptor_id: descriptor_id.0,
                procedure_version: procedure_version.0,
                role,
                run_id: run_id.0,
            },
            RawArtifactSourceV4::ExternalHarnessWitness {
                claim_body_hash,
                claim_id,
                descriptor_id,
                genesis_hash,
                harness_id,
                harness_revision,
                harness_source_hash,
                policy_revision_hash,
                procedure_version,
                property_id,
                repository_id,
                repository_source_hash,
                run_id,
                snapshot_id,
                test_artifact_id,
                universe_id,
            } => Self::ExternalHarnessWitness {
                claim_body_hash: claim_body_hash.0,
                claim_id: claim_id.0,
                descriptor_id: descriptor_id.0,
                genesis_hash: genesis_hash.0,
                harness_id: harness_id.0,
                harness_revision: harness_revision.0,
                harness_source_hash: harness_source_hash.0,
                policy_revision_hash: policy_revision_hash.0,
                procedure_version: procedure_version.0,
                property_id: property_id.0,
                repository_id: repository_id.0,
                repository_source_hash: repository_source_hash.0,
                run_id: run_id.0,
                snapshot_id: snapshot_id.0,
                test_artifact_id: test_artifact_id.0,
                universe_id: universe_id.0,
            },
            RawArtifactSourceV4::GluingInput {
                context_id,
                descriptor_hash,
                descriptor_id,
                descriptor_media_type,
                descriptor_sensitivity,
                descriptor_size,
                genesis_hash,
                plan_id,
                policy_revision_hash,
                profile_descriptor_id,
                repository_id,
                repository_source_hash,
                run_id,
                snapshot_id,
                universe_id,
            } => Self::GluingInput {
                context_id: context_id.0,
                descriptor_hash: descriptor_hash.0,
                descriptor_id: descriptor_id.0,
                descriptor_media_type: descriptor_media_type.0,
                descriptor_sensitivity,
                descriptor_size,
                genesis_hash: genesis_hash.0,
                plan_id: plan_id.0,
                policy_revision_hash: policy_revision_hash.0,
                profile_descriptor_id: profile_descriptor_id.0,
                repository_id: repository_id.0,
                repository_source_hash: repository_source_hash.0,
                run_id: run_id.0,
                snapshot_id: snapshot_id.0,
                universe_id: universe_id.0,
            },
        }
    }
}

impl<'de> Deserialize<'de> for ArtifactSourceV4 {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let source: Self = RawArtifactSourceV4::deserialize(deserializer)?.into();
        source.validate().map_err(serde::de::Error::custom)?;
        Ok(source)
    }
}

impl ArtifactSourceV4 {
    fn run_id(&self) -> &StableId {
        match self {
            Self::RunGenesis { run_id }
            | Self::SnapshotIngest { run_id, .. }
            | Self::ReviewerExecution { run_id, .. }
            | Self::VerifierArtifact { run_id, .. }
            | Self::ExternalHarnessWitness { run_id, .. }
            | Self::GluingInput { run_id, .. } => run_id,
        }
    }

    fn validate(&self) -> Result<()> {
        if self.run_id().kind() != "run" {
            return Err(DomainError::Validation(
                "event-v4 artifact source requires a run ID".to_owned(),
            ));
        }
        let bytes = crate::canonical::canonical_json_count_bounded(
            self,
            MAX_V3_REGISTRATION_IDENTITY_BYTES,
            "event-v4 artifact source bytes",
        )?;
        if bytes == 0 {
            return Err(DomainError::Validation(
                "event-v4 artifact source must not be empty".to_owned(),
            ));
        }
        if let Self::GluingInput {
            context_id,
            descriptor_id,
            descriptor_media_type,
            descriptor_sensitivity,
            profile_descriptor_id,
            snapshot_id,
            universe_id,
            plan_id,
            repository_id,
            ..
        } = self
            && (context_id.kind() != "context"
                || descriptor_id.kind() != "gluing-input-descriptor-v4"
                || descriptor_media_type != GLUING_INPUT_MEDIA_TYPE_V4
                || *descriptor_sensitivity != ArtifactSensitivity::CanonicalState
                || profile_descriptor_id != crate::DOUBLE_SUBMIT_GLUING_DESCRIPTOR_ID
                || snapshot_id.kind() != "snapshot"
                || universe_id.kind() != "universe"
                || plan_id.kind() != "plan"
                || repository_id.kind() != "repository")
        {
            return Err(DomainError::Validation(
                "invalid event-v4 gluing input source closure".to_owned(),
            ));
        }
        Ok(())
    }

    fn allocated_bytes(&self) -> usize {
        match self {
            Self::RunGenesis { run_id } => run_id.allocated_bytes(),
            Self::SnapshotIngest {
                adapter_id,
                run_id,
                snapshot_id,
            } => adapter_id
                .capacity()
                .saturating_add(run_id.allocated_bytes())
                .saturating_add(snapshot_id.allocated_bytes()),
            Self::ReviewerExecution {
                execution_id,
                reviewer_id,
                run_id,
            } => execution_id
                .allocated_bytes()
                .saturating_add(reviewer_id.capacity())
                .saturating_add(run_id.allocated_bytes()),
            Self::VerifierArtifact {
                claim_id,
                descriptor_id,
                procedure_version,
                run_id,
                ..
            } => claim_id
                .allocated_bytes()
                .saturating_add(descriptor_id.capacity())
                .saturating_add(procedure_version.capacity())
                .saturating_add(run_id.allocated_bytes()),
            Self::ExternalHarnessWitness {
                claim_body_hash,
                claim_id,
                descriptor_id,
                genesis_hash,
                harness_id,
                harness_revision,
                harness_source_hash,
                policy_revision_hash,
                procedure_version,
                property_id,
                repository_id,
                repository_source_hash,
                run_id,
                snapshot_id,
                test_artifact_id,
                universe_id,
            } => [
                claim_body_hash.allocated_bytes(),
                claim_id.allocated_bytes(),
                descriptor_id.capacity(),
                genesis_hash.allocated_bytes(),
                harness_id.capacity(),
                harness_revision.capacity(),
                harness_source_hash.allocated_bytes(),
                policy_revision_hash.allocated_bytes(),
                procedure_version.capacity(),
                property_id.capacity(),
                repository_id.allocated_bytes(),
                repository_source_hash.allocated_bytes(),
                run_id.allocated_bytes(),
                snapshot_id.allocated_bytes(),
                test_artifact_id.allocated_bytes(),
                universe_id.allocated_bytes(),
            ]
            .into_iter()
            .fold(0_usize, usize::saturating_add),
            Self::GluingInput {
                context_id,
                descriptor_hash,
                descriptor_id,
                descriptor_media_type,
                genesis_hash,
                plan_id,
                policy_revision_hash,
                profile_descriptor_id,
                repository_id,
                repository_source_hash,
                run_id,
                snapshot_id,
                universe_id,
                ..
            } => [
                context_id.allocated_bytes(),
                descriptor_hash.allocated_bytes(),
                descriptor_id.allocated_bytes(),
                descriptor_media_type.capacity(),
                genesis_hash.allocated_bytes(),
                plan_id.allocated_bytes(),
                policy_revision_hash.allocated_bytes(),
                profile_descriptor_id.capacity(),
                repository_id.allocated_bytes(),
                repository_source_hash.allocated_bytes(),
                run_id.allocated_bytes(),
                snapshot_id.allocated_bytes(),
                universe_id.allocated_bytes(),
            ]
            .into_iter()
            .fold(0_usize, usize::saturating_add),
        }
    }
}

/// Strict event-v4 registration. Its `registration-v4` identity commits to
/// the complete closed source object and exact outer CAS tuple.
#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct ArtifactRegistrationV4 {
    schema: String,
    id: StableId,
    run_id: StableId,
    cas_hash: ContentHash,
    media_type: String,
    size: u64,
    sensitivity: ArtifactSensitivity,
    source: ArtifactSourceV4,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawArtifactRegistrationV4 {
    schema: BoundedV3String<MAX_V3_TRACE_BYTES>,
    id: BoundedV3StableId,
    run_id: BoundedV3StableId,
    cas_hash: BoundedV3ContentHash,
    media_type: BoundedV3String<MAX_V3_TRACE_BYTES>,
    size: u64,
    sensitivity: ArtifactSensitivity,
    source: ArtifactSourceV4,
}

impl ArtifactRegistrationV4 {
    fn derived_id(
        run_id: &StableId,
        cas_hash: &ContentHash,
        media_type: &str,
        size: u64,
        sensitivity: ArtifactSensitivity,
        source: &ArtifactSourceV4,
    ) -> Result<StableId> {
        #[derive(Serialize)]
        struct Identity<'a> {
            cas_hash: &'a ContentHash,
            media_type: &'a str,
            run_id: &'a StableId,
            sensitivity: ArtifactSensitivity,
            size: u64,
            source: &'a ArtifactSourceV4,
        }
        let body = Identity {
            cas_hash,
            media_type,
            run_id,
            sensitivity,
            size,
            source,
        };
        StableId::derived_streaming(
            "registration-v4",
            &body,
            MAX_V3_REGISTRATION_IDENTITY_BYTES,
            "event-v4 registration identity",
        )
    }

    fn from_raw(raw: RawArtifactRegistrationV4) -> Result<Self> {
        let registration = Self {
            schema: raw.schema.0,
            id: raw.id.0,
            run_id: raw.run_id.0,
            cas_hash: raw.cas_hash.0,
            media_type: raw.media_type.0,
            size: raw.size,
            sensitivity: raw.sensitivity,
            source: raw.source,
        };
        registration.validate()?;
        Ok(registration)
    }

    fn from_gluing_binding(binding: &GluingInputTrustBindingV4) -> Result<Self> {
        let registration = Self {
            schema: "reviewgraphen.artifact_registration.v4".to_owned(),
            id: binding.registration_id.clone(),
            run_id: binding.run_id.clone(),
            cas_hash: binding.descriptor_hash.clone(),
            media_type: binding.descriptor_media_type.clone(),
            size: binding.descriptor_size,
            sensitivity: binding.descriptor_sensitivity,
            source: binding.source.clone(),
        };
        registration.validate()?;
        Ok(registration)
    }

    fn validate(&self) -> Result<()> {
        self.source.validate()?;
        let gluing_tuple_matches = match &self.source {
            ArtifactSourceV4::GluingInput {
                descriptor_hash,
                descriptor_size,
                descriptor_media_type,
                descriptor_sensitivity,
                ..
            } => {
                descriptor_hash == &self.cas_hash
                    && *descriptor_size == self.size
                    && descriptor_media_type == &self.media_type
                    && *descriptor_sensitivity == self.sensitivity
            }
            _ => true,
        };
        if self.schema != "reviewgraphen.artifact_registration.v4"
            || self.run_id.kind() != "run"
            || self.source.run_id() != &self.run_id
            || self.media_type.trim().is_empty()
            || self.media_type.len() > MAX_V3_TRACE_BYTES
            || !is_cas_hash(&self.cas_hash)
            || !gluing_tuple_matches
            || self.id
                != Self::derived_id(
                    &self.run_id,
                    &self.cas_hash,
                    &self.media_type,
                    self.size,
                    self.sensitivity,
                    &self.source,
                )?
        {
            return Err(DomainError::Validation(
                "invalid event-v4 artifact registration".to_owned(),
            ));
        }
        Ok(())
    }

    fn allocated_bytes(&self) -> usize {
        self.schema
            .capacity()
            .saturating_add(self.id.allocated_bytes())
            .saturating_add(self.run_id.allocated_bytes())
            .saturating_add(self.cas_hash.allocated_bytes())
            .saturating_add(self.media_type.capacity())
            .saturating_add(self.source.allocated_bytes())
    }

    pub fn from_json_bytes(input: &[u8]) -> Result<Self> {
        if input.len() > MAX_V3_REGISTRATION_IDENTITY_BYTES {
            return Err(DomainError::Incomplete {
                operation: "event-v4 registration JSON",
                limit: MAX_V3_REGISTRATION_IDENTITY_BYTES,
                observed: input.len(),
            });
        }
        preflight_event_json_structure(input)?;
        let raw: RawArtifactRegistrationV4 =
            serde_json::from_slice(input).map_err(|error| DomainError::Json(error.to_string()))?;
        let value = Self::from_raw(raw)?;
        if canonical_json(&value)? != input {
            return Err(DomainError::Validation(
                "event-v4 registration JSON must be canonical".to_owned(),
            ));
        }
        Ok(value)
    }

    pub fn id(&self) -> &StableId {
        &self.id
    }
    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }
    pub fn source(&self) -> &ArtifactSourceV4 {
        &self.source
    }
    #[must_use]
    pub fn cas_hash(&self) -> &ContentHash {
        &self.cas_hash
    }
    #[must_use]
    pub fn media_type(&self) -> &str {
        &self.media_type
    }
    #[must_use]
    pub const fn size(&self) -> u64 {
        self.size
    }
    #[must_use]
    pub const fn sensitivity(&self) -> ArtifactSensitivity {
        self.sensitivity
    }
}

impl<'de> Deserialize<'de> for ArtifactRegistrationV4 {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        Self::from_raw(RawArtifactRegistrationV4::deserialize(deserializer)?)
            .map_err(serde::de::Error::custom)
    }
}

fn artifact_source_v3_matches_run(source: &ArtifactSourceV3, run_id: &StableId) -> bool {
    match source {
        ArtifactSourceV3::RunGenesis {
            run_id: source_run_id,
        }
        | ArtifactSourceV3::SnapshotIngest {
            run_id: source_run_id,
            ..
        }
        | ArtifactSourceV3::ReviewerExecution {
            run_id: source_run_id,
            ..
        }
        | ArtifactSourceV3::VerifierArtifact {
            run_id: source_run_id,
            ..
        }
        | ArtifactSourceV3::ExternalHarnessWitness {
            run_id: source_run_id,
            ..
        } => source_run_id == run_id,
    }
}

fn artifact_source_v3_is_authority_significant(source: &ArtifactSourceV3) -> bool {
    matches!(
        source,
        ArtifactSourceV3::VerifierArtifact { .. } | ArtifactSourceV3::ExternalHarnessWitness { .. }
    )
}

fn artifact_source_v3_closure(
    source: &ArtifactSourceV3,
    sensitivity: ArtifactSensitivity,
    media_type: &str,
    cas_hash: &ContentHash,
    size: u64,
) -> bool {
    match (source, sensitivity) {
        (ArtifactSourceV3::RunGenesis { run_id }, ArtifactSensitivity::CanonicalState) => {
            run_id.kind() == "run" && media_type == "application/json"
        }
        (
            ArtifactSourceV3::SnapshotIngest {
                adapter_id,
                run_id,
                snapshot_id,
            },
            ArtifactSensitivity::WorkspaceSource,
        ) => {
            run_id.kind() == "run"
                && snapshot_id.kind() == "snapshot"
                && !adapter_id.trim().is_empty()
                && adapter_id.len() <= MAX_V3_TRACE_BYTES
        }
        (
            ArtifactSourceV3::ReviewerExecution {
                execution_id,
                reviewer_id,
                run_id,
            },
            ArtifactSensitivity::Sensitive,
        ) => {
            run_id.kind() == "run"
                && execution_id.kind() == "execution"
                && !reviewer_id.trim().is_empty()
                && reviewer_id.len() <= MAX_V3_TRACE_BYTES
        }
        (
            ArtifactSourceV3::VerifierArtifact {
                claim_id,
                descriptor_id,
                procedure_version,
                role,
                run_id,
            },
            ArtifactSensitivity::CanonicalState,
        ) => {
            let exact = match (descriptor_id.as_str(), procedure_version.as_str(), role) {
                (STATIC_DESCRIPTOR_ID, STATIC_PROCEDURE_ID, VerifierArtifactRoleV3::Input) => {
                    media_type == STATIC_INPUT_MEDIA_TYPE
                }
                (STATIC_DESCRIPTOR_ID, STATIC_PROCEDURE_ID, VerifierArtifactRoleV3::Output) => {
                    media_type == STATIC_OUTPUT_MEDIA_TYPE
                }
                (FIXTURE_DESCRIPTOR_ID, FIXTURE_PROCEDURE_ID, VerifierArtifactRoleV3::Output) => {
                    media_type == FIXTURE_OUTPUT_MEDIA_TYPE
                }
                _ => false,
            };
            run_id.kind() == "run" && claim_id.kind() == "claim" && exact
        }
        (
            ArtifactSourceV3::ExternalHarnessWitness {
                claim_body_hash,
                claim_id,
                descriptor_id,
                genesis_hash,
                harness_id,
                harness_revision,
                harness_source_hash,
                policy_revision_hash,
                procedure_version,
                property_id,
                repository_id,
                repository_source_hash,
                run_id,
                snapshot_id,
                test_artifact_id,
                universe_id,
            },
            ArtifactSensitivity::CanonicalState,
        ) => {
            run_id.kind() == "run"
                && snapshot_id.kind() == "snapshot"
                && universe_id.kind() == "universe"
                && repository_id.kind() == "repository"
                && claim_id.kind() == "claim"
                && test_artifact_id.as_str() == FIXTURE_TEST_ARTIFACT_ID
                && descriptor_id == FIXTURE_DESCRIPTOR_ID
                && procedure_version == FIXTURE_PROCEDURE_ID
                && harness_id == FIXTURE_HARNESS_ID
                && harness_revision == FIXTURE_HARNESS_REVISION
                && harness_source_hash.as_str() == FIXTURE_HARNESS_SOURCE_HASH
                && property_id == M4_PROPERTY_ID
                && media_type == FIXTURE_MEDIA_TYPE
                && cas_hash.to_string() == FIXTURE_WITNESS_HASH
                && size == 145
                && [
                    claim_body_hash,
                    genesis_hash,
                    harness_source_hash,
                    policy_revision_hash,
                ]
                .into_iter()
                .all(is_cas_hash)
                // Repository source identities come from ProgramSpace and may use
                // its shorter, validated fixture hashes. Their authority is
                // established later by exact equality with the ProgramSpace root.
                && !repository_source_hash.as_str().is_empty()
        }
        _ => false,
    }
}

fn artifact_source_v3_allocated_bytes(source: &ArtifactSourceV3) -> usize {
    match source {
        ArtifactSourceV3::RunGenesis { run_id } => run_id.allocated_bytes(),
        ArtifactSourceV3::SnapshotIngest {
            adapter_id,
            run_id,
            snapshot_id,
        } => adapter_id
            .capacity()
            .saturating_add(run_id.allocated_bytes())
            .saturating_add(snapshot_id.allocated_bytes()),
        ArtifactSourceV3::ReviewerExecution {
            execution_id,
            reviewer_id,
            run_id,
        } => execution_id
            .allocated_bytes()
            .saturating_add(reviewer_id.capacity())
            .saturating_add(run_id.allocated_bytes()),
        ArtifactSourceV3::VerifierArtifact {
            claim_id,
            descriptor_id,
            procedure_version,
            run_id,
            ..
        } => claim_id
            .allocated_bytes()
            .saturating_add(descriptor_id.capacity())
            .saturating_add(procedure_version.capacity())
            .saturating_add(run_id.allocated_bytes()),
        ArtifactSourceV3::ExternalHarnessWitness {
            claim_body_hash,
            claim_id,
            descriptor_id,
            genesis_hash,
            harness_id,
            harness_revision,
            harness_source_hash,
            policy_revision_hash,
            procedure_version,
            property_id,
            repository_id,
            repository_source_hash,
            run_id,
            snapshot_id,
            test_artifact_id,
            universe_id,
        } => [
            claim_body_hash.allocated_bytes(),
            claim_id.allocated_bytes(),
            descriptor_id.capacity(),
            genesis_hash.allocated_bytes(),
            harness_id.capacity(),
            harness_revision.capacity(),
            harness_source_hash.allocated_bytes(),
            policy_revision_hash.allocated_bytes(),
            procedure_version.capacity(),
            property_id.capacity(),
            repository_id.allocated_bytes(),
            repository_source_hash.allocated_bytes(),
            run_id.allocated_bytes(),
            snapshot_id.allocated_bytes(),
            test_artifact_id.allocated_bytes(),
            universe_id.allocated_bytes(),
        ]
        .into_iter()
        .fold(0usize, usize::saturating_add),
    }
}

fn valid_artifact_source_sensitivity(
    source: &ArtifactSource,
    sensitivity: ArtifactSensitivity,
) -> bool {
    match (source, sensitivity) {
        (ArtifactSource::RunGenesis { run_id }, ArtifactSensitivity::CanonicalState) => {
            run_id.kind() == "run"
        }
        (
            ArtifactSource::SnapshotIngest {
                run_id,
                snapshot_id,
                adapter_id,
            },
            ArtifactSensitivity::WorkspaceSource,
        ) => {
            run_id.kind() == "run"
                && snapshot_id.kind() == "snapshot"
                && !adapter_id.trim().is_empty()
        }
        (
            ArtifactSource::ReviewerExecution {
                run_id,
                execution_id,
                reviewer_id,
            },
            ArtifactSensitivity::Sensitive,
        ) => {
            run_id.kind() == "run"
                && execution_id.kind() == "execution"
                && !reviewer_id.trim().is_empty()
        }
        _ => false,
    }
}

fn artifact_source_matches_run(source: &ArtifactSource, run_id: &StableId) -> bool {
    match source {
        ArtifactSource::RunGenesis {
            run_id: source_run_id,
        }
        | ArtifactSource::SnapshotIngest {
            run_id: source_run_id,
            ..
        }
        | ArtifactSource::ReviewerExecution {
            run_id: source_run_id,
            ..
        } => source_run_id == run_id,
    }
}

/// The mandatory first v2 event, binding a run to its typed baseline CAS
/// artifact and snapshot/profile provenance.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct RunGenesisManifest {
    run_id: StableId,
    event_contract_version: String,
    genesis_artifact: ArtifactRegistered,
    repository_identity: String,
    snapshot_id: StableId,
    profile_id: String,
    profile_version: String,
}

impl RunGenesisManifest {
    pub(crate) fn allocated_bytes(&self) -> usize {
        self.run_id
            .allocated_bytes()
            .saturating_add(self.event_contract_version.capacity())
            .saturating_add(self.genesis_artifact.allocated_bytes())
            .saturating_add(self.repository_identity.capacity())
            .saturating_add(self.snapshot_id.allocated_bytes())
            .saturating_add(self.profile_id.capacity())
            .saturating_add(self.profile_version.capacity())
    }
    /// Builds the sole v2 run-genesis manifest.
    pub fn new(
        run_id: StableId,
        genesis_artifact: ArtifactRegistered,
        repository_identity: impl Into<String>,
        snapshot_id: StableId,
        profile_id: impl Into<String>,
        profile_version: impl Into<String>,
    ) -> Result<Self> {
        let manifest = Self {
            run_id,
            event_contract_version: EventContractVersion::V2.schema().to_owned(),
            genesis_artifact,
            repository_identity: repository_identity.into(),
            snapshot_id,
            profile_id: profile_id.into(),
            profile_version: profile_version.into(),
        };
        manifest.validate()?;
        Ok(manifest)
    }

    fn validate(&self) -> Result<()> {
        if self.run_id.kind() != "run"
            || self.event_contract_version != EventContractVersion::V2.schema()
            || self.repository_identity.trim().is_empty()
            || self.profile_id.trim().is_empty()
            || self.profile_version.trim().is_empty()
            || self.genesis_artifact.media_type != "application/json"
            || !matches!(
                &self.genesis_artifact.source,
                ArtifactSource::RunGenesis { run_id } if run_id == &self.run_id
            )
        {
            return Err(DomainError::Validation(
                "invalid v2 run genesis manifest".to_owned(),
            ));
        }
        self.genesis_artifact.validate()
    }

    fn validate_against_genesis(
        &self,
        run_id: &StableId,
        snapshot: &RunGenesisSnapshot,
        bytes: &[u8],
    ) -> Result<()> {
        self.validate()?;
        let size = u64::try_from(bytes.len())
            .map_err(|_| DomainError::Validation("genesis bytes do not fit u64".to_owned()))?;
        if self.run_id != *run_id
            || self.genesis_artifact.run_id != *run_id
            || self.genesis_artifact.cas_hash != ContentHash::sha256(bytes)
            || self.genesis_artifact.size != size
            || self.repository_identity != snapshot.program_space.repository_identity()
            || self.snapshot_id != *snapshot.program_space.snapshot_id()
            || self.profile_id != snapshot.program_space.profile_id()
            || self.profile_version != snapshot.program_space.profile_version()
            || !matches!(
                &self.genesis_artifact.source,
                ArtifactSource::RunGenesis { run_id: source_run_id } if source_run_id == run_id
            )
        {
            return Err(DomainError::Validation(
                "run genesis manifest must exactly bind verified genesis bytes and provenance"
                    .to_owned(),
            ));
        }
        Ok(())
    }

    #[must_use]
    pub fn genesis_artifact(&self) -> &ArtifactRegistered {
        &self.genesis_artifact
    }
    #[must_use]
    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }
    #[must_use]
    pub fn snapshot_id(&self) -> &StableId {
        &self.snapshot_id
    }
}

