/// Mandatory sequence-one event-v4 record. Its nested artifact intentionally
/// remains the frozen v3 RunGenesis registration body.
#[derive(Clone, Debug, Eq, PartialEq, Serialize)]
pub struct RunGenesisManifestV4 {
    run_id: StableId,
    event_contract_version: String,
    genesis_artifact: ArtifactRegisteredV3,
    repository_identity: String,
    snapshot_id: StableId,
    profile_id: String,
    profile_version: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawRunGenesisManifestV4 {
    run_id: BoundedV3StableId,
    event_contract_version: BoundedV3String<MAX_V3_TRACE_BYTES>,
    genesis_artifact: ArtifactRegisteredV3,
    repository_identity: BoundedV3String<MAX_V3_TRACE_BYTES>,
    snapshot_id: BoundedV3StableId,
    profile_id: BoundedV3String<MAX_V3_TRACE_BYTES>,
    profile_version: BoundedV3String<MAX_V3_TRACE_BYTES>,
}

impl RunGenesisManifestV4 {
    fn new(
        run_id: StableId,
        genesis_artifact: ArtifactRegisteredV3,
        repository_identity: String,
        snapshot_id: StableId,
        profile_id: String,
        profile_version: String,
    ) -> Result<Self> {
        let value = Self {
            run_id,
            event_contract_version: EventContractVersion::V4.schema().to_owned(),
            genesis_artifact,
            repository_identity,
            snapshot_id,
            profile_id,
            profile_version,
        };
        value.validate()?;
        Ok(value)
    }

    fn from_raw(raw: RawRunGenesisManifestV4) -> Result<Self> {
        let value = Self {
            run_id: raw.run_id.0,
            event_contract_version: raw.event_contract_version.0,
            genesis_artifact: raw.genesis_artifact,
            repository_identity: raw.repository_identity.0,
            snapshot_id: raw.snapshot_id.0,
            profile_id: raw.profile_id.0,
            profile_version: raw.profile_version.0,
        };
        value.validate()?;
        Ok(value)
    }

    fn validate(&self) -> Result<()> {
        for value in [
            &self.repository_identity,
            &self.profile_id,
            &self.profile_version,
        ] {
            if value.trim().is_empty() || value.len() > MAX_V3_TRACE_BYTES {
                return Err(DomainError::Validation(
                    "invalid event-v4 genesis provenance".to_owned(),
                ));
            }
        }
        if self.run_id.kind() != "run"
            || self.snapshot_id.kind() != "snapshot"
            || self.event_contract_version != EventContractVersion::V4.schema()
            || self.genesis_artifact.run_id() != &self.run_id
            || self.genesis_artifact.media_type() != "application/json"
            || self.genesis_artifact.sensitivity() != ArtifactSensitivity::CanonicalState
            || !matches!(
                self.genesis_artifact.source(),
                ArtifactSourceV3::RunGenesis { run_id } if run_id == &self.run_id
            )
        {
            return Err(DomainError::Validation(
                "invalid event-v4 run genesis manifest".to_owned(),
            ));
        }
        self.genesis_artifact.validate()
    }

    fn allocated_bytes(&self) -> usize {
        self.run_id
            .allocated_bytes()
            .saturating_add(self.event_contract_version.capacity())
            .saturating_add(self.genesis_artifact.allocated_bytes())
            .saturating_add(self.repository_identity.capacity())
            .saturating_add(self.snapshot_id.allocated_bytes())
            .saturating_add(self.profile_id.capacity())
            .saturating_add(self.profile_version.capacity())
    }

    fn validate_against_genesis(
        &self,
        run_id: &StableId,
        snapshot: &RunGenesisSnapshot,
        bytes: &[u8],
    ) -> Result<()> {
        self.validate()?;
        let size = u64::try_from(bytes.len()).map_err(|_| DomainError::Incomplete {
            operation: "event-v4 genesis bytes",
            limit: usize::MAX,
            observed: usize::MAX,
        })?;
        if &self.run_id != run_id
            || self.genesis_artifact.cas_hash() != &ContentHash::sha256(bytes)
            || self.genesis_artifact.size() != size
            || self.repository_identity != snapshot.program_space.repository_identity()
            || self.snapshot_id != *snapshot.program_space.snapshot_id()
            || self.profile_id != snapshot.program_space.profile_id()
            || self.profile_version != snapshot.program_space.profile_version()
        {
            return Err(DomainError::Validation(
                "event-v4 genesis manifest does not bind its exact source closure".to_owned(),
            ));
        }
        Ok(())
    }

    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }

    pub fn genesis_artifact(&self) -> &ArtifactRegisteredV3 {
        &self.genesis_artifact
    }
}

impl<'de> Deserialize<'de> for RunGenesisManifestV4 {
    fn deserialize<D>(deserializer: D) -> std::result::Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        Self::from_raw(RawRunGenesisManifestV4::deserialize(deserializer)?)
            .map_err(serde::de::Error::custom)
    }
}

/// Complete pure source closure for fresh event-v4 genesis construction.
#[derive(Debug)]
pub struct RunGenesisBootstrapRequestV4 {
    run_id: StableId,
    canonical_genesis_bytes: Vec<u8>,
    repository_identity: String,
    snapshot_id: StableId,
    profile_id: String,
    profile_version: String,
}

impl RunGenesisBootstrapRequestV4 {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        run_id: StableId,
        canonical_genesis_bytes: Vec<u8>,
        repository_identity: impl Into<String>,
        snapshot_id: StableId,
        profile_id: impl Into<String>,
        profile_version: impl Into<String>,
    ) -> Result<Self> {
        if canonical_genesis_bytes.len() > crate::m4::MAX_RETAINED_WORKING_BYTES as usize {
            return Err(DomainError::Incomplete {
                operation: "event-v4 bootstrap genesis bytes",
                limit: crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
                observed: canonical_genesis_bytes.len(),
            });
        }
        Ok(Self {
            run_id,
            canonical_genesis_bytes,
            repository_identity: repository_identity.into(),
            snapshot_id,
            profile_id: profile_id.into(),
            profile_version: profile_version.into(),
        })
    }
}

fn validate_v2_genesis_contract(
    run_id: &StableId,
    initial: &ReviewAggregate,
    bytes: &[u8],
    manifest: &RunGenesisManifest,
) -> Result<RunGenesisSnapshot> {
    let snapshot = RunGenesisSnapshot::from_canonical_bytes(bytes)?;
    let rebuilt = snapshot.rebuild_aggregate()?;
    if canonical_json(&rebuilt)? != canonical_json(initial)? {
        return Err(DomainError::Validation(
            "verified run genesis bytes do not reconstruct the supplied initial aggregate"
                .to_owned(),
        ));
    }
    manifest.validate_against_genesis(run_id, &snapshot, bytes)?;
    Ok(snapshot)
}

fn validate_v2_genesis_envelope(
    run_id: &StableId,
    initial: &ReviewAggregate,
    bytes: &[u8],
    envelope: &EventEnvelope,
) -> Result<RunGenesisSnapshot> {
    if envelope.genesis_hash != ContentHash::sha256(bytes) {
        return Err(DomainError::EventSequence(
            "v2 genesis envelope hash must equal the verified canonical genesis CAS".to_owned(),
        ));
    }
    let payload = decode_canonical_payload(EventContractVersion::V2, envelope.payload.get())?;
    let PersistedPayload::RunGenesisManifest(manifest) = payload else {
        return Err(DomainError::EventSequence(
            "v2 sequence one must carry RunGenesisManifest".to_owned(),
        ));
    };
    validate_v2_genesis_contract(run_id, initial, bytes, &manifest)
}

fn validate_v3_genesis_contract(
    run_id: &StableId,
    initial: &ReviewAggregate,
    bytes: &[u8],
    manifest: &RunGenesisManifestV3,
) -> Result<RunGenesisSnapshot> {
    let snapshot = RunGenesisSnapshot::from_canonical_bytes_v3(bytes)?;
    let rebuilt = snapshot.rebuild_aggregate()?;
    let rebuilt_bytes = RunGenesisSnapshot::from_aggregate_v3(&rebuilt)?.canonical_bytes_v3()?;
    let initial_bytes = encode_exact_compact_json(
        &BorrowedRunGenesisSnapshot(initial),
        "event-v3 genesis validation bytes",
    )?;
    if rebuilt_bytes != initial_bytes {
        return Err(DomainError::Validation(
            "verified v3 genesis bytes do not reconstruct the supplied initial aggregate"
                .to_owned(),
        ));
    }
    manifest.validate_against_genesis(run_id, &snapshot, bytes)?;
    Ok(snapshot)
}

fn validate_v3_genesis_envelope(
    run_id: &StableId,
    initial: &ReviewAggregate,
    bytes: &[u8],
    envelope: &EventEnvelope,
) -> Result<RunGenesisSnapshot> {
    let payload = decode_canonical_payload(EventContractVersion::V3, envelope.payload.get())?;
    validate_v3_genesis_decoded_envelope(run_id, initial, bytes, envelope, &payload)
}

fn validate_v3_genesis_decoded_envelope(
    run_id: &StableId,
    initial: &ReviewAggregate,
    bytes: &[u8],
    envelope: &EventEnvelope,
    payload: &PersistedPayload,
) -> Result<RunGenesisSnapshot> {
    if envelope.genesis_hash != ContentHash::sha256(bytes) {
        return Err(DomainError::EventSequence(
            "v3 genesis envelope hash must equal the verified canonical genesis CAS".to_owned(),
        ));
    }
    if envelope.sequence != 1 {
        return Err(DomainError::EventSequence(
            "v3 genesis manifest must occupy sequence one".to_owned(),
        ));
    }
    let PersistedPayload::RunGenesisManifestV3(manifest) = payload else {
        return Err(DomainError::EventSequence(
            "v3 sequence one must carry RunGenesisManifestV3".to_owned(),
        ));
    };
    validate_v3_genesis_contract(run_id, initial, bytes, manifest)
}

fn validate_v4_genesis_envelope(
    run_id: &StableId,
    initial: &ReviewAggregate,
    bytes: &[u8],
    envelope: &EventEnvelope,
) -> Result<RunGenesisSnapshot> {
    let snapshot = RunGenesisSnapshot::from_canonical_bytes_v3(bytes)?;
    let rebuilt = snapshot.rebuild_aggregate()?;
    let rebuilt_bytes = RunGenesisSnapshot::from_aggregate_v3(&rebuilt)?.canonical_bytes_v3()?;
    let initial_bytes = encode_exact_compact_json(
        &BorrowedRunGenesisSnapshot(initial),
        "event-v4 genesis validation bytes",
    )?;
    if rebuilt_bytes != initial_bytes {
        return Err(DomainError::Validation(
            "verified v4 genesis bytes do not reconstruct the supplied initial aggregate"
                .to_owned(),
        ));
    }
    if envelope.genesis_hash != ContentHash::sha256(bytes) || envelope.sequence != 1 {
        return Err(DomainError::EventSequence(
            "v4 genesis manifest must occupy sequence one and bind the canonical genesis CAS"
                .to_owned(),
        ));
    }
    let payload = decode_canonical_payload(EventContractVersion::V4, envelope.payload.get())?;
    let PersistedPayload::RunGenesisManifestV4(manifest) = payload else {
        return Err(DomainError::EventSequence(
            "v4 sequence one must carry RunGenesisManifestV4".to_owned(),
        ));
    };
    manifest.validate_against_genesis(run_id, &snapshot, bytes)?;
    Ok(snapshot)
}

/// One persisted source entry, referring to a prior registration rather than
/// embedding workspace bytes in the event stream.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct SnapshotSourceRecordEntry {
    artifact_id: StableId,
    path: String,
    content_hash: ContentHash,
    registration_id: StableId,
    cas_hash: ContentHash,
    line_count: u64,
}

impl SnapshotSourceRecordEntry {
    /// Creates one immutable source-registration reference.
    pub fn new(
        artifact_id: StableId,
        path: impl Into<String>,
        content_hash: ContentHash,
        registration_id: StableId,
        cas_hash: ContentHash,
        line_count: u64,
    ) -> Result<Self> {
        let entry = Self {
            artifact_id,
            path: path.into(),
            content_hash,
            registration_id,
            cas_hash,
            line_count,
        };
        if entry.path.is_empty()
            || entry.registration_id.kind() != "registration"
            || !is_cas_hash(&entry.content_hash)
            || !is_cas_hash(&entry.cas_hash)
            || entry.content_hash != entry.cas_hash
            || entry.line_count == 0
        {
            return Err(DomainError::Validation(
                "invalid snapshot source registration entry".to_owned(),
            ));
        }
        Ok(entry)
    }
}

/// Exact source-registration projection for one accepted snapshot.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct SnapshotSourcesRecorded {
    snapshot_id: StableId,
    entries: Vec<SnapshotSourceRecordEntry>,
}

impl SnapshotSourcesRecorded {
    pub(crate) fn allocated_bytes(&self) -> usize {
        self.snapshot_id
            .allocated_bytes()
            .saturating_add(
                self.entries
                    .capacity()
                    .saturating_mul(std::mem::size_of::<SnapshotSourceRecordEntry>()),
            )
            .saturating_add(self.entries.iter().fold(0_usize, |total, entry| {
                total
                    .saturating_add(entry.artifact_id.allocated_bytes())
                    .saturating_add(entry.path.capacity())
                    .saturating_add(entry.content_hash.allocated_bytes())
                    .saturating_add(entry.registration_id.allocated_bytes())
                    .saturating_add(entry.cas_hash.allocated_bytes())
            }))
    }
    /// Constructs a path-ordered exact source record set.
    pub fn new(snapshot_id: StableId, entries: Vec<SnapshotSourceRecordEntry>) -> Result<Self> {
        let sources = Self {
            snapshot_id,
            entries,
        };
        sources.validate_shape()?;
        Ok(sources)
    }

    fn validate_shape(&self) -> Result<()> {
        let mut paths = BTreeMap::new();
        let mut artifacts = BTreeMap::new();
        let mut previous = None;
        for entry in &self.entries {
            if entry.path.is_empty()
                || !is_cas_hash(&entry.content_hash)
                || !is_cas_hash(&entry.cas_hash)
                || entry.content_hash != entry.cas_hash
                || entry.line_count == 0
            {
                return Err(DomainError::Validation(
                    "snapshot source entries require non-empty paths and SHA-256 CAS hashes"
                        .to_owned(),
                ));
            }
            if previous
                .as_ref()
                .is_some_and(|path: &String| path >= &entry.path)
                || paths.insert(entry.path.clone(), ()).is_some()
                || artifacts.insert(entry.artifact_id.clone(), ()).is_some()
            {
                return Err(DomainError::Validation(
                    "snapshot source entries must be uniquely ordered by path".to_owned(),
                ));
            }
            previous = Some(entry.path.clone());
        }
        Ok(())
    }

    #[must_use]
    pub fn snapshot_id(&self) -> &StableId {
        &self.snapshot_id
    }

    #[must_use]
    pub fn entries(&self) -> &[SnapshotSourceRecordEntry] {
        &self.entries
    }
}

impl SnapshotSourceRecordEntry {
    #[must_use]
    pub fn artifact_id(&self) -> &StableId {
        &self.artifact_id
    }
    #[must_use]
    pub fn path(&self) -> &str {
        &self.path
    }
    #[must_use]
    pub fn content_hash(&self) -> &ContentHash {
        &self.content_hash
    }
    #[must_use]
    pub fn registration_id(&self) -> &StableId {
        &self.registration_id
    }
    #[must_use]
    pub fn cas_hash(&self) -> &ContentHash {
        &self.cas_hash
    }
    #[must_use]
    pub const fn line_count(&self) -> u64 {
        self.line_count
    }
}

fn is_cas_hash(hash: &ContentHash) -> bool {
    let value = hash.to_string();
    value.len() == 71
        && value.starts_with("sha256:")
        && value[7..]
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

/// Internal exact append point for non-serializable event admissions.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct StreamPosition {
    pub(crate) run_id: StableId,
    pub(crate) genesis_hash: ContentHash,
    pub(crate) tail_hash: ContentHash,
    pub(crate) sequence: u64,
}

/// An opaque, locally admitted command for an append-only M1 event log.
///
/// It deliberately has no JSON deserializer. Persisted records are decoded by
/// a private DTO at replay time, where their trust capabilities are checked
/// again. This prevents a caller from forging an accepting decision or an
/// exact evidence admission by deserializing a public payload enum.
#[derive(Clone, Debug)]
pub struct EventCommand {
    payload: PersistedPayload,
    admission: CommandAdmission,
}

#[derive(Clone, Debug)]
enum CommandAdmission {
    None,
    Evidence(EvidenceAdmission),
    Binding(EvidenceBindingAdmission),
    Verification(VerificationAdmission),
    Decision(DecisionAdmission),
    ContextProjection(ContextProjectionAdmission),
    ReviewerRaw(ReviewerRawClosure),
}

#[derive(Default)]
struct MatchedAdmissions {
    evidence: Option<EvidenceAdmission>,
    binding: Option<EvidenceBindingAdmission>,
    verification: Option<VerificationAdmission>,
    decision: Option<DecisionAdmission>,
    context_projection: Option<PositionedContextProjectionAdmission>,
    reviewer_raw: Option<ReviewerRawClosure>,
}

/// A private byte admission sealed to one exact persisted event position.
#[derive(Clone, Debug, Eq, PartialEq)]
struct PositionedContextProjectionAdmission {
    run_id: StableId,
    genesis_hash: ContentHash,
    previous_event_hash: ContentHash,
    sequence: u64,
    event_id: StableId,
    projection: ContextProjectionAdmission,
}

impl PositionedContextProjectionAdmission {
    fn allocated_bytes(&self) -> usize {
        self.run_id
            .allocated_bytes()
            .saturating_add(self.genesis_hash.allocated_bytes())
            .saturating_add(self.previous_event_hash.allocated_bytes())
            .saturating_add(self.event_id.allocated_bytes())
            .saturating_add(self.projection.allocated_bytes())
    }

    fn seal(
        event: &EventEnvelope,
        context: &ReviewContextEnvelope,
        projection: ContextProjectionAdmission,
    ) -> Result<Self> {
        if !projection.matches_projection(context) {
            return Err(DomainError::Validation(
                "context projection admission does not match the persisted envelope".to_owned(),
            ));
        }
        Ok(Self {
            run_id: event.run_id.clone(),
            genesis_hash: event.genesis_hash.clone(),
            previous_event_hash: event.previous_event_hash.clone(),
            sequence: event.sequence,
            event_id: event.id.clone(),
            projection,
        })
    }

    fn matches(
        &self,
        event: &EventEnvelope,
        context: &ReviewContextEnvelope,
        aggregate: &ReviewAggregate,
    ) -> Result<bool> {
        Ok(self.matches_position(event) && self.projection.matches(context, aggregate)?)
    }

    fn matches_position(&self, event: &EventEnvelope) -> bool {
        self.run_id == event.run_id
            && self.genesis_hash == event.genesis_hash
            && self.previous_event_hash == event.previous_event_hash
            && self.sequence == event.sequence
            && self.event_id == event.id
    }
}

/// Opaque, non-serializable authorization for one exact claim/evidence binding
/// at one immutable event-log genesis and append position.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct EvidenceBindingAdmission {
    run_id: StableId,
    genesis_hash: ContentHash,
    tail_hash: ContentHash,
    sequence: u64,
    binding_id: StableId,
    digest: ContentHash,
}

/// Opaque, non-serializable authorization for one exact, canonical verifier
/// result in one immutable event-log genesis and append position.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct VerificationAdmission {
    run_id: StableId,
    genesis_hash: ContentHash,
    tail_hash: ContentHash,
    sequence: u64,
    verification_id: StableId,
    digest: ContentHash,
}

/// Non-serializable host admissions required to replay authority-bearing events.
///
/// Each token is exact, run/genesis/body-bound, and bound to the mint-time
/// chain tail plus expected next sequence. Empty admissions are appropriate
/// only for streams with no such events.
#[derive(Clone, Debug, Default)]
pub struct EventAdmissions {
    evidence: Vec<EvidenceAdmission>,
    bindings: Vec<EvidenceBindingAdmission>,
    verifications: Vec<VerificationAdmission>,
    decisions: Vec<DecisionAdmission>,
    context_projections: Vec<PositionedContextProjectionAdmission>,
    reviewer_raw: Vec<ReviewerRawClosure>,
}

impl EventAdmissions {
    /// Builds a host-supplied admission set for imported events.
    #[must_use]
    pub fn new(evidence: Vec<EvidenceAdmission>, decisions: Vec<DecisionAdmission>) -> Self {
        Self {
            evidence,
            bindings: Vec::new(),
            verifications: Vec::new(),
            decisions,
            context_projections: Vec::new(),
            reviewer_raw: Vec::new(),
        }
    }

    /// Consumes independently rebuilt projections paired with the exact
    /// imported events they authorize, sealing each private byte admission to
    /// that event's run, genesis, predecessor, sequence, and event ID.
    pub fn with_context_projections(
        mut self,
        projections: Vec<(EventEnvelope, BuiltContextProjection)>,
    ) -> Result<Self> {
        for (event, built) in projections {
            let (built_context, projection) = built.into_parts();
            let payload = decode_canonical_payload(event.contract_version()?, event.payload.get())?;
            let PersistedPayload::ContextEnvelopeProjected(event_context) = payload else {
                return Err(DomainError::Validation(
                    "context projection admission must be paired with a context event".to_owned(),
                ));
            };
            if built_context
                .canonical_bytes()
                .map_err(context_domain_error)?
                != event_context
                    .canonical_bytes()
                    .map_err(context_domain_error)?
            {
                return Err(DomainError::Validation(
                    "rebuilt context projection does not equal its paired event payload".to_owned(),
                ));
            }
            self.context_projections
                .push(PositionedContextProjectionAdmission::seal(
                    &event,
                    &event_context,
                    projection,
                )?);
        }
        Ok(self)
    }

    /// Adds byte-derived, authority-free closure for imported D2 execution
    /// events. The bytes are consumed only to recheck hash and size; no
    /// reviewer capability or acceptance authority is minted.
    pub fn with_reviewer_artifacts(
        mut self,
        artifacts: Vec<(EventEnvelope, Vec<u8>)>,
    ) -> Result<Self> {
        for (event, raw_bytes) in artifacts {
            if raw_bytes.len() > crate::execution::MAX_D2_RAW_REVIEWER_BYTES {
                return Err(DomainError::Incomplete {
                    operation: "D2 raw reviewer bytes",
                    limit: crate::execution::MAX_D2_RAW_REVIEWER_BYTES,
                    observed: raw_bytes.len(),
                });
            }
            let payload = decode_canonical_payload(event.contract_version()?, event.payload.get())?;
            let PersistedPayload::ReviewExecutionRecorded(recorded) = payload else {
                return Err(DomainError::Validation(
                    "reviewer artifact bytes must be paired with a D2 execution event".to_owned(),
                ));
            };
            let closure = ReviewerRawClosure::from_bytes(&recorded, &raw_bytes)?;
            self.reviewer_raw.push(closure);
        }
        Ok(self)
    }

    fn with_context_admissions(
        mut self,
        admissions: Vec<PositionedContextProjectionAdmission>,
    ) -> Self {
        self.context_projections = admissions;
        self
    }

    fn with_reviewer_raw(mut self, reviewer_raw: Vec<ReviewerRawClosure>) -> Self {
        self.reviewer_raw = reviewer_raw;
        self
    }

    /// Adds the exact non-serializable admissions retained by locally recorded
    /// binding and verification events before a stream is imported again.
    #[must_use]
    pub fn with_trace_admissions(
        mut self,
        bindings: Vec<EvidenceBindingAdmission>,
        verifications: Vec<VerificationAdmission>,
    ) -> Self {
        self.bindings = bindings;
        self.verifications = verifications;
        self
    }

    fn evidence_for(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        tail_hash: &ContentHash,
        sequence: u64,
        evidence: &Evidence,
    ) -> Option<EvidenceAdmission> {
        self.evidence
            .iter()
            .find(|admission| {
                admission.matches(run_id, genesis_hash, tail_hash, sequence, evidence)
            })
            .cloned()
    }

    fn binding_for(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        tail_hash: &ContentHash,
        sequence: u64,
        binding: &EvidenceBinding,
    ) -> Option<EvidenceBindingAdmission> {
        self.bindings
            .iter()
            .find(|admission| admission.matches(run_id, genesis_hash, tail_hash, sequence, binding))
            .cloned()
    }

    fn verification_for(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        tail_hash: &ContentHash,
        sequence: u64,
        verification: &Verification,
    ) -> Option<VerificationAdmission> {
        self.verifications
            .iter()
            .find(|admission| {
                admission.matches(run_id, genesis_hash, tail_hash, sequence, verification)
            })
            .cloned()
    }

    fn decision_for(
        &self,
        position: &StreamPosition,
        universe_id: &StableId,
        closure_digest: &ContentHash,
        decision: &Decision,
    ) -> Option<DecisionAdmission> {
        self.decisions
            .iter()
            .find(|admission| {
                decision.matches_decision_admission(
                    position,
                    universe_id,
                    closure_digest,
                    admission,
                )
            })
            .cloned()
    }

    fn context_projection_for(
        &self,
        event: &EventEnvelope,
        envelope: &ReviewContextEnvelope,
        aggregate: &ReviewAggregate,
    ) -> Result<Option<PositionedContextProjectionAdmission>> {
        for admission in &self.context_projections {
            if admission.matches(event, envelope, aggregate)? {
                return Ok(Some(admission.clone()));
            }
        }
        Ok(None)
    }

    fn reviewer_raw_for(&self, recorded: &ReviewExecutionRecorded) -> Option<ReviewerRawClosure> {
        self.reviewer_raw
            .iter()
            .find(|closure| closure.matches(recorded))
            .cloned()
    }
}

impl EvidenceBindingAdmission {
    fn new(
        run_id: StableId,
        genesis_hash: ContentHash,
        tail_hash: ContentHash,
        sequence: u64,
        binding: &EvidenceBinding,
    ) -> Result<Self> {
        Ok(Self {
            run_id,
            genesis_hash,
            tail_hash,
            sequence,
            binding_id: binding.id().clone(),
            digest: ContentHash::sha256(&canonical_json(binding)?),
        })
    }

    fn matches(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        tail_hash: &ContentHash,
        sequence: u64,
        binding: &EvidenceBinding,
    ) -> bool {
        self.run_id == *run_id
            && self.genesis_hash == *genesis_hash
            && self.tail_hash == *tail_hash
            && self.sequence == sequence
            && self.binding_id == *binding.id()
            && canonical_json(binding).is_ok_and(|bytes| ContentHash::sha256(&bytes) == self.digest)
    }
}

impl VerificationAdmission {
    fn new(
        run_id: StableId,
        genesis_hash: ContentHash,
        tail_hash: ContentHash,
        sequence: u64,
        verification: &Verification,
    ) -> Result<Self> {
        Ok(Self {
            run_id,
            genesis_hash,
            tail_hash,
            sequence,
            verification_id: verification.id().clone(),
            digest: ContentHash::sha256(&canonical_json(verification)?),
        })
    }

    fn matches(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        tail_hash: &ContentHash,
        sequence: u64,
        verification: &Verification,
    ) -> bool {
        self.run_id == *run_id
            && self.genesis_hash == *genesis_hash
            && self.tail_hash == *tail_hash
            && self.sequence == sequence
            && self.verification_id == *verification.id()
            && canonical_json(verification)
                .is_ok_and(|bytes| ContentHash::sha256(&bytes) == self.digest)
    }
}

impl EventCommand {
    /// Requests a lifecycle transition. Completion has no trust implication.
    #[must_use]
    pub fn obligation_transition(obligation_id: StableId, next: ObligationLifecycle) -> Self {
        Self {
            payload: PersistedPayload::ObligationTransition {
                obligation_id,
                next,
            },
            admission: CommandAdmission::None,
        }
    }

    /// Adds a new, necessarily proposed and unreviewed claim.
    #[must_use]
    #[cfg(test)]
    pub(crate) fn claim_proposed(claim: ReviewClaim) -> Self {
        Self {
            payload: PersistedPayload::ClaimProposed(claim),
            admission: CommandAdmission::None,
        }
    }

    /// Records exact snapshot-bound evidence using a run-bound admission.
    #[must_use]
    pub fn evidence_recorded(evidence: Evidence, admission: EvidenceAdmission) -> Self {
        Self {
            payload: PersistedPayload::EvidenceRecorded(Box::new(evidence)),
            admission: CommandAdmission::Evidence(admission),
        }
    }

    /// Binds one separately recorded evidence item to one claim.
    #[must_use]
    pub fn evidence_bound(binding: EvidenceBinding, admission: EvidenceBindingAdmission) -> Self {
        Self {
            payload: PersistedPayload::EvidenceBound(binding),
            admission: CommandAdmission::Binding(admission),
        }
    }

    /// Records an explicit verifier result. The log derives and persists its
    /// freshness before hashing the event.
    #[must_use]
    pub fn verification_recorded(
        verification: Verification,
        admission: VerificationAdmission,
    ) -> Self {
        Self {
            payload: PersistedPayload::VerificationRecorded(verification),
            admission: CommandAdmission::Verification(admission),
        }
    }

    /// Records an exact, run-bound trusted human decision.
    #[must_use]
    pub fn decision_recorded(decision: Decision, admission: DecisionAdmission) -> Self {
        Self {
            payload: PersistedPayload::DecisionRecorded(decision),
            admission: CommandAdmission::Decision(admission),
        }
    }

    /// Adds a report finding; aggregate validation determines its status.
    #[must_use]
    pub fn finding_recorded(finding: Finding) -> Self {
        Self {
            payload: PersistedPayload::FindingRecorded(finding),
            admission: CommandAdmission::None,
        }
    }

    /// Registers a persisted artifact in a v2 stream.
    #[must_use]
    pub fn artifact_registered(registration: ArtifactRegistered) -> Self {
        Self {
            payload: PersistedPayload::ArtifactRegistered(registration),
            admission: CommandAdmission::None,
        }
    }

    /// Registers one size-bound artifact in a fresh homogeneous v3 stream.
    #[must_use]
    pub fn artifact_registered_v3(registration: ArtifactRegisteredV3) -> Self {
        Self {
            payload: PersistedPayload::ArtifactRegisteredV3(registration),
            admission: CommandAdmission::None,
        }
    }

    /// Records source registrations for one accepted snapshot in a v2 stream.
    #[must_use]
    pub fn snapshot_sources_recorded(sources: SnapshotSourcesRecorded) -> Self {
        Self {
            payload: PersistedPayload::SnapshotSourcesRecorded(sources),
            admission: CommandAdmission::None,
        }
    }

    /// Records one deterministic, aggregate-bound review plan in a v2 stream.
    #[must_use]
    pub fn review_plan_recorded(plan: ReviewPlan) -> Self {
        Self {
            payload: PersistedPayload::ReviewPlanRecorded(plan),
            admission: CommandAdmission::None,
        }
    }

    /// Records one byte-reverified context projection. A metadata-only
    /// envelope cannot be supplied here because the builder result is consumed
    /// together with its private runtime admission.
    #[must_use]
    pub fn context_envelope_projected(projection: BuiltContextProjection) -> Self {
        let (envelope, admission) = projection.into_parts();
        Self {
            payload: PersistedPayload::ContextEnvelopeProjected(envelope),
            admission: CommandAdmission::ContextProjection(admission),
        }
    }

    /// Records one validated fake/no-tools D2 execution and all of its claims
    /// in the only atomic v2 payload that can introduce D2 claim state.
    #[must_use]
    pub fn review_execution_recorded(bundle: ValidatedExecutionBundle) -> Self {
        let (recorded, raw_closure) = bundle.into_parts();
        Self {
            payload: PersistedPayload::ReviewExecutionRecorded(recorded),
            admission: CommandAdmission::ReviewerRaw(raw_closure),
        }
    }
}

/// The closed persisted event vocabulary. It is private so it can never be
/// constructed from untrusted JSON through a public typed API.
#[derive(Clone, Debug, Serialize)]
#[serde(tag = "type", content = "data", rename_all = "snake_case")]
enum PersistedPayload {
    ObligationTransition {
        obligation_id: StableId,
        next: ObligationLifecycle,
    },
    ClaimProposed(LegacyClaimV1),
    EvidenceRecorded(Box<Evidence>),
    EvidenceBound(EvidenceBinding),
    VerificationRecorded(Verification),
    DecisionRecorded(Decision),
    FindingRecorded(Finding),
    RunGenesisManifest(RunGenesisManifest),
    #[serde(rename = "run_genesis_manifest")]
    RunGenesisManifestV3(RunGenesisManifestV3),
    #[serde(rename = "run_genesis_manifest")]
    RunGenesisManifestV4(RunGenesisManifestV4),
    ArtifactRegistered(ArtifactRegistered),
    #[serde(rename = "artifact_registered")]
    ArtifactRegisteredV3(ArtifactRegisteredV3),
    #[serde(rename = "artifact_registered_v4")]
    ArtifactRegisteredV4(ArtifactRegistrationV4),
    #[serde(rename = "gluing_bundle_recorded_v4")]
    GluingBundleRecordedV4(Box<RawValue>),
    #[serde(rename = "incremental_source_bound_v5")]
    IncrementalSourceBoundV5(Box<RawValue>),
    #[serde(rename = "program_mapping_recorded_v5")]
    ProgramMappingRecordedV5(Box<RawValue>),
    #[serde(rename = "change_morphism_sealed_v5")]
    ChangeMorphismSealedV5(Box<RawValue>),
    #[serde(rename = "obligation_correspondence_entry_recorded_v5")]
    ObligationCorrespondenceEntryRecordedV5(Box<RawValue>),
    #[serde(rename = "obligation_correspondence_sealed_v5")]
    ObligationCorrespondenceSealedV5(Box<RawValue>),
    #[serde(rename = "historical_record_assessed_v5")]
    HistoricalRecordAssessedV5(Box<RawValue>),
    #[serde(rename = "gluing_freshness_recorded_v5")]
    GluingFreshnessRecordedV5(Box<RawValue>),
    #[serde(rename = "staleness_assessment_sealed_v5")]
    StalenessAssessmentSealedV5(Box<RawValue>),
    #[serde(rename = "artifact_registered_v5")]
    ArtifactRegisteredV5(crate::ArtifactRegistrationV5),
    #[serde(rename = "preservation_verified_v5")]
    PreservationVerifiedV5 {
        evidence: crate::PreservationEvidenceV5,
        verification: crate::PreservationVerificationV5,
    },
    #[serde(rename = "partial_rerun_action_recorded_v5")]
    PartialRerunActionRecordedV5(crate::PartialRerunActionV5),
    #[serde(rename = "partial_rerun_plan_sealed_v5")]
    PartialRerunPlanSealedV5(crate::PartialRerunPlanV5),
    #[serde(rename = "gluing_rerun_action_recorded_v5")]
    GluingRerunActionRecordedV5(crate::GluingRerunActionV5),
    #[serde(rename = "gluing_rerun_plan_sealed_v5")]
    GluingRerunPlanSealedV5(crate::GluingRerunPlanSealV5),
    /// Final sealed terminal receipt. This raw canonical DTO is private to
    /// the M5 cursor; its decoder/grammar admission is added with the terminal
    /// persistence slice rather than exposed as a generic append command.
    #[serde(rename = "terminal_completed_v5")]
    TerminalCompletedV5(Box<RawValue>),
    #[serde(rename = "evidence_recorded_v3")]
    EvidenceRecordedV3(EvidenceV3),
    #[serde(rename = "evidence_bound_v3")]
    EvidenceBoundV3(EvidenceBindingV3),
    #[serde(rename = "verification_recorded_v3")]
    VerificationRecordedV3(VerificationV3),
    #[serde(rename = "decision_recorded_v3")]
    DecisionRecordedV3(DecisionV3),
    #[serde(rename = "finding_recorded_v3")]
    FindingRecordedV3(FindingV3),
    SnapshotSourcesRecorded(SnapshotSourcesRecorded),
    ReviewPlanRecorded(ReviewPlan),
    ContextEnvelopeProjected(ReviewContextEnvelope),
    ReviewExecutionRecorded(ReviewExecutionRecorded),
}

fn validate_m6_raw_payload_v5(
    raw: &RawValue,
    expected_schema: &'static str,
    expected_id_kind: &'static str,
) -> Result<()> {
    #[derive(Deserialize)]
    struct Header {
        schema: String,
        id: StableId,
    }
    preflight_event_json_structure(raw.get().as_bytes())?;
    let value: Value =
        serde_json::from_str(raw.get()).map_err(|error| DomainError::Json(error.to_string()))?;
    if canonical_json(&value)?.as_slice() != raw.get().as_bytes() {
        return Err(DomainError::EventSequence(
            "M6 event body must be exact canonical JSON".to_owned(),
        ));
    }
    let header: Header =
        serde_json::from_value(value).map_err(|error| DomainError::Json(error.to_string()))?;
    if header.schema != expected_schema || header.id.kind() != expected_id_kind {
        return Err(DomainError::Validation(
            "M6 event body schema or ID kind is outside the closed payload contract".to_owned(),
        ));
    }
    Ok(())
}

impl PersistedPayload {
    fn validation_heap_bytes_v5(&self) -> Result<u64> {
        let bytes = match self {
            Self::ObligationTransition { obligation_id, .. } => obligation_id.allocated_bytes(),
            Self::RunGenesisManifestV4(value) => value.allocated_bytes(),
            Self::ArtifactRegisteredV3(value) => value.allocated_bytes(),
            Self::ArtifactRegisteredV4(value) => value.allocated_bytes(),
            Self::GluingBundleRecordedV4(value) => value.get().len(),
            Self::IncrementalSourceBoundV5(value)
            | Self::ProgramMappingRecordedV5(value)
            | Self::ChangeMorphismSealedV5(value)
            | Self::ObligationCorrespondenceEntryRecordedV5(value)
            | Self::ObligationCorrespondenceSealedV5(value)
            | Self::HistoricalRecordAssessedV5(value)
            | Self::GluingFreshnessRecordedV5(value)
            | Self::StalenessAssessmentSealedV5(value) => value.get().len(),
            Self::ArtifactRegisteredV5(value) => canonical_json(value)?.len(),
            Self::PreservationVerifiedV5 {
                evidence,
                verification,
            } => canonical_json(evidence)?
                .len()
                .saturating_add(canonical_json(verification)?.len()),
            Self::PartialRerunActionRecordedV5(value) => canonical_json(value)?.len(),
            Self::PartialRerunPlanSealedV5(value) => canonical_json(value)?.len(),
            // Count rather than materialize canonical JSON.  Post-D2 replay
            // uses this value for admission before it decodes a suffix
            // member, so allocating a temporary Vec here would invalidate
            // that pre-allocation gate.
            Self::GluingRerunActionRecordedV5(value) => {
                usize::try_from(crate::canonical::canonical_json_count_bounded(
                    value,
                    crate::m6::MAX_M6_CANONICAL_BYTES,
                    "M6 gluing action validation bytes",
                )?)
                .unwrap_or(usize::MAX)
            }
            Self::GluingRerunPlanSealedV5(value) => {
                usize::try_from(crate::canonical::canonical_json_count_bounded(
                    value,
                    crate::m6::MAX_M6_CANONICAL_BYTES,
                    "M6 gluing seal validation bytes",
                )?)
                .unwrap_or(usize::MAX)
            }
            Self::TerminalCompletedV5(value) => value.get().len(),
            Self::EvidenceRecordedV3(value) => {
                usize::try_from(value.allocated_bytes().map_err(m4_domain_error)?)
                    .unwrap_or(usize::MAX)
            }
            Self::EvidenceBoundV3(value) => {
                usize::try_from(value.allocated_bytes().map_err(m4_domain_error)?)
                    .unwrap_or(usize::MAX)
            }
            Self::VerificationRecordedV3(value) => {
                usize::try_from(value.allocated_bytes().map_err(m4_domain_error)?)
                    .unwrap_or(usize::MAX)
            }
            Self::DecisionRecordedV3(value) => {
                usize::try_from(value.allocated_bytes().map_err(m4_domain_error)?)
                    .unwrap_or(usize::MAX)
            }
            Self::FindingRecordedV3(value) => {
                usize::try_from(value.allocated_bytes().map_err(m4_domain_error)?)
                    .unwrap_or(usize::MAX)
            }
            Self::SnapshotSourcesRecorded(value) => value.allocated_bytes(),
            Self::ReviewPlanRecorded(value) => value.allocated_bytes(),
            Self::ContextEnvelopeProjected(value) => value.allocated_bytes(),
            Self::ReviewExecutionRecorded(value) => value.allocated_bytes(),
            Self::ClaimProposed(_)
            | Self::EvidenceRecorded(_)
            | Self::EvidenceBound(_)
            | Self::VerificationRecorded(_)
            | Self::DecisionRecorded(_)
            | Self::FindingRecorded(_)
            | Self::RunGenesisManifest(_)
            | Self::RunGenesisManifestV3(_)
            | Self::ArtifactRegistered(_) => {
                return Err(DomainError::EventSequence(
                    "V5 validation accounting refuses a payload outside the closed V5 vocabulary"
                        .to_owned(),
                ));
            }
        };
        u64::try_from(bytes).map_err(|_| DomainError::Incomplete {
            operation: "V5 decoded payload recursive heap",
            limit: usize::try_from(MAX_V5_REPLAY_WORKING_BYTES).unwrap_or(usize::MAX),
            observed: usize::MAX,
        })
    }

    fn unreconciled_kind_and_id(&self) -> Option<(UnreconciledRecordKind, &StableId)> {
        match self {
            Self::EvidenceRecorded(value) => Some((UnreconciledRecordKind::Evidence, value.id())),
            Self::EvidenceBound(value) => {
                Some((UnreconciledRecordKind::EvidenceBinding, value.id()))
            }
            Self::VerificationRecorded(value) => {
                Some((UnreconciledRecordKind::Verification, value.id()))
            }
            Self::DecisionRecorded(value) => Some((UnreconciledRecordKind::Decision, value.id())),
            Self::ReviewExecutionRecorded(value) => Some((
                UnreconciledRecordKind::ReviewExecution,
                value.execution.id(),
            )),
            _ => None,
        }
    }

    fn is_v2_only(&self) -> bool {
        matches!(
            self,
            Self::RunGenesisManifest(_)
                | Self::ArtifactRegistered(_)
                | Self::SnapshotSourcesRecorded(_)
                | Self::ReviewPlanRecorded(_)
                | Self::ContextEnvelopeProjected(_)
                | Self::ReviewExecutionRecorded(_)
        )
    }

    fn is_m6_v5(&self) -> bool {
        matches!(
            self,
            Self::IncrementalSourceBoundV5(_)
                | Self::ProgramMappingRecordedV5(_)
                | Self::ChangeMorphismSealedV5(_)
                | Self::ObligationCorrespondenceEntryRecordedV5(_)
                | Self::ObligationCorrespondenceSealedV5(_)
                | Self::HistoricalRecordAssessedV5(_)
                | Self::GluingFreshnessRecordedV5(_)
                | Self::StalenessAssessmentSealedV5(_)
                | Self::ArtifactRegisteredV5(_)
                | Self::PreservationVerifiedV5 { .. }
                | Self::PartialRerunActionRecordedV5(_)
                | Self::PartialRerunPlanSealedV5(_)
                | Self::GluingRerunActionRecordedV5(_)
                | Self::GluingRerunPlanSealedV5(_)
                | Self::TerminalCompletedV5(_)
        )
    }

    fn allowed_in(&self, version: EventContractVersion) -> bool {
        match version {
            EventContractVersion::V1 => {
                !self.is_v2_only()
                    && !self.is_m6_v5()
                    && !matches!(
                        self,
                        Self::RunGenesisManifestV3(_)
                            | Self::ArtifactRegisteredV3(_)
                            | Self::EvidenceRecordedV3(_)
                            | Self::EvidenceBoundV3(_)
                            | Self::VerificationRecordedV3(_)
                            | Self::DecisionRecordedV3(_)
                            | Self::FindingRecordedV3(_)
                            | Self::RunGenesisManifestV4(_)
                            | Self::ArtifactRegisteredV4(_)
                            | Self::GluingBundleRecordedV4(_)
                    )
            }
            EventContractVersion::V2 => {
                !self.is_m6_v5()
                    && !matches!(
                        self,
                        Self::RunGenesisManifestV3(_)
                            | Self::ArtifactRegisteredV3(_)
                            | Self::EvidenceRecordedV3(_)
                            | Self::EvidenceBoundV3(_)
                            | Self::VerificationRecordedV3(_)
                            | Self::DecisionRecordedV3(_)
                            | Self::FindingRecordedV3(_)
                            | Self::RunGenesisManifestV4(_)
                            | Self::ArtifactRegisteredV4(_)
                            | Self::GluingBundleRecordedV4(_)
                    )
            }
            EventContractVersion::V3 => {
                !self.is_m6_v5()
                    && !matches!(
                        self,
                        Self::ClaimProposed(_)
                            | Self::EvidenceRecorded(_)
                            | Self::EvidenceBound(_)
                            | Self::VerificationRecorded(_)
                            | Self::DecisionRecorded(_)
                            | Self::FindingRecorded(_)
                            | Self::RunGenesisManifest(_)
                            | Self::ArtifactRegistered(_)
                            | Self::RunGenesisManifestV4(_)
                            | Self::ArtifactRegisteredV4(_)
                            | Self::GluingBundleRecordedV4(_)
                    )
            }
            EventContractVersion::V4 => {
                !self.is_m6_v5()
                    && !matches!(
                        self,
                        Self::ClaimProposed(_)
                            | Self::EvidenceRecorded(_)
                            | Self::EvidenceBound(_)
                            | Self::VerificationRecorded(_)
                            | Self::DecisionRecorded(_)
                            | Self::FindingRecorded(_)
                            | Self::RunGenesisManifest(_)
                            | Self::ArtifactRegistered(_)
                            | Self::RunGenesisManifestV3(_) // v4-only payloads are admitted only by v4.
                    )
            }
            EventContractVersion::V5 => !matches!(
                self,
                Self::ClaimProposed(_)
                    | Self::EvidenceRecorded(_)
                    | Self::EvidenceBound(_)
                    | Self::VerificationRecorded(_)
                    | Self::DecisionRecorded(_)
                    | Self::FindingRecorded(_)
                    | Self::RunGenesisManifest(_)
                    | Self::ArtifactRegistered(_)
                    | Self::RunGenesisManifestV3(_)
            ),
        }
    }

    fn is_d1_bounded(&self) -> bool {
        matches!(
            self,
            Self::ReviewPlanRecorded(_)
                | Self::ContextEnvelopeProjected(_)
                | Self::ReviewExecutionRecorded(_)
                | Self::RunGenesisManifestV3(_)
                | Self::ArtifactRegisteredV3(_)
                | Self::EvidenceRecordedV3(_)
                | Self::EvidenceBoundV3(_)
                | Self::VerificationRecordedV3(_)
                | Self::DecisionRecordedV3(_)
                | Self::FindingRecordedV3(_)
                | Self::RunGenesisManifestV4(_)
                | Self::ArtifactRegisteredV4(_)
                | Self::GluingBundleRecordedV4(_)
                | Self::IncrementalSourceBoundV5(_)
                | Self::ProgramMappingRecordedV5(_)
                | Self::ChangeMorphismSealedV5(_)
                | Self::ObligationCorrespondenceEntryRecordedV5(_)
                | Self::ObligationCorrespondenceSealedV5(_)
                | Self::HistoricalRecordAssessedV5(_)
                | Self::GluingFreshnessRecordedV5(_)
                | Self::StalenessAssessmentSealedV5(_)
                | Self::ArtifactRegisteredV5(_)
                | Self::PreservationVerifiedV5 { .. }
                | Self::PartialRerunActionRecordedV5(_)
                | Self::PartialRerunPlanSealedV5(_)
                | Self::GluingRerunActionRecordedV5(_)
                | Self::GluingRerunPlanSealedV5(_)
        )
    }

    fn actor(&self) -> &str {
        match self {
            Self::DecisionRecorded(decision) => decision.actor(),
            Self::EvidenceRecordedV3(evidence) => match evidence.descriptor() {
                crate::VerifierDescriptorV3::StaticFactV1 => {
                    "verifier:reviewgraphen.static_fact_verifier@1"
                }
                crate::VerifierDescriptorV3::FixedFixtureV1 => {
                    "verifier:reviewgraphen.fixture_test_verifier@1"
                }
            },
            Self::EvidenceBoundV3(binding) => match binding.relation() {
                crate::EvidenceRelationV3::Qualifies => {
                    "verifier:reviewgraphen.static_fact_verifier@1"
                }
                crate::EvidenceRelationV3::Reproduces => {
                    "verifier:reviewgraphen.fixture_test_verifier@1"
                }
            },
            Self::VerificationRecordedV3(verification) => match verification.descriptor() {
                crate::VerifierDescriptorV3::StaticFactV1 => {
                    "verifier:reviewgraphen.static_fact_verifier@1"
                }
                crate::VerifierDescriptorV3::FixedFixtureV1 => {
                    "verifier:reviewgraphen.fixture_test_verifier@1"
                }
            },
            Self::DecisionRecordedV3(decision) => decision.actor(),
            Self::FindingRecordedV3(_) => "projection:reviewgraphen.finding_projection@1",
            Self::ArtifactRegisteredV4(_) => "engine:reviewgraphen.m5_gluing_input@1",
            Self::GluingBundleRecordedV4(_) => "engine:reviewgraphen.m5_gluing@1",
            Self::ArtifactRegisteredV5(_) | Self::PreservationVerifiedV5 { .. } => {
                "verifier:reviewgraphen.structural_preservation@1"
            }
            Self::PartialRerunActionRecordedV5(_)
            | Self::PartialRerunPlanSealedV5(_)
            | Self::GluingRerunActionRecordedV5(_)
            | Self::GluingRerunPlanSealedV5(_) => SYSTEM_ACTOR,
            Self::TerminalCompletedV5(_) => "engine:reviewgraphen.m5_terminal@1",
            _ => SYSTEM_ACTOR,
        }
    }

    fn validate_shape(&self) -> Result<()> {
        match self {
            Self::ObligationTransition { .. } => Ok(()),
            Self::ClaimProposed(claim) => claim.validate_initial(),
            Self::EvidenceRecorded(evidence) => evidence.validate_for_review_event(),
            Self::EvidenceBound(binding) => {
                if binding
                    .scope()
                    .get("property_id")
                    .is_none_or(String::is_empty)
                {
                    return Err(DomainError::Validation(
                        "evidence binding requires a non-empty property_id scope".to_owned(),
                    ));
                }
                Ok(())
            }
            Self::VerificationRecorded(verification) => verification.validate_event_shape(),
            Self::DecisionRecorded(decision) => decision.validate_event_admission(),
            Self::FindingRecorded(_) => Ok(()),
            Self::RunGenesisManifest(manifest) => manifest.validate(),
            Self::RunGenesisManifestV3(manifest) => manifest.validate(),
            Self::RunGenesisManifestV4(manifest) => manifest.validate(),
            Self::ArtifactRegistered(registration) => registration.validate(),
            Self::ArtifactRegisteredV3(registration) => registration.validate(),
            Self::ArtifactRegisteredV4(registration) => registration.validate(),
            Self::GluingBundleRecordedV4(bundle) => {
                crate::GluingBundleV4::preflight_json_bytes(bundle.get().as_bytes())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::IncrementalSourceBoundV5(value) => validate_m6_raw_payload_v5(
                value,
                "reviewgraphen.incremental_source_closure.v5",
                "incremental-source-closure-v5",
            )
            .and_then(|()| {
                crate::IncrementalSourceClosureV5::validate_event_wire(value.get().as_bytes())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }),
            Self::ProgramMappingRecordedV5(value) => {
                validate_m6_raw_payload_v5(
                    value,
                    "reviewgraphen.program_mapping.v5",
                    "program-mapping-v5",
                )?;
                crate::ProgramMappingV5::from_json_bytes(value.get().as_bytes())
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::ChangeMorphismSealedV5(value) => validate_m6_raw_payload_v5(
                value,
                "reviewgraphen.change_morphism.v5",
                "change-morphism-v5",
            )
            .and_then(|()| {
                crate::ChangeMorphismV5::validate_event_wire(value.get().as_bytes())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }),
            Self::ObligationCorrespondenceEntryRecordedV5(value) => {
                validate_m6_raw_payload_v5(
                    value,
                    "reviewgraphen.obligation_correspondence_entry.v5",
                    "obligation-correspondence-entry-v5",
                )?;
                crate::ObligationCorrespondenceEntryV5::from_json_bytes(value.get().as_bytes())
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::ObligationCorrespondenceSealedV5(value) => validate_m6_raw_payload_v5(
                value,
                "reviewgraphen.obligation_correspondence.v5",
                "obligation-correspondence-v5",
            )
            .and_then(|()| {
                crate::ObligationCorrespondenceV5::validate_event_wire(value.get().as_bytes())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }),
            Self::HistoricalRecordAssessedV5(value) => {
                validate_m6_raw_payload_v5(
                    value,
                    "reviewgraphen.historical_record_assessment.v5",
                    "historical-record-assessment-v5",
                )?;
                crate::HistoricalRecordAssessmentV5::from_json_bytes(value.get().as_bytes())
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::GluingFreshnessRecordedV5(value) => {
                validate_m6_raw_payload_v5(
                    value,
                    "reviewgraphen.gluing_freshness.v5",
                    "gluing-freshness-v5",
                )?;
                crate::GluingFreshnessV5::from_json_bytes(value.get().as_bytes())
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::StalenessAssessmentSealedV5(value) => validate_m6_raw_payload_v5(
                value,
                "reviewgraphen.staleness_assessment.v5",
                "staleness-assessment-v5",
            )
            .and_then(|()| {
                crate::StalenessAssessmentV5::validate_event_wire(value.get().as_bytes())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }),
            Self::ArtifactRegisteredV5(value) => {
                crate::ArtifactRegistrationV5::from_json_bytes(&canonical_json(value)?)
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::PreservationVerifiedV5 {
                evidence,
                verification,
            } => {
                crate::PreservationEvidenceV5::from_json_bytes(&canonical_json(evidence)?)
                    .map_err(|error| DomainError::Validation(error.to_string()))?;
                crate::PreservationVerificationV5::from_json_bytes(&canonical_json(verification)?)
                    .map_err(|error| DomainError::Validation(error.to_string()))?;
                if verification.evidence_id() != evidence.id()
                    || evidence.target_obligation_id() != verification.target_obligation_id()
                    || evidence.source_verification_id() != verification.source_verification_id()
                {
                    return Err(DomainError::Validation(
                        "atomic preservation evidence and verification closure differs".to_owned(),
                    ));
                }
                Ok(())
            }
            Self::PartialRerunActionRecordedV5(action) => {
                crate::PartialRerunActionV5::from_json_bytes(&canonical_json(action)?)
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::PartialRerunPlanSealedV5(plan) => {
                crate::PartialRerunPlanV5::validate_event_wire(&canonical_json(plan)?)
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::GluingRerunActionRecordedV5(action) => {
                crate::GluingRerunActionV5::from_event_json_bytes(&canonical_json(action)?)
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::GluingRerunPlanSealedV5(plan) => {
                crate::GluingRerunPlanSealV5::from_event_json_bytes(&canonical_json(plan)?)
                    .map(|_| ())
                    .map_err(|error| DomainError::Validation(error.to_string()))
            }
            Self::TerminalCompletedV5(value) => {
                validate_m6_raw_payload_v5(
                    value,
                    "reviewgraphen.terminal_completed.v5",
                    "terminal-completed-v5",
                )?;
                let marker: TerminalCompletedWireV5 = serde_json::from_str(value.get())
                    .map_err(|error| DomainError::Json(error.to_string()))?;
                marker.validate()
            }
            Self::EvidenceRecordedV3(evidence) => evidence
                .canonical_bytes()
                .map(|_| ())
                .map_err(m4_domain_error),
            Self::EvidenceBoundV3(binding) => binding
                .canonical_bytes()
                .map(|_| ())
                .map_err(m4_domain_error),
            Self::VerificationRecordedV3(verification) => verification
                .canonical_bytes()
                .map(|_| ())
                .map_err(m4_domain_error),
            Self::DecisionRecordedV3(decision) => decision
                .canonical_bytes()
                .map(|_| ())
                .map_err(m4_domain_error),
            Self::FindingRecordedV3(finding) => finding
                .canonical_bytes()
                .map(|_| ())
                .map_err(m4_domain_error),
            Self::SnapshotSourcesRecorded(sources) => sources.validate_shape(),
            Self::ReviewPlanRecorded(plan) => {
                let _ = plan.canonical_bytes()?;
                Ok(())
            }
            Self::ContextEnvelopeProjected(envelope) => envelope
                .canonical_bytes()
                .map(|_| ())
                .map_err(context_domain_error),
            Self::ReviewExecutionRecorded(recorded) => recorded.validate_shape(),
        }
    }

    fn validate_for_enclosing_run(&self, run_id: &StableId) -> Result<()> {
        match self {
            Self::ArtifactRegistered(registration) if registration.run_id() != run_id => {
                Err(DomainError::Validation(
                    "artifact registration must bind the enclosing event run".to_owned(),
                ))
            }
            Self::RunGenesisManifest(manifest)
                if manifest.run_id() != run_id
                    || manifest.genesis_artifact().run_id() != run_id =>
            {
                Err(DomainError::Validation(
                    "genesis manifest and nested artifact must bind the enclosing event run"
                        .to_owned(),
                ))
            }
            Self::ArtifactRegisteredV3(registration) if registration.run_id() != run_id => {
                Err(DomainError::Validation(
                    "v3 artifact registration must bind the enclosing event run".to_owned(),
                ))
            }
            Self::RunGenesisManifestV3(manifest)
                if manifest.run_id() != run_id
                    || manifest.genesis_artifact().run_id() != run_id =>
            {
                Err(DomainError::Validation(
                    "v3 genesis manifest and nested artifact must bind the enclosing event run"
                        .to_owned(),
                ))
            }
            Self::ArtifactRegisteredV4(registration) if registration.run_id() != run_id => {
                Err(DomainError::Validation(
                    "v4 artifact registration must bind the enclosing event run".to_owned(),
                ))
            }
            Self::ArtifactRegisteredV5(registration) if registration.run_id() != run_id => {
                Err(DomainError::Validation(
                    "V5 preservation registration must bind the enclosing run".to_owned(),
                ))
            }
            Self::GluingBundleRecordedV4(_) => Ok(()),
            Self::RunGenesisManifestV4(manifest)
                if &manifest.run_id != run_id || manifest.genesis_artifact().run_id() != run_id =>
            {
                Err(DomainError::Validation(
                    "v4 genesis manifest and nested artifact must bind the enclosing run"
                        .to_owned(),
                ))
            }
            _ => Ok(()),
        }
    }
}

fn m4_domain_error(error: crate::M4Error) -> DomainError {
    match error {
        crate::M4Error::Incomplete {
            operation,
            limit,
            observed,
        } => DomainError::Incomplete {
            operation,
            limit,
            observed,
        },
        crate::M4Error::IdCollision { id } => DomainError::IdCollision { id },
        other => DomainError::Validation(other.to_string()),
    }
}

#[derive(Clone, Copy)]
enum JsonFrame {
    Array(JsonArrayState),
    Object(JsonObjectState),
}

#[derive(Clone, Copy, Eq, PartialEq)]
enum JsonArrayState {
    ValueOrEnd,
    CommaOrEnd,
}

#[derive(Clone, Copy, Eq, PartialEq)]
enum JsonObjectState {
    KeyOrEnd,
    Colon,
    Value,
    CommaOrEnd,
}

/// Performs the fixed structural admission required for every persisted event
/// JSON document. The scanner intentionally does not allocate or decide
/// duplicate-key semantics; serde and the closed typed DTOs retain those
/// responsibilities after this resource check succeeds.
pub(crate) fn preflight_event_json_structure(input: &[u8]) -> Result<()> {
    preflight_json_structure(
        input,
        "index event JSON structure",
        MAX_EVENT_JSON_DEPTH,
        MAX_EVENT_JSON_VALUES,
    )
}

pub fn preflight_index_genesis_json_structure(input: &[u8]) -> Result<()> {
    preflight_json_structure(
        input,
        "index genesis JSON structure",
        MAX_GENESIS_JSON_DEPTH,
        MAX_GENESIS_JSON_VALUES,
    )
}

fn preflight_genesis_json_structure(input: &[u8]) -> Result<()> {
    preflight_index_genesis_json_structure(input)
}

fn preflight_v3_genesis(input: &[u8]) -> Result<()> {
    preflight_genesis_json_structure(input)?;
    let raw = u64::try_from(input.len()).unwrap_or(u64::MAX);
    let observed = raw
        .checked_mul(V3_GENESIS_WORKING_COPIES)
        .ok_or_else(|| v3_memory_error("event-v3 genesis working bytes", u64::MAX))?;
    if observed > crate::m4::MAX_RETAINED_WORKING_BYTES {
        return Err(v3_memory_error("event-v3 genesis working bytes", observed));
    }
    Ok(())
}

fn preflight_v3_initial(initial: &ReviewAggregate) -> Result<u64> {
    let retained = initial.retained_bytes_v3()?;
    // Each term names one concurrently owned capacity at the construction
    // seam. Keeping them separate prevents an unexplained multiplier from
    // hiding a newly added owner.
    let validation_scratch = retained;
    let typed_snapshot = retained;
    let pristine_rebuild = retained;
    let retained_initial_clone = retained;
    let retained_current_clone = retained;
    let initial_peak = ensure_v3_working_peak(
        retained,
        [
            validation_scratch,
            typed_snapshot,
            pristine_rebuild,
            retained_initial_clone,
            retained_current_clone,
        ],
    )?;
    record_v3_test_selected_peak(initial_peak);
    let count = crate::canonical::canonical_json_count_bounded(
        &BorrowedRunGenesisSnapshot(initial),
        crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
        "event-v3 genesis canonical count",
    )?;
    let canonical_peak = ensure_v3_working_peak(
        retained,
        [
            validation_scratch,
            typed_snapshot,
            pristine_rebuild,
            retained_initial_clone,
            retained_current_clone,
            count,
            count,
        ],
    )?;
    record_v3_test_selected_peak(canonical_peak);
    Ok(count)
}

/// Counts every object member and array element without constructing a JSON
/// value tree. The fixed 128-entry stack is sufficient for both contracts, so
/// successful scans retain no owned allocation.
fn preflight_json_structure(
    input: &[u8],
    operation: &'static str,
    max_depth: usize,
    max_values: usize,
) -> Result<()> {
    let mut stack = [JsonFrame::Array(JsonArrayState::ValueOrEnd); MAX_EVENT_JSON_DEPTH];
    let mut stack_len = 0_usize;
    let mut values = 0_usize;
    let mut root_started = false;
    let mut root_complete = false;
    let mut index = 0_usize;

    while index < input.len() {
        if input[index].is_ascii_whitespace() {
            index += 1;
            continue;
        }
        if root_complete {
            return invalid_json_structure();
        }

        match input[index] {
            b'{' | b'[' => {
                accept_json_value(
                    &mut stack,
                    stack_len,
                    &mut values,
                    &mut root_started,
                    operation,
                    max_values,
                )?;
                let next_depth = stack_len.saturating_add(1);
                if next_depth > max_depth {
                    return Err(DomainError::Incomplete {
                        operation,
                        limit: max_depth,
                        observed: next_depth,
                    });
                }
                stack[stack_len] = if input[index] == b'{' {
                    JsonFrame::Object(JsonObjectState::KeyOrEnd)
                } else {
                    JsonFrame::Array(JsonArrayState::ValueOrEnd)
                };
                stack_len = next_depth;
                index += 1;
            }
            b'}' => {
                let Some(JsonFrame::Object(state)) =
                    stack_len.checked_sub(1).map(|position| stack[position])
                else {
                    return invalid_json_structure();
                };
                if !matches!(
                    state,
                    JsonObjectState::KeyOrEnd | JsonObjectState::CommaOrEnd
                ) {
                    return invalid_json_structure();
                }
                stack_len -= 1;
                if stack_len == 0 {
                    root_complete = true;
                }
                index += 1;
            }
            b']' => {
                let Some(JsonFrame::Array(state)) =
                    stack_len.checked_sub(1).map(|position| stack[position])
                else {
                    return invalid_json_structure();
                };
                if !matches!(
                    state,
                    JsonArrayState::ValueOrEnd | JsonArrayState::CommaOrEnd
                ) {
                    return invalid_json_structure();
                }
                stack_len -= 1;
                if stack_len == 0 {
                    root_complete = true;
                }
                index += 1;
            }
            b',' => {
                let Some(frame) = stack_len
                    .checked_sub(1)
                    .map(|position| &mut stack[position])
                else {
                    return invalid_json_structure();
                };
                match frame {
                    JsonFrame::Array(state) if *state == JsonArrayState::CommaOrEnd => {
                        *state = JsonArrayState::ValueOrEnd;
                    }
                    JsonFrame::Object(state) if *state == JsonObjectState::CommaOrEnd => {
                        *state = JsonObjectState::KeyOrEnd;
                    }
                    _ => return invalid_json_structure(),
                }
                index += 1;
            }
            b':' => {
                let Some(JsonFrame::Object(state)) = stack_len
                    .checked_sub(1)
                    .map(|position| &mut stack[position])
                else {
                    return invalid_json_structure();
                };
                if *state != JsonObjectState::Colon {
                    return invalid_json_structure();
                }
                *state = JsonObjectState::Value;
                index += 1;
            }
            b'"' => {
                let string_end = scan_json_string(input, index)?;
                let is_object_key = matches!(
                    stack_len.checked_sub(1).map(|position| &stack[position]),
                    Some(JsonFrame::Object(JsonObjectState::KeyOrEnd))
                );
                if is_object_key {
                    if let JsonFrame::Object(state) = &mut stack[stack_len - 1] {
                        *state = JsonObjectState::Colon;
                    }
                } else {
                    accept_json_value(
                        &mut stack,
                        stack_len,
                        &mut values,
                        &mut root_started,
                        operation,
                        max_values,
                    )?;
                    if stack_len == 0 {
                        root_complete = true;
                    }
                }
                index = string_end;
            }
            _ => {
                let value_end = scan_json_primitive(input, index)?;
                accept_json_value(
                    &mut stack,
                    stack_len,
                    &mut values,
                    &mut root_started,
                    operation,
                    max_values,
                )?;
                if stack_len == 0 {
                    root_complete = true;
                }
                index = value_end;
            }
        }
    }

    if !root_started || !root_complete || stack_len != 0 {
        return invalid_json_structure();
    }
    Ok(())
}

fn accept_json_value(
    stack: &mut [JsonFrame; MAX_EVENT_JSON_DEPTH],
    stack_len: usize,
    values: &mut usize,
    root_started: &mut bool,
    operation: &'static str,
    max_values: usize,
) -> Result<()> {
    if stack_len == 0 {
        if *root_started {
            return invalid_json_structure();
        }
        *root_started = true;
        return Ok(());
    }
    match &mut stack[stack_len - 1] {
        JsonFrame::Array(state) if *state == JsonArrayState::ValueOrEnd => {
            *state = JsonArrayState::CommaOrEnd;
        }
        JsonFrame::Object(state) if *state == JsonObjectState::Value => {
            *state = JsonObjectState::CommaOrEnd;
        }
        _ => return invalid_json_structure(),
    }
    *values = values.saturating_add(1);
    if *values > max_values {
        return Err(DomainError::Incomplete {
            operation,
            limit: max_values,
            observed: *values,
        });
    }
    Ok(())
}

fn scan_json_string(input: &[u8], mut index: usize) -> Result<usize> {
    debug_assert_eq!(input[index], b'"');
    index += 1;
    while index < input.len() {
        match input[index] {
            b'"' => return Ok(index + 1),
            b'\\' => {
                index = index.saturating_add(2);
            }
            _ => index += 1,
        }
    }
    invalid_json_structure()
}

fn scan_json_primitive(input: &[u8], mut index: usize) -> Result<usize> {
    let start = index;
    while index < input.len()
        && !input[index].is_ascii_whitespace()
        && !matches!(input[index], b',' | b']' | b'}' | b':' | b'{' | b'[' | b'"')
    {
        index += 1;
    }
    if index == start {
        return invalid_json_structure();
    }
    Ok(index)
}

fn skip_json_whitespace(input: &[u8], mut index: usize) -> usize {
    while input.get(index).is_some_and(u8::is_ascii_whitespace) {
        index += 1;
    }
    index
}

fn skip_json_value_lexically(input: &[u8], index: usize) -> Result<usize> {
    let Some(first) = input.get(index).copied() else {
        return invalid_json_structure();
    };
    if first == b'"' {
        return scan_json_string(input, index);
    }
    if !matches!(first, b'{' | b'[') {
        return scan_json_primitive(input, index);
    }
    let mut cursor = index;
    let mut depth = 0_usize;
    while cursor < input.len() {
        match input[cursor] {
            b'"' => cursor = scan_json_string(input, cursor)?,
            b'{' | b'[' => {
                depth = depth.checked_add(1).ok_or(DomainError::Incomplete {
                    operation: "event schema lexical depth",
                    limit: usize::MAX,
                    observed: usize::MAX,
                })?;
                cursor += 1;
            }
            b'}' | b']' => {
                depth = depth
                    .checked_sub(1)
                    .ok_or_else(|| DomainError::Json("invalid JSON structure".to_owned()))?;
                cursor += 1;
                if depth == 0 {
                    return Ok(cursor);
                }
            }
            _ => cursor += 1,
        }
    }
    invalid_json_structure()
}

/// Finds exact top-level schema discriminators without allocating the payload.
/// Escaped JSON spellings are decoded, while prose and nested literals do not
/// influence which ingress limits apply.
fn top_level_schema_mentions_v3(input: &[u8]) -> Result<bool> {
    top_level_schema_mentions(input, EventContractVersion::V3)
}

fn top_level_schema_mentions_v4(input: &[u8]) -> Result<bool> {
    top_level_schema_mentions(input, EventContractVersion::V4)
}

fn top_level_schema_mentions_v5(input: &[u8]) -> Result<bool> {
    top_level_schema_mentions(input, EventContractVersion::V5)
}

fn top_level_schema_mentions(input: &[u8], target: EventContractVersion) -> Result<bool> {
    let mut cursor = skip_json_whitespace(input, 0);
    if input.get(cursor) != Some(&b'{') {
        return Ok(false);
    }
    cursor += 1;
    let mut found_v3 = false;
    loop {
        cursor = skip_json_whitespace(input, cursor);
        if input.get(cursor) == Some(&b'}') {
            return Ok(found_v3);
        }
        if input.get(cursor) != Some(&b'"') {
            return Ok(found_v3);
        }
        let key_end = scan_json_string(input, cursor)?;
        let key_is_schema = key_end.saturating_sub(cursor) <= 64
            && serde_json::from_slice::<String>(&input[cursor..key_end])
                .is_ok_and(|key| key == "schema");
        cursor = skip_json_whitespace(input, key_end);
        if input.get(cursor) != Some(&b':') {
            return Ok(found_v3);
        }
        cursor = skip_json_whitespace(input, cursor + 1);
        if key_is_schema && input.get(cursor) == Some(&b'"') {
            let value_end = scan_json_string(input, cursor)?;
            if value_end.saturating_sub(cursor) <= 256
                && serde_json::from_slice::<String>(&input[cursor..value_end])
                    .is_ok_and(|schema| schema == target.schema())
            {
                found_v3 = true;
            }
            cursor = value_end;
        } else {
            cursor = skip_json_value_lexically(input, cursor)?;
        }
        cursor = skip_json_whitespace(input, cursor);
        match input.get(cursor) {
            Some(b',') => cursor += 1,
            Some(b'}') => return Ok(found_v3),
            _ => return Ok(found_v3),
        }
    }
}

fn invalid_json_structure<T>() -> Result<T> {
    Err(DomainError::Json("invalid JSON structure".to_owned()))
}

struct BoundedEventJson {
    bytes: Vec<u8>,
    max: usize,
    overflow: Option<usize>,
}

impl BoundedEventJson {
    fn new(max: usize) -> Self {
        Self {
            bytes: Vec::new(),
            max,
            overflow: None,
        }
    }

    fn new_reserved(max: usize, capacity: usize) -> Result<Self> {
        let mut bytes = Vec::new();
        bytes
            .try_reserve_exact(capacity)
            .map_err(|_| DomainError::Incomplete {
                operation: "index canonical event destination",
                limit: capacity,
                observed: capacity,
            })?;
        Ok(Self {
            bytes,
            max,
            overflow: None,
        })
    }

    fn push(&mut self, bytes: &[u8]) -> Result<()> {
        self.write_all(bytes).map_err(|error| {
            if let Some(observed) = self.overflow {
                DomainError::Incomplete {
                    operation: "D1 canonical event JSONL",
                    limit: MAX_D1_EVENT_LINE_BYTES,
                    observed: observed.saturating_add(1),
                }
            } else {
                DomainError::CanonicalJson(error.to_string())
            }
        })
    }

    fn string(&mut self, value: &str) -> Result<()> {
        serde_json::to_writer(&mut *self, value).map_err(|error| {
            if let Some(observed) = self.overflow {
                DomainError::Incomplete {
                    operation: "D1 canonical event JSONL",
                    limit: MAX_D1_EVENT_LINE_BYTES,
                    observed: observed.saturating_add(1),
                }
            } else {
                DomainError::CanonicalJson(error.to_string())
            }
        })
    }

    fn number(&mut self, value: u64) -> Result<()> {
        write!(self, "{value}").map_err(|error| DomainError::CanonicalJson(error.to_string()))
    }

    fn finish(self) -> Result<Vec<u8>> {
        if let Some(observed) = self.overflow {
            return Err(DomainError::Incomplete {
                operation: "D1 canonical event JSONL",
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed: observed.saturating_add(1),
            });
        }
        Ok(self.bytes)
    }
}

impl std::io::Write for BoundedEventJson {
    fn write(&mut self, bytes: &[u8]) -> std::io::Result<usize> {
        let observed = self.bytes.len().saturating_add(bytes.len());
        if observed > self.max {
            self.overflow = Some(observed);
            return Err(std::io::Error::other(
                "bounded event JSON exceeded its limit",
            ));
        }
        self.bytes.extend_from_slice(bytes);
        Ok(bytes.len())
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn d1_payload_bytes(kind: &str, data: &[u8]) -> Result<Vec<u8>> {
    let mut out = BoundedEventJson::new(MAX_D1_EVENT_LINE_BYTES - 1);
    out.push(b"{\"data\":")?;
    out.push(data)?;
    out.push(b",\"type\":")?;
    out.string(kind)?;
    out.push(b"}")?;
    out.finish()
}

fn payload_canonical_bytes(payload: &PersistedPayload) -> Result<Vec<u8>> {
    match payload {
        PersistedPayload::ReviewPlanRecorded(plan) => {
            d1_payload_bytes("review_plan_recorded", &plan.canonical_bytes()?)
        }
        PersistedPayload::ContextEnvelopeProjected(envelope) => d1_payload_bytes(
            "context_envelope_projected",
            &envelope.canonical_bytes().map_err(context_domain_error)?,
        ),
        PersistedPayload::ReviewExecutionRecorded(recorded) => {
            d1_payload_bytes("review_execution_recorded", &recorded.canonical_bytes()?)
        }
        _ => canonical_json(payload),
    }
}

fn raw_payload(bytes: Vec<u8>) -> Result<Box<RawValue>> {
    let text =
        String::from_utf8(bytes).map_err(|error| DomainError::CanonicalJson(error.to_string()))?;
    RawValue::from_string(text).map_err(|error| DomainError::Json(error.to_string()))
}

fn validate_stream_payload_position(
    version: EventContractVersion,
    sequence: u64,
    payload: &PersistedPayload,
) -> Result<()> {
    match version {
        EventContractVersion::V2
            if (sequence == 1) != matches!(payload, PersistedPayload::RunGenesisManifest(_)) =>
        {
            return Err(DomainError::EventSequence(
                "v2 streams require RunGenesisManifest exactly at sequence one".to_owned(),
            ));
        }
        EventContractVersion::V3
            if (sequence == 1) != matches!(payload, PersistedPayload::RunGenesisManifestV3(_)) =>
        {
            return Err(DomainError::EventSequence(
                "v3 streams require RunGenesisManifestV3 exactly at sequence one".to_owned(),
            ));
        }
        EventContractVersion::V4
            if (sequence == 1) != matches!(payload, PersistedPayload::RunGenesisManifestV4(_)) =>
        {
            return Err(DomainError::EventSequence(
                "v4 streams require RunGenesisManifestV4 exactly at sequence one".to_owned(),
            ));
        }
        EventContractVersion::V5
            if (sequence == 1) != matches!(payload, PersistedPayload::RunGenesisManifestV4(_)) =>
        {
            return Err(DomainError::EventSequence(
                "v5 streams require the frozen RunGenesisManifestV4 exactly at sequence one"
                    .to_owned(),
            ));
        }
        _ => {}
    }
    Ok(())
}

fn reject_v2_legacy_execution_payload(
    version: EventContractVersion,
    payload: &PersistedPayload,
) -> Result<()> {
    if matches!(
        version,
        EventContractVersion::V2
            | EventContractVersion::V3
            | EventContractVersion::V4
            | EventContractVersion::V5
    ) && matches!(payload, PersistedPayload::ClaimProposed(_))
    {
        return Err(DomainError::Validation(
            "v2/v3 requires the Unit D atomic execution record before claims or completed obligations"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_v2_completed_transition(
    version: EventContractVersion,
    aggregate: &ReviewAggregate,
    payload: &PersistedPayload,
) -> Result<()> {
    validate_v2_completed_transition_with_shadow(version, aggregate, &BTreeSet::new(), payload)
}

/// Offline projection preserves D2 executions as unreconciled shadows, so a
/// subsequent lifecycle event needs the already shape-validated structured
/// scope without treating the execution as accepted state.
fn validate_v2_completed_transition_with_shadow(
    version: EventContractVersion,
    aggregate: &ReviewAggregate,
    shadow_structured_execution_obligations: &BTreeSet<StableId>,
    payload: &PersistedPayload,
) -> Result<()> {
    if matches!(
        version,
        EventContractVersion::V2
            | EventContractVersion::V3
            | EventContractVersion::V4
            | EventContractVersion::V5
    ) && let PersistedPayload::ObligationTransition {
        obligation_id,
        next: ObligationLifecycle::Completed,
    } = payload
        && !aggregate.has_structured_execution(obligation_id)
        && !shadow_structured_execution_obligations.contains(obligation_id)
    {
        return Err(DomainError::Validation(
            "v2 completed lifecycle requires an earlier structured D2 execution".to_owned(),
        ));
    }
    Ok(())
}

fn reject_duplicate_d1_record(
    aggregate: &ReviewAggregate,
    payload: &PersistedPayload,
) -> Result<()> {
    let duplicate = match payload {
        PersistedPayload::ReviewPlanRecorded(plan) => aggregate.review_plan(plan.id()).is_some(),
        PersistedPayload::ContextEnvelopeProjected(context) => {
            aggregate.context_envelope(context.id()).is_some()
        }
        _ => false,
    };
    if duplicate {
        let id = match payload {
            PersistedPayload::ReviewPlanRecorded(plan) => plan.id().clone(),
            PersistedPayload::ContextEnvelopeProjected(context) => context.id().clone(),
            _ => unreachable!("duplicate is true only for D1 records"),
        };
        return Err(DomainError::IdCollision { id });
    }
    Ok(())
}

/// A validated event envelope binding a closed persisted payload to one logical
/// run and to the canonical genesis aggregate of that run.
#[derive(Clone, Debug, Serialize)]
pub struct EventEnvelope {
    schema: String,
    id: StableId,
    run_id: StableId,
    genesis_hash: ContentHash,
    sequence: u64,
    actor: String,
    logical_time: u64,
    payload: Box<RawValue>,
    payload_hash: ContentHash,
    previous_event_hash: ContentHash,
    event_hash: ContentHash,
    #[serde(skip)]
    canonical_line_bytes_v4: Option<u64>,
    #[serde(skip)]
    canonical_line_bytes_v5: Option<u64>,
}

impl EventEnvelope {
    fn from_raw(raw: RawEventEnvelope) -> Result<Self> {
        Self::from_raw_at_v5_position(raw, V5SealedPayloadPosition::General)
    }

    fn from_raw_at_v5_position(
        raw: RawEventEnvelope,
        position: V5SealedPayloadPosition,
    ) -> Result<Self> {
        let mut envelope = Self {
            schema: raw.schema,
            id: raw.id,
            run_id: raw.run_id,
            genesis_hash: raw.genesis_hash,
            sequence: raw.sequence,
            actor: raw.actor,
            logical_time: raw.logical_time,
            payload: raw.payload,
            payload_hash: raw.payload_hash,
            previous_event_hash: raw.previous_event_hash,
            event_hash: raw.event_hash,
            canonical_line_bytes_v4: None,
            canonical_line_bytes_v5: None,
        };
        envelope.validate_at_v5_position(position)?;
        envelope.set_canonical_line_bytes_v4()?;
        match position {
            V5SealedPayloadPosition::General => envelope.set_canonical_line_bytes_v5()?,
            V5SealedPayloadPosition::ScheduledM6Execution => {
                envelope.set_canonical_line_bytes_v5_scheduled_execution()?;
            }
            V5SealedPayloadPosition::GluingRerun => envelope.set_canonical_line_bytes_v5()?,
        }
        Ok(envelope)
    }

    /// Heap capacity retained by this decoded envelope, excluding the inline
    /// `EventEnvelope` value charged by its owning vector.
    #[must_use]
    pub fn allocated_bytes(&self) -> usize {
        self.schema.capacity()
            + self.id.allocated_bytes()
            + self.run_id.allocated_bytes()
            + self.genesis_hash.allocated_bytes()
            + self.actor.capacity()
            + self.payload.get().len()
            + self.payload_hash.allocated_bytes()
            + self.previous_event_hash.allocated_bytes()
            + self.event_hash.allocated_bytes()
    }

    /// Declared closed event-contract version after envelope validation.
    pub fn contract_version(&self) -> Result<EventContractVersion> {
        EventContractVersion::parse(&self.schema)
    }

    // Each field is independently hash-bound. Grouping them would obscure
    // the selected schema input at call sites and risks a mismatched tuple.
    #[allow(clippy::too_many_arguments)]
    fn new(
        version: EventContractVersion,
        run_id: StableId,
        genesis_hash: ContentHash,
        sequence: u64,
        actor: impl Into<String>,
        logical_time: u64,
        previous_event_hash: ContentHash,
        payload: PersistedPayload,
    ) -> Result<Self> {
        Self::new_at_v5_position(
            version,
            run_id,
            genesis_hash,
            sequence,
            actor,
            logical_time,
            previous_event_hash,
            payload,
            V5SealedPayloadPosition::General,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn new_at_v5_position(
        version: EventContractVersion,
        run_id: StableId,
        genesis_hash: ContentHash,
        sequence: u64,
        actor: impl Into<String>,
        logical_time: u64,
        previous_event_hash: ContentHash,
        payload: PersistedPayload,
        position: V5SealedPayloadPosition,
    ) -> Result<Self> {
        match position {
            V5SealedPayloadPosition::General => payload.validate_shape()?,
            V5SealedPayloadPosition::ScheduledM6Execution => match &payload {
                PersistedPayload::ReviewExecutionRecorded(recorded) => {
                    recorded.validate_shape_for_m6()?;
                }
                _ => {
                    return Err(DomainError::EventSequence(
                        "scheduled M6 execution position requires execution payload".to_owned(),
                    ));
                }
            },
            V5SealedPayloadPosition::GluingRerun => match &payload {
                PersistedPayload::GluingRerunActionRecordedV5(_)
                | PersistedPayload::GluingRerunPlanSealedV5(_) => payload.validate_shape()?,
                _ => {
                    return Err(DomainError::EventSequence(
                        "gluing rerun position requires a post-D2 gluing payload".to_owned(),
                    ));
                }
            },
        }
        let actor = actor.into();
        let payload_bytes = payload_canonical_bytes(&payload)?;
        let payload_hash = ContentHash::sha256(&payload_bytes);
        let payload = raw_payload(payload_bytes)?;
        let id = event_id(
            version.schema(),
            &run_id,
            &genesis_hash,
            sequence,
            &actor,
            logical_time,
            &payload_hash,
            &previous_event_hash,
        )?;
        let event_hash = envelope_hash(EventHashInput {
            schema: version.schema(),
            id: &id,
            run_id: &run_id,
            genesis_hash: &genesis_hash,
            sequence,
            actor: &actor,
            logical_time,
            payload_hash: &payload_hash,
            previous_event_hash: &previous_event_hash,
        })?;
        let mut envelope = Self {
            schema: version.schema().to_owned(),
            id,
            run_id,
            genesis_hash,
            sequence,
            actor,
            logical_time,
            payload,
            payload_hash,
            previous_event_hash,
            event_hash,
            canonical_line_bytes_v4: None,
            canonical_line_bytes_v5: None,
        };
        envelope.validate_at_v5_position(position)?;
        envelope.set_canonical_line_bytes_v4()?;
        match position {
            V5SealedPayloadPosition::General => envelope.set_canonical_line_bytes_v5()?,
            V5SealedPayloadPosition::ScheduledM6Execution => {
                envelope.set_canonical_line_bytes_v5_scheduled_execution()?;
            }
            V5SealedPayloadPosition::GluingRerun => envelope.set_canonical_line_bytes_v5()?,
        }
        if position == V5SealedPayloadPosition::General && envelope.payload_is_d1()? {
            let _ = envelope.canonical_bytes()?;
        }
        Ok(envelope)
    }

    fn set_canonical_line_bytes_v4(&mut self) -> Result<()> {
        if self.contract_version()? != EventContractVersion::V4 {
            return Ok(());
        }
        let body_bytes = crate::canonical::canonical_json_count_bounded(
            self,
            MAX_D1_EVENT_LINE_BYTES - 1,
            "event-v4 canonical line body",
        )?;
        let line_bytes = body_bytes.checked_add(1).ok_or(DomainError::Incomplete {
            operation: "event-v4 canonical line bytes",
            limit: MAX_D1_EVENT_LINE_BYTES,
            observed: usize::MAX,
        })?;
        if line_bytes > u64::try_from(MAX_D1_EVENT_LINE_BYTES).unwrap_or(u64::MAX) {
            return Err(DomainError::Incomplete {
                operation: "event-v4 canonical line bytes",
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed: usize::try_from(line_bytes).unwrap_or(usize::MAX),
            });
        }
        self.canonical_line_bytes_v4 = Some(line_bytes);
        Ok(())
    }

    fn set_canonical_line_bytes_v5(&mut self) -> Result<()> {
        if self.contract_version()? != EventContractVersion::V5 {
            return Ok(());
        }
        let body_bytes = crate::canonical::canonical_json_count_bounded(
            self,
            MAX_D1_EVENT_LINE_BYTES - 1,
            "event-v5 canonical line body",
        )?;
        let line_bytes = body_bytes.checked_add(1).ok_or(DomainError::Incomplete {
            operation: "event-v5 canonical line bytes",
            limit: MAX_D1_EVENT_LINE_BYTES,
            observed: usize::MAX,
        })?;
        if line_bytes > u64::try_from(MAX_D1_EVENT_LINE_BYTES).unwrap_or(u64::MAX) {
            return Err(DomainError::Incomplete {
                operation: "event-v5 canonical line bytes",
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed: usize::try_from(line_bytes).unwrap_or(usize::MAX),
            });
        }
        self.canonical_line_bytes_v5 = Some(line_bytes);
        Ok(())
    }

    fn set_canonical_line_bytes_v5_scheduled_execution(&mut self) -> Result<()> {
        if self.contract_version()? != EventContractVersion::V5 {
            return Err(DomainError::EventSequence(
                "scheduled M6 execution line requires V5 envelope".to_owned(),
            ));
        }
        #[derive(Serialize)]
        struct Wire<'a> {
            actor: &'a str,
            event_hash: &'a ContentHash,
            genesis_hash: &'a ContentHash,
            id: &'a StableId,
            logical_time: u64,
            payload: &'a RawValue,
            payload_hash: &'a ContentHash,
            previous_event_hash: &'a ContentHash,
            run_id: &'a StableId,
            schema: &'a str,
            sequence: u64,
        }
        let line_bytes = crate::canonical::canonical_json_count_bounded(
            &Wire {
                actor: &self.actor,
                event_hash: &self.event_hash,
                genesis_hash: &self.genesis_hash,
                id: &self.id,
                logical_time: self.logical_time,
                payload: &self.payload,
                payload_hash: &self.payload_hash,
                previous_event_hash: &self.previous_event_hash,
                run_id: &self.run_id,
                schema: &self.schema,
                sequence: self.sequence,
            },
            MAX_D1_EVENT_LINE_BYTES - 1,
            "scheduled M6 canonical event line body",
        )?
        .checked_add(1)
        .ok_or(DomainError::Incomplete {
            operation: "scheduled M6 canonical event line bytes",
            limit: MAX_D1_EVENT_LINE_BYTES,
            observed: usize::MAX,
        })?;
        self.canonical_line_bytes_v5 = Some(line_bytes);
        Ok(())
    }

    #[cfg(test)]
    pub(crate) fn next_context_duplicate_for_test(
        &self,
        context: ReviewContextEnvelope,
    ) -> Result<Self> {
        let sequence = self.sequence.checked_add(1).ok_or_else(|| {
            DomainError::EventSequence("event sequence overflow in test fixture".to_owned())
        })?;
        Self::new(
            EventContractVersion::parse(&self.schema)?,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            sequence,
            SYSTEM_ACTOR,
            sequence,
            self.event_hash.clone(),
            PersistedPayload::ContextEnvelopeProjected(context),
        )
    }

    /// Imports and structurally validates one JSON envelope. Applying it still
    /// requires replay with its matching run-bound decision admissions.
    pub fn from_json_slice(input: &[u8]) -> Result<Self> {
        Self::from_json_slice_with_d2_working_limit(input, MAX_D2_WORKING_BYTES)
    }

    fn from_json_slice_with_d2_working_limit(input: &[u8], working_limit: usize) -> Result<Self> {
        let is_d2 = input
            .windows(b"review_execution_recorded".len())
            .any(|window| window == b"review_execution_recorded");
        let is_v3 = top_level_schema_mentions_v3(input)?;
        let is_v4 = top_level_schema_mentions_v4(input)?;
        let is_v5 = top_level_schema_mentions_v5(input)?;
        if is_d2 || is_v3 || is_v4 || is_v5 {
            let operation = if is_d2 {
                "D2 canonical event JSONL"
            } else if is_v3 {
                "event-v3 canonical JSONL"
            } else if is_v5 {
                "event-v5 canonical JSONL"
            } else {
                "event-v4 canonical JSONL"
            };
            let line_bytes = input.len().checked_add(1).ok_or(DomainError::Incomplete {
                operation,
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed: usize::MAX,
            })?;
            if line_bytes > MAX_D1_EVENT_LINE_BYTES {
                return Err(DomainError::Incomplete {
                    operation,
                    limit: MAX_D1_EVENT_LINE_BYTES,
                    observed: line_bytes,
                });
            }
            preflight_event_json_structure(input)?;
        }
        if is_d2 {
            preflight_d2_decode_working(input, working_limit)?;
        }
        let raw: RawEventEnvelope =
            serde_json::from_slice(input).map_err(|error| DomainError::Json(error.to_string()))?;
        Self::from_raw(raw)
    }

    fn from_json_slice_at_v5_position(
        input: &[u8],
        position: V5SealedPayloadPosition,
    ) -> Result<Self> {
        if input.len().saturating_add(1) > MAX_D1_EVENT_LINE_BYTES {
            return Err(DomainError::Incomplete {
                operation: "scheduled M6 canonical event JSONL",
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed: input.len().saturating_add(1),
            });
        }
        preflight_event_json_structure(input)?;
        preflight_d2_decode_working(input, MAX_D2_WORKING_BYTES)?;
        let raw: RawEventEnvelope =
            serde_json::from_slice(input).map_err(|error| DomainError::Json(error.to_string()))?;
        Self::from_raw_at_v5_position(raw, position)
    }

    /// Index-only bounded import seam. The structural cap is operational and
    /// does not change which historical envelopes are canonical.
    pub fn from_json_slice_for_index(input: &[u8]) -> Result<Self> {
        preflight_event_json_structure(input)?;
        Self::from_json_slice(input)
    }

    /// Validates deterministic envelope bindings and every nested untrusted
    /// DTO before the record can enter a replay stream.
    pub fn validate(&self) -> Result<()> {
        self.validate_at_v5_position(V5SealedPayloadPosition::General)
    }

    fn validate_at_v5_position(&self, position: V5SealedPayloadPosition) -> Result<()> {
        let version = EventContractVersion::parse(&self.schema)?;
        if self.run_id.kind() != "run" || self.sequence == 0 || self.logical_time != self.sequence {
            return Err(DomainError::EventSequence(
                "event requires a run ID, one-based sequence, and matching logical time".to_owned(),
            ));
        }
        if self.actor.is_empty() {
            return Err(DomainError::EventSequence(
                "event actor must be non-empty".to_owned(),
            ));
        }
        let payload = match position {
            V5SealedPayloadPosition::General => {
                decode_canonical_payload(version, self.payload.get())?
            }
            V5SealedPayloadPosition::ScheduledM6Execution
                if version == EventContractVersion::V5 =>
            {
                decode_canonical_scheduled_m6_execution_payload(self.payload.get())?
            }
            V5SealedPayloadPosition::ScheduledM6Execution => {
                return Err(DomainError::EventSequence(
                    "scheduled M6 execution position requires V5 envelope".to_owned(),
                ));
            }
            V5SealedPayloadPosition::GluingRerun => {
                let payload = decode_canonical_payload(version, self.payload.get())?;
                if !matches!(
                    payload,
                    PersistedPayload::GluingRerunActionRecordedV5(_)
                        | PersistedPayload::GluingRerunPlanSealedV5(_)
                ) {
                    return Err(DomainError::EventSequence(
                        "gluing rerun position requires a post-D2 gluing payload".to_owned(),
                    ));
                }
                payload
            }
        };
        if !payload.allowed_in(version) {
            return Err(DomainError::EventSequence(
                "event stream payload is not admitted by its envelope contract".to_owned(),
            ));
        }
        validate_stream_payload_position(version, self.sequence, &payload)?;
        if let PersistedPayload::RunGenesisManifest(manifest) = &payload
            && (manifest.run_id != self.run_id
                || manifest.genesis_artifact.cas_hash != self.genesis_hash)
        {
            return Err(DomainError::EventSequence(
                "v2 genesis manifest must bind its envelope run ID and genesis hash".to_owned(),
            ));
        }
        if let PersistedPayload::RunGenesisManifestV3(manifest) = &payload
            && (manifest.run_id() != &self.run_id
                || manifest.genesis_artifact().cas_hash() != &self.genesis_hash)
        {
            return Err(DomainError::EventSequence(
                "v3 genesis manifest must bind its envelope run ID and genesis hash".to_owned(),
            ));
        }
        if let PersistedPayload::RunGenesisManifestV4(manifest) = &payload
            && (manifest.run_id() != &self.run_id
                || manifest.genesis_artifact().cas_hash() != &self.genesis_hash)
        {
            return Err(DomainError::EventSequence(
                "v4 genesis manifest must bind its envelope run ID and genesis hash".to_owned(),
            ));
        }
        if self.actor != payload.actor() {
            return Err(DomainError::EventSequence(
                "event actor must match the typed payload authority".to_owned(),
            ));
        }
        let expected_payload_bytes = payload_canonical_bytes(&payload)?;
        let actual_payload_bytes = self.payload.get().as_bytes();
        if actual_payload_bytes != expected_payload_bytes {
            return Err(DomainError::EventSequence(
                "persisted event payload must equal its canonical closed representation".to_owned(),
            ));
        }
        let expected_hash = ContentHash::sha256(&expected_payload_bytes);
        if self.payload_hash != expected_hash {
            return Err(DomainError::EventSequence(
                "event payload hash does not match payload".to_owned(),
            ));
        }
        let expected_id = event_id(
            version.schema(),
            &self.run_id,
            &self.genesis_hash,
            self.sequence,
            &self.actor,
            self.logical_time,
            &self.payload_hash,
            &self.previous_event_hash,
        )?;
        if self.id != expected_id {
            return Err(DomainError::EventSequence(
                "event ID does not bind its envelope".to_owned(),
            ));
        }
        let expected_event_hash = envelope_hash(EventHashInput {
            schema: version.schema(),
            id: &self.id,
            run_id: &self.run_id,
            genesis_hash: &self.genesis_hash,
            sequence: self.sequence,
            actor: &self.actor,
            logical_time: self.logical_time,
            payload_hash: &self.payload_hash,
            previous_event_hash: &self.previous_event_hash,
        })?;
        if self.event_hash != expected_event_hash {
            return Err(DomainError::EventSequence(
                "event hash does not bind its envelope and predecessor".to_owned(),
            ));
        }
        if position == V5SealedPayloadPosition::General && payload.is_d1_bounded() {
            let _ = self.canonical_bytes()?;
        }
        Ok(())
    }

    fn validate_chain_position_at_v5(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        expected_sequence: u64,
        previous_event_hash: &ContentHash,
        position: V5SealedPayloadPosition,
    ) -> Result<()> {
        self.validate_at_v5_position(position)?;
        if self.contract_version()? != EventContractVersion::V5
            || &self.run_id != run_id
            || &self.genesis_hash != genesis_hash
            || self.sequence != expected_sequence
            || &self.previous_event_hash != previous_event_hash
        {
            return Err(DomainError::EventSequence(
                "scheduled V5 event does not form the expected contiguous prefix".to_owned(),
            ));
        }
        Ok(())
    }

    /// Checks the v3 envelope and hash chain without interpreting its payload.
    /// Authority replay performs the one canonical semantic decode later,
    /// after the common working-set preflight has admitted it.
    fn validate_v3_structure_without_payload_decode(&self) -> Result<()> {
        let version = EventContractVersion::parse(&self.schema)?;
        if version != EventContractVersion::V3
            || self.run_id.kind() != "run"
            || self.sequence == 0
            || self.logical_time != self.sequence
            || self.actor.is_empty()
        {
            return Err(DomainError::EventSequence(
                "invalid structural v3 event envelope".to_owned(),
            ));
        }
        if self.payload_hash != ContentHash::sha256(self.payload.get().as_bytes()) {
            return Err(DomainError::EventSequence(
                "event payload hash does not match raw payload bytes".to_owned(),
            ));
        }
        let expected_id = event_id(
            version.schema(),
            &self.run_id,
            &self.genesis_hash,
            self.sequence,
            &self.actor,
            self.logical_time,
            &self.payload_hash,
            &self.previous_event_hash,
        )?;
        if self.id != expected_id {
            return Err(DomainError::EventSequence(
                "event ID does not bind its envelope".to_owned(),
            ));
        }
        let expected_event_hash = envelope_hash(EventHashInput {
            schema: version.schema(),
            id: &self.id,
            run_id: &self.run_id,
            genesis_hash: &self.genesis_hash,
            sequence: self.sequence,
            actor: &self.actor,
            logical_time: self.logical_time,
            payload_hash: &self.payload_hash,
            previous_event_hash: &self.previous_event_hash,
        })?;
        if self.event_hash != expected_event_hash {
            return Err(DomainError::EventSequence(
                "event hash does not bind its envelope and predecessor".to_owned(),
            ));
        }
        Ok(())
    }

    fn payload_is_d1(&self) -> Result<bool> {
        Ok(decode_canonical_payload(self.contract_version()?, self.payload.get())?.is_d1_bounded())
    }

    /// Exact canonical event bytes. D1 payloads are written through a bounded
    /// writer whose limit reserves the mandatory trailing LF byte.
    pub fn canonical_bytes(&self) -> Result<Vec<u8>> {
        let payload = decode_canonical_payload(self.contract_version()?, self.payload.get())?;
        if !payload.is_d1_bounded() {
            return canonical_json(self);
        }
        let payload_bytes = payload_canonical_bytes(&payload)?;
        let mut out = BoundedEventJson::new(MAX_D1_EVENT_LINE_BYTES - 1);
        out.push(b"{\"actor\":")?;
        out.string(&self.actor)?;
        out.push(b",\"event_hash\":")?;
        out.string(&self.event_hash.to_string())?;
        out.push(b",\"genesis_hash\":")?;
        out.string(&self.genesis_hash.to_string())?;
        out.push(b",\"id\":")?;
        out.string(&self.id.to_string())?;
        out.push(b",\"logical_time\":")?;
        out.number(self.logical_time)?;
        out.push(b",\"payload\":")?;
        out.push(&payload_bytes)?;
        out.push(b",\"payload_hash\":")?;
        out.string(&self.payload_hash.to_string())?;
        out.push(b",\"previous_event_hash\":")?;
        out.string(&self.previous_event_hash.to_string())?;
        out.push(b",\"run_id\":")?;
        out.string(&self.run_id.to_string())?;
        out.push(b",\"schema\":")?;
        out.string(&self.schema)?;
        out.push(b",\"sequence\":")?;
        out.number(self.sequence)?;
        out.push(b"}")?;
        let bytes = out.finish()?;
        let line_length = bytes.len().checked_add(1).ok_or(DomainError::Incomplete {
            operation: "D1 canonical event JSONL",
            limit: MAX_D1_EVENT_LINE_BYTES,
            observed: usize::MAX,
        })?;
        if line_length > MAX_D1_EVENT_LINE_BYTES {
            return Err(DomainError::Incomplete {
                operation: "D1 canonical event JSONL",
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed: line_length,
            });
        }
        Ok(bytes)
    }

    #[cfg(test)]
    fn canonical_bytes_at_v5_position(&self, position: V5SealedPayloadPosition) -> Result<Vec<u8>> {
        self.validate_at_v5_position(position)?;
        #[derive(Serialize)]
        struct Wire<'a> {
            actor: &'a str,
            event_hash: &'a ContentHash,
            genesis_hash: &'a ContentHash,
            id: &'a StableId,
            logical_time: u64,
            payload: &'a RawValue,
            payload_hash: &'a ContentHash,
            previous_event_hash: &'a ContentHash,
            run_id: &'a StableId,
            schema: &'a str,
            sequence: u64,
        }
        canonical_json(&Wire {
            actor: &self.actor,
            event_hash: &self.event_hash,
            genesis_hash: &self.genesis_hash,
            id: &self.id,
            logical_time: self.logical_time,
            payload: &self.payload,
            payload_hash: &self.payload_hash,
            previous_event_hash: &self.previous_event_hash,
            run_id: &self.run_id,
            schema: &self.schema,
            sequence: self.sequence,
        })
    }

    /// Canonical writer used only by the bounded derived-index scanner. The
    /// destination request is made at the caller-admitted capacity before
    /// serialization; serde/value-tree transients remain core-owned.
    pub fn canonical_bytes_for_index(&self, capacity: usize) -> Result<Vec<u8>> {
        let payload = decode_canonical_payload(self.contract_version()?, self.payload.get())?;
        if payload.is_d1_bounded() {
            let payload_bytes = payload_canonical_bytes(&payload)?;
            let mut out = BoundedEventJson::new_reserved(capacity, capacity)?;
            out.push(b"{\"actor\":")?;
            out.string(&self.actor)?;
            out.push(b",\"event_hash\":")?;
            out.string(&self.event_hash.to_string())?;
            out.push(b",\"genesis_hash\":")?;
            out.string(&self.genesis_hash.to_string())?;
            out.push(b",\"id\":")?;
            out.string(&self.id.to_string())?;
            out.push(b",\"logical_time\":")?;
            out.number(self.logical_time)?;
            out.push(b",\"payload\":")?;
            out.push(&payload_bytes)?;
            out.push(b",\"payload_hash\":")?;
            out.string(&self.payload_hash.to_string())?;
            out.push(b",\"previous_event_hash\":")?;
            out.string(&self.previous_event_hash.to_string())?;
            out.push(b",\"run_id\":")?;
            out.string(&self.run_id.to_string())?;
            out.push(b",\"schema\":")?;
            out.string(&self.schema)?;
            out.push(b",\"sequence\":")?;
            out.number(self.sequence)?;
            out.push(b"}")?;
            return out.finish();
        }
        let value = serde_json::to_value(self)
            .map(canonical_json_value)
            .map_err(|error| DomainError::CanonicalJson(error.to_string()))?;
        let mut output = Vec::new();
        output
            .try_reserve_exact(capacity)
            .map_err(|_| DomainError::Incomplete {
                operation: "index canonical event destination",
                limit: capacity,
                observed: capacity,
            })?;
        serde_json::to_writer(&mut output, &value)
            .map_err(|error| DomainError::CanonicalJson(error.to_string()))?;
        if output.len() > capacity {
            return Err(DomainError::Incomplete {
                operation: "index canonical event destination",
                limit: capacity,
                observed: output.len(),
            });
        }
        Ok(output)
    }

    /// Validates a contiguous prefix, including the requested run even for an
    /// empty stream and the exact initial aggregate hash for every event.
    pub fn validate_sequence(
        version: EventContractVersion,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        events: &[EventEnvelope],
    ) -> Result<()> {
        if run_id.kind() != "run" {
            return Err(DomainError::EventSequence(
                "event stream requires a run ID even when empty".to_owned(),
            ));
        }
        let chain_genesis_hash = event_chain_genesis_hash(run_id, genesis_hash)?;
        let mut previous_event_hash = &chain_genesis_hash;
        for (index, event) in events.iter().enumerate() {
            let expected = u64::try_from(index).map_err(|_| {
                DomainError::EventSequence("event count does not fit u64".to_owned())
            })? + 1;
            event.validate()?;
            let event_version = EventContractVersion::parse(&event.schema)?;
            if event_version != version {
                return Err(DomainError::EventSequence(
                    "event stream schema must match its explicit contract version".to_owned(),
                ));
            }
            if &event.run_id != run_id
                || &event.genesis_hash != genesis_hash
                || event.sequence != expected
                || &event.previous_event_hash != previous_event_hash
            {
                return Err(DomainError::EventSequence(
                    "event run IDs, genesis hashes, sequences, and hashes must form one contiguous prefix"
                    .to_owned(),
                ));
            }
            previous_event_hash = &event.event_hash;
        }
        Ok(())
    }

    #[must_use]
    pub fn id(&self) -> &StableId {
        &self.id
    }

    #[must_use]
    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }

    /// Canonical initial aggregate binding for the complete event stream.
    #[must_use]
    pub fn genesis_hash(&self) -> &ContentHash {
        &self.genesis_hash
    }

    #[must_use]
    pub const fn sequence(&self) -> u64 {
        self.sequence
    }

    #[must_use]
    pub fn actor(&self) -> &str {
        &self.actor
    }

    #[must_use]
    pub const fn logical_time(&self) -> u64 {
        self.logical_time
    }

    #[must_use]
    pub fn payload_hash(&self) -> &ContentHash {
        &self.payload_hash
    }

    /// Hash of the immediately preceding event, or the deterministic genesis
    /// sentinel for the first event in a stream.
    #[must_use]
    pub fn previous_event_hash(&self) -> &ContentHash {
        &self.previous_event_hash
    }

    /// Hash binding this event's canonical envelope and predecessor.
    #[must_use]
    pub fn event_hash(&self) -> &ContentHash {
        &self.event_hash
    }

    /// Decodes the closed payload for an envelope whose stream cursor is
    /// validated online by a durable reader. Envelope shape and payload hash
    /// are still rechecked here; callers receive no access to raw JSON.
    pub fn decode_for_streaming_projection(&self) -> Result<ValidatedEvent<'_>> {
        self.validate()?;
        preflight_event_json_structure(self.payload.get().as_bytes())?;
        Ok(ValidatedEvent {
            envelope: self,
            payload: decoded_payload(decode_canonical_payload(
                self.contract_version()?,
                self.payload.get(),
            )?),
        })
    }

    /// Validates one complete, confirmed stream prefix and exposes only
    /// typed payloads. Store code must not inspect the private JSON payload.
    pub fn validated_view<'a>(
        version: EventContractVersion,
        run_id: &StableId,
        genesis: EventStreamGenesis<'_>,
        events: &'a [EventEnvelope],
    ) -> Result<ValidatedEventView<'a>> {
        let (genesis_hash, snapshot, verified) = match (version, genesis) {
            (EventContractVersion::V1, EventStreamGenesis::V1(hash)) => (hash.clone(), None, None),
            (EventContractVersion::V2, EventStreamGenesis::V2(bytes)) => {
                let snapshot = RunGenesisSnapshot::from_canonical_bytes(bytes)?;
                (ContentHash::sha256(bytes), Some(snapshot), None)
            }
            (EventContractVersion::V2, EventStreamGenesis::V2Verified(verified)) => {
                (verified.genesis_hash.clone(), None, Some(verified))
            }
            (EventContractVersion::V3, EventStreamGenesis::V3(bytes)) => {
                let snapshot = RunGenesisSnapshot::from_canonical_bytes_v3(bytes)?;
                (ContentHash::sha256(bytes), Some(snapshot), None)
            }
            (EventContractVersion::V4, EventStreamGenesis::V4(_)) => {
                return Err(DomainError::EventSequence(
                    "v4 streams require the opaque strict v4 stream validator".to_owned(),
                ));
            }
            (EventContractVersion::V5, EventStreamGenesis::V5(_)) => {
                return Err(DomainError::EventSequence(
                    "v5 streams require the opaque strict v5 stream validator".to_owned(),
                ));
            }
            _ => {
                return Err(DomainError::EventSequence(
                    "event stream genesis material must match its explicit contract version"
                        .to_owned(),
                ));
            }
        };
        Self::validate_sequence(version, run_id, &genesis_hash, events)?;
        if let (EventContractVersion::V2, Some(first), Some(snapshot)) =
            (version, events.first(), snapshot.as_ref())
        {
            let initial = snapshot.rebuild_aggregate()?;
            let bytes = snapshot.canonical_bytes()?;
            validate_v2_genesis_envelope(run_id, &initial, &bytes, first)?;
        }
        if let (EventContractVersion::V3, Some(first), Some(snapshot)) =
            (version, events.first(), snapshot.as_ref())
        {
            let initial = snapshot.rebuild_aggregate()?;
            let bytes = snapshot.canonical_bytes()?;
            validate_v3_genesis_envelope(run_id, &initial, &bytes, first)?;
        }
        let events = events
            .iter()
            .map(|envelope| {
                Ok(ValidatedEvent {
                    envelope,
                    payload: decoded_payload(decode_canonical_payload(
                        envelope.contract_version()?,
                        envelope.payload.get(),
                    )?),
                })
            })
            .collect::<Result<Vec<_>>>()?;
        if let (EventContractVersion::V2, Some(first), Some(verified)) =
            (version, events.first(), verified)
        {
            let DecodedPayload::RunGenesisManifest(manifest) = first.payload() else {
                return Err(DomainError::EventSequence(
                    "v2 sequence one must carry RunGenesisManifest".to_owned(),
                ));
            };
            verified.validate_manifest(run_id, manifest)?;
        }
        Ok(ValidatedEventView {
            version,
            run_id: run_id.clone(),
            genesis_hash,
            verified_v2_genesis: snapshot.is_some() || verified.is_some(),
            verified_pristine_hash: verified.map(|value| value.pristine_aggregate_hash.clone()),
            events,
        })
    }

    /// Strictly validates a homogeneous v4 stream for durable identity and
    /// framing decisions without exposing its closed payload values. This is
    /// intentionally structural: authority replay still requires
    /// [`EventLogV4::replay_confirmed_v4_prefix`].
    pub fn validate_v4_stream(
        run_id: &StableId,
        canonical_genesis_bytes: &[u8],
        events: &[EventEnvelope],
    ) -> Result<()> {
        let snapshot = RunGenesisSnapshot::from_canonical_bytes_v3(canonical_genesis_bytes)?;
        let initial = snapshot.rebuild_aggregate()?;
        initial.validate_pristine_for_event_log()?;
        let genesis_hash = ContentHash::sha256(canonical_genesis_bytes);
        Self::validate_sequence(EventContractVersion::V4, run_id, &genesis_hash, events)?;
        if let Some(first) = events.first() {
            validate_v4_genesis_envelope(run_id, &initial, canonical_genesis_bytes, first)?;
        }
        for envelope in events {
            let payload =
                decode_canonical_payload(EventContractVersion::V4, envelope.payload.get())?;
            if envelope.actor() != payload.actor() {
                return Err(DomainError::EventSequence(
                    "v4 event actor does not match its closed payload actor".to_owned(),
                ));
            }
            validate_stream_payload_position(
                EventContractVersion::V4,
                envelope.sequence(),
                &payload,
            )?;
            payload.validate_for_enclosing_run(run_id)?;
        }
        Ok(())
    }

    /// Strictly validates a homogeneous v5 stream for durable identity and
    /// framing decisions.  V5 deliberately reuses the frozen V4 genesis body
    /// while changing the envelope contract; this is not an upcast path and
    /// therefore refuses every V4 envelope.
    pub(crate) fn validate_v5_stream(
        run_id: &StableId,
        canonical_genesis_bytes: &[u8],
        events: &[EventEnvelope],
    ) -> Result<()> {
        Self::validate_v5_stream_with_accounting(run_id, canonical_genesis_bytes, events)
            .map(|_| ())
    }

    /// Borrow-only structural validator used by Store before durable V5
    /// publication. It validates no authority and exposes no append cursor.
    #[doc(hidden)]
    pub fn validate_v5_stream_for_store(
        run_id: &StableId,
        canonical_genesis_bytes: &[u8],
        events: &[EventEnvelope],
    ) -> Result<()> {
        Self::validate_v5_stream(run_id, canonical_genesis_bytes, events)
    }

    fn validate_v5_stream_with_accounting(
        run_id: &StableId,
        canonical_genesis_bytes: &[u8],
        events: &[EventEnvelope],
    ) -> Result<V5ValidationScratch> {
        let snapshot = RunGenesisSnapshot::from_canonical_bytes_v3(canonical_genesis_bytes)?;
        let snapshot_bytes = snapshot.owned_bytes()?;
        let initial = snapshot.rebuild_aggregate()?;
        let aggregate_bytes = initial.retained_bytes_v3()?;
        initial.validate_pristine_for_event_log()?;
        let genesis_hash = ContentHash::sha256(canonical_genesis_bytes);
        Self::validate_sequence(EventContractVersion::V5, run_id, &genesis_hash, events)?;
        if let Some(first) = events.first() {
            let payload = decode_canonical_payload(EventContractVersion::V5, first.payload.get())?;
            let PersistedPayload::RunGenesisManifestV4(manifest) = payload else {
                return Err(DomainError::EventSequence(
                    "V5 sequence one must carry the frozen RunGenesisManifestV4".to_owned(),
                ));
            };
            manifest.validate_against_genesis(run_id, &snapshot, canonical_genesis_bytes)?;
        }
        let mut max_event_validation_bytes = 0_u64;
        let mut post_d2 = initial_v5_structural_post_d2_phase();
        for envelope in events {
            let payload =
                decode_canonical_payload(EventContractVersion::V5, envelope.payload.get())?;
            let line_bytes = envelope.canonical_line_bytes_v5.ok_or_else(|| {
                DomainError::EventSequence(
                    "V5 validation requires the admitted LF-inclusive event line length".to_owned(),
                )
            })?;
            let event_validation_bytes = line_bytes
                .checked_add(payload.validation_heap_bytes_v5()?)
                .ok_or(DomainError::Incomplete {
                    operation: "V5 event validation recursive ownership",
                    limit: usize::try_from(MAX_V5_REPLAY_WORKING_BYTES).unwrap_or(usize::MAX),
                    observed: usize::MAX,
                })?;
            max_event_validation_bytes = max_event_validation_bytes.max(event_validation_bytes);
            if envelope.actor() != payload.actor() {
                return Err(DomainError::EventSequence(
                    "v5 event actor does not match its closed payload actor".to_owned(),
                ));
            }
            validate_stream_payload_position(
                EventContractVersion::V5,
                envelope.sequence(),
                &payload,
            )?;
            advance_v5_structural_post_d2(&mut post_d2, &payload)?;
            payload.validate_for_enclosing_run(run_id)?;
        }
        Ok(V5ValidationScratch {
            snapshot_bytes,
            aggregate_bytes,
            max_event_validation_bytes,
        })
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct V5ValidationScratch {
    snapshot_bytes: u64,
    aggregate_bytes: u64,
    max_event_validation_bytes: u64,
}

impl V5ValidationScratch {
    #[allow(dead_code)] // Reserved for the crate-private Store/session admission builder.
    const ZERO: Self = Self {
        snapshot_bytes: 0,
        aggregate_bytes: 0,
        max_event_validation_bytes: 0,
    };
}

/// Typed, hash-chain-validated event prefix for durable projections.
#[derive(Clone, Debug)]
pub struct ValidatedEventView<'a> {
    version: EventContractVersion,
    run_id: StableId,
    genesis_hash: ContentHash,
    verified_v2_genesis: bool,
    verified_pristine_hash: Option<ContentHash>,
    events: Vec<ValidatedEvent<'a>>,
}

/// Retained-capacity charge exposed to bounded durable projections.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct EventViewAccounting {
    retained_bytes: u64,
    scratch_peak_bytes: u64,
}

impl EventViewAccounting {
    #[must_use]
    pub const fn retained_bytes(self) -> u64 {
        self.retained_bytes
    }
    #[must_use]
    pub const fn scratch_peak_bytes(self) -> u64 {
        self.scratch_peak_bytes
    }
}

impl<'a> ValidatedEventView<'a> {
    /// Builds a typed view only after reserving its complete input-derived
    /// allocation charge against the caller's combined working limit.
    pub fn with_working_limit(
        version: EventContractVersion,
        run_id: &StableId,
        genesis: EventStreamGenesis<'_>,
        events: &'a [EventEnvelope],
        already_retained: u64,
        working_limit: u64,
    ) -> Result<(Self, EventViewAccounting)> {
        let working_limit_usize = usize::try_from(working_limit).unwrap_or(usize::MAX);
        let genesis_scratch = match genesis {
            EventStreamGenesis::V1(_) => 0,
            EventStreamGenesis::V2(bytes) => u64::try_from(bytes.len())
                .ok()
                .and_then(|length| length.checked_mul(2))
                .ok_or(DomainError::Incomplete {
                    operation: "validated genesis scratch",
                    limit: working_limit_usize,
                    observed: usize::MAX,
                })?,
            EventStreamGenesis::V2Verified(_) => 0,
            EventStreamGenesis::V3(bytes) => u64::try_from(bytes.len())
                .ok()
                .and_then(|length| length.checked_mul(2))
                .ok_or(DomainError::Incomplete {
                    operation: "validated genesis scratch",
                    limit: working_limit_usize,
                    observed: usize::MAX,
                })?,
            EventStreamGenesis::V4(bytes) => u64::try_from(bytes.len())
                .ok()
                .and_then(|length| length.checked_mul(2))
                .ok_or(DomainError::Incomplete {
                    operation: "validated genesis scratch",
                    limit: working_limit_usize,
                    observed: usize::MAX,
                })?,
            EventStreamGenesis::V5(bytes) => u64::try_from(bytes.len())
                .ok()
                .and_then(|length| length.checked_mul(2))
                .ok_or(DomainError::Incomplete {
                    operation: "validated genesis scratch",
                    limit: working_limit_usize,
                    observed: usize::MAX,
                })?,
        };
        let payload_scratch = events
            .iter()
            .map(|event| u64::try_from(event.payload.get().len()).unwrap_or(u64::MAX))
            .max()
            .unwrap_or(0)
            .checked_mul(2)
            .ok_or(DomainError::Incomplete {
                operation: "validated payload scratch",
                limit: working_limit_usize,
                observed: usize::MAX,
            })?;
        let scratch_peak_bytes = genesis_scratch.max(payload_scratch);
        let view = EventEnvelope::validated_view(version, run_id, genesis, events)?;
        let retained_bytes = view.allocated_bytes()?;
        let observed = already_retained
            .checked_add(retained_bytes)
            .and_then(|value| value.checked_add(scratch_peak_bytes))
            .ok_or(DomainError::Incomplete {
                operation: "validated event view allocation",
                limit: working_limit_usize,
                observed: usize::MAX,
            })?;
        if observed > working_limit {
            return Err(DomainError::Incomplete {
                operation: "validated event view allocation",
                limit: working_limit_usize,
                observed: usize::try_from(observed).unwrap_or(usize::MAX),
            });
        }
        Ok((
            view,
            EventViewAccounting {
                retained_bytes,
                scratch_peak_bytes,
            },
        ))
    }

    fn allocated_bytes(&self) -> Result<u64> {
        let vector = self
            .events
            .capacity()
            .checked_mul(std::mem::size_of::<ValidatedEvent<'_>>())
            .ok_or(DomainError::Incomplete {
                operation: "validated event view retained capacity",
                limit: usize::MAX,
                observed: usize::MAX,
            })?;
        let heap = self.events.iter().fold(0_usize, |total, event| {
            total.saturating_add(event.payload_allocated_bytes())
        });
        u64::try_from(
            vector
                .saturating_add(heap)
                .saturating_add(self.run_id.allocated_bytes())
                .saturating_add(self.genesis_hash.allocated_bytes()),
        )
        .map_err(|_| DomainError::Incomplete {
            operation: "validated event view retained capacity",
            limit: usize::MAX,
            observed: usize::MAX,
        })
    }
    #[must_use]
    pub const fn event_contract_version(&self) -> EventContractVersion {
        self.version
    }
    #[must_use]
    pub fn events(&self) -> &[ValidatedEvent<'a>] {
        &self.events
    }

    #[must_use]
    pub fn genesis_hash(&self) -> &ContentHash {
        &self.genesis_hash
    }
    #[must_use]
    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }

    fn validate_initial(&self, initial: &ReviewAggregate) -> Result<()> {
        initial.validate_pristine_for_event_log()?;
        match (self.version, self.verified_v2_genesis) {
            (EventContractVersion::V1, false) => {
                if self.genesis_hash != ContentHash::sha256(&canonical_json(initial)?) {
                    return Err(DomainError::Validation(
                        "offline v1 projection initial aggregate does not match its genesis hash"
                            .to_owned(),
                    ));
                }
            }
            (EventContractVersion::V2, true) => {
                let matches = if let Some(expected) = &self.verified_pristine_hash {
                    expected == &ContentHash::sha256(&canonical_json(initial)?)
                } else {
                    let snapshot = RunGenesisSnapshot::from_aggregate(initial)?;
                    let bytes = snapshot.canonical_bytes()?;
                    self.genesis_hash == ContentHash::sha256(&bytes)
                };
                if !matches {
                    return Err(DomainError::Validation(
                        "offline v2 projection initial aggregate does not match verified genesis bytes"
                            .to_owned(),
                    ));
                }
            }
            (EventContractVersion::V3, true) => {
                let bytes = encode_exact_compact_json(
                    &BorrowedRunGenesisSnapshot(initial),
                    "event-v3 validated-view genesis bytes",
                )?;
                if self.genesis_hash != ContentHash::sha256(&bytes) {
                    return Err(DomainError::Validation(
                        "event-v3 validated view initial aggregate does not match verified genesis bytes"
                            .to_owned(),
                    ));
                }
            }
            _ => {
                return Err(DomainError::Validation(
                    "validated event view has inconsistent genesis material".to_owned(),
                ));
            }
        }
        Ok(())
    }
}

/// A validated envelope paired with its decoded closed payload.
#[derive(Clone, Debug)]
pub struct ValidatedEvent<'a> {
    envelope: &'a EventEnvelope,
    payload: DecodedPayload,
}

impl<'a> ValidatedEvent<'a> {
    fn payload_allocated_bytes(&self) -> usize {
        match &self.payload {
            DecodedPayload::ObligationTransition { obligation_id, .. } => {
                obligation_id.allocated_bytes()
            }
            DecodedPayload::ClaimProposed(value) => value.allocated_bytes(),
            DecodedPayload::EvidenceRecorded(value) => value.allocated_bytes(),
            DecodedPayload::EvidenceBound(value) => value.allocated_bytes(),
            DecodedPayload::VerificationRecorded(value) => value.allocated_bytes(),
            DecodedPayload::DecisionRecorded(value) => value.allocated_bytes(),
            DecodedPayload::FindingRecorded(value) => value.allocated_bytes(),
            DecodedPayload::RunGenesisManifest(value) => value.allocated_bytes(),
            DecodedPayload::RunGenesisManifestV3(value) => value.allocated_bytes(),
            DecodedPayload::ArtifactRegistered(value) => value.allocated_bytes(),
            DecodedPayload::ArtifactRegisteredV3(value) => value.allocated_bytes(),
            DecodedPayload::EvidenceRecordedV3(value) => {
                value.allocated_bytes().map_or(usize::MAX, |bytes| {
                    usize::try_from(bytes).unwrap_or(usize::MAX)
                })
            }
            DecodedPayload::EvidenceBoundV3(value) => {
                value.allocated_bytes().map_or(usize::MAX, |bytes| {
                    usize::try_from(bytes).unwrap_or(usize::MAX)
                })
            }
            DecodedPayload::VerificationRecordedV3(value) => {
                value.allocated_bytes().map_or(usize::MAX, |bytes| {
                    usize::try_from(bytes).unwrap_or(usize::MAX)
                })
            }
            DecodedPayload::DecisionRecordedV3(value) => {
                value.allocated_bytes().map_or(usize::MAX, |bytes| {
                    usize::try_from(bytes).unwrap_or(usize::MAX)
                })
            }
            DecodedPayload::FindingRecordedV3(value) => {
                value.allocated_bytes().map_or(usize::MAX, |bytes| {
                    usize::try_from(bytes).unwrap_or(usize::MAX)
                })
            }
            DecodedPayload::SnapshotSourcesRecorded(value) => value.allocated_bytes(),
            DecodedPayload::ReviewPlanRecorded(value) => value.allocated_bytes(),
            DecodedPayload::ContextEnvelopeProjected(value) => value.allocated_bytes(),
            DecodedPayload::ReviewExecutionRecorded { execution, claims } => execution
                .allocated_bytes()
                .saturating_add(
                    claims
                        .capacity()
                        .saturating_mul(std::mem::size_of::<ExecutionClaimV2>()),
                )
                .saturating_add(
                    claims
                        .iter()
                        .map(ExecutionClaimV2::allocated_bytes)
                        .sum::<usize>(),
                ),
        }
    }

    #[must_use]
    pub fn envelope(&self) -> &'a EventEnvelope {
        self.envelope
    }
    #[must_use]
    pub fn payload(&self) -> &DecodedPayload {
        &self.payload
    }
}

/// Store-facing typed metadata. It intentionally excludes raw JSON.
#[derive(Clone, Debug)]
pub enum DecodedPayload {
    ObligationTransition {
        obligation_id: StableId,
        next: ObligationLifecycle,
    },
    ClaimProposed(ReviewClaim),
    EvidenceRecorded(Evidence),
    EvidenceBound(EvidenceBinding),
    VerificationRecorded(Verification),
    DecisionRecorded(Decision),
    FindingRecorded(Finding),
    RunGenesisManifest(RunGenesisManifest),
    RunGenesisManifestV3(RunGenesisManifestV3),
    ArtifactRegistered(ArtifactRegistered),
    ArtifactRegisteredV3(ArtifactRegisteredV3),
    EvidenceRecordedV3(EvidenceV3),
    EvidenceBoundV3(EvidenceBindingV3),
    VerificationRecordedV3(VerificationV3),
    DecisionRecordedV3(DecisionV3),
    FindingRecordedV3(FindingV3),
    SnapshotSourcesRecorded(SnapshotSourcesRecorded),
    ReviewPlanRecorded(ReviewPlan),
    ContextEnvelopeProjected(ReviewContextEnvelope),
    ReviewExecutionRecorded {
        execution: ExecutionRecord,
        claims: Vec<ExecutionClaimV2>,
    },
}

/// Read-only event-v4 payload vocabulary for the derived Store index-v5.
///
/// Every reference is lent synchronously from Core's authority replay and
/// expires before that replay step releases its decoded DTO. The enum
/// deliberately contains neither raw JSON nor an authority-bearing value and
/// cannot be constructed by callers from untrusted input. Observations become
/// usable only after the complete replay returns successfully.
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedProjectionPayloadV4;
/// fn retain<'a>(
///     slot: &mut Option<BorrowedProjectionPayloadV4<'static>>,
///     value: BorrowedProjectionPayloadV4<'a>,
/// ) {
///     *slot = Some(value);
/// }
/// ```
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedProjectionPayloadV4;
/// fn requires_clone<T: Clone>() {}
/// requires_clone::<BorrowedProjectionPayloadV4<'static>>();
/// ```
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedProjectionPayloadV4;
/// fn requires_serialize<T: serde::Serialize>() {}
/// requires_serialize::<BorrowedProjectionPayloadV4<'static>>();
/// ```
pub struct BorrowedProjectionPayloadV4<'a> {
    inner: BorrowedProjectionPayloadInnerV4<'a>,
}

enum BorrowedProjectionPayloadInnerV4<'a> {
    Genesis(&'a RunGenesisManifestV4),
    Persisted {
        payload: &'a PersistedPayload,
        decoded_bundle: Option<&'a crate::GluingBundleV4>,
        decoded_descriptor: Option<&'a crate::GluingInputDescriptorV4>,
    },
    Direct(BorrowedDirectProjectionV4<'a>),
}

enum BorrowedDirectProjectionV4<'a> {
    ObligationTransition {
        obligation_id: &'a StableId,
        next: ObligationLifecycle,
    },
    ArtifactRegisteredV3(&'a ArtifactRegisteredV3),
    SnapshotSourcesRecorded(&'a SnapshotSourcesRecorded),
    ReviewPlanRecorded(&'a ReviewPlan),
    ContextEnvelopeProjected(&'a ReviewContextEnvelope),
    ReviewExecutionRecorded {
        execution: &'a ExecutionRecord,
        claims: &'a BTreeMap<StableId, ExecutionClaimV2>,
    },
    EvidenceRecordedV3(&'a EvidenceV3),
    EvidenceBoundV3(&'a EvidenceBindingV3),
    VerificationRecordedV3(&'a VerificationV3),
    DecisionRecordedV3(&'a DecisionV3),
    FindingRecordedV3(&'a FindingV3),
    ArtifactRegisteredV4 {
        registration: &'a ArtifactRegistrationV4,
        descriptor: &'a crate::GluingInputDescriptorV4,
    },
    GluingBundleRecordedV4(&'a crate::GluingBundleV4),
}

/// Callback-scoped, scalar-only metadata for one already validated V4 event.
///
/// It exposes neither the envelope nor raw/canonical payload bytes. The type
/// is intentionally non-`Clone` and non-Serde, and its private fields prevent
/// caller construction.
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedV4EventMetadata;
/// fn requires_clone<T: Clone>() {}
/// requires_clone::<BorrowedV4EventMetadata<'static>>();
/// ```
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedV4EventMetadata;
/// fn requires_serialize<T: serde::Serialize>() {}
/// requires_serialize::<BorrowedV4EventMetadata<'static>>();
/// ```
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedV4EventMetadata;
/// fn retain<'a>(
///     slot: &mut Option<BorrowedV4EventMetadata<'static>>,
///     value: BorrowedV4EventMetadata<'a>,
/// ) {
///     *slot = Some(value);
/// }
/// ```
pub struct BorrowedV4EventMetadata<'a> {
    sequence: u64,
    id: &'a StableId,
    schema: &'a str,
    event_hash: &'a ContentHash,
    payload_hash: &'a ContentHash,
    actor: &'a str,
    logical_time: u64,
    canonical_line_bytes: u64,
}

impl<'a> BorrowedV4EventMetadata<'a> {
    #[must_use]
    pub const fn sequence(&self) -> u64 {
        self.sequence
    }

    #[must_use]
    pub const fn id(&self) -> &'a StableId {
        self.id
    }

    #[must_use]
    pub const fn schema(&self) -> &'a str {
        self.schema
    }

    #[must_use]
    pub const fn event_hash(&self) -> &'a ContentHash {
        self.event_hash
    }

    #[must_use]
    pub const fn payload_hash(&self) -> &'a ContentHash {
        self.payload_hash
    }

    #[must_use]
    pub const fn actor(&self) -> &'a str {
        self.actor
    }

    #[must_use]
    pub const fn logical_time(&self) -> u64 {
        self.logical_time
    }

    /// Exact canonical JSONL bytes including the mandatory trailing LF.
    #[must_use]
    pub const fn canonical_line_bytes(&self) -> u64 {
        self.canonical_line_bytes
    }
}

fn borrowed_v4_event_metadata(envelope: &EventEnvelope) -> Result<BorrowedV4EventMetadata<'_>> {
    if envelope.contract_version()? != EventContractVersion::V4 {
        return Err(DomainError::EventSequence(
            "borrowed V4 metadata requires an event-v4 envelope".to_owned(),
        ));
    }
    Ok(BorrowedV4EventMetadata {
        sequence: envelope.sequence,
        id: &envelope.id,
        schema: &envelope.schema,
        event_hash: &envelope.event_hash,
        payload_hash: &envelope.payload_hash,
        actor: &envelope.actor,
        logical_time: envelope.logical_time,
        canonical_line_bytes: envelope.canonical_line_bytes_v4.ok_or_else(|| {
            DomainError::EventSequence(
                "borrowed V4 metadata requires a validated canonical line length".to_owned(),
            )
        })?,
    })
}

impl<'a> BorrowedProjectionPayloadV4<'a> {
    #[must_use]
    pub fn view(&self) -> BorrowedProjectionPayloadRefV4<'_> {
        match &self.inner {
            BorrowedProjectionPayloadInnerV4::Genesis(value) => {
                BorrowedProjectionPayloadRefV4::RunGenesisManifestV4(
                    BorrowedRunGenesisManifestProjectionV4 { value },
                )
            }
            BorrowedProjectionPayloadInnerV4::Persisted {
                payload,
                decoded_bundle,
                decoded_descriptor,
            } => borrowed_projection_payload_ref_v4(payload, *decoded_bundle, *decoded_descriptor)
                .expect("Core constructs borrowed projection payloads only after closed V4 replay"),
            BorrowedProjectionPayloadInnerV4::Direct(value) => match value {
                BorrowedDirectProjectionV4::ObligationTransition {
                    obligation_id,
                    next,
                } => BorrowedProjectionPayloadRefV4::ObligationTransition(
                    BorrowedObligationTransitionProjectionV4 {
                        obligation_id,
                        next: *next,
                    },
                ),
                BorrowedDirectProjectionV4::ArtifactRegisteredV3(value) => {
                    BorrowedProjectionPayloadRefV4::ArtifactRegisteredV3(
                        BorrowedArtifactRegistrationProjectionV3 { value },
                    )
                }
                BorrowedDirectProjectionV4::SnapshotSourcesRecorded(value) => {
                    BorrowedProjectionPayloadRefV4::SnapshotSourcesRecorded(
                        BorrowedSnapshotSourcesProjectionV4 { value },
                    )
                }
                BorrowedDirectProjectionV4::ReviewPlanRecorded(value) => {
                    BorrowedProjectionPayloadRefV4::ReviewPlanRecorded(
                        BorrowedReviewPlanProjectionV4 { value },
                    )
                }
                BorrowedDirectProjectionV4::ContextEnvelopeProjected(value) => {
                    BorrowedProjectionPayloadRefV4::ContextEnvelopeProjected(
                        BorrowedContextEnvelopeProjectionV4 { value },
                    )
                }
                BorrowedDirectProjectionV4::ReviewExecutionRecorded { execution, claims } => {
                    BorrowedProjectionPayloadRefV4::ReviewExecutionRecorded(
                        BorrowedReviewExecutionProjectionV4 {
                            source: BorrowedReviewExecutionSourceV4::Aggregate {
                                execution,
                                claims,
                            },
                        },
                    )
                }
                BorrowedDirectProjectionV4::EvidenceRecordedV3(value) => {
                    BorrowedProjectionPayloadRefV4::EvidenceRecordedV3(
                        BorrowedEvidenceProjectionV3 { value },
                    )
                }
                BorrowedDirectProjectionV4::EvidenceBoundV3(value) => {
                    BorrowedProjectionPayloadRefV4::EvidenceBoundV3(
                        BorrowedEvidenceBindingProjectionV3 { value },
                    )
                }
                BorrowedDirectProjectionV4::VerificationRecordedV3(value) => {
                    BorrowedProjectionPayloadRefV4::VerificationRecordedV3(
                        BorrowedVerificationProjectionV3 { value },
                    )
                }
                BorrowedDirectProjectionV4::DecisionRecordedV3(value) => {
                    BorrowedProjectionPayloadRefV4::DecisionRecordedV3(
                        BorrowedDecisionProjectionV3 { value },
                    )
                }
                BorrowedDirectProjectionV4::FindingRecordedV3(value) => {
                    BorrowedProjectionPayloadRefV4::FindingRecordedV3(BorrowedFindingProjectionV3 {
                        value,
                    })
                }
                BorrowedDirectProjectionV4::ArtifactRegisteredV4 {
                    registration,
                    descriptor,
                } => BorrowedProjectionPayloadRefV4::ArtifactRegisteredV4(
                    BorrowedArtifactRegistrationProjectionV4 {
                        value: registration,
                        descriptor: Some(descriptor),
                    },
                ),
                BorrowedDirectProjectionV4::GluingBundleRecordedV4(value) => {
                    BorrowedProjectionPayloadRefV4::GluingBundleRecordedV4(
                        BorrowedGluingBundleProjectionV4 { value },
                    )
                }
            },
        }
    }
}

/// Closed read-only view of one callback-scoped V4 projection payload.
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedProjectionPayloadRefV4;
/// fn requires_clone<T: Clone>() {}
/// requires_clone::<BorrowedProjectionPayloadRefV4<'static>>();
/// ```
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedProjectionPayloadRefV4;
/// fn requires_serialize<T: serde::Serialize>() {}
/// requires_serialize::<BorrowedProjectionPayloadRefV4<'static>>();
/// ```
///
/// ```compile_fail
/// use reviewgraphen_core::BorrowedProjectionPayloadRefV4;
/// fn retain<'a>(
///     slot: &mut Option<BorrowedProjectionPayloadRefV4<'static>>,
///     value: BorrowedProjectionPayloadRefV4<'a>,
/// ) {
///     *slot = Some(value);
/// }
/// ```
pub enum BorrowedProjectionPayloadRefV4<'a> {
    RunGenesisManifestV4(BorrowedRunGenesisManifestProjectionV4<'a>),
    ObligationTransition(BorrowedObligationTransitionProjectionV4<'a>),
    ArtifactRegisteredV3(BorrowedArtifactRegistrationProjectionV3<'a>),
    SnapshotSourcesRecorded(BorrowedSnapshotSourcesProjectionV4<'a>),
    ReviewPlanRecorded(BorrowedReviewPlanProjectionV4<'a>),
    ContextEnvelopeProjected(BorrowedContextEnvelopeProjectionV4<'a>),
    ReviewExecutionRecorded(BorrowedReviewExecutionProjectionV4<'a>),
    EvidenceRecordedV3(BorrowedEvidenceProjectionV3<'a>),
    EvidenceBoundV3(BorrowedEvidenceBindingProjectionV3<'a>),
    VerificationRecordedV3(BorrowedVerificationProjectionV3<'a>),
    DecisionRecordedV3(BorrowedDecisionProjectionV3<'a>),
    FindingRecordedV3(BorrowedFindingProjectionV3<'a>),
    ArtifactRegisteredV4(BorrowedArtifactRegistrationProjectionV4<'a>),
    GluingInputDescriptorV4(BorrowedGluingInputDescriptorProjectionV4<'a>),
    GluingBundleRecordedV4(BorrowedGluingBundleProjectionV4<'a>),
}

macro_rules! opaque_projection_wrapper {
    ($name:ident, $value:ty) => {
        pub struct $name<'a> {
            pub(crate) value: &'a $value,
        }
    };
}

opaque_projection_wrapper!(BorrowedRunGenesisManifestProjectionV4, RunGenesisManifestV4);
opaque_projection_wrapper!(
    BorrowedArtifactRegistrationProjectionV3,
    ArtifactRegisteredV3
);
opaque_projection_wrapper!(BorrowedSnapshotSourcesProjectionV4, SnapshotSourcesRecorded);
opaque_projection_wrapper!(BorrowedReviewPlanProjectionV4, ReviewPlan);
opaque_projection_wrapper!(BorrowedContextEnvelopeProjectionV4, ReviewContextEnvelope);
