fn borrowed_projection_payload_v4<'a>(
    payload: &'a PersistedPayload,
    decoded_bundle: Option<&'a crate::GluingBundleV4>,
    decoded_descriptor: Option<&'a crate::GluingInputDescriptorV4>,
) -> Result<BorrowedProjectionPayloadV4<'a>> {
    let _ = borrowed_projection_payload_ref_v4(payload, decoded_bundle, decoded_descriptor)?;
    Ok(BorrowedProjectionPayloadV4 {
        inner: BorrowedProjectionPayloadInnerV4::Persisted {
            payload,
            decoded_bundle,
            decoded_descriptor,
        },
    })
}

fn borrowed_projection_payload_ref_v4<'a>(
    payload: &'a PersistedPayload,
    decoded_bundle: Option<&'a crate::GluingBundleV4>,
    decoded_descriptor: Option<&'a crate::GluingInputDescriptorV4>,
) -> Result<BorrowedProjectionPayloadRefV4<'a>> {
    Ok(match payload {
        PersistedPayload::RunGenesisManifestV4(value) => {
            BorrowedProjectionPayloadRefV4::RunGenesisManifestV4(
                BorrowedRunGenesisManifestProjectionV4 { value },
            )
        }
        PersistedPayload::ObligationTransition {
            obligation_id,
            next,
        } => BorrowedProjectionPayloadRefV4::ObligationTransition(
            BorrowedObligationTransitionProjectionV4 {
                obligation_id,
                next: *next,
            },
        ),
        PersistedPayload::ArtifactRegisteredV3(value) => {
            BorrowedProjectionPayloadRefV4::ArtifactRegisteredV3(
                BorrowedArtifactRegistrationProjectionV3 { value },
            )
        }
        PersistedPayload::SnapshotSourcesRecorded(value) => {
            BorrowedProjectionPayloadRefV4::SnapshotSourcesRecorded(
                BorrowedSnapshotSourcesProjectionV4 { value },
            )
        }
        PersistedPayload::ReviewPlanRecorded(value) => {
            BorrowedProjectionPayloadRefV4::ReviewPlanRecorded(BorrowedReviewPlanProjectionV4 {
                value,
            })
        }
        PersistedPayload::ContextEnvelopeProjected(value) => {
            BorrowedProjectionPayloadRefV4::ContextEnvelopeProjected(
                BorrowedContextEnvelopeProjectionV4 { value },
            )
        }
        PersistedPayload::ReviewExecutionRecorded(value) => {
            BorrowedProjectionPayloadRefV4::ReviewExecutionRecorded(
                BorrowedReviewExecutionProjectionV4 {
                    source: BorrowedReviewExecutionSourceV4::Persisted(value),
                },
            )
        }
        PersistedPayload::EvidenceRecordedV3(value) => {
            BorrowedProjectionPayloadRefV4::EvidenceRecordedV3(BorrowedEvidenceProjectionV3 {
                value,
            })
        }
        PersistedPayload::EvidenceBoundV3(value) => {
            BorrowedProjectionPayloadRefV4::EvidenceBoundV3(BorrowedEvidenceBindingProjectionV3 {
                value,
            })
        }
        PersistedPayload::VerificationRecordedV3(value) => {
            BorrowedProjectionPayloadRefV4::VerificationRecordedV3(
                BorrowedVerificationProjectionV3 { value },
            )
        }
        PersistedPayload::DecisionRecordedV3(value) => {
            BorrowedProjectionPayloadRefV4::DecisionRecordedV3(BorrowedDecisionProjectionV3 {
                value,
            })
        }
        PersistedPayload::FindingRecordedV3(value) => {
            BorrowedProjectionPayloadRefV4::FindingRecordedV3(BorrowedFindingProjectionV3 { value })
        }
        PersistedPayload::ArtifactRegisteredV4(value) => {
            BorrowedProjectionPayloadRefV4::ArtifactRegisteredV4(
                BorrowedArtifactRegistrationProjectionV4 {
                    value,
                    descriptor: decoded_descriptor,
                },
            )
        }
        PersistedPayload::GluingBundleRecordedV4(_) => {
            BorrowedProjectionPayloadRefV4::GluingBundleRecordedV4(
                BorrowedGluingBundleProjectionV4 {
                    value: decoded_bundle.ok_or(DomainError::GluingBundleMismatch)?,
                },
            )
        }
        PersistedPayload::ClaimProposed(_)
        | PersistedPayload::EvidenceRecorded(_)
        | PersistedPayload::EvidenceBound(_)
        | PersistedPayload::VerificationRecorded(_)
        | PersistedPayload::DecisionRecorded(_)
        | PersistedPayload::FindingRecorded(_)
        | PersistedPayload::RunGenesisManifest(_)
        | PersistedPayload::RunGenesisManifestV3(_)
        | PersistedPayload::ArtifactRegistered(_)
        | PersistedPayload::IncrementalSourceBoundV5(_)
        | PersistedPayload::ProgramMappingRecordedV5(_)
        | PersistedPayload::ChangeMorphismSealedV5(_)
        | PersistedPayload::ObligationCorrespondenceEntryRecordedV5(_)
        | PersistedPayload::ObligationCorrespondenceSealedV5(_)
        | PersistedPayload::HistoricalRecordAssessedV5(_)
        | PersistedPayload::GluingFreshnessRecordedV5(_)
        | PersistedPayload::StalenessAssessmentSealedV5(_)
        | PersistedPayload::ArtifactRegisteredV5(_)
        | PersistedPayload::PreservationVerifiedV5 { .. }
        | PersistedPayload::PartialRerunActionRecordedV5(_)
        | PersistedPayload::PartialRerunPlanSealedV5(_)
        | PersistedPayload::GluingRerunActionRecordedV5(_)
        | PersistedPayload::GluingRerunPlanSealedV5(_)
        | PersistedPayload::TerminalCompletedV5(_) => {
            return Err(DomainError::EventSequence(
                "event-v4 projection encountered a payload outside its closed contract".to_owned(),
            ));
        }
    })
}

fn decoded_payload(payload: PersistedPayload) -> DecodedPayload {
    match payload {
        PersistedPayload::ObligationTransition {
            obligation_id,
            next,
        } => DecodedPayload::ObligationTransition {
            obligation_id,
            next,
        },
        PersistedPayload::ClaimProposed(value) => DecodedPayload::ClaimProposed(value),
        PersistedPayload::EvidenceRecorded(value) => DecodedPayload::EvidenceRecorded(*value),
        PersistedPayload::EvidenceBound(value) => DecodedPayload::EvidenceBound(value),
        PersistedPayload::VerificationRecorded(value) => {
            DecodedPayload::VerificationRecorded(value)
        }
        PersistedPayload::DecisionRecorded(value) => DecodedPayload::DecisionRecorded(value),
        PersistedPayload::FindingRecorded(value) => DecodedPayload::FindingRecorded(value),
        PersistedPayload::RunGenesisManifest(value) => DecodedPayload::RunGenesisManifest(value),
        PersistedPayload::RunGenesisManifestV3(value) => {
            DecodedPayload::RunGenesisManifestV3(value)
        }
        PersistedPayload::ArtifactRegistered(value) => DecodedPayload::ArtifactRegistered(value),
        PersistedPayload::ArtifactRegisteredV3(value) => {
            DecodedPayload::ArtifactRegisteredV3(value)
        }
        PersistedPayload::EvidenceRecordedV3(value) => DecodedPayload::EvidenceRecordedV3(value),
        PersistedPayload::EvidenceBoundV3(value) => DecodedPayload::EvidenceBoundV3(value),
        PersistedPayload::VerificationRecordedV3(value) => {
            DecodedPayload::VerificationRecordedV3(value)
        }
        PersistedPayload::DecisionRecordedV3(value) => DecodedPayload::DecisionRecordedV3(value),
        PersistedPayload::FindingRecordedV3(value) => DecodedPayload::FindingRecordedV3(value),
        PersistedPayload::SnapshotSourcesRecorded(value) => {
            DecodedPayload::SnapshotSourcesRecorded(value)
        }
        PersistedPayload::ReviewPlanRecorded(value) => DecodedPayload::ReviewPlanRecorded(value),
        PersistedPayload::ContextEnvelopeProjected(value) => {
            DecodedPayload::ContextEnvelopeProjected(value)
        }
        PersistedPayload::ReviewExecutionRecorded(value) => {
            DecodedPayload::ReviewExecutionRecorded {
                execution: value.execution,
                claims: value.claims,
            }
        }
        PersistedPayload::RunGenesisManifestV4(_)
        | PersistedPayload::ArtifactRegisteredV4(_)
        | PersistedPayload::GluingBundleRecordedV4(_)
        | PersistedPayload::IncrementalSourceBoundV5(_)
        | PersistedPayload::ProgramMappingRecordedV5(_)
        | PersistedPayload::ChangeMorphismSealedV5(_)
        | PersistedPayload::ObligationCorrespondenceEntryRecordedV5(_)
        | PersistedPayload::ObligationCorrespondenceSealedV5(_)
        | PersistedPayload::HistoricalRecordAssessedV5(_)
        | PersistedPayload::GluingFreshnessRecordedV5(_)
        | PersistedPayload::StalenessAssessmentSealedV5(_)
        | PersistedPayload::ArtifactRegisteredV5(_)
        | PersistedPayload::PreservationVerifiedV5 { .. }
        | PersistedPayload::PartialRerunActionRecordedV5(_)
        | PersistedPayload::PartialRerunPlanSealedV5(_)
        | PersistedPayload::GluingRerunActionRecordedV5(_)
        | PersistedPayload::GluingRerunPlanSealedV5(_)
        | PersistedPayload::TerminalCompletedV5(_) => {
            unreachable!("v4 payloads are not exposed through the legacy EventLog decoder")
        }
    }
}

/// The kind of a record retained by an offline projection without making it
/// part of the accepted aggregate.
#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub enum UnreconciledRecordKind {
    /// Separately stored evidence.
    Evidence,
    /// A claim-to-evidence link.
    EvidenceBinding,
    /// A verifier outcome.
    Verification,
    /// A human authority decision.
    Decision,
    /// A D2 execution whose raw CAS bytes were unavailable offline.
    ReviewExecution,
}

/// Safe, typed index metadata for a record which has not been reconciled into
/// accepted aggregate state.  The record body remains private to the
/// projection so callers cannot mistake it for an accepted review fact.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct UnreconciledRecordMetadata {
    kind: UnreconciledRecordKind,
    id: StableId,
    body_hash: ContentHash,
    authority_reconciled: bool,
}

impl UnreconciledRecordMetadata {
    /// Persisted record kind.
    #[must_use]
    pub fn kind(&self) -> UnreconciledRecordKind {
        self.kind
    }

    /// Stable record identifier.
    #[must_use]
    pub fn id(&self) -> &StableId {
        &self.id
    }

    /// Hash of the canonical persisted payload body.
    #[must_use]
    pub fn body_hash(&self) -> &ContentHash {
        &self.body_hash
    }

    /// Always false until an explicit reconciliation path is added.
    #[must_use]
    pub const fn authority_reconciled(&self) -> bool {
        self.authority_reconciled
    }
}

/// Authority-free finding metadata projected against the private authority
/// shadow. It is intentionally distinct from unreconciled authority records.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProjectedFindingMetadata {
    id: StableId,
    body_hash: ContentHash,
}

/// Metadata-only context projection retained during offline replay. The
/// envelope body stays private and never enters the live aggregate map.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProjectedContextEnvelopeMetadata {
    id: StableId,
    projection_hash: ContentHash,
    body_hash: ContentHash,
}

impl ProjectedContextEnvelopeMetadata {
    #[must_use]
    pub fn id(&self) -> &StableId {
        &self.id
    }

    #[must_use]
    pub fn projection_hash(&self) -> &ContentHash {
        &self.projection_hash
    }

    #[must_use]
    pub fn body_hash(&self) -> &ContentHash {
        &self.body_hash
    }
}

impl ProjectedFindingMetadata {
    #[must_use]
    pub fn id(&self) -> &StableId {
        &self.id
    }

    #[must_use]
    pub fn body_hash(&self) -> &ContentHash {
        &self.body_hash
    }
}

/// Semantic projection state for offline indexing. Authority-bearing records
/// are validated against a private shadow overlay, never replayed into the
/// accepted aggregate because an offline store cannot mint their admissions.
#[derive(Clone, Debug)]
pub struct OfflineProjectionState {
    version: EventContractVersion,
    run_id: StableId,
    genesis_hash: ContentHash,
    next_sequence: u64,
    previous_event_hash: ContentHash,
    expected_events: Option<Vec<OfflineExpectedEvent>>,
    aggregate: ReviewAggregate,
    unreconciled_records: BTreeMap<StableId, PersistedPayload>,
    unreconciled_metadata: BTreeMap<StableId, UnreconciledRecordMetadata>,
    projected_findings: BTreeMap<StableId, Finding>,
    projected_finding_metadata: BTreeMap<StableId, ProjectedFindingMetadata>,
    projected_context_metadata: BTreeMap<StableId, ProjectedContextEnvelopeMetadata>,
    /// Structured D2 execution scope retained only to validate the later
    /// authority-free lifecycle transition while the execution itself remains
    /// an offline shadow.  This never promotes the execution or its claims
    /// into accepted aggregate state.
    shadow_structured_execution_obligations: BTreeSet<StableId>,
    unreconciled_order: Vec<StableId>,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct OfflineExpectedEvent {
    id: StableId,
    event_hash: ContentHash,
}

impl OfflineProjectionState {
    /// Seeds offline semantic validation only from a view whose immutable
    /// genesis has already been verified at the durable boundary.
    pub fn new(view: &ValidatedEventView<'_>, initial: ReviewAggregate) -> Result<Self> {
        if view.version == EventContractVersion::V3 {
            return Err(DomainError::EventV3AuthorityReplayRequired {
                operation: "offline projection",
            });
        }
        view.validate_initial(&initial)?;
        Ok(Self {
            version: view.version,
            run_id: view.run_id.clone(),
            genesis_hash: view.genesis_hash.clone(),
            next_sequence: 1,
            previous_event_hash: event_chain_genesis_hash(&view.run_id, &view.genesis_hash)?,
            expected_events: Some(
                view.events
                    .iter()
                    .map(|event| OfflineExpectedEvent {
                        id: event.envelope.id.clone(),
                        event_hash: event.envelope.event_hash.clone(),
                    })
                    .collect(),
            ),
            aggregate: initial,
            unreconciled_records: BTreeMap::new(),
            unreconciled_metadata: BTreeMap::new(),
            projected_findings: BTreeMap::new(),
            projected_finding_metadata: BTreeMap::new(),
            projected_context_metadata: BTreeMap::new(),
            shadow_structured_execution_obligations: BTreeSet::new(),
            unreconciled_order: Vec::new(),
        })
    }

    /// Seeds a V2 projection whose envelopes will be validated and decoded
    /// one at a time by a lock-held durable stream reader.
    pub fn new_streaming_v2(
        run_id: &StableId,
        verified_genesis: &VerifiedV2Genesis,
        initial: ReviewAggregate,
    ) -> Result<Self> {
        if verified_genesis.run_id() != run_id {
            return Err(DomainError::EventSequence(
                "streaming projection run does not match verified genesis".to_owned(),
            ));
        }
        verified_genesis.validate_pristine_aggregate(&initial)?;
        let genesis_hash = verified_genesis.genesis_hash().clone();
        Ok(Self {
            version: EventContractVersion::V2,
            run_id: run_id.clone(),
            next_sequence: 1,
            previous_event_hash: event_chain_genesis_hash(run_id, &genesis_hash)?,
            genesis_hash,
            expected_events: None,
            aggregate: initial,
            unreconciled_records: BTreeMap::new(),
            unreconciled_metadata: BTreeMap::new(),
            projected_findings: BTreeMap::new(),
            projected_finding_metadata: BTreeMap::new(),
            projected_context_metadata: BTreeMap::new(),
            shadow_structured_execution_obligations: BTreeSet::new(),
            unreconciled_order: Vec::new(),
        })
    }

    /// Applies the next exact validated-view event atomically. Returns `true`
    /// only when an authority-free event is applied to the accepted aggregate.
    /// Returns `false` when either an authority-bearing event is retained as
    /// unreconciled shadow metadata, or an authority-free `FindingRecorded`
    /// is validated against that shadow and retained as projected-finding
    /// metadata. Neither `false` case promotes state into the accepted
    /// aggregate.
    pub fn apply(&mut self, event: &ValidatedEvent<'_>) -> Result<bool> {
        let envelope = event.envelope();
        if let Some(expected_events) = &self.expected_events {
            let expected = expected_events
                .get(usize::try_from(self.next_sequence - 1).map_err(|_| {
                    DomainError::EventSequence(
                        "offline projection sequence does not fit usize".to_owned(),
                    )
                })?)
                .ok_or_else(|| {
                    DomainError::EventSequence(
                        "offline projection cannot apply an event beyond its validated view"
                            .to_owned(),
                    )
                })?;
            if envelope.id != expected.id || envelope.event_hash != expected.event_hash {
                return Err(DomainError::EventSequence(
                    "offline projection event is not the expected validated-view event".to_owned(),
                ));
            }
        }
        if envelope.run_id != self.run_id
            || envelope.genesis_hash != self.genesis_hash
            || envelope.sequence != self.next_sequence
            || envelope.previous_event_hash != self.previous_event_hash
        {
            return Err(DomainError::EventSequence(
                "offline projection event does not continue its validated view cursor".to_owned(),
            ));
        }
        if EventContractVersion::parse(&event.envelope().schema)? != self.version {
            return Err(DomainError::EventSequence(
                "offline projection event schema does not match its validated view contract"
                    .to_owned(),
            ));
        }
        let payload = match event.payload() {
            DecodedPayload::EvidenceRecorded(value) => {
                return self.apply_unreconciled(
                    PersistedPayload::EvidenceRecorded(Box::new(value.clone())),
                    envelope,
                    event.envelope().actor(),
                );
            }
            DecodedPayload::EvidenceBound(value) => {
                return self.apply_unreconciled(
                    PersistedPayload::EvidenceBound(value.clone()),
                    envelope,
                    event.envelope().actor(),
                );
            }
            DecodedPayload::VerificationRecorded(value) => {
                return self.apply_unreconciled(
                    PersistedPayload::VerificationRecorded(value.clone()),
                    envelope,
                    event.envelope().actor(),
                );
            }
            DecodedPayload::DecisionRecorded(value) => {
                return self.apply_unreconciled(
                    PersistedPayload::DecisionRecorded(value.clone()),
                    envelope,
                    event.envelope().actor(),
                );
            }
            DecodedPayload::ObligationTransition {
                obligation_id,
                next,
            } => PersistedPayload::ObligationTransition {
                obligation_id: obligation_id.clone(),
                next: *next,
            },
            DecodedPayload::ClaimProposed(value) => PersistedPayload::ClaimProposed(value.clone()),
            DecodedPayload::FindingRecorded(value) => {
                return self.apply_projected_finding(
                    value.clone(),
                    envelope,
                    event.envelope().actor(),
                );
            }
            DecodedPayload::RunGenesisManifest(value) => {
                PersistedPayload::RunGenesisManifest(value.clone())
            }
            DecodedPayload::RunGenesisManifestV3(_)
            | DecodedPayload::ArtifactRegisteredV3(_)
            | DecodedPayload::EvidenceRecordedV3(_)
            | DecodedPayload::EvidenceBoundV3(_)
            | DecodedPayload::VerificationRecordedV3(_)
            | DecodedPayload::DecisionRecordedV3(_)
            | DecodedPayload::FindingRecordedV3(_) => {
                return Err(DomainError::EventV3AuthorityReplayRequired {
                    operation: "offline apply",
                });
            }
            DecodedPayload::ArtifactRegistered(value) => {
                PersistedPayload::ArtifactRegistered(value.clone())
            }
            DecodedPayload::SnapshotSourcesRecorded(value) => {
                PersistedPayload::SnapshotSourcesRecorded(value.clone())
            }
            DecodedPayload::ReviewPlanRecorded(value) => {
                PersistedPayload::ReviewPlanRecorded(value.clone())
            }
            DecodedPayload::ContextEnvelopeProjected(value) => {
                return self.apply_projected_context(value.clone(), envelope);
            }
            DecodedPayload::ReviewExecutionRecorded { execution, claims } => {
                return self.apply_unreconciled(
                    PersistedPayload::ReviewExecutionRecorded(ReviewExecutionRecorded {
                        execution: execution.clone(),
                        claims: claims.clone(),
                    }),
                    envelope,
                    event.envelope().actor(),
                );
            }
        };
        reject_v2_legacy_execution_payload(self.version, &payload)?;
        validate_v2_completed_transition_with_shadow(
            self.version,
            &self.aggregate,
            &self.shadow_structured_execution_obligations,
            &payload,
        )?;
        reject_duplicate_d1_record(&self.aggregate, &payload)?;
        payload.validate_for_enclosing_run(&self.run_id)?;
        let mut next = self.aggregate.clone();
        apply(
            &mut next,
            &payload,
            event.envelope().actor(),
            &self.run_id,
            None,
        )?;
        next.validate()?;
        self.aggregate = next;
        self.advance_offline_cursor(envelope)?;
        Ok(true)
    }

    fn advance_offline_cursor(&mut self, envelope: &EventEnvelope) -> Result<()> {
        self.previous_event_hash = envelope.event_hash.clone();
        self.next_sequence = self.next_sequence.checked_add(1).ok_or_else(|| {
            DomainError::EventSequence("offline projection sequence overflow".to_owned())
        })?;
        Ok(())
    }

    fn apply_unreconciled(
        &mut self,
        payload: PersistedPayload,
        envelope: &EventEnvelope,
        actor: &str,
    ) -> Result<bool> {
        reject_v2_legacy_execution_payload(self.version, &payload)?;
        validate_v2_completed_transition(self.version, &self.aggregate, &payload)?;
        payload.validate_shape()?;
        payload.validate_for_enclosing_run(&self.run_id)?;
        let (kind, id) = payload
            .unreconciled_kind_and_id()
            .map(|(kind, id)| (kind, id.clone()))
            .ok_or_else(|| {
                DomainError::Validation("offline shadow received a non-shadow payload".to_owned())
            })?;
        if self.unreconciled_records.contains_key(&id) || self.projected_findings.contains_key(&id)
        {
            if matches!(payload, PersistedPayload::ReviewExecutionRecorded(_)) {
                return Err(DomainError::IdCollision { id });
            }
            return Err(DomainError::Validation(format!(
                "offline shadow record ID collision: {id}"
            )));
        }
        if !matches!(payload, PersistedPayload::ReviewExecutionRecorded(_)) {
            let mut candidate = self.shadow_candidate()?;
            apply(&mut candidate, &payload, actor, &self.run_id, None)?;
            candidate.validate()?;
        } else if let PersistedPayload::ReviewExecutionRecorded(recorded) = &payload {
            self.aggregate.validate_offline_execution_shadow(
                &self.run_id,
                &recorded.execution,
                &recorded.claims,
            )?;
        }
        let metadata = UnreconciledRecordMetadata {
            kind,
            id: id.clone(),
            body_hash: ContentHash::sha256(&canonical_json(&payload)?),
            authority_reconciled: false,
        };
        self.unreconciled_records.insert(id.clone(), payload);
        self.unreconciled_metadata.insert(id.clone(), metadata);
        if let Some(PersistedPayload::ReviewExecutionRecorded(ReviewExecutionRecorded {
            execution,
            ..
        })) = self.unreconciled_records.get(&id)
            && execution.outcome().is_structured()
        {
            self.shadow_structured_execution_obligations
                .extend(execution.obligation_ids().iter().cloned());
        }
        self.unreconciled_order.push(id.clone());
        self.advance_offline_cursor(envelope)?;
        Ok(false)
    }

    fn apply_projected_finding(
        &mut self,
        finding: Finding,
        envelope: &EventEnvelope,
        actor: &str,
    ) -> Result<bool> {
        let id = finding.id().clone();
        if self.unreconciled_records.contains_key(&id) || self.projected_findings.contains_key(&id)
        {
            return Err(DomainError::Validation(format!(
                "offline shadow record ID collision: {id}"
            )));
        }
        let payload = PersistedPayload::FindingRecorded(finding.clone());
        let mut candidate = self.shadow_candidate()?;
        apply(&mut candidate, &payload, actor, &self.run_id, None)?;
        candidate.validate()?;
        self.projected_finding_metadata.insert(
            id.clone(),
            ProjectedFindingMetadata {
                id: id.clone(),
                body_hash: ContentHash::sha256(&canonical_json(&payload)?),
            },
        );
        self.projected_findings.insert(id.clone(), finding);
        self.unreconciled_order.push(id);
        self.advance_offline_cursor(envelope)?;
        Ok(false)
    }

    fn apply_projected_context(
        &mut self,
        context: ReviewContextEnvelope,
        envelope: &EventEnvelope,
    ) -> Result<bool> {
        context.validate_for_event(&self.aggregate)?;
        let id = context.id().clone();
        if self.projected_context_metadata.contains_key(&id) {
            return Err(DomainError::IdCollision { id });
        }
        let bytes = context.canonical_bytes().map_err(context_domain_error)?;
        self.projected_context_metadata.insert(
            id.clone(),
            ProjectedContextEnvelopeMetadata {
                id: id.clone(),
                projection_hash: context.projection_hash().clone(),
                body_hash: ContentHash::sha256(&bytes),
            },
        );
        // The canonical envelope metadata is retained privately in the
        // authority-free aggregate so later D2 execution/claim events can
        // close their references during offline replay. No runtime admission
        // or reviewer-resume capability is created by this metadata replay.
        self.aggregate.record_offline_execution_envelope(context)?;
        self.advance_offline_cursor(envelope)?;
        Ok(false)
    }

    fn shadow_candidate(&self) -> Result<ReviewAggregate> {
        let mut candidate = self.aggregate.clone();
        for id in &self.unreconciled_order {
            if let Some(payload) = self.unreconciled_records.get(id) {
                if !matches!(payload, PersistedPayload::ReviewExecutionRecorded(_)) {
                    apply(&mut candidate, payload, payload.actor(), &self.run_id, None)?;
                }
            } else if let Some(finding) = self.projected_findings.get(id) {
                apply(
                    &mut candidate,
                    &PersistedPayload::FindingRecorded(finding.clone()),
                    SYSTEM_ACTOR,
                    &self.run_id,
                    None,
                )?;
            } else {
                return Err(DomainError::Validation(
                    "offline shadow order references a missing record".to_owned(),
                ));
            }
        }
        candidate.validate()?;
        Ok(candidate)
    }

    #[must_use]
    pub fn aggregate(&self) -> &ReviewAggregate {
        &self.aggregate
    }

    /// Returns metadata only; no unreconciled authority record is exposed as
    /// accepted aggregate state.
    #[must_use]
    pub fn unreconciled_records(&self) -> Vec<&UnreconciledRecordMetadata> {
        self.unreconciled_order
            .iter()
            .filter_map(|id| self.unreconciled_metadata.get(id))
            .collect()
    }

    /// Returns authority-free findings validated against the private shadow.
    #[must_use]
    pub fn projected_findings(&self) -> Vec<&ProjectedFindingMetadata> {
        self.unreconciled_order
            .iter()
            .filter_map(|id| self.projected_finding_metadata.get(id))
            .collect()
    }

    /// Returns metadata only. No offline replay path exposes a live context
    /// envelope or a context admission.
    #[must_use]
    pub fn projected_context_envelopes(&self) -> Vec<&ProjectedContextEnvelopeMetadata> {
        self.projected_context_metadata.values().collect()
    }

    /// Whether every event in the bound validated view has been applied.
    #[must_use]
    pub fn is_complete(&self) -> bool {
        self.expected_events.as_ref().is_some_and(|events| {
            usize::try_from(self.next_sequence - 1).is_ok_and(|count| count == events.len())
        })
    }

    /// Confirms the terminal cursor for a streaming projection after the
    /// durable reader has issued its complete-prefix certificate.
    #[must_use]
    pub fn streaming_cursor_matches(&self, event_count: u64, tail_hash: &ContentHash) -> bool {
        self.expected_events.is_none()
            && self.next_sequence.checked_sub(1) == Some(event_count)
            && &self.previous_event_hash == tail_hash
    }

    /// The hash at the projection cursor; on completion this equals the
    /// validated view's tail event hash (or its chain-genesis hash when empty).
    #[must_use]
    pub fn tail_hash(&self) -> &ContentHash {
        &self.previous_event_hash
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawEventEnvelope {
    schema: String,
    id: StableId,
    run_id: StableId,
    genesis_hash: ContentHash,
    sequence: u64,
    actor: String,
    logical_time: u64,
    payload: Box<RawValue>,
    payload_hash: ContentHash,
    previous_event_hash: ContentHash,
    event_hash: ContentHash,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct RawPayloadHeader<'a> {
    #[serde(rename = "type", borrow)]
    kind: &'a str,
    #[serde(borrow)]
    data: &'a RawValue,
}

fn decode_payload(version: EventContractVersion, input: &str) -> Result<PersistedPayload> {
    let raw: RawPayloadHeader<'_> =
        serde_json::from_str(input).map_err(|error| DomainError::Json(error.to_string()))?;
    if matches!(
        raw.kind,
        "review_plan_recorded" | "context_envelope_projected" | "review_execution_recorded"
    ) {
        return match raw.kind {
            "review_plan_recorded" => Ok(PersistedPayload::ReviewPlanRecorded(
                ReviewPlan::from_event_bytes(raw.data.get().as_bytes())?,
            )),
            "context_envelope_projected" => Ok(PersistedPayload::ContextEnvelopeProjected(
                ReviewContextEnvelope::from_event_bytes(raw.data.get().as_bytes())
                    .map_err(context_domain_error)?,
            )),
            "review_execution_recorded" => {
                preflight_d2_decode_working(raw.data.get().as_bytes(), MAX_D2_WORKING_BYTES)?;
                let recorded: ReviewExecutionRecorded = serde_json::from_str(raw.data.get())
                    .map_err(|error| DomainError::Json(error.to_string()))?;
                recorded.validate_shape()?;
                recorded.validate_decode_working(raw.data.get().len())?;
                Ok(PersistedPayload::ReviewExecutionRecorded(recorded))
            }
            _ => unreachable!("closed D1 kind checked"),
        };
    }
    if matches!(
        version,
        EventContractVersion::V3 | EventContractVersion::V4 | EventContractVersion::V5
    ) {
        let payload = match raw.kind {
            "run_genesis_manifest" if version == EventContractVersion::V3 => {
                PersistedPayload::RunGenesisManifestV3(
                    serde_json::from_str(raw.data.get())
                        .map_err(|error| DomainError::Json(error.to_string()))?,
                )
            }
            "run_genesis_manifest"
                if matches!(version, EventContractVersion::V4 | EventContractVersion::V5) =>
            {
                PersistedPayload::RunGenesisManifestV4(
                    serde_json::from_str(raw.data.get())
                        .map_err(|error| DomainError::Json(error.to_string()))?,
                )
            }
            "artifact_registered" => PersistedPayload::ArtifactRegisteredV3(
                serde_json::from_str(raw.data.get())
                    .map_err(|error| DomainError::Json(error.to_string()))?,
            ),
            "artifact_registered_v4"
                if matches!(version, EventContractVersion::V4 | EventContractVersion::V5) =>
            {
                PersistedPayload::ArtifactRegisteredV4(
                    serde_json::from_str(raw.data.get())
                        .map_err(|error| DomainError::Json(error.to_string()))?,
                )
            }
            "gluing_bundle_recorded_v4"
                if matches!(version, EventContractVersion::V4 | EventContractVersion::V5) =>
            {
                PersistedPayload::GluingBundleRecordedV4(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "incremental_source_bound_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::IncrementalSourceBoundV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "program_mapping_recorded_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::ProgramMappingRecordedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "change_morphism_sealed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::ChangeMorphismSealedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "obligation_correspondence_entry_recorded_v5"
                if version == EventContractVersion::V5 =>
            {
                PersistedPayload::ObligationCorrespondenceEntryRecordedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "obligation_correspondence_sealed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::ObligationCorrespondenceSealedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "historical_record_assessed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::HistoricalRecordAssessedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "gluing_freshness_recorded_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::GluingFreshnessRecordedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "staleness_assessment_sealed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::StalenessAssessmentSealedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "artifact_registered_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::ArtifactRegisteredV5(
                    crate::ArtifactRegistrationV5::from_json_bytes(raw.data.get().as_bytes())
                        .map_err(|error| DomainError::Validation(error.to_string()))?,
                )
            }
            "preservation_verified_v5" if version == EventContractVersion::V5 => {
                #[derive(Deserialize)]
                #[serde(deny_unknown_fields)]
                struct Wire {
                    evidence: crate::PreservationEvidenceV5,
                    verification: crate::PreservationVerificationV5,
                }
                let value: Wire = serde_json::from_str(raw.data.get())
                    .map_err(|error| DomainError::Json(error.to_string()))?;
                PersistedPayload::PreservationVerifiedV5 {
                    evidence: value.evidence,
                    verification: value.verification,
                }
            }
            "partial_rerun_action_recorded_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::PartialRerunActionRecordedV5(
                    crate::PartialRerunActionV5::from_json_bytes(raw.data.get().as_bytes())
                        .map_err(|error| DomainError::Validation(error.to_string()))?,
                )
            }
            "partial_rerun_plan_sealed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::PartialRerunPlanSealedV5(
                    crate::PartialRerunPlanV5::from_event_json_bytes(raw.data.get().as_bytes())
                        .map_err(|error| DomainError::Validation(error.to_string()))?,
                )
            }
            "gluing_rerun_action_recorded_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::GluingRerunActionRecordedV5(
                    crate::GluingRerunActionV5::from_event_json_bytes(raw.data.get().as_bytes())
                        .map_err(|error| DomainError::Validation(error.to_string()))?,
                )
            }
            "gluing_rerun_plan_sealed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::GluingRerunPlanSealedV5(
                    crate::GluingRerunPlanSealV5::from_event_json_bytes(raw.data.get().as_bytes())
                        .map_err(|error| DomainError::Validation(error.to_string()))?,
                )
            }
            "terminal_completed_v5" if version == EventContractVersion::V5 => {
                PersistedPayload::TerminalCompletedV5(raw_payload(
                    raw.data.get().as_bytes().to_vec(),
                )?)
            }
            "evidence_recorded_v3" => PersistedPayload::EvidenceRecordedV3(
                EvidenceV3::from_json_bytes(raw.data.get().as_bytes()).map_err(m4_domain_error)?,
            ),
            "evidence_bound_v3" => PersistedPayload::EvidenceBoundV3(
                EvidenceBindingV3::from_json_bytes(raw.data.get().as_bytes())
                    .map_err(m4_domain_error)?,
            ),
            "verification_recorded_v3" => PersistedPayload::VerificationRecordedV3(
                VerificationV3::from_json_bytes(raw.data.get().as_bytes())
                    .map_err(m4_domain_error)?,
            ),
            "decision_recorded_v3" => PersistedPayload::DecisionRecordedV3(
                DecisionV3::from_json_bytes(raw.data.get().as_bytes()).map_err(m4_domain_error)?,
            ),
            "finding_recorded_v3" => PersistedPayload::FindingRecordedV3(
                FindingV3::from_json_bytes(raw.data.get().as_bytes()).map_err(m4_domain_error)?,
            ),
            _ => {
                let legacy = decode_non_d1_legacy_payload(raw.kind, raw.data.get())?;
                if !legacy.allowed_in(version) {
                    return Err(DomainError::EventSequence(
                        "event-v3/v4 refuses a legacy authority or registration payload".to_owned(),
                    ));
                }
                legacy
            }
        };
        return Ok(payload);
    }
    decode_non_d1_legacy_payload(raw.kind, raw.data.get())
}

fn decode_non_d1_legacy_payload(kind: &str, input: &str) -> Result<PersistedPayload> {
    let data: Value =
        serde_json::from_str(input).map_err(|error| DomainError::Json(error.to_string()))?;
    match kind {
        "obligation_transition" => {
            #[derive(Deserialize)]
            #[serde(deny_unknown_fields)]
            struct RawTransition {
                obligation_id: StableId,
                next: ObligationLifecycle,
            }
            let data: RawTransition = serde_json::from_value(data)
                .map_err(|error| DomainError::Json(error.to_string()))?;
            Ok(PersistedPayload::ObligationTransition {
                obligation_id: data.obligation_id,
                next: data.next,
            })
        }
        "claim_proposed" => Ok(PersistedPayload::ClaimProposed(
            ReviewClaim::from_event_value(data)?,
        )),
        "evidence_recorded" => Ok(PersistedPayload::EvidenceRecorded(Box::new(
            Evidence::from_event_value(data)?,
        ))),
        "evidence_bound" => Ok(PersistedPayload::EvidenceBound(
            EvidenceBinding::from_event_value(data)?,
        )),
        "verification_recorded" => Ok(PersistedPayload::VerificationRecorded(
            Verification::from_event_value(data)?,
        )),
        "decision_recorded" => Ok(PersistedPayload::DecisionRecorded(
            Decision::from_event_value(data)?,
        )),
        "finding_recorded" => Ok(PersistedPayload::FindingRecorded(
            Finding::from_event_value(data)?,
        )),
        "run_genesis_manifest" => Ok(PersistedPayload::RunGenesisManifest(
            serde_json::from_value(data).map_err(|error| DomainError::Json(error.to_string()))?,
        )),
        "artifact_registered" => Ok(PersistedPayload::ArtifactRegistered(
            serde_json::from_value(data).map_err(|error| DomainError::Json(error.to_string()))?,
        )),
        "snapshot_sources_recorded" => Ok(PersistedPayload::SnapshotSourcesRecorded(
            serde_json::from_value(data).map_err(|error| DomainError::Json(error.to_string()))?,
        )),
        _ => Err(DomainError::EventSequence(
            "unknown persisted event payload type".to_owned(),
        )),
    }
}

fn decode_canonical_payload(
    version: EventContractVersion,
    input: &str,
) -> Result<PersistedPayload> {
    #[cfg(test)]
    V3_TEST_REPLAY_DECODE_SCOPE_ACTIVE.with(|active| {
        if active.get() {
            V3_TEST_REPLAY_PAYLOAD_DECODE_COUNT.with(|value| value.set(value.get() + 1));
        }
    });
    let payload = decode_payload(version, input)?;
    if !payload.allowed_in(version) {
        return Err(DomainError::EventSequence(
            "persisted payload is not admitted by this event contract version".to_owned(),
        ));
    }
    if payload.is_m6_v5() {
        payload.validate_shape()?;
    }
    let canonical_raw = input.as_bytes();
    let canonical_typed = payload_canonical_bytes(&payload)?;
    if canonical_raw != canonical_typed {
        return Err(DomainError::EventSequence(
            "persisted event payload must equal the canonical closed payload representation"
                .to_owned(),
        ));
    }
    Ok(payload)
}

/// Private contextual decoder contract for the future single atomic execution
/// position of a sealed scheduled M6 reviewer action. It performs no append.
/// Every general replay/index/offline caller continues to use
/// `decode_canonical_payload` and therefore rejects structured zero-claim
/// records under frozen D2 policy.
#[allow(dead_code)] // Consumed by the scheduled-position recovery FSM in the next unit.
fn decode_canonical_scheduled_m6_execution_payload(input: &str) -> Result<PersistedPayload> {
    let raw: RawPayloadHeader<'_> =
        serde_json::from_str(input).map_err(|error| DomainError::Json(error.to_string()))?;
    if raw.kind != "review_execution_recorded" {
        return Err(DomainError::EventSequence(
            "scheduled M6 execution position requires review_execution_recorded".to_owned(),
        ));
    }
    let recorded = ReviewExecutionRecorded::from_event_bytes_for_m6(raw.data.get().as_bytes())?;
    let payload = PersistedPayload::ReviewExecutionRecorded(recorded);
    if input.as_bytes() != payload_canonical_bytes(&payload)? {
        return Err(DomainError::EventSequence(
            "scheduled M6 execution payload is not canonical".to_owned(),
        ));
    }
    Ok(payload)
}

#[cfg(test)]
pub(crate) fn decode_scheduled_m6_payload_for_test(input: &str) -> Result<()> {
    decode_canonical_scheduled_m6_execution_payload(input).map(|_| ())
}

#[cfg(test)]
pub(crate) fn generic_v5_payload_rejects_for_test(input: &str) -> bool {
    decode_payload(EventContractVersion::V5, input).is_err()
}

/// A validated immutable event. Its payload remains private; consumers may
/// retain the envelope and replay it through the validation boundary.
#[derive(Clone, Debug)]
pub struct Event {
    envelope: EventEnvelope,
    evidence_admission: Option<EvidenceAdmission>,
    binding_admission: Option<EvidenceBindingAdmission>,
    verification_admission: Option<VerificationAdmission>,
    decision_admission: Option<DecisionAdmission>,
    context_projection_admission: Option<PositionedContextProjectionAdmission>,
    reviewer_raw_closure: Option<ReviewerRawClosure>,
}

impl Event {
    fn retained_bytes(&self) -> Result<u64> {
        let mut total = u64::try_from(self.envelope.allocated_bytes()).unwrap_or(u64::MAX);
        let additions = [
            self.evidence_admission
                .as_ref()
                .map_or(0, EvidenceAdmission::allocated_bytes),
            self.binding_admission.as_ref().map_or(0, |value| {
                value.run_id.allocated_bytes()
                    + value.genesis_hash.allocated_bytes()
                    + value.tail_hash.allocated_bytes()
                    + value.binding_id.allocated_bytes()
                    + value.digest.allocated_bytes()
            }),
            self.verification_admission.as_ref().map_or(0, |value| {
                value.run_id.allocated_bytes()
                    + value.genesis_hash.allocated_bytes()
                    + value.tail_hash.allocated_bytes()
                    + value.verification_id.allocated_bytes()
                    + value.digest.allocated_bytes()
            }),
            self.decision_admission
                .as_ref()
                .map_or(0, DecisionAdmission::allocated_bytes),
            self.context_projection_admission
                .as_ref()
                .map_or(0, PositionedContextProjectionAdmission::allocated_bytes),
            self.reviewer_raw_closure
                .as_ref()
                .map_or(0, ReviewerRawClosure::allocated_bytes),
        ];
        for bytes in additions {
            v3_add(
                &mut total,
                u64::try_from(bytes).unwrap_or(u64::MAX),
                "event-v3 retained event",
            )?;
        }
        Ok(total)
    }

    #[must_use]
    pub fn envelope(&self) -> &EventEnvelope {
        &self.envelope
    }

    /// Retained non-serializable admission for exact evidence replay.
    #[must_use]
    pub fn evidence_admission(&self) -> Option<&EvidenceAdmission> {
        self.evidence_admission.as_ref()
    }

    /// Retained non-serializable admission for exact binding replay.
    #[must_use]
    pub fn binding_admission(&self) -> Option<&EvidenceBindingAdmission> {
        self.binding_admission.as_ref()
    }

    /// Retained non-serializable admission for exact verification replay.
    #[must_use]
    pub fn verification_admission(&self) -> Option<&VerificationAdmission> {
        self.verification_admission.as_ref()
    }

    /// Retained non-serializable admission for exact decision replay.
    #[must_use]
    pub fn decision_admission(&self) -> Option<&DecisionAdmission> {
        self.decision_admission.as_ref()
    }
}

fn event_vector_retained(events: &Vec<Event>) -> Result<u64> {
    let mut total =
        u64::try_from(events.capacity().saturating_mul(size_of::<Event>())).unwrap_or(u64::MAX);
    for event in events {
        v3_add(
            &mut total,
            event.retained_bytes()?,
            "event-v3 retained event shadow",
        )?;
    }
    Ok(total)
}

/// Private event-v3 state which deliberately stays separate from the frozen
/// v2 registration map embedded in `ReviewAggregate`. M4 assessments are added
/// in the following authority integration unit; this foundation owns only the
/// versioned manifest and exact registration namespace.
#[derive(Clone, Debug, Default)]
pub(crate) struct V3RunAggregate {
    genesis_manifest: Option<RunGenesisManifestV3>,
    registrations: BTreeMap<StableId, ArtifactRegisteredV3>,
    assessments: BTreeMap<StableId, crate::ClaimAssessmentV3>,
    assessment_scopes: BTreeMap<StableId, crate::m4::ClaimAssessmentScopeV3>,
    evidence: BTreeMap<StableId, EvidenceV3>,
    bindings: BTreeMap<StableId, EvidenceBindingV3>,
    verifications: BTreeMap<StableId, VerificationV3>,
    decisions: BTreeMap<StableId, DecisionV3>,
    findings: BTreeMap<StableId, FindingV3>,
}

