fn validate_repository_trust_root(
    aggregate: &ReviewAggregate,
    roots: &impl AuthorityTrustRootsV3View,
) -> Result<()> {
    let source_hash = aggregate
        .program()
        .repository_source()
        .content_hash()
        .ok_or(DomainError::AuthorityPolicyMismatch)?;
    if aggregate.program().repository_id() != roots.repository_id_view()
        || source_hash != roots.repository_source_hash_view()
    {
        return Err(DomainError::AuthorityPolicyMismatch);
    }
    Ok(())
}

fn resolve_registered_bytes(
    registration: &ArtifactRegisteredV3,
    resolver: &impl AuthorityArtifactResolverV3,
) -> Result<Vec<u8>> {
    resolve_registered_bytes_with(registration, |cas_hash, destination| {
        resolver.read_exact(cas_hash, destination)
    })
}

/// Shared position-independent CAS boundary for V3-family registrations.
/// Callers supply only their version-specific resolver capability; hash, size,
/// source-role cap, and canonical byte checks remain centralized here.
fn resolve_registered_bytes_with(
    registration: &ArtifactRegisteredV3,
    read_exact: impl FnOnce(&ContentHash, &mut [u8]) -> Result<()>,
) -> Result<Vec<u8>> {
    let limit = match registration.source() {
        ArtifactSourceV3::VerifierArtifact { .. } => crate::m4::MAX_RECORD_BYTES as u64,
        ArtifactSourceV3::ExternalHarnessWitness { .. } => 145,
        ArtifactSourceV3::ReviewerExecution { .. } => {
            crate::execution::MAX_D2_RAW_REVIEWER_BYTES as u64
        }
        ArtifactSourceV3::SnapshotIngest { .. } => 1_048_576,
        ArtifactSourceV3::RunGenesis { .. } => {
            return Err(DomainError::Validation(
                "genesis bytes must come from the canonical replay input".to_owned(),
            ));
        }
    };
    rebuild_exact_cas_bytes(
        registration.cas_hash(),
        registration.size(),
        limit,
        "event-v3 role-specific CAS bytes",
        read_exact,
    )
}

/// Rebuilds one immutable, pre-sized CAS object and rechecks its registered
/// hash. V3 inherited-authority replay and V4 gluing-context replay share
/// this exact byte boundary; resolver metadata never contributes authority.
fn rebuild_exact_cas_bytes(
    cas_hash: &ContentHash,
    object_size: u64,
    limit: u64,
    operation: &'static str,
    read_exact: impl FnOnce(&ContentHash, &mut [u8]) -> Result<()>,
) -> Result<Vec<u8>> {
    if object_size > limit {
        return Err(DomainError::Incomplete {
            operation,
            limit: usize::try_from(limit).unwrap_or(usize::MAX),
            observed: usize::try_from(object_size).unwrap_or(usize::MAX),
        });
    }
    let size = usize::try_from(object_size).map_err(|_| DomainError::Incomplete {
        operation,
        limit: usize::try_from(limit).unwrap_or(usize::MAX),
        observed: usize::MAX,
    })?;
    let mut bytes = Vec::new();
    bytes
        .try_reserve_exact(size)
        .map_err(|_| DomainError::Incomplete {
            operation,
            limit: size,
            observed: size,
        })?;
    bytes.resize(size, 0);
    read_exact(cas_hash, &mut bytes)?;
    if ContentHash::sha256(&bytes) != *cas_hash {
        return Err(DomainError::Validation(
            "resolved CAS bytes do not match the registered hash and size".to_owned(),
        ));
    }
    Ok(bytes)
}

/// Rebuilds the exact deterministic D1 context envelope from its ordered CAS
/// sources. V3 and V4 replay deliberately share this reducer: context bytes
/// are not trusted merely because an envelope decoded or an event hashes.
fn rebuild_context_projection_from_cas(
    aggregate: &ReviewAggregate,
    expected: &ReviewContextEnvelope,
    read_exact: impl FnMut(&ContentHash, &mut [u8]) -> Result<()>,
    observe_source: impl FnMut(u64) -> Result<()>,
) -> Result<(
    ReviewContextEnvelope,
    crate::context::ContextProjectionAdmission,
)> {
    rebuild_context_projection_from_cas_with_sealed_gate(
        aggregate,
        expected,
        |_| Ok(()),
        read_exact,
        observe_source,
    )
}

/// Variant used by V5 D2 replay to inspect the allocator-sealed context
/// reservation. The gate runs after `prepare_context` has reserved every
/// arena, but before `next_source_request` can expose a request or trigger a
/// CAS allocation/read. Historical V3/V4 replay uses the no-op wrapper above.
fn rebuild_context_projection_from_cas_with_sealed_gate(
    aggregate: &ReviewAggregate,
    expected: &ReviewContextEnvelope,
    mut observe_sealed: impl FnMut(crate::context::ContextResourceOracle) -> Result<()>,
    mut read_exact: impl FnMut(&ContentHash, &mut [u8]) -> Result<()>,
    mut observe_source: impl FnMut(u64) -> Result<()>,
) -> Result<(
    ReviewContextEnvelope,
    crate::context::ContextProjectionAdmission,
)> {
    let obligation_id = expected
        .obligation_ids()
        .first()
        .ok_or_else(|| DomainError::Validation("context envelope has no obligation".to_owned()))?;
    let mut session =
        crate::prepare_context(aggregate, obligation_id.clone()).map_err(context_domain_error)?;
    observe_sealed(session.sealed_resource_oracle())?;
    while let Some(request) = session
        .next_source_request()
        .map_err(context_domain_error)?
    {
        observe_source(request.expected_length())?;
        let bytes = rebuild_exact_cas_bytes(
            request.cas_hash(),
            request.expected_length(),
            1_048_576,
            "event context source bytes",
            |cas_hash, destination| read_exact(cas_hash, destination),
        )?;
        session
            .submit_source(&request, &bytes)
            .map_err(context_domain_error)?;
    }
    Ok(session.finish().map_err(context_domain_error)?.into_parts())
}

fn authority_record_identity(
    payload: &PersistedPayload,
) -> Result<Option<(&'static str, StableId, ContentHash)>> {
    let value = match payload {
        PersistedPayload::EvidenceRecordedV3(record) => (
            "evidence_recorded_v3",
            record.id().clone(),
            record.body_hash().map_err(m4_domain_error)?,
        ),
        PersistedPayload::EvidenceBoundV3(record) => (
            "evidence_bound_v3",
            record.id().clone(),
            record.body_hash().map_err(m4_domain_error)?,
        ),
        PersistedPayload::VerificationRecordedV3(record) => (
            "verification_recorded_v3",
            record.id().clone(),
            record.body_hash().map_err(m4_domain_error)?,
        ),
        PersistedPayload::DecisionRecordedV3(record) => (
            "decision_recorded_v3",
            record.id().clone(),
            record.body_hash().map_err(m4_domain_error)?,
        ),
        _ => return Ok(None),
    };
    Ok(Some(value))
}

fn selected_verifier_for_evidence_v4<'a>(
    state: &V3RunAggregate,
    roots: &'a AuthorityTrustRootsV4,
    evidence: &EvidenceV3,
) -> Result<SelectedVerifierAuthorityV4<'a>> {
    match evidence.descriptor() {
        crate::VerifierDescriptorV3::StaticFactV1 => Ok(SelectedVerifierAuthorityV4::Static {
            policy_revision_hash: &roots.policy_revision_hash,
            repository_id: &roots.repository_id,
            repository_source_hash: &roots.repository_source_hash,
        }),
        crate::VerifierDescriptorV3::FixedFixtureV1 => {
            let input = state
                .registrations
                .get(evidence.input_registration_id())
                .ok_or_else(|| DomainError::DanglingReference {
                    owner: "v4 inherited evidence input",
                    owner_id: evidence.id().clone(),
                    reference: evidence.input_registration_id().clone(),
                })?;
            roots
                .harness_for_source(input)
                .map(SelectedVerifierAuthorityV4::Harness)
                .ok_or(DomainError::HarnessTrustRootMissing)
        }
    }
}

fn selected_verifier_for_verification_v4<'a>(
    state: &V3RunAggregate,
    roots: &'a AuthorityTrustRootsV4,
    verification: &VerificationV3,
) -> Result<SelectedVerifierAuthorityV4<'a>> {
    let Some(evidence_id) = verification.evidence_ids().first() else {
        return Ok(SelectedVerifierAuthorityV4::Static {
            policy_revision_hash: &roots.policy_revision_hash,
            repository_id: &roots.repository_id,
            repository_source_hash: &roots.repository_source_hash,
        });
    };
    let evidence =
        state
            .evidence
            .get(evidence_id)
            .ok_or_else(|| DomainError::DanglingReference {
                owner: "v4 inherited verification",
                owner_id: verification.id().clone(),
                reference: evidence_id.clone(),
            })?;
    selected_verifier_for_evidence_v4(state, roots, evidence)
}

fn inherited_authority_preimage_v4<'a>(
    state: &V3RunAggregate,
    roots: &'a AuthorityTrustRootsV4,
    payload: &PersistedPayload,
) -> Result<Option<InheritedAuthorityPreimageV4<'a>>> {
    let value = match payload {
        PersistedPayload::EvidenceRecordedV3(evidence) => InheritedAuthorityPreimageV4 {
            verifier: Some(selected_verifier_for_evidence_v4(state, roots, evidence)?),
            human: None,
        },
        PersistedPayload::EvidenceBoundV3(binding) => {
            let evidence = state.evidence.get(binding.evidence_id()).ok_or_else(|| {
                DomainError::DanglingReference {
                    owner: "v4 inherited binding",
                    owner_id: binding.id().clone(),
                    reference: binding.evidence_id().clone(),
                }
            })?;
            let verifier = selected_verifier_for_evidence_v4(state, roots, evidence)?;
            if let SelectedVerifierAuthorityV4::Harness(root) = &verifier
                && binding.claim_id() != &root.claim_id
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
            InheritedAuthorityPreimageV4 {
                verifier: Some(verifier),
                human: None,
            }
        }
        PersistedPayload::VerificationRecordedV3(verification) => {
            let verifier = selected_verifier_for_verification_v4(state, roots, verification)?;
            if let SelectedVerifierAuthorityV4::Harness(root) = &verifier
                && verification.claim_id() != &root.claim_id
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
            InheritedAuthorityPreimageV4 {
                verifier: Some(verifier),
                human: None,
            }
        }
        PersistedPayload::DecisionRecordedV3(decision) => InheritedAuthorityPreimageV4 {
            verifier: None,
            human: Some(
                roots
                    .human_grant_for(decision)
                    .ok_or(DomainError::HumanTrustRootMissing)?,
            ),
        },
        _ => return Ok(None),
    };
    Ok(Some(value))
}

fn verifier_registration_matches(
    registration: &ArtifactRegisteredV3,
    claim_id: &StableId,
    descriptor_id: &str,
    procedure_version: &str,
    role: VerifierArtifactRoleV3,
) -> bool {
    matches!(
        registration.source(),
        ArtifactSourceV3::VerifierArtifact {
            run_id,
            claim_id: registered_claim,
            descriptor_id: registered_descriptor,
            procedure_version: registered_procedure,
            role: registered_role,
        } if run_id == registration.run_id()
            && registered_claim == claim_id
            && registered_descriptor == descriptor_id
            && registered_procedure == procedure_version
            && *registered_role == role
    )
}

fn evidence_trust_digest(
    state: &V3RunAggregate,
    roots: &impl AuthorityTrustRootsV3View,
    evidence: &EvidenceV3,
) -> Result<ContentHash> {
    let input = state
        .registrations
        .get(evidence.input_registration_id())
        .ok_or_else(|| DomainError::DanglingReference {
            owner: "v3 evidence input",
            owner_id: evidence.id().clone(),
            reference: evidence.input_registration_id().clone(),
        })?;
    let output = state
        .registrations
        .get(evidence.output_registration_id())
        .ok_or_else(|| DomainError::DanglingReference {
            owner: "v3 evidence output",
            owner_id: evidence.id().clone(),
            reference: evidence.output_registration_id().clone(),
        })?;
    match evidence.descriptor() {
        crate::VerifierDescriptorV3::StaticFactV1 => {
            let claim_id = match input.source() {
                ArtifactSourceV3::VerifierArtifact { claim_id, .. } => claim_id,
                _ => return Err(DomainError::VerificationBundleMismatch),
            };
            if !verifier_registration_matches(
                input,
                claim_id,
                STATIC_DESCRIPTOR_ID,
                STATIC_PROCEDURE_ID,
                VerifierArtifactRoleV3::Input,
            ) || !verifier_registration_matches(
                output,
                claim_id,
                STATIC_DESCRIPTOR_ID,
                STATIC_PROCEDURE_ID,
                VerifierArtifactRoleV3::Output,
            ) {
                return Err(DomainError::VerificationBundleMismatch);
            }
            static_trust_digest(roots)
        }
        crate::VerifierDescriptorV3::FixedFixtureV1 => {
            let root = roots
                .harness_for_source_view(input)
                .ok_or(DomainError::HarnessTrustRootMissing)?;
            if !verifier_registration_matches(
                output,
                root.claim_id,
                FIXTURE_DESCRIPTOR_ID,
                FIXTURE_PROCEDURE_ID,
                VerifierArtifactRoleV3::Output,
            ) {
                return Err(DomainError::VerificationBundleMismatch);
            }
            trust_digest_for_harness(root)
        }
    }
}

fn authority_trust_digest(
    state: &V3RunAggregate,
    roots: &impl AuthorityTrustRootsV3View,
    payload: &PersistedPayload,
) -> Result<Option<ContentHash>> {
    match payload {
        PersistedPayload::EvidenceRecordedV3(evidence) => {
            evidence_trust_digest(state, roots, evidence).map(Some)
        }
        PersistedPayload::EvidenceBoundV3(binding) => {
            let evidence = state.evidence.get(binding.evidence_id()).ok_or_else(|| {
                DomainError::DanglingReference {
                    owner: "v3 authority binding",
                    owner_id: binding.id().clone(),
                    reference: binding.evidence_id().clone(),
                }
            })?;
            if evidence.descriptor() == crate::VerifierDescriptorV3::FixedFixtureV1 {
                let input = state
                    .registrations
                    .get(evidence.input_registration_id())
                    .ok_or(DomainError::VerificationBundleMismatch)?;
                let root = roots
                    .harness_for_source_view(input)
                    .ok_or(DomainError::HarnessTrustRootMissing)?;
                if binding.claim_id() != root.claim_id {
                    return Err(DomainError::VerificationBundleMismatch);
                }
            }
            evidence_trust_digest(state, roots, evidence).map(Some)
        }
        PersistedPayload::VerificationRecordedV3(verification) => {
            if let Some(evidence_id) = verification.evidence_ids().first() {
                let evidence = state.evidence.get(evidence_id).ok_or_else(|| {
                    DomainError::DanglingReference {
                        owner: "v3 authority verification",
                        owner_id: verification.id().clone(),
                        reference: evidence_id.clone(),
                    }
                })?;
                if evidence.descriptor() == crate::VerifierDescriptorV3::FixedFixtureV1 {
                    let input = state
                        .registrations
                        .get(evidence.input_registration_id())
                        .ok_or(DomainError::VerificationBundleMismatch)?;
                    let root = roots
                        .harness_for_source_view(input)
                        .ok_or(DomainError::HarnessTrustRootMissing)?;
                    if verification.claim_id() != root.claim_id {
                        return Err(DomainError::VerificationBundleMismatch);
                    }
                }
                evidence_trust_digest(state, roots, evidence).map(Some)
            } else {
                Ok(Some(static_trust_digest(roots)?))
            }
        }
        PersistedPayload::DecisionRecordedV3(decision) => {
            if decision.policy_revision_hash() != roots.policy_revision_hash_view() {
                return Err(DomainError::AuthorityPolicyMismatch);
            }
            roots
                .human_grant_for_view(decision)
                .ok_or(DomainError::HumanTrustRootMissing)
                .and_then(trust_digest_for_human)
                .map(Some)
        }
        _ => Ok(None),
    }
}

fn validate_authority_registration(
    aggregate: &ReviewAggregate,
    registration: &ArtifactRegisteredV3,
    bytes: &[u8],
    roots: &impl AuthorityTrustRootsV3View,
    expected_genesis_hash: &ContentHash,
) -> Result<()> {
    match registration.source() {
        ArtifactSourceV3::VerifierArtifact {
            claim_id,
            descriptor_id,
            role,
            ..
        } => {
            let claim = aggregate
                .execution_claims()
                .find(|claim| claim.id() == claim_id)
                .ok_or_else(|| DomainError::DanglingReference {
                    owner: "v3 verifier registration claim",
                    owner_id: registration.registration_id().clone(),
                    reference: claim_id.clone(),
                })?;
            let obligation_id = claim
                .obligation_ids()
                .first()
                .ok_or(DomainError::VerificationBundleMismatch)?;
            let obligation = aggregate.obligation(obligation_id).ok_or_else(|| {
                DomainError::DanglingReference {
                    owner: "v3 verifier registration obligation",
                    owner_id: registration.registration_id().clone(),
                    reference: obligation_id.clone(),
                }
            })?;
            match (descriptor_id.as_str(), role) {
                (STATIC_DESCRIPTOR_ID, VerifierArtifactRoleV3::Input) => {
                    let actual = crate::StaticFactInputV1::from_json_bytes(bytes)
                        .map_err(m4_domain_error)?;
                    let expected = crate::m4::reconstruct_static_evaluation_v1(
                        aggregate.program(),
                        obligation,
                        claim,
                    )
                    .map_err(m4_domain_error)?;
                    if &actual != expected.input() {
                        return Err(DomainError::VerificationBundleMismatch);
                    }
                }
                (STATIC_DESCRIPTOR_ID, VerifierArtifactRoleV3::Output) => {
                    let actual = crate::StaticFactResultV1::from_json_bytes(bytes)
                        .map_err(m4_domain_error)?;
                    let expected = crate::m4::reconstruct_static_evaluation_v1(
                        aggregate.program(),
                        obligation,
                        claim,
                    )
                    .map_err(m4_domain_error)?;
                    if &actual != expected.result() {
                        return Err(DomainError::VerificationBundleMismatch);
                    }
                }
                (FIXTURE_DESCRIPTOR_ID, VerifierArtifactRoleV3::Output) => {
                    let root = roots
                        .harness_for_fixture_registration_view(
                            registration,
                            expected_genesis_hash,
                            aggregate,
                            claim_id,
                        )
                        .ok_or(DomainError::HarnessTrustRootMissing)?;
                    validate_fixture_result_for_root(aggregate, root, bytes)?;
                }
                _ => return Err(DomainError::VerificationBundleMismatch),
            }
        }
        ArtifactSourceV3::ExternalHarnessWitness {
            claim_id,
            claim_body_hash,
            ..
        } => {
            let root = roots
                .harness_for_source_view(registration)
                .ok_or(DomainError::HarnessTrustRootMissing)?;
            let claim = aggregate
                .execution_claims()
                .find(|claim| claim.id() == claim_id)
                .ok_or_else(|| DomainError::DanglingReference {
                    owner: "v3 external witness claim",
                    owner_id: registration.registration_id().clone(),
                    reference: claim_id.clone(),
                })?;
            if claim.body_hash()? != *claim_body_hash
                || claim.body_hash()? != *root.claim_body_hash
                || bytes.len() != usize::try_from(FIXTURE_WITNESS_SIZE).unwrap_or(usize::MAX)
                || ContentHash::sha256(bytes).as_str() != FIXTURE_WITNESS_HASH
                || bytes != FIXTURE_WITNESS_BYTES
            {
                return Err(DomainError::WitnessAdmissionMismatch);
            }
        }
        _ => {}
    }
    Ok(())
}

fn static_proposal_for_registrations(
    aggregate: &ReviewAggregate,
    state: &V3RunAggregate,
    resolver: &impl AuthorityArtifactResolverV3,
    input_registration_id: &StableId,
    output_registration_id: &StableId,
) -> Result<crate::StaticRecordProposalV1> {
    let input_registration = state
        .registrations
        .get(input_registration_id)
        .ok_or_else(|| DomainError::DanglingReference {
            owner: "static verifier input",
            owner_id: input_registration_id.clone(),
            reference: input_registration_id.clone(),
        })?;
    let output_registration = state
        .registrations
        .get(output_registration_id)
        .ok_or_else(|| DomainError::DanglingReference {
            owner: "static verifier output",
            owner_id: output_registration_id.clone(),
            reference: output_registration_id.clone(),
        })?;
    let claim_id = match input_registration.source() {
        ArtifactSourceV3::VerifierArtifact {
            claim_id,
            descriptor_id,
            procedure_version,
            role: VerifierArtifactRoleV3::Input,
            ..
        } if descriptor_id == STATIC_DESCRIPTOR_ID && procedure_version == STATIC_PROCEDURE_ID => {
            claim_id
        }
        _ => return Err(DomainError::VerificationBundleMismatch),
    };
    if !verifier_registration_matches(
        output_registration,
        claim_id,
        STATIC_DESCRIPTOR_ID,
        STATIC_PROCEDURE_ID,
        VerifierArtifactRoleV3::Output,
    ) {
        return Err(DomainError::VerificationBundleMismatch);
    }
    let claim = aggregate
        .execution_claims()
        .find(|claim| claim.id() == claim_id)
        .ok_or_else(|| DomainError::DanglingReference {
            owner: "static verifier claim",
            owner_id: claim_id.clone(),
            reference: claim_id.clone(),
        })?;
    let obligation_id = claim
        .obligation_ids()
        .first()
        .ok_or(DomainError::VerificationBundleMismatch)?;
    let obligation =
        aggregate
            .obligation(obligation_id)
            .ok_or_else(|| DomainError::DanglingReference {
                owner: "static verifier obligation",
                owner_id: claim_id.clone(),
                reference: obligation_id.clone(),
            })?;
    ensure_v3_working_peak(
        state.retained_bytes()?,
        [input_registration.size(), output_registration.size()],
    )?;
    let input_bytes = resolve_registered_bytes(input_registration, resolver)?;
    let output_bytes = resolve_registered_bytes(output_registration, resolver)?;
    let input = crate::StaticFactInputV1::from_json_bytes(&input_bytes).map_err(m4_domain_error)?;
    let reconstructed = crate::m4::reconstruct_static_result_from_durable_input_v1(
        aggregate.program(),
        obligation,
        claim,
        &input,
    )
    .map_err(m4_domain_error)?;
    if reconstructed.canonical_bytes().map_err(m4_domain_error)? != output_bytes {
        return Err(DomainError::VerificationBundleMismatch);
    }
    crate::m4::materialize_static_from_durable_input_v1(
        aggregate.program(),
        obligation,
        claim,
        input,
        input_registration_id.clone(),
        output_registration_id.clone(),
    )
    .map_err(m4_domain_error)
}

fn projected_static_registration_heap_bytes(
    log: &EventLog,
    claim_id: &StableId,
    media_type: &str,
) -> Result<u64> {
    // All values are constructed by exact-length `Clone`, `to_owned`, SHA-256,
    // or the fixed `registration:<sha256>` namespace below the preflight.
    const SHA256_TEXT_BYTES: usize = "sha256:".len() + 64;
    const REGISTRATION_ID_TEXT_BYTES: usize = "registration:".len() + SHA256_TEXT_BYTES;
    let mut total = 0_u64;
    for bytes in [
        log.run_id.as_str().len(),
        REGISTRATION_ID_TEXT_BYTES,
        SHA256_TEXT_BYTES,
        media_type.len(),
        claim_id.as_str().len(),
        STATIC_DESCRIPTOR_ID.len(),
        STATIC_PROCEDURE_ID.len(),
        log.run_id.as_str().len(),
    ] {
        v3_add(
            &mut total,
            u64::try_from(bytes).unwrap_or(u64::MAX),
            "static verifier registration projection",
        )?;
    }
    Ok(total)
}

fn projected_static_expected_bytes(
    log: &EventLog,
    claim_id: &StableId,
    basis: &AuthorityReplayBasisV3,
    input_size: u64,
    output_size: u64,
) -> Result<u64> {
    let mut total = u64::try_from(size_of::<ExpectedVerificationAttemptV3>())
        .map_err(|_| v3_memory_error("static expected attempt projection", u64::MAX))?;
    for bytes in [
        log.run_id.as_str().len(),
        log.genesis_hash.as_str().len(),
        claim_id.as_str().len(),
        basis.basis_digest.as_str().len(),
        log.tail_hash.as_str().len(),
    ] {
        v3_add(
            &mut total,
            u64::try_from(bytes).unwrap_or(u64::MAX),
            "static expected attempt projection",
        )?;
    }
    // ArtifactRegisteredV3 is inline in ExpectedVerificationAttemptV3; only
    // its owned heap is additional here.
    v3_add(
        &mut total,
        projected_static_registration_heap_bytes(log, claim_id, STATIC_INPUT_MEDIA_TYPE)?,
        "static expected attempt projection",
    )?;
    v3_add(
        &mut total,
        projected_static_registration_heap_bytes(log, claim_id, STATIC_OUTPUT_MEDIA_TYPE)?,
        "static expected attempt projection",
    )?;
    v3_add(&mut total, input_size, "static expected attempt projection")?;
    v3_add(
        &mut total,
        output_size,
        "static expected attempt projection",
    )?;
    Ok(total)
}

fn static_expectation_preflight(
    stage: u8,
    log: &EventLog,
    basis: &AuthorityReplayBasisV3,
    additions: impl IntoIterator<Item = u64>,
) -> Result<u64> {
    let mut retained = log.retained_bytes_v3()?;
    v3_add(
        &mut retained,
        basis.retained_bytes()?,
        "static expected attempt retained bytes",
    )?;
    let peak = ensure_v3_working_peak(retained, additions)?;
    record_static_expectation_peak(stage, peak);
    Ok(peak)
}

fn static_fresh_expectation_preflight(
    log: &EventLog,
    claim_id: &StableId,
    evaluation: &crate::StaticFactEvaluationV1,
    reconstructed: &crate::StaticFactResultV1,
    basis: &AuthorityReplayBasisV3,
) -> Result<()> {
    let input_size = evaluation
        .input()
        .canonical_size()
        .map_err(m4_domain_error)?;
    let output_size = evaluation
        .result()
        .canonical_size()
        .map_err(m4_domain_error)?;
    let evaluation_bytes = u64::try_from(size_of::<crate::StaticFactEvaluationV1>())
        .unwrap_or(u64::MAX)
        .checked_add(evaluation.allocated_bytes().map_err(m4_domain_error)?)
        .ok_or_else(|| v3_memory_error("static borrowed evaluation", u64::MAX))?;
    let projected_result_bytes = u64::try_from(size_of::<crate::StaticFactResultV1>())
        .unwrap_or(u64::MAX)
        .checked_add(reconstructed.allocated_bytes().map_err(m4_domain_error)?)
        .ok_or_else(|| v3_memory_error("static reconstructed result", u64::MAX))?;
    let expected = projected_static_expected_bytes(log, claim_id, basis, input_size, output_size)?;
    // The canonical buffers are staged while registration identities are
    // serialized. Expected owns the same buffers, so compare the two actual
    // phases instead of double-counting mutually exclusive ownership.
    let mut registration_phase = evaluation_bytes;
    for addition in [
        projected_result_bytes,
        input_size,
        output_size,
        projected_static_registration_heap_bytes(log, claim_id, STATIC_INPUT_MEDIA_TYPE)?,
        projected_static_registration_heap_bytes(log, claim_id, STATIC_OUTPUT_MEDIA_TYPE)?,
        MAX_V3_REGISTRATION_IDENTITY_BYTES as u64,
    ] {
        v3_add(
            &mut registration_phase,
            addition,
            "static registration construction phase",
        )?;
    }
    let mut expected_phase = evaluation_bytes;
    v3_add(
        &mut expected_phase,
        projected_result_bytes,
        "static Expected construction phase",
    )?;
    v3_add(
        &mut expected_phase,
        expected,
        "static Expected construction phase",
    )?;
    static_expectation_preflight(1, log, basis, [registration_phase.max(expected_phase)])?;
    Ok(())
}

fn static_fresh_pre_reconstruction_preflight(
    log: &EventLog,
    claim_id: &StableId,
    obligation: &crate::Obligation,
    evaluation: &crate::StaticFactEvaluationV1,
    basis: &AuthorityReplayBasisV3,
) -> Result<()> {
    let input_size = evaluation
        .input()
        .canonical_size()
        .map_err(m4_domain_error)?;
    let output_size = evaluation
        .result()
        .canonical_size()
        .map_err(m4_domain_error)?;
    let evaluation_bytes = u64::try_from(size_of::<crate::StaticFactEvaluationV1>())
        .unwrap_or(u64::MAX)
        .checked_add(evaluation.allocated_bytes().map_err(m4_domain_error)?)
        .ok_or_else(|| v3_memory_error("static borrowed evaluation", u64::MAX))?;
    let reconstruction = crate::m4::static_reconstruction_scratch_bytes(
        log.aggregate.program(),
        obligation,
        log.aggregate
            .execution_claims()
            .find(|claim| claim.id() == claim_id)
            .ok_or(DomainError::VerificationBundleMismatch)?,
    )
    .map_err(m4_domain_error)?;
    let expected = projected_static_expected_bytes(log, claim_id, basis, input_size, output_size)?;
    let mut downstream = input_size;
    for addition in [
        output_size,
        projected_static_registration_heap_bytes(log, claim_id, STATIC_INPUT_MEDIA_TYPE)?,
        projected_static_registration_heap_bytes(log, claim_id, STATIC_OUTPUT_MEDIA_TYPE)?,
        MAX_V3_REGISTRATION_IDENTITY_BYTES as u64,
        expected,
    ] {
        v3_add(
            &mut downstream,
            addition,
            "static fresh downstream construction",
        )?;
    }
    static_expectation_preflight(
        1,
        log,
        basis,
        [evaluation_bytes, reconstruction, downstream],
    )?;
    Ok(())
}

fn static_durable_read_preflight(
    log: &EventLog,
    claim_id: &StableId,
    obligation: &crate::Obligation,
    claim: &crate::ExecutionClaimV2,
    input_size: u64,
    basis: &AuthorityReplayBasisV3,
) -> Result<()> {
    let record_bound = crate::m4::MAX_RECORD_BYTES as u64;
    let expected = projected_static_expected_bytes(log, claim_id, basis, input_size, record_bound)?;
    let decoded_input =
        crate::m4::static_input_structural_upper_bound_bytes().map_err(m4_domain_error)?;
    let reconstructed =
        crate::m4::static_reconstruction_scratch_bytes(log.aggregate.program(), obligation, claim)
            .map_err(m4_domain_error)?;
    let result =
        crate::m4::static_result_structural_upper_bound_bytes().map_err(m4_domain_error)?;
    // The admitted input buffer, decoded DTO backing, reconstructed result,
    // output canonical bytes, registration identity scratch, and final token
    // all fit under this pre-CAS bound. This makes refusal precede read_exact.
    static_expectation_preflight(
        2,
        log,
        basis,
        [
            input_size,
            decoded_input,
            reconstructed,
            result,
            record_bound,
            expected,
            MAX_V3_REGISTRATION_IDENTITY_BYTES as u64,
        ],
    )?;
    Ok(())
}

fn static_durable_reconstruction_preflight(
    log: &EventLog,
    claim_id: &StableId,
    obligation: &crate::Obligation,
    claim: &crate::ExecutionClaimV2,
    input_bytes: &[u8],
    input: &crate::StaticFactInputV1,
    basis: &AuthorityReplayBasisV3,
) -> Result<()> {
    let input_dto = u64::try_from(size_of::<crate::StaticFactInputV1>())
        .unwrap_or(u64::MAX)
        .checked_add(input.allocated_bytes().map_err(m4_domain_error)?)
        .ok_or_else(|| v3_memory_error("static durable decoded input", u64::MAX))?;
    let reconstruction =
        crate::m4::static_reconstruction_scratch_bytes(log.aggregate.program(), obligation, claim)
            .map_err(m4_domain_error)?;
    let (result, output_size) = input
        .projected_result_accounting()
        .map_err(m4_domain_error)?;
    let expected = projected_static_expected_bytes(
        log,
        claim_id,
        basis,
        u64::try_from(input_bytes.len()).unwrap_or(u64::MAX),
        output_size,
    )?;
    static_expectation_preflight(
        2,
        log,
        basis,
        [
            u64::try_from(input_bytes.len()).unwrap_or(u64::MAX),
            input_dto,
            reconstruction,
            result,
            output_size,
            projected_static_registration_heap_bytes(log, claim_id, STATIC_INPUT_MEDIA_TYPE)?,
            projected_static_registration_heap_bytes(log, claim_id, STATIC_OUTPUT_MEDIA_TYPE)?,
            MAX_V3_REGISTRATION_IDENTITY_BYTES as u64,
            expected,
        ],
    )?;
    Ok(())
}

fn expected_static_attempt_from_bytes(
    log: &EventLog,
    claim_id: &StableId,
    input_bytes: Vec<u8>,
    output_bytes: Vec<u8>,
    basis: &AuthorityReplayBasisV3,
    stage: u8,
    borrowed_bytes: u64,
) -> Result<ExpectedVerificationAttemptV3> {
    let input_registration = ArtifactRegisteredV3::new_validated(
        log.run_id.clone(),
        ContentHash::sha256(&input_bytes),
        STATIC_INPUT_MEDIA_TYPE,
        u64::try_from(input_bytes.len()).unwrap_or(u64::MAX),
        ArtifactSensitivity::CanonicalState,
        ArtifactSourceV3::VerifierArtifact {
            run_id: log.run_id.clone(),
            claim_id: claim_id.clone(),
            descriptor_id: STATIC_DESCRIPTOR_ID.to_owned(),
            procedure_version: STATIC_PROCEDURE_ID.to_owned(),
            role: VerifierArtifactRoleV3::Input,
        },
    )?;
    let output_registration = ArtifactRegisteredV3::new_validated(
        log.run_id.clone(),
        ContentHash::sha256(&output_bytes),
        STATIC_OUTPUT_MEDIA_TYPE,
        u64::try_from(output_bytes.len()).unwrap_or(u64::MAX),
        ArtifactSensitivity::CanonicalState,
        ArtifactSourceV3::VerifierArtifact {
            run_id: log.run_id.clone(),
            claim_id: claim_id.clone(),
            descriptor_id: STATIC_DESCRIPTOR_ID.to_owned(),
            procedure_version: STATIC_PROCEDURE_ID.to_owned(),
            role: VerifierArtifactRoleV3::Output,
        },
    )?;
    let mut expected_bytes = u64::try_from(size_of::<ExpectedVerificationAttemptV3>())
        .map_err(|_| v3_memory_error("static expected attempt", u64::MAX))?;
    for bytes in [
        log.run_id.allocated_bytes(),
        log.genesis_hash.allocated_bytes(),
        claim_id.allocated_bytes(),
        basis.basis_digest.allocated_bytes(),
        log.tail_hash.allocated_bytes(),
        input_registration.allocated_bytes(),
        input_bytes.capacity(),
        output_registration.allocated_bytes(),
        output_bytes.capacity(),
    ] {
        v3_add(
            &mut expected_bytes,
            u64::try_from(bytes).unwrap_or(u64::MAX),
            "static expected attempt",
        )?;
    }
    static_expectation_preflight(stage, log, basis, [borrowed_bytes, expected_bytes])?;
    mark_static_expectation_allocation_seam(stage);
    Ok(ExpectedVerificationAttemptV3 {
        kind: ExpectedVerificationKindV3::Static,
        run_id: log.run_id.clone(),
        genesis_hash: log.genesis_hash.clone(),
        claim_id: claim_id.clone(),
        basis_digest: basis.basis_digest.clone(),
        tail_hash: log.tail_hash.clone(),
        input_registration,
        input_bytes,
        output_registration,
        output_bytes,
    })
}

struct FixtureReplayClosure {
    claim_id: StableId,
    property_id: String,
    snapshot_id: StableId,
    input_registration_id: StableId,
    output_registration_id: StableId,
    subject_ids: Vec<StableId>,
    proposal: crate::m4::FixtureRecordProposalV1,
}

fn validate_fixture_result_for_root<'a>(
    aggregate: &ReviewAggregate,
    root: impl Into<HarnessTrustRootView<'a>>,
    output_bytes: &[u8],
) -> Result<crate::FixedFixtureResultV1> {
    let root = root.into();
    let claim = aggregate
        .execution_claims()
        .find(|claim| claim.id() == root.claim_id)
        .ok_or(DomainError::VerificationBundleMismatch)?;
    let result =
        crate::FixedFixtureResultV1::from_json_bytes(output_bytes).map_err(m4_domain_error)?;
    let mut subject_ids = claim.target_refs().iter().cloned().collect::<Vec<_>>();
    subject_ids.push(StableId::parse(FIXTURE_TEST_ARTIFACT_ID)?);
    subject_ids.sort_unstable();
    if claim.body_hash()? != *root.claim_body_hash
        || claim.property_id() != root.property_id
        || claim.polarity() != crate::ClaimPolarity::IssuePresent
        || result.claim_id() != root.claim_id
        || result.property_id() != root.property_id
        || result.descriptor() != crate::VerifierDescriptorV3::FixedFixtureV1
        || result.procedure() != crate::VerifierProcedureV3::DuplicateSubmitV1
        || result.outcome() != crate::VerificationOutcomeV3::Passed
        || result.witness_hash().as_str() != FIXTURE_WITNESS_HASH
        || result.subject_ids() != subject_ids
    {
        return Err(DomainError::VerificationBundleMismatch);
    }
    Ok(result)
}

fn validate_fixture_receipt_for_log<'a>(
    log: &EventLog,
    receipt: &'a FixtureExecutionReceiptV1,
    basis: &AuthorityReplayBasisV3,
    durable_stage: u64,
) -> Result<&'a HarnessTrustRootInputV3> {
    if durable_stage > 2 {
        return Err(DomainError::WitnessAdmissionMismatch);
    }
    let root = &receipt
        .harness
        .as_ref()
        .ok_or(DomainError::WitnessAdmissionMismatch)?
        .scope;
    let expected_sequence = receipt
        .expected_first_sequence
        .checked_add(durable_stage)
        .ok_or_else(|| DomainError::EventSequence("fixture stage overflow".to_owned()))?;
    if basis.policy_revision_hash != root.policy_revision_hash
        || log.next_sequence()? != expected_sequence
        || (durable_stage == 0
            && (receipt.basis_digest != basis.basis_digest || receipt.tail_hash != log.tail_hash))
        || receipt.witness_bytes.as_slice() != FIXTURE_WITNESS_BYTES
        || ContentHash::sha256(&receipt.witness_bytes) != root.result_hash
        || ContentHash::sha256(&receipt.fixture_result_bytes) != receipt.fixture_result_hash
    {
        return Err(DomainError::WitnessAdmissionMismatch);
    }
    validate_fresh_fixture_scope(log, basis, root)?;
    let exact_event = |expected: &ExpectedFixtureRegistrationEventV1| -> Result<()> {
        let index = usize::try_from(expected.envelope.sequence().saturating_sub(1))
            .map_err(|_| DomainError::WitnessAdmissionMismatch)?;
        let observed = log
            .events
            .get(index)
            .ok_or(DomainError::WitnessAdmissionMismatch)?
            .envelope();
        if observed.id() != expected.envelope.id()
            || observed.event_hash() != expected.envelope.event_hash()
            || observed.previous_event_hash() != expected.envelope.previous_event_hash()
            || observed.actor() != expected.envelope.actor()
            || observed.payload_hash() != expected.envelope.payload_hash()
            || observed.canonical_bytes()? != expected.envelope.canonical_bytes()?
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        Ok(())
    };
    if durable_stage >= 1 {
        let expected = receipt
            .expected_witness_event
            .as_ref()
            .ok_or(DomainError::WitnessAdmissionMismatch)?;
        if expected.envelope.sequence() != receipt.expected_first_sequence
            || expected.envelope.previous_event_hash() != &receipt.tail_hash
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        exact_event(expected)?;
        if durable_stage == 1 && log.tail_hash() != expected.envelope.event_hash() {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
    }
    if durable_stage == 2 {
        let witness = receipt
            .expected_witness_event
            .as_ref()
            .ok_or(DomainError::WitnessAdmissionMismatch)?;
        let output = receipt
            .expected_output_event
            .as_ref()
            .ok_or(DomainError::WitnessAdmissionMismatch)?;
        if output.envelope.sequence() != receipt.expected_first_sequence + 1
            || output.envelope.previous_event_hash() != witness.envelope.event_hash()
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        exact_event(output)?;
        if log.tail_hash() != output.envelope.event_hash() {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
    }
    let result =
        validate_fixture_result_for_root(&log.aggregate, root, &receipt.fixture_result_bytes)?;
    if result.subject_ids() != receipt.subject_ids {
        return Err(DomainError::VerificationBundleMismatch);
    }
    Ok(root)
}

fn validate_fresh_fixture_witness_registration(
    aggregate: &ReviewAggregate,
    registration: &ArtifactRegisteredV3,
    bytes: &[u8],
    scope: &HarnessTrustRootInputV3,
) -> Result<()> {
    if !fixture_registration_matches_scope(registration, scope)
        || bytes != FIXTURE_WITNESS_BYTES
        || ContentHash::sha256(bytes) != scope.result_hash
    {
        return Err(DomainError::WitnessAdmissionMismatch);
    }
    let claim = aggregate
        .execution_claims()
        .find(|claim| claim.id() == &scope.claim_id)
        .ok_or_else(|| DomainError::DanglingReference {
            owner: "v3 external witness claim",
            owner_id: registration.registration_id().clone(),
            reference: scope.claim_id.clone(),
        })?;
    if claim.body_hash()? != scope.claim_body_hash
        || !aggregate
            .program()
            .known_ids()
            .contains(&scope.test_artifact_id)
    {
        return Err(DomainError::WitnessAdmissionMismatch);
    }
    Ok(())
}

fn expected_fixture_registration_event(
    log: &EventLog,
    registration: &ArtifactRegisteredV3,
) -> Result<ExpectedFixtureRegistrationEventV1> {
    let payload = PersistedPayload::ArtifactRegisteredV3(registration.clone());
    let sequence = log.next_sequence()?;
    let actor = payload.actor().to_owned();
    let envelope = EventEnvelope::new(
        EventContractVersion::V3,
        log.run_id.clone(),
        log.genesis_hash.clone(),
        sequence,
        actor,
        sequence,
        log.tail_hash.clone(),
        payload,
    )?;
    Ok(ExpectedFixtureRegistrationEventV1 {
        registration_id: registration.registration_id().clone(),
        envelope,
    })
}

fn same_expected_fixture_event(
    left: &ExpectedFixtureRegistrationEventV1,
    right: &ExpectedFixtureRegistrationEventV1,
) -> Result<bool> {
    Ok(left.registration_id == right.registration_id
        && left.envelope.id() == right.envelope.id()
        && left.envelope.event_hash() == right.envelope.event_hash()
        && left.envelope.canonical_bytes()? == right.envelope.canonical_bytes()?)
}

fn fixture_replay_closure(
    aggregate: &ReviewAggregate,
    state: &V3RunAggregate,
    evidence: &EvidenceV3,
    resolver: &impl AuthorityArtifactResolverV3,
    roots: &impl AuthorityTrustRootsV3View,
) -> Result<FixtureReplayClosure> {
    let input = state
        .registrations
        .get(evidence.input_registration_id())
        .ok_or(DomainError::VerificationBundleMismatch)?;
    let output = state
        .registrations
        .get(evidence.output_registration_id())
        .ok_or(DomainError::VerificationBundleMismatch)?;
    let root = roots
        .harness_for_source_view(input)
        .ok_or(DomainError::HarnessTrustRootMissing)?;
    let claim = aggregate
        .execution_claims()
        .find(|claim| claim.id() == root.claim_id)
        .ok_or(DomainError::VerificationBundleMismatch)?;
    if claim.body_hash()? != *root.claim_body_hash
        || claim.property_id() != root.property_id
        || claim.polarity() != crate::ClaimPolarity::IssuePresent
        || aggregate.program().snapshot_id() != root.snapshot_id
        || aggregate.universe().id() != root.universe_id
        || !verifier_registration_matches(
            output,
            root.claim_id,
            FIXTURE_DESCRIPTOR_ID,
            FIXTURE_PROCEDURE_ID,
            VerifierArtifactRoleV3::Output,
        )
    {
        return Err(DomainError::VerificationBundleMismatch);
    }
    ensure_v3_working_peak(state.retained_bytes()?, [output.size()])?;
    let output_bytes = resolve_registered_bytes(output, resolver)?;
    let result = validate_fixture_result_for_root(aggregate, root, &output_bytes)?;
    let mut subject_ids = claim.target_refs().iter().cloned().collect::<Vec<_>>();
    subject_ids.push(StableId::parse(FIXTURE_TEST_ARTIFACT_ID)?);
    subject_ids.sort_unstable();
    if evidence.snapshot_id() != root.snapshot_id
        || evidence.subject_ids() != subject_ids
        || evidence.input_registration_id() != input.registration_id()
        || evidence.output_registration_id() != output.registration_id()
    {
        return Err(DomainError::VerificationBundleMismatch);
    }
    let scope = state
        .assessment_scopes
        .get(root.claim_id)
        .ok_or(DomainError::VerificationBundleMismatch)?;
    let proposal = crate::m4::materialize_fixture_replay_v1(
        scope,
        &result,
        input.registration_id().clone(),
        output.registration_id().clone(),
    )
    .map_err(m4_domain_error)?;
    Ok(FixtureReplayClosure {
        claim_id: root.claim_id.clone(),
        property_id: root.property_id.to_owned(),
        snapshot_id: root.snapshot_id.clone(),
        input_registration_id: input.registration_id().clone(),
        output_registration_id: output.registration_id().clone(),
        subject_ids,
        proposal,
    })
}

fn validate_authority_payload_against_cas(
    aggregate: &ReviewAggregate,
    state: &V3RunAggregate,
    payload: &PersistedPayload,
    resolver: &impl AuthorityArtifactResolverV3,
    roots: &impl AuthorityTrustRootsV3View,
) -> Result<()> {
    match payload {
        PersistedPayload::EvidenceRecordedV3(evidence)
            if evidence.descriptor() == crate::VerifierDescriptorV3::StaticFactV1 =>
        {
            let proposal = static_proposal_for_registrations(
                aggregate,
                state,
                resolver,
                evidence.input_registration_id(),
                evidence.output_registration_id(),
            )?;
            if proposal.evidence() != Some(evidence) {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        PersistedPayload::EvidenceBoundV3(binding)
            if binding.relation() == crate::EvidenceRelationV3::Qualifies =>
        {
            let evidence = state
                .evidence
                .get(binding.evidence_id())
                .ok_or(DomainError::VerificationBundleMismatch)?;
            let proposal = static_proposal_for_registrations(
                aggregate,
                state,
                resolver,
                evidence.input_registration_id(),
                evidence.output_registration_id(),
            )?;
            if proposal.binding() != Some(binding) {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        PersistedPayload::VerificationRecordedV3(verification)
            if verification.descriptor() == crate::VerifierDescriptorV3::StaticFactV1 =>
        {
            let proposal = static_proposal_for_registrations(
                aggregate,
                state,
                resolver,
                verification.input_registration_id(),
                verification.output_registration_id(),
            )?;
            if proposal.verification() != verification {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        PersistedPayload::EvidenceRecordedV3(evidence)
            if evidence.descriptor() == crate::VerifierDescriptorV3::FixedFixtureV1 =>
        {
            let closure = fixture_replay_closure(aggregate, state, evidence, resolver, roots)?;
            if evidence != &closure.proposal.evidence {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        PersistedPayload::EvidenceBoundV3(binding)
            if binding.relation() == crate::EvidenceRelationV3::Reproduces =>
        {
            let evidence = state
                .evidence
                .get(binding.evidence_id())
                .ok_or(DomainError::VerificationBundleMismatch)?;
            let closure = fixture_replay_closure(aggregate, state, evidence, resolver, roots)?;
            if binding.claim_id() != &closure.claim_id
                || binding.property_id() != closure.property_id
                || evidence.snapshot_id() != &closure.snapshot_id
                || binding != &closure.proposal.binding
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        PersistedPayload::VerificationRecordedV3(verification)
            if verification.descriptor() == crate::VerifierDescriptorV3::FixedFixtureV1 =>
        {
            let [evidence_id] = verification.evidence_ids() else {
                return Err(DomainError::VerificationBundleMismatch);
            };
            let evidence = state
                .evidence
                .get(evidence_id)
                .ok_or(DomainError::VerificationBundleMismatch)?;
            let closure = fixture_replay_closure(aggregate, state, evidence, resolver, roots)?;
            if verification.claim_id() != &closure.claim_id
                || verification.outcome() != crate::VerificationOutcomeV3::Passed
                || verification.input_registration_id() != &closure.input_registration_id
                || verification.output_registration_id() != &closure.output_registration_id
                || evidence.subject_ids() != closure.subject_ids
                || verification != &closure.proposal.verification
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        _ => {}
    }
    Ok(())
}

fn authority_payload_cas_working_bytes(
    state: &V3RunAggregate,
    payload: &PersistedPayload,
) -> Result<u64> {
    let evidence = match payload {
        PersistedPayload::EvidenceRecordedV3(value) => Some(value),
        PersistedPayload::EvidenceBoundV3(value) => state.evidence.get(value.evidence_id()),
        PersistedPayload::VerificationRecordedV3(value) => value
            .evidence_ids()
            .first()
            .and_then(|id| state.evidence.get(id)),
        _ => None,
    };
    let Some(evidence) = evidence else {
        return Ok(0);
    };
    let input = state
        .registrations
        .get(evidence.input_registration_id())
        .ok_or(DomainError::VerificationBundleMismatch)?;
    let output = state
        .registrations
        .get(evidence.output_registration_id())
        .ok_or(DomainError::VerificationBundleMismatch)?;
    match evidence.descriptor() {
        crate::VerifierDescriptorV3::StaticFactV1 => input
            .size()
            .checked_add(output.size())
            .ok_or_else(|| v3_memory_error("event-v3 authority CAS staging", u64::MAX)),
        crate::VerifierDescriptorV3::FixedFixtureV1 => Ok(output.size()),
    }
}

impl EventReplayLimits {
    #[must_use]
    pub const fn new(max_events: u64, max_canonical_bytes: u64) -> Self {
        Self {
            max_events,
            max_canonical_bytes,
        }
    }
}

impl EventLog {
    fn retained_bytes_v3(&self) -> Result<u64> {
        self.retained_bytes_v3_with(
            &self.aggregate,
            self.v3_aggregate.as_ref(),
            &self.events,
            &self.tail_hash,
        )
    }

    fn retained_bytes_v3_with(
        &self,
        aggregate: &ReviewAggregate,
        v3_aggregate: Option<&V3RunAggregate>,
        events: &Vec<Event>,
        tail_hash: &ContentHash,
    ) -> Result<u64> {
        let mut total = u64::try_from(
            size_of::<EventContractVersion>()
                + size_of::<bool>()
                + size_of::<Vec<Event>>()
                + size_of::<Option<V3RunAggregate>>(),
        )
        .unwrap_or(u64::MAX);
        for bytes in [
            self.run_id.allocated_bytes(),
            self.genesis_hash.allocated_bytes(),
            tail_hash.allocated_bytes(),
        ] {
            v3_add(
                &mut total,
                u64::try_from(bytes).unwrap_or(u64::MAX),
                "event-v3 retained EventLog",
            )?;
        }
        v3_add(
            &mut total,
            self.initial.retained_bytes_v3()?,
            "event-v3 retained initial aggregate",
        )?;
        v3_add(
            &mut total,
            aggregate.retained_bytes_v3()?,
            "event-v3 retained current aggregate",
        )?;
        if let Some(state) = v3_aggregate {
            v3_add(
                &mut total,
                state.retained_bytes()?,
                "event-v3 retained v3 aggregate",
            )?;
        }
        v3_add(
            &mut total,
            u64::try_from(events.capacity().saturating_mul(size_of::<Event>())).unwrap_or(u64::MAX),
            "event-v3 retained event slots",
        )?;
        for event in events {
            v3_add(
                &mut total,
                event.retained_bytes()?,
                "event-v3 retained events",
            )?;
        }
        Ok(total)
    }

    fn preflight_v3_outer_transaction(
        &self,
        basis: &AuthorityReplayBasisV3,
        payloads: &[PersistedPayload],
    ) -> Result<()> {
        let retained = self.retained_bytes_v3()?;
        let basis_retained = basis.retained_bytes()?;
        let mut sealed_payloads =
            u64::try_from(payloads.len().saturating_mul(size_of::<PersistedPayload>()))
                .unwrap_or(u64::MAX);
        let mut canonical_payloads = 0_u64;
        let mut reducer_growth = 0_u64;
        for payload in payloads {
            let typed = v3_payload_staging_bytes(payload)?;
            // Bound canonicalization before it allocates. The closed payload
            // schemas serialize no binary expansion; twice the retained typed
            // ownership is a conservative lexical destination bound.
            ensure_v3_working_peak(retained, [basis_retained, typed, typed])?;
            v3_add(
                &mut sealed_payloads,
                typed,
                "event-v3 sealed authority payloads",
            )?;
            v3_add(
                &mut canonical_payloads,
                crate::canonical::canonical_json_count_bounded(
                    payload,
                    crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
                    "event-v3 canonical authority payload count",
                )?,
                "event-v3 canonical authority payloads",
            )?;
            v3_add(
                &mut reducer_growth,
                v3_reducer_growth_upper_bound(payload)?,
                "event-v3 authority reducer growth",
            )?;
        }
        let trust_digests =
            u64::try_from(payloads.len().saturating_mul(size_of::<ContentHash>() + 71))
                .unwrap_or(u64::MAX);
        let reducer_aggregate = self.aggregate.retained_bytes_v3()?;
        let reducer_v3 = self
            .v3_aggregate
            .as_ref()
            .ok_or(DomainError::EventV3AuthorityReplayRequired {
                operation: "event-v3 authority transaction reducer",
            })?
            .retained_bytes()?;
        let reducer_events = event_vector_retained(&self.events)?;
        // Originals, transaction clones, sealed validated values, their exact
        // canonical bytes, and the per-record trust digests coexist.
        ensure_v3_working_peak(retained, [basis_retained, retained, basis_retained])?;
        ensure_v3_working_peak(
            retained,
            [
                basis_retained,
                retained,
                basis_retained,
                sealed_payloads,
                canonical_payloads,
                trust_digests,
                reducer_aggregate,
                reducer_v3,
                reducer_events,
                reducer_growth,
            ],
        )?;
        Ok(())
    }

    fn preflight_v3_live_append(&self, payload: &PersistedPayload) -> Result<()> {
        let retained = self.retained_bytes_v3()?;
        let typed = v3_payload_staging_bytes(payload)?;
        ensure_v3_working_peak(retained, [typed, typed])?;
        let canonical = crate::canonical::canonical_json_count_bounded(
            payload,
            crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
            "event-v3 live payload canonical count",
        )?;
        let reducer_growth = v3_reducer_growth_upper_bound(payload)?;
        ensure_v3_working_peak(
            retained,
            [
                typed,
                canonical,
                canonical,
                self.aggregate.retained_bytes_v3()?,
                self.v3_aggregate
                    .as_ref()
                    .ok_or(DomainError::EventV3AuthorityReplayRequired {
                        operation: "event-v3 live append preflight",
                    })?
                    .retained_bytes()?,
                event_vector_retained(&self.events)?,
                reducer_growth,
                u64::try_from(size_of::<Event>()).unwrap_or(u64::MAX),
            ],
        )?;
        Ok(())
    }

    /// Admits the complete common append/replay shadow before payload decode
    /// or any envelope/event clone. Payload-specific CAS buffers are admitted
    /// separately once their sealed registration metadata is available.
    fn preflight_v3_encoded_append(
        &self,
        envelope: &EventEnvelope,
        external_live_bytes: u64,
        event_admission_bytes: u64,
        decoded_payload: Option<&PersistedPayload>,
    ) -> Result<u64> {
        let retained = self.retained_bytes_v3()?;
        let raw = u64::try_from(envelope.payload.get().len()).unwrap_or(u64::MAX);
        let envelope_owned = u64::try_from(envelope.allocated_bytes()).unwrap_or(u64::MAX);
        let typed = decoded_payload
            .map(v3_payload_staging_bytes)
            .transpose()?
            .unwrap_or(raw);
        let reducer_growth = decoded_payload
            .map(v3_reducer_growth_upper_bound)
            .transpose()?
            .unwrap_or(0);
        let binding_index_growth = if decoded_payload
            .is_some_and(|payload| matches!(payload, PersistedPayload::EvidenceBoundV3(_)))
        {
            let review_binding_table = typed;
            let v3_binding_table = typed;
            let assessment_binding_link = typed;
            let claim_binding_link = typed;
            let obligation_binding_link = typed;
            let identity_registry_link = typed;
            let committed_binding_index = typed;
            [
                review_binding_table,
                v3_binding_table,
                assessment_binding_link,
                claim_binding_link,
                obligation_binding_link,
                identity_registry_link,
                committed_binding_index,
            ]
            .into_iter()
            .try_fold(0_u64, |total, value| total.checked_add(value))
            .ok_or_else(|| v3_memory_error("event-v3 binding index growth", u64::MAX))?
        } else {
            0
        };
        let common_peak = ensure_v3_working_peak(
            retained,
            [
                external_live_bytes,
                event_admission_bytes,
                raw,
                typed,
                envelope_owned,
                self.aggregate.retained_bytes_v3()?,
                self.v3_aggregate
                    .as_ref()
                    .ok_or(DomainError::EventV3AuthorityReplayRequired {
                        operation: "event-v3 encoded append preflight",
                    })?
                    .retained_bytes()?,
                event_vector_retained(&self.events)?,
                u64::try_from(size_of::<Event>()).unwrap_or(u64::MAX),
                reducer_growth,
                binding_index_growth,
            ],
        )?;
        let projected_post_retained = retained
            .checked_add(external_live_bytes)
            .and_then(|value| value.checked_add(envelope_owned))
            .and_then(|value| {
                value.checked_add(u64::try_from(size_of::<Event>()).unwrap_or(u64::MAX))
            })
            .and_then(|value| value.checked_add(typed))
            .and_then(|value| value.checked_add(reducer_growth))
            .and_then(|value| value.checked_add(binding_index_growth))
            .and_then(|value| value.checked_add(event_admission_bytes))
            .ok_or_else(|| v3_memory_error("event-v3 projected append retention", u64::MAX))?;
        let post_peak = ensure_v3_working_peak(retained, [projected_post_retained])?;
        Ok(common_peak.max(post_peak))
    }

    /// Rebuilds an editable V2 log only from canonical genesis bytes, a fully
    /// validated homogeneous prefix, and caller-supplied exact admissions.
    /// This method never derives authority admissions from persisted metadata.
    pub fn replay_validated_v2_prefix(
        run_id: StableId,
        genesis_bytes: &[u8],
        envelopes: &[EventEnvelope],
        admissions: &EventAdmissions,
        limits: EventReplayLimits,
    ) -> Result<Self> {
        preflight_v2_replay_limits(envelopes, limits)?;
        let verified = VerifiedV2Genesis::from_canonical_bytes(&run_id, genesis_bytes)?;
        if verified.genesis_hash != ContentHash::sha256(genesis_bytes) {
            return Err(DomainError::Validation(
                "verified genesis hash mismatch".to_owned(),
            ));
        }
        let initial =
            RunGenesisSnapshot::from_canonical_bytes(genesis_bytes)?.rebuild_aggregate()?;
        Self::replay_envelopes_with_event_capacity(
            EventContractVersion::V2,
            run_id,
            initial,
            envelopes,
            admissions,
            envelopes.len(),
        )
    }

    /// Rebuilds a v3 log and its opaque authority basis from the canonical
    /// prefix, exact CAS bytes, and host trust roots. No caller-provided basis,
    /// index, report, or fresh admission participates in this validation.
    pub fn replay_validated_v3_prefix(
        run_id: StableId,
        genesis_bytes: &[u8],
        envelopes: &[EventEnvelope],
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        limits: EventReplayLimits,
    ) -> Result<(Self, AuthorityReplayBasisV3)> {
        #[cfg(test)]
        let _decode_scope = V3ReplayDecodeScope::enter();
        if envelopes.is_empty() {
            return Err(DomainError::EventSequence(
                "V3 replay requires the sequence-one genesis manifest".to_owned(),
            ));
        }
        let count = u64::try_from(envelopes.len()).map_err(|_| DomainError::Incomplete {
            operation: "V3 replay event count",
            limit: usize::try_from(limits.max_events).unwrap_or(usize::MAX),
            observed: usize::MAX,
        })?;
        if count > limits.max_events {
            return Err(replay_incomplete(
                "V3 replay event count",
                limits.max_events,
                count,
            ));
        }
        let mut canonical_total = 0_u64;
        for envelope in envelopes {
            if envelope.contract_version()? != EventContractVersion::V3 {
                return Err(DomainError::Validation(
                    "V3 replay refuses a non-V3 envelope".to_owned(),
                ));
            }
            canonical_total = replay_add(
                "V3 replay canonical bytes",
                limits.max_canonical_bytes,
                canonical_total,
                crate::canonical::canonical_json_count_bounded(
                    envelope,
                    usize::try_from(limits.max_canonical_bytes).unwrap_or(usize::MAX),
                    "V3 replay canonical envelope count",
                )?,
            )?;
        }
        let initial =
            RunGenesisSnapshot::from_canonical_bytes_v3(genesis_bytes)?.rebuild_aggregate()?;
        validate_repository_trust_root(&initial, roots)?;
        let genesis_hash = ContentHash::sha256(genesis_bytes);
        validate_v3_replay_sequence_without_payload_decode(&run_id, &genesis_hash, envelopes)?;
        if envelopes[0].genesis_hash != genesis_hash || envelopes[0].sequence != 1 {
            return Err(DomainError::EventSequence(
                "v3 sequence-one envelope must bind the supplied canonical genesis".to_owned(),
            ));
        }
        let mut log = Self::new_with_version(EventContractVersion::V3, run_id, initial)?;
        let replay_capacity_peak = ensure_v3_working_peak(
            log.retained_bytes_v3()?,
            [
                u64::try_from(envelopes.len().saturating_mul(size_of::<Event>()))
                    .unwrap_or(u64::MAX),
                u64::try_from(
                    envelopes
                        .len()
                        .saturating_mul(size_of::<AuthorityReplayEntryV3>()),
                )
                .unwrap_or(u64::MAX),
            ],
        )?;
        record_v3_test_selected_peak(replay_capacity_peak);
        log.events
            .try_reserve_exact(envelopes.len())
            .map_err(|_| DomainError::Incomplete {
                operation: "V3 replay event output capacity",
                limit: envelopes.len(),
                observed: envelopes.len(),
            })?;
        let mut entries = Vec::new();
        entries
            .try_reserve_exact(envelopes.len())
            .map_err(|_| DomainError::Incomplete {
                operation: "V3 authority replay entries",
                limit: envelopes.len(),
                observed: envelopes.len(),
            })?;
        for envelope in envelopes {
            let entries_live = authority_entries_retained(&entries)?;
            let encoded_peak = log.preflight_v3_encoded_append(envelope, entries_live, 0, None)?;
            record_v3_test_selected_peak(encoded_peak);
            let payload =
                decode_canonical_payload(EventContractVersion::V3, envelope.payload.get())?;
            if envelope.sequence == 1 {
                validate_v3_genesis_decoded_envelope(
                    &log.run_id,
                    &log.initial,
                    genesis_bytes,
                    envelope,
                    &payload,
                )?;
            }
            let mut external_live_bytes = entries_live;
            let mut reviewer_raw = None;
            let mut context_projection = None;
            if let PersistedPayload::ArtifactRegisteredV3(registration) = &payload {
                v3_add(
                    &mut external_live_bytes,
                    registration.size(),
                    "event-v3 replay external registration bytes",
                )?;
                let registration_peak = ensure_v3_working_peak(
                    log.retained_bytes_v3()?,
                    [
                        authority_entries_retained(&entries)?,
                        v3_payload_staging_bytes(&payload)?,
                        registration.size(),
                    ],
                )?;
                record_v3_test_selected_peak(registration_peak);
                let bytes = resolve_registered_bytes(registration, resolver)?;
                validate_authority_registration(
                    &log.aggregate,
                    registration,
                    &bytes,
                    roots,
                    &log.genesis_hash,
                )
                .map_err(|error| DomainError::AuthorityReplayRefused {
                    event_sequence: envelope.sequence(),
                    reason: error.to_string(),
                })?;
            }
            if let PersistedPayload::ReviewExecutionRecorded(recorded) = &payload {
                let registration = log
                    .v3_aggregate
                    .as_ref()
                    .and_then(|state| {
                        state
                            .registrations
                            .get(recorded.execution.raw_artifact_registration_id())
                    })
                    .ok_or_else(|| DomainError::DanglingReference {
                        owner: "v3 D2 raw registration",
                        owner_id: recorded.execution.id().clone(),
                        reference: recorded.execution.raw_artifact_registration_id().clone(),
                    })?;
                let reviewer_peak = ensure_v3_working_peak(
                    log.retained_bytes_v3()?,
                    [authority_entries_retained(&entries)?, registration.size()],
                )?;
                record_v3_test_selected_peak(reviewer_peak);
                v3_add(
                    &mut external_live_bytes,
                    registration.size(),
                    "event-v3 replay external reviewer bytes",
                )?;
                let bytes = resolve_registered_bytes(registration, resolver)?;
                reviewer_raw = Some(ReviewerRawClosure::from_bytes(recorded, &bytes)?);
            }
            if let PersistedPayload::ContextEnvelopeProjected(context) = &payload {
                let (rebuilt, admission) = rebuild_context_projection_from_cas(
                    &log.aggregate,
                    context,
                    |cas_hash, destination| resolver.read_exact(cas_hash, destination),
                    |source_size| {
                        let context_source_peak = ensure_v3_working_peak(
                            log.retained_bytes_v3()?,
                            [authority_entries_retained(&entries)?, source_size],
                        )?;
                        record_v3_test_selected_peak(context_source_peak);
                        v3_add(
                            &mut external_live_bytes,
                            source_size,
                            "event-v3 replay external context bytes",
                        )
                    },
                )?;
                if &rebuilt != context {
                    return Err(DomainError::AuthorityReplayRefused {
                        event_sequence: envelope.sequence(),
                        reason: "context projection bytes do not rebuild from registered sources"
                            .to_owned(),
                    });
                }
                context_projection = Some(PositionedContextProjectionAdmission::seal(
                    envelope, context, admission,
                )?);
            }
            let identity = authority_record_identity(&payload)?;
            let authority_cas_live = authority_payload_cas_working_bytes(
                log.v3_aggregate
                    .as_ref()
                    .ok_or_else(|| DomainError::Validation("missing v3 aggregate".to_owned()))?,
                &payload,
            )?;
            v3_add(
                &mut external_live_bytes,
                authority_cas_live,
                "event-v3 replay external authority CAS bytes",
            )?;
            let authority_cas_peak = ensure_v3_working_peak(
                log.retained_bytes_v3()?,
                [authority_entries_retained(&entries)?, authority_cas_live],
            )?;
            record_v3_test_selected_peak(authority_cas_peak);
            validate_authority_payload_against_cas(
                &log.aggregate,
                log.v3_aggregate
                    .as_ref()
                    .ok_or_else(|| DomainError::Validation("missing v3 aggregate".to_owned()))?,
                &payload,
                resolver,
                roots,
            )
            .map_err(|error| match error {
                incomplete @ DomainError::Incomplete { .. } => incomplete,
                other => DomainError::AuthorityReplayRefused {
                    event_sequence: envelope.sequence(),
                    reason: other.to_string(),
                },
            })?;
            let trust_digest = log
                .v3_aggregate
                .as_ref()
                .ok_or_else(|| DomainError::Validation("missing v3 aggregate".to_owned()))
                .and_then(|state| authority_trust_digest(state, roots, &payload))
                .map_err(|error| DomainError::AuthorityReplayRefused {
                    event_sequence: envelope.sequence(),
                    reason: error.to_string(),
                })?;
            let completion_reserve = projected_authority_completion_reserve(
                &log,
                envelope,
                &entries,
                identity.as_ref(),
                trust_digest.as_ref(),
                &roots.policy_revision_hash,
            )?;
            v3_add(
                &mut external_live_bytes,
                completion_reserve,
                "event-v3 replay completion reserve",
            )?;
            log.append_decoded_v3(
                envelope.clone(),
                payload,
                context_projection,
                reviewer_raw,
                external_live_bytes,
            )
            .map_err(|error| match error {
                incomplete @ DomainError::Incomplete { .. } => incomplete,
                other => DomainError::AuthorityReplayRefused {
                    event_sequence: envelope.sequence(),
                    reason: other.to_string(),
                },
            })?;
            if let (Some((payload_kind, record_id, record_body_hash)), Some(trust_binding_digest)) =
                (identity, trust_digest)
            {
                entries.push(AuthorityReplayEntryV3 {
                    event_sequence: envelope.sequence(),
                    event_id: envelope.id().clone(),
                    payload_kind: payload_kind.to_owned(),
                    record_id,
                    record_body_hash,
                    predecessor_event_hash: envelope.previous_event_hash().clone(),
                    trust_binding_digest,
                });
            }
        }
        let event_count = u64::try_from(log.events.len()).map_err(|_| DomainError::Incomplete {
            operation: "V3 replay event count",
            limit: usize::MAX,
            observed: usize::MAX,
        })?;
        let entries_retained = authority_entries_retained(&entries)?;
        ensure_v3_working_peak(
            log.retained_bytes_v3()?,
            [entries_retained, entries_retained],
        )?;
        let basis = AuthorityReplayBasisV3::build(
            log.run_id.clone(),
            log.genesis_hash.clone(),
            log.tail_hash.clone(),
            event_count,
            roots.policy_revision_hash.clone(),
            entries,
        )?;
        ensure_v3_working_peak(log.retained_bytes_v3()?, [basis.retained_bytes()?])?;
        Ok((log, basis))
    }

    /// Starts an empty log from a validated initial aggregate.
    pub fn new(run_id: StableId, initial: ReviewAggregate) -> Result<Self> {
        Self::new_v2(run_id, initial)
    }

    /// Starts a newly minted v2 stream with its mandatory genesis manifest.
    pub fn new_v2(run_id: StableId, initial: ReviewAggregate) -> Result<Self> {
        let mut log = Self::new_with_version(EventContractVersion::V2, run_id, initial)?;
        log.append_v2_genesis_manifest()?;
        Ok(log)
    }

    /// Starts a fresh homogeneous v3 stream with its size-bound genesis
    /// registration. Durable authority replay is deliberately not exposed by
    /// this constructor.
    pub fn new_v3(run_id: StableId, initial: ReviewAggregate) -> Result<Self> {
        let mut log = Self::new_with_version(EventContractVersion::V3, run_id, initial)?;
        log.append_v3_genesis_manifest()?;
        Ok(log)
    }

    /// Establishes the initial empty authority basis for a healthy fresh v3
    /// session. Once any authority-significant registration or M4 record is
    /// present, callers must use canonical roots-bound replay instead.
    pub fn fresh_authority_basis_v3(
        &self,
        roots: &AuthorityTrustRootsV3,
    ) -> Result<AuthorityReplayBasisV3> {
        if self.version != EventContractVersion::V3 {
            return Err(DomainError::EventV3AuthorityReplayRequired {
                operation: "fresh authority basis",
            });
        }
        validate_repository_trust_root(&self.aggregate, roots)?;
        for event in &self.events {
            let payload = decode_canonical_payload(self.version, event.envelope.payload.get())?;
            if authority_record_identity(&payload)?.is_some()
                || matches!(payload, PersistedPayload::FindingRecordedV3(_))
                || matches!(
                    payload,
                    PersistedPayload::ArtifactRegisteredV3(ref registration)
                        if artifact_source_v3_is_authority_significant(registration.source())
                )
            {
                return Err(DomainError::EventV3AuthorityReplayRequired {
                    operation: "non-pristine authority basis",
                });
            }
        }
        AuthorityReplayBasisV3::build(
            self.run_id.clone(),
            self.genesis_hash.clone(),
            self.tail_hash.clone(),
            u64::try_from(self.events.len()).map_err(|_| DomainError::Incomplete {
                operation: "V3 fresh event count",
                limit: usize::MAX,
                observed: usize::MAX,
            })?,
            roots.policy_revision_hash.clone(),
            Vec::new(),
        )
    }

    pub fn seal_static_verification_attempt_v3(
        &self,
        claim_id: &StableId,
        evaluation: &crate::StaticFactEvaluationV1,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ExpectedVerificationAttemptV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        let claim = self
            .aggregate
            .execution_claims()
            .find(|claim| claim.id() == claim_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        let obligation_id = claim
            .obligation_ids()
            .first()
            .ok_or(DomainError::VerificationBundleMismatch)?;
        let obligation = self
            .aggregate
            .obligation(obligation_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        static_fresh_pre_reconstruction_preflight(self, claim_id, obligation, evaluation, basis)?;
        let reconstructed = crate::m4::reconstruct_static_result_from_durable_input_v1(
            self.aggregate.program(),
            obligation,
            claim,
            evaluation.input(),
        )
        .map_err(m4_domain_error)?;
        if &reconstructed != evaluation.result() {
            return Err(DomainError::VerificationBundleMismatch);
        }
        static_fresh_expectation_preflight(self, claim_id, evaluation, &reconstructed, basis)?;
        let reconstructed_allocated = reconstructed.allocated_bytes().map_err(m4_domain_error)?;
        let borrowed_bytes = u64::try_from(size_of::<crate::StaticFactEvaluationV1>())
            .unwrap_or(u64::MAX)
            .checked_add(evaluation.allocated_bytes().map_err(m4_domain_error)?)
            .and_then(|value| {
                value.checked_add(
                    u64::try_from(size_of::<crate::StaticFactResultV1>()).unwrap_or(u64::MAX),
                )
            })
            .and_then(|value| value.checked_add(reconstructed_allocated))
            .ok_or_else(|| v3_memory_error("static fresh borrowed values", u64::MAX))?;
        expected_static_attempt_from_bytes(
            self,
            claim_id,
            evaluation
                .input()
                .canonical_bytes()
                .map_err(m4_domain_error)?,
            evaluation
                .result()
                .canonical_bytes()
                .map_err(m4_domain_error)?,
            basis,
            1,
            borrowed_bytes,
        )
    }

    pub fn inspect_static_verification_attempt_v3(
        &self,
        claim_id: &StableId,
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<StaticVerificationAttemptInspectionV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "static verification attempt inspection",
            }
        })?;
        let mut input = None;
        let mut output = None;
        for registration in state.registrations.values() {
            let ArtifactSourceV3::VerifierArtifact {
                claim_id: registered_claim,
                descriptor_id,
                procedure_version,
                role,
                ..
            } = registration.source()
            else {
                continue;
            };
            if registered_claim != claim_id {
                continue;
            }
            if descriptor_id != STATIC_DESCRIPTOR_ID || procedure_version != STATIC_PROCEDURE_ID {
                return Err(DomainError::VerificationBundleMismatch);
            }
            let slot = match role {
                VerifierArtifactRoleV3::Input => &mut input,
                VerifierArtifactRoleV3::Output => &mut output,
            };
            if slot.replace(registration).is_some() {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        let Some(input_registration) = input else {
            if output.is_some()
                || state
                    .verifications
                    .values()
                    .any(|record| record.claim_id() == claim_id)
                || state
                    .bindings
                    .values()
                    .any(|record| record.claim_id() == claim_id)
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
            return Ok(StaticVerificationAttemptInspectionV3::Ready);
        };
        let claim = self
            .aggregate
            .execution_claims()
            .find(|claim| claim.id() == claim_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        let obligation_id = claim
            .obligation_ids()
            .first()
            .ok_or(DomainError::VerificationBundleMismatch)?;
        let obligation = self
            .aggregate
            .obligation(obligation_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        static_durable_read_preflight(
            self,
            claim_id,
            obligation,
            claim,
            input_registration.size(),
            basis,
        )?;
        let input_bytes = resolve_registered_bytes(input_registration, resolver)?;
        let input_dto =
            crate::StaticFactInputV1::from_json_bytes(&input_bytes).map_err(m4_domain_error)?;
        static_durable_reconstruction_preflight(
            self,
            claim_id,
            obligation,
            claim,
            &input_bytes,
            &input_dto,
            basis,
        )?;
        let output_dto = crate::m4::reconstruct_static_result_from_durable_input_v1(
            self.aggregate.program(),
            obligation,
            claim,
            &input_dto,
        )
        .map_err(m4_domain_error)?;
        let output_bytes = output_dto.canonical_bytes().map_err(m4_domain_error)?;
        let output_allocated = output_dto.allocated_bytes().map_err(m4_domain_error)?;
        let borrowed_bytes = u64::try_from(size_of::<crate::StaticFactInputV1>())
            .unwrap_or(u64::MAX)
            .checked_add(input_dto.allocated_bytes().map_err(m4_domain_error)?)
            .and_then(|value| {
                value.checked_add(
                    u64::try_from(size_of::<crate::StaticFactResultV1>()).unwrap_or(u64::MAX),
                )
            })
            .and_then(|value| value.checked_add(output_allocated))
            .ok_or_else(|| v3_memory_error("static durable borrowed values", u64::MAX))?;
        let expected = expected_static_attempt_from_bytes(
            self,
            claim_id,
            input_bytes,
            output_bytes,
            basis,
            2,
            borrowed_bytes,
        )?;
        if input_registration != &expected.input_registration
            || output.is_some_and(|registration| registration != &expected.output_registration)
        {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let stage = self.inspect_verification_attempt_v3(&expected, resolver, roots, basis)?;
        Ok(StaticVerificationAttemptInspectionV3::Existing { expected, stage })
    }

    pub fn expect_fixture_verification_attempt_v3(
        &self,
        claim_id: &StableId,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ExpectedVerificationAttemptV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        let claim = exact_fixture_claim_for_log(self, claim_id)?;
        let scope = expected_fixture_scope_for_claim(self, claim, basis)?;
        if roots.harness_for_scope(&scope).is_none() {
            return Err(DomainError::HarnessTrustRootMissing);
        }
        let (_, output_bytes, output_hash) =
            deterministic_fixture_result_for_claim(&self.aggregate, claim, &scope)?;
        let input_bytes = FIXTURE_WITNESS_BYTES.to_vec();
        let input_registration = ArtifactRegisteredV3::new_validated(
            self.run_id.clone(),
            scope.result_hash.clone(),
            FIXTURE_MEDIA_TYPE,
            FIXTURE_WITNESS_SIZE,
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::ExternalHarnessWitness {
                policy_revision_hash: scope.policy_revision_hash.clone(),
                repository_id: scope.repository_id.clone(),
                repository_source_hash: scope.repository_source_hash.clone(),
                run_id: scope.run_id.clone(),
                genesis_hash: scope.genesis_hash.clone(),
                snapshot_id: scope.snapshot_id.clone(),
                universe_id: scope.universe_id.clone(),
                property_id: scope.property_id.clone(),
                claim_id: scope.claim_id.clone(),
                claim_body_hash: scope.claim_body_hash.clone(),
                harness_id: scope.harness_id.clone(),
                harness_revision: scope.harness_revision.clone(),
                harness_source_hash: scope.harness_source_hash.clone(),
                test_artifact_id: scope.test_artifact_id.clone(),
                descriptor_id: scope.descriptor_id.clone(),
                procedure_version: scope.procedure_version.clone(),
            },
        )?;
        let output_registration = ArtifactRegisteredV3::new_validated(
            self.run_id.clone(),
            output_hash,
            FIXTURE_OUTPUT_MEDIA_TYPE,
            u64::try_from(output_bytes.len()).unwrap_or(u64::MAX),
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::VerifierArtifact {
                run_id: self.run_id.clone(),
                claim_id: claim_id.clone(),
                descriptor_id: FIXTURE_DESCRIPTOR_ID.to_owned(),
                procedure_version: FIXTURE_PROCEDURE_ID.to_owned(),
                role: VerifierArtifactRoleV3::Output,
            },
        )?;
        ensure_v3_working_peak(
            self.retained_bytes_v3()?,
            [
                FIXTURE_WITNESS_SIZE,
                u64::try_from(output_bytes.len()).unwrap_or(u64::MAX),
                fixture_scope_allocated_bytes(&scope)?,
                8_192,
            ],
        )?;
        Ok(ExpectedVerificationAttemptV3 {
            kind: ExpectedVerificationKindV3::Fixture,
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            claim_id: claim_id.clone(),
            basis_digest: basis.basis_digest.clone(),
            tail_hash: self.tail_hash.clone(),
            input_registration,
            input_bytes,
            output_registration,
            output_bytes,
        })
    }

    /// Classifies only the exact attempt described by `expected`.  Existing
    /// registrations are re-read from CAS; wrong-role, wrong-source and
    /// ambiguous claim-local registrations are refusals, never misses.
    pub fn inspect_verification_attempt_v3(
        &self,
        expected: &ExpectedVerificationAttemptV3,
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<VerificationAttemptStageV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash
            || expected.run_id != self.run_id
            || expected.genesis_hash != self.genesis_hash
            || expected.basis_digest != basis.basis_digest
            || expected.tail_hash != self.tail_hash
        {
            return Err(DomainError::AuthorityReplayBasisMismatch);
        }
        if expected.kind == ExpectedVerificationKindV3::Fixture {
            let root = roots
                .harness_for_source(&expected.input_registration)
                .ok_or(DomainError::HarnessTrustRootMissing)?;
            validate_fresh_fixture_scope(self, basis, root)?;
        }
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "verification attempt inspection",
            }
        })?;
        let mut input = None;
        let mut output = None;
        for registration in state.registrations.values() {
            let belongs_to_claim = match registration.source() {
                ArtifactSourceV3::VerifierArtifact { claim_id, .. } => {
                    claim_id == &expected.claim_id
                }
                ArtifactSourceV3::ExternalHarnessWitness { claim_id, .. } => {
                    claim_id == &expected.claim_id
                }
                _ => false,
            };
            if !belongs_to_claim {
                continue;
            }
            if registration.registration_id() == expected.input_registration.registration_id() {
                if registration != &expected.input_registration
                    || input.replace(registration).is_some()
                {
                    return Err(DomainError::VerificationBundleMismatch);
                }
            } else if registration.registration_id()
                == expected.output_registration.registration_id()
            {
                if registration != &expected.output_registration
                    || output.replace(registration).is_some()
                {
                    return Err(DomainError::VerificationBundleMismatch);
                }
            } else {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }

        if let Some(registration) = input {
            let bytes = resolve_registered_bytes(registration, resolver)?;
            if bytes != expected.input_bytes {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        if let Some(registration) = output {
            let bytes = resolve_registered_bytes(registration, resolver)?;
            if bytes != expected.output_bytes {
                return Err(DomainError::VerificationBundleMismatch);
            }
        }
        let mut input_event = None;
        let mut output_event = None;
        for event in &self.events {
            let payload = decode_canonical_payload(self.version, event.envelope.payload.get())?;
            if let PersistedPayload::ArtifactRegisteredV3(registration) = payload {
                if registration.registration_id() == expected.input_registration.registration_id() {
                    input_event = Some(&event.envelope);
                }
                if registration.registration_id() == expected.output_registration.registration_id()
                {
                    output_event = Some(&event.envelope);
                }
            }
        }
        match (input, output) {
            (None, None) => return Ok(VerificationAttemptStageV3::Ready),
            (Some(_), None) => {
                let input_event = input_event.ok_or(DomainError::VerificationBundleMismatch)?;
                if self.tail_hash != *input_event.event_hash()
                    || self.next_sequence()?
                        != input_event
                            .sequence()
                            .checked_add(1)
                            .ok_or(DomainError::VerificationBundleMismatch)?
                {
                    return Err(DomainError::VerificationBundleMismatch);
                }
                return Ok(match expected.kind {
                    ExpectedVerificationKindV3::Static => {
                        VerificationAttemptStageV3::InputRegistered
                    }
                    ExpectedVerificationKindV3::Fixture => {
                        VerificationAttemptStageV3::WitnessRegistered
                    }
                });
            }
            (None, Some(_)) => return Err(DomainError::VerificationBundleMismatch),
            (Some(_), Some(_)) => {
                let input_event = input_event.ok_or(DomainError::VerificationBundleMismatch)?;
                let output_event = output_event.ok_or(DomainError::VerificationBundleMismatch)?;
                if output_event.sequence()
                    != input_event
                        .sequence()
                        .checked_add(1)
                        .ok_or(DomainError::VerificationBundleMismatch)?
                    || output_event.previous_event_hash() != input_event.event_hash()
                {
                    return Err(DomainError::VerificationBundleMismatch);
                }
            }
        }

        let (expected_evidence, expected_binding, expected_verification) = match expected.kind {
            ExpectedVerificationKindV3::Static => {
                let proposal = static_proposal_for_registrations(
                    &self.aggregate,
                    state,
                    resolver,
                    expected.input_registration.registration_id(),
                    expected.output_registration.registration_id(),
                )?;
                (
                    proposal.evidence().cloned(),
                    proposal.binding().cloned(),
                    proposal.verification().clone(),
                )
            }
            ExpectedVerificationKindV3::Fixture => {
                let input = state
                    .registrations
                    .get(expected.input_registration.registration_id())
                    .ok_or(DomainError::VerificationBundleMismatch)?;
                let root = roots
                    .harness_for_source(input)
                    .ok_or(DomainError::HarnessTrustRootMissing)?;
                validate_fresh_fixture_scope(self, basis, root)?;
                let result = validate_fixture_result_for_root(
                    &self.aggregate,
                    root,
                    &expected.output_bytes,
                )?;
                let scope = state
                    .assessment_scopes
                    .get(&expected.claim_id)
                    .ok_or(DomainError::VerificationBundleMismatch)?;
                let proposal = crate::m4::materialize_fixture_replay_v1(
                    scope,
                    &result,
                    expected.input_registration.registration_id().clone(),
                    expected.output_registration.registration_id().clone(),
                )
                .map_err(m4_domain_error)?;
                (
                    Some(proposal.evidence),
                    Some(proposal.binding),
                    proposal.verification,
                )
            }
        };

        let evidence_present = if let Some(record) = &expected_evidence {
            state
                .evidence
                .get(record.id())
                .is_some_and(|found| found == record)
        } else {
            false
        };
        let binding_present = if let Some(record) = &expected_binding {
            state
                .bindings
                .get(record.id())
                .is_some_and(|found| found == record)
        } else {
            false
        };
        let verification_present = state
            .verifications
            .get(expected_verification.id())
            .is_some_and(|found| found == &expected_verification);

        let unexpected_evidence = state.evidence.values().any(|record| {
            (record.input_registration_id() == expected.input_registration.registration_id()
                || record.output_registration_id()
                    == expected.output_registration.registration_id())
                && expected_evidence
                    .as_ref()
                    .is_none_or(|expected| record != expected)
        });
        let unexpected_binding = state.bindings.values().any(|record| {
            record.claim_id() == &expected.claim_id
                && expected_binding
                    .as_ref()
                    .is_none_or(|expected| record != expected)
        });
        let unexpected_verification = state.verifications.values().any(|record| {
            record.claim_id() == &expected.claim_id && record != &expected_verification
        });
        if unexpected_evidence || unexpected_binding || unexpected_verification {
            return Err(DomainError::VerificationBundleMismatch);
        }

        let expected_record_count =
            usize::from(expected_evidence.is_some()) + usize::from(expected_binding.is_some()) + 1;
        let present_record_count = usize::from(evidence_present)
            + usize::from(binding_present)
            + usize::from(verification_present);
        if present_record_count == 0 {
            let output_event = output_event.ok_or(DomainError::VerificationBundleMismatch)?;
            if self.tail_hash != *output_event.event_hash()
                || self.next_sequence()?
                    != output_event
                        .sequence()
                        .checked_add(1)
                        .ok_or(DomainError::VerificationBundleMismatch)?
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
            Ok(VerificationAttemptStageV3::OutputRegistered)
        } else if present_record_count == expected_record_count {
            Ok(VerificationAttemptStageV3::Complete)
        } else {
            Ok(VerificationAttemptStageV3::BundlePartial)
        }
    }

    // Every argument is independently sealed into the registration or its
    // authority basis; grouping them would introduce a caller-shaped DTO.
    #[allow(clippy::too_many_arguments)]
    pub fn prepare_static_verifier_artifact_registration_v3(
        &self,
        claim_id: StableId,
        role: VerifierArtifactRoleV3,
        cas_hash: ContentHash,
        size: u64,
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedArtifactRegistrationV3> {
        if !self
            .aggregate
            .execution_claims()
            .any(|claim| claim.id() == &claim_id)
        {
            return Err(DomainError::DanglingReference {
                owner: "static verifier registration claim",
                owner_id: claim_id.clone(),
                reference: claim_id,
            });
        }
        let media_type = match role {
            VerifierArtifactRoleV3::Input => STATIC_INPUT_MEDIA_TYPE,
            VerifierArtifactRoleV3::Output => STATIC_OUTPUT_MEDIA_TYPE,
        };
        let registration = ArtifactRegisteredV3::new_validated(
            self.run_id.clone(),
            cas_hash,
            media_type,
            size,
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::VerifierArtifact {
                run_id: self.run_id.clone(),
                claim_id,
                descriptor_id: STATIC_DESCRIPTOR_ID.to_owned(),
                procedure_version: STATIC_PROCEDURE_ID.to_owned(),
                role,
            },
        )?;
        self.prepare_authority_registration_v3(registration, resolver, roots, basis)
    }

    /// Executes the fixed, checked-in duplicate-submit harness against one
    /// current D2 claim. No replay root, source assertion, hash, path, command,
    /// or harness metadata is accepted from the caller.
    pub fn execute_fixture_harness_v1(
        &self,
        claim_id: &StableId,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<FixtureExecutionReceiptV1> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        let claim = exact_fixture_claim_for_log(self, claim_id)?;
        let scope = expected_fixture_scope_for_claim(self, claim, basis)?;
        if roots.harness_for_scope(&scope).is_none() {
            return Err(DomainError::HarnessTrustRootMissing);
        }
        fixture_stage_preflight(
            1,
            self,
            basis,
            None,
            [
                FIXTURE_WITNESS_SIZE,
                crate::m4::MAX_RECORD_BYTES as u64,
                8_192,
            ],
        )?;
        if crate::harness_source_v1::HARNESS_ID != FIXTURE_HARNESS_ID
            || crate::harness_source_v1::HARNESS_REVISION != FIXTURE_HARNESS_REVISION
        {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let witness_bytes = crate::harness_source_v1::run_duplicate_submit_harness();
        if witness_bytes.as_slice() != FIXTURE_WITNESS_BYTES
            || u64::try_from(witness_bytes.len()).unwrap_or(u64::MAX) != FIXTURE_WITNESS_SIZE
            || ContentHash::sha256(&witness_bytes).as_str() != FIXTURE_WITNESS_HASH
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        let (subject_ids, fixture_result_bytes, fixture_result_hash) =
            deterministic_fixture_result_for_claim(&self.aggregate, claim, &scope)?;
        Ok(FixtureExecutionReceiptV1 {
            harness: Some(TrustedFixtureHarnessV1::from_execution(scope)),
            basis_digest: basis.basis_digest.clone(),
            tail_hash: self.tail_hash.clone(),
            expected_first_sequence: self.next_sequence()?,
            subject_ids,
            fixture_result_hash,
            fixture_result_bytes,
            witness_bytes,
            expected_witness_event: None,
            expected_output_event: None,
        })
    }

    /// Prepares the witness registration emitted by one actual fixture
    /// execution. All durable source fields are derived from the receipt.
    pub fn prepare_external_fixture_witness_registration_v3(
        &self,
        receipt: &mut FixtureExecutionReceiptV1,
        resolver: &impl AuthorityArtifactResolverV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedArtifactRegistrationV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        fixture_stage_preflight(2, self, basis, Some(receipt), [FIXTURE_WITNESS_SIZE, 8_192])?;
        let root = validate_fixture_receipt_for_log(self, receipt, basis, 0)?;
        let registration = ArtifactRegisteredV3::new_validated(
            self.run_id.clone(),
            root.result_hash.clone(),
            FIXTURE_MEDIA_TYPE,
            FIXTURE_WITNESS_SIZE,
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::ExternalHarnessWitness {
                policy_revision_hash: root.policy_revision_hash.clone(),
                repository_id: root.repository_id.clone(),
                repository_source_hash: root.repository_source_hash.clone(),
                run_id: root.run_id.clone(),
                genesis_hash: root.genesis_hash.clone(),
                snapshot_id: root.snapshot_id.clone(),
                universe_id: root.universe_id.clone(),
                property_id: root.property_id.clone(),
                claim_id: root.claim_id.clone(),
                claim_body_hash: root.claim_body_hash.clone(),
                harness_id: root.harness_id.clone(),
                harness_revision: root.harness_revision.clone(),
                harness_source_hash: root.harness_source_hash.clone(),
                test_artifact_id: root.test_artifact_id.clone(),
                descriptor_id: root.descriptor_id.clone(),
                procedure_version: root.procedure_version.clone(),
            },
        )?;
        let bytes = resolve_registered_bytes(&registration, resolver)?;
        validate_fresh_fixture_witness_registration(&self.aggregate, &registration, &bytes, root)?;
        let expected = expected_fixture_registration_event(self, &registration)?;
        if let Some(prior) = &receipt.expected_witness_event
            && !same_expected_fixture_event(prior, &expected)?
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        receipt.expected_witness_event = Some(expected);
        Ok(ValidatedArtifactRegistrationV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
            registration,
        })
    }

    /// Prepares the deterministic fixture-result output registration for one
    /// exact D2 claim. Only its already-CAS-backed hash and size are named.
    pub fn prepare_fixture_verifier_output_registration_v3(
        &self,
        receipt: &mut FixtureExecutionReceiptV1,
        resolver: &impl AuthorityArtifactResolverV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedArtifactRegistrationV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        fixture_stage_preflight(
            3,
            self,
            basis,
            Some(receipt),
            [
                u64::try_from(receipt.fixture_result_bytes.len()).unwrap_or(u64::MAX),
                8_192,
            ],
        )?;
        let root = validate_fixture_receipt_for_log(self, receipt, basis, 1)?;
        let registration = ArtifactRegisteredV3::new_validated(
            self.run_id.clone(),
            receipt.fixture_result_hash.clone(),
            FIXTURE_OUTPUT_MEDIA_TYPE,
            u64::try_from(receipt.fixture_result_bytes.len()).map_err(|_| {
                DomainError::Incomplete {
                    operation: "fixture result registration size",
                    limit: usize::MAX,
                    observed: usize::MAX,
                }
            })?,
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::VerifierArtifact {
                run_id: self.run_id.clone(),
                claim_id: root.claim_id.clone(),
                descriptor_id: FIXTURE_DESCRIPTOR_ID.to_owned(),
                procedure_version: FIXTURE_PROCEDURE_ID.to_owned(),
                role: VerifierArtifactRoleV3::Output,
            },
        )?;
        let bytes = resolve_registered_bytes(&registration, resolver)?;
        if bytes != receipt.fixture_result_bytes {
            return Err(DomainError::VerificationBundleMismatch);
        }
        validate_fixture_result_for_root(&self.aggregate, root, &bytes)?;
        let expected = expected_fixture_registration_event(self, &registration)?;
        if let Some(prior) = &receipt.expected_output_event
            && !same_expected_fixture_event(prior, &expected)?
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        receipt.expected_output_event = Some(expected);
        Ok(ValidatedArtifactRegistrationV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
            registration,
        })
    }

    fn prepare_authority_registration_v3(
        &self,
        registration: ArtifactRegisteredV3,
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedArtifactRegistrationV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        let admitted_registration = matches!(
            registration.source(),
            ArtifactSourceV3::VerifierArtifact {
                descriptor_id,
                procedure_version,
                role: VerifierArtifactRoleV3::Input | VerifierArtifactRoleV3::Output,
                ..
            } if descriptor_id == STATIC_DESCRIPTOR_ID
                && procedure_version == STATIC_PROCEDURE_ID
        ) || matches!(
            registration.source(),
            ArtifactSourceV3::VerifierArtifact {
                descriptor_id,
                procedure_version,
                role: VerifierArtifactRoleV3::Output,
                ..
            } if descriptor_id == FIXTURE_DESCRIPTOR_ID
                && procedure_version == FIXTURE_PROCEDURE_ID
        ) || matches!(
            registration.source(),
            ArtifactSourceV3::ExternalHarnessWitness { .. }
        );
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        if self.version != EventContractVersion::V3
            || !admitted_registration
            || registration.run_id() != &self.run_id
        {
            return Err(DomainError::Validation(
                "fresh v3 authority registration is outside the closed verifier registry"
                    .to_owned(),
            ));
        }
        ensure_v3_working_peak(
            self.v3_aggregate
                .as_ref()
                .ok_or(DomainError::EventV3AuthorityReplayRequired {
                    operation: "authority registration prepare",
                })?
                .retained_bytes()?,
            [registration.size()],
        )?;
        let bytes = resolve_registered_bytes(&registration, resolver)?;
        validate_authority_registration(
            &self.aggregate,
            &registration,
            &bytes,
            roots,
            &self.genesis_hash,
        )?;
        Ok(ValidatedArtifactRegistrationV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
            registration,
        })
    }

    pub fn append_authority_registration_v3(
        &mut self,
        validated: ValidatedArtifactRegistrationV3,
        basis: &mut AuthorityReplayBasisV3,
    ) -> Result<&Event> {
        if validated.run_id != self.run_id
            || validated.genesis_hash != self.genesis_hash
            || validated.tail_hash != self.tail_hash
            || validated.sequence != self.next_sequence()?
        {
            return Err(DomainError::AuthorityReplayBasisMismatch);
        }
        let payload = PersistedPayload::ArtifactRegisteredV3(validated.registration);
        self.preflight_v3_outer_transaction(basis, std::slice::from_ref(&payload))?;
        basis.validate_for_log(self)?;
        mark_v3_transaction_allocation_seam();
        let actor = payload.actor().to_owned();
        let envelope = EventEnvelope::new(
            self.version,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            validated.sequence,
            actor,
            validated.sequence,
            self.tail_hash.clone(),
            payload,
        )?;
        let mut next = self.clone();
        next.append_envelope(envelope, None, None, None, None, None, None, true)?;
        let next_basis = basis.advanced_for_log(&next, basis.entries.clone())?;
        *self = next;
        *basis = next_basis;
        self.events.last().ok_or_else(|| {
            DomainError::EventSequence("authority registration append was not retained".to_owned())
        })
    }

    /// Reconstructs narrowly scoped authority after the exact fixed fixture
    /// witness registration became durable.  This path never runs the
    /// harness and never reconstructs `TrustedFixtureHarnessV1`.
    pub fn recover_fixture_registration_resume_authority_v3(
        &self,
        claim_id: &StableId,
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<FixtureRegistrationResumeAuthorityV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        let claim = exact_fixture_claim_for_log(self, claim_id)?;
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "fixture registration resume",
            }
        })?;

        // A registration resume authority is valid only before any bundle or
        // human-review record for this claim.  Bundle-prefix recovery has its
        // own, separately sealed authority.
        if state
            .verifications
            .values()
            .any(|record| record.claim_id() == claim_id)
        {
            return Err(DomainError::AlreadyComplete);
        }
        if state
            .bindings
            .values()
            .any(|record| record.claim_id() == claim_id)
            || state
                .decisions
                .values()
                .any(|record| record.claim_id() == claim_id)
            || state
                .findings
                .values()
                .any(|record| record.claim_id() == claim_id)
        {
            return Err(DomainError::VerificationBundleMismatch);
        }

        let mut witness = None;
        let mut output = None;
        for registration in state.registrations.values() {
            match registration.source() {
                ArtifactSourceV3::ExternalHarnessWitness {
                    claim_id: registered_claim,
                    ..
                } if registered_claim == claim_id => match witness {
                    None => witness = Some(registration),
                    Some(_) => return Err(DomainError::VerificationBundleMismatch),
                },
                ArtifactSourceV3::VerifierArtifact {
                    claim_id: registered_claim,
                    descriptor_id,
                    procedure_version,
                    role,
                    ..
                } if registered_claim == claim_id => {
                    if descriptor_id != FIXTURE_DESCRIPTOR_ID
                        || procedure_version != FIXTURE_PROCEDURE_ID
                        || *role != VerifierArtifactRoleV3::Output
                    {
                        return Err(DomainError::VerificationBundleMismatch);
                    }
                    match output {
                        None => output = Some(registration),
                        Some(_) => return Err(DomainError::VerificationBundleMismatch),
                    }
                }
                _ => {}
            }
        }
        let witness = witness.ok_or(DomainError::WitnessAdmissionMismatch)?;
        if state.evidence.values().any(|record| {
            [
                record.input_registration_id(),
                record.output_registration_id(),
            ]
            .into_iter()
            .any(|registration_id| {
                state
                    .registrations
                    .get(registration_id)
                    .is_some_and(|registration| match registration.source() {
                        ArtifactSourceV3::VerifierArtifact {
                            claim_id: registered_claim,
                            ..
                        }
                        | ArtifactSourceV3::ExternalHarnessWitness {
                            claim_id: registered_claim,
                            ..
                        } => registered_claim == claim_id,
                        _ => false,
                    })
            })
        }) {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let root = roots
            .harness_for_source(witness)
            .ok_or(DomainError::HarnessTrustRootMissing)?;
        validate_fresh_fixture_scope(self, basis, root)?;
        if !fixture_registration_matches_scope(witness, root) {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        let witness_bytes = resolve_registered_bytes(witness, resolver)?;
        validate_fresh_fixture_witness_registration(
            &self.aggregate,
            witness,
            &witness_bytes,
            root,
        )?;
        let (_, fixture_result_bytes, fixture_result_hash) =
            deterministic_fixture_result_for_claim(&self.aggregate, claim, root)?;

        let mut witness_event = None;
        let mut output_event = None;
        for event in &self.events {
            let payload = decode_canonical_payload(self.version, event.envelope.payload.get())?;
            if let PersistedPayload::ArtifactRegisteredV3(registration) = payload {
                if registration.registration_id() == witness.registration_id() {
                    witness_event = Some(&event.envelope);
                }
                if output.is_some_and(|candidate| {
                    candidate.registration_id() == registration.registration_id()
                }) {
                    output_event = Some(&event.envelope);
                }
            }
        }
        let witness_event = witness_event.ok_or(DomainError::WitnessAdmissionMismatch)?;
        let output_registration_id = if let Some(output) = output {
            let output_event = output_event.ok_or(DomainError::VerificationBundleMismatch)?;
            if !verifier_registration_matches(
                output,
                claim_id,
                FIXTURE_DESCRIPTOR_ID,
                FIXTURE_PROCEDURE_ID,
                VerifierArtifactRoleV3::Output,
            ) || output.cas_hash() != &fixture_result_hash
                || output.size() != u64::try_from(fixture_result_bytes.len()).unwrap_or(u64::MAX)
                || output.media_type() != FIXTURE_OUTPUT_MEDIA_TYPE
                || output.sensitivity() != ArtifactSensitivity::CanonicalState
                || output_event.sequence()
                    != witness_event
                        .sequence()
                        .checked_add(1)
                        .ok_or(DomainError::VerificationBundleMismatch)?
                || output_event.previous_event_hash() != witness_event.event_hash()
                || self.tail_hash != *output_event.event_hash()
            {
                return Err(DomainError::VerificationBundleMismatch);
            }
            let bytes = resolve_registered_bytes(output, resolver)?;
            if bytes != fixture_result_bytes {
                return Err(DomainError::VerificationBundleMismatch);
            }
            Some(output.registration_id().clone())
        } else {
            if self.tail_hash != *witness_event.event_hash()
                || self.next_sequence()?
                    != witness_event
                        .sequence()
                        .checked_add(1)
                        .ok_or(DomainError::WitnessAdmissionMismatch)?
            {
                return Err(DomainError::WitnessAdmissionMismatch);
            }
            None
        };

        fixture_stage_preflight(
            6,
            self,
            basis,
            None,
            [
                fixture_scope_allocated_bytes(root)?,
                u64::try_from(fixture_result_bytes.len()).unwrap_or(u64::MAX),
                8_192,
            ],
        )?;
        Ok(FixtureRegistrationResumeAuthorityV3 {
            scope: clone_harness_root_input(root),
            basis_digest: basis.basis_digest.clone(),
            tail_hash: self.tail_hash.clone(),
            expected_sequence: self.next_sequence()?,
            witness_registration_id: witness.registration_id().clone(),
            output_registration_id,
            fixture_result_hash,
            fixture_result_bytes,
            expected_output_event: None,
        })
    }

    /// Prepares the first missing deterministic fixture output registration.
    /// A token recovered after an already-durable output cannot use this seam.
    pub fn prepare_fixture_output_from_resume_v3(
        &self,
        authority: &mut FixtureRegistrationResumeAuthorityV3,
        resolver: &impl AuthorityArtifactResolverV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedArtifactRegistrationV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        fixture_stage_preflight(
            7,
            self,
            basis,
            None,
            [
                u64::try_from(authority.fixture_result_bytes.len()).unwrap_or(u64::MAX),
                8_192,
            ],
        )?;
        if authority.output_registration_id.is_some()
            || authority.basis_digest != basis.basis_digest
            || authority.tail_hash != self.tail_hash
            || authority.expected_sequence != self.next_sequence()?
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        validate_fresh_fixture_scope(self, basis, &authority.scope)?;
        let registration = ArtifactRegisteredV3::new_validated(
            self.run_id.clone(),
            authority.fixture_result_hash.clone(),
            FIXTURE_OUTPUT_MEDIA_TYPE,
            u64::try_from(authority.fixture_result_bytes.len()).map_err(|_| {
                DomainError::Incomplete {
                    operation: "fixture resume result registration size",
                    limit: usize::MAX,
                    observed: usize::MAX,
                }
            })?,
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::VerifierArtifact {
                run_id: self.run_id.clone(),
                claim_id: authority.scope.claim_id.clone(),
                descriptor_id: FIXTURE_DESCRIPTOR_ID.to_owned(),
                procedure_version: FIXTURE_PROCEDURE_ID.to_owned(),
                role: VerifierArtifactRoleV3::Output,
            },
        )?;
        let bytes = resolve_registered_bytes(&registration, resolver)?;
        if bytes != authority.fixture_result_bytes {
            return Err(DomainError::VerificationBundleMismatch);
        }
        validate_fixture_result_for_root(&self.aggregate, &authority.scope, &bytes)?;
        let expected = expected_fixture_registration_event(self, &registration)?;
        authority.output_registration_id = Some(registration.registration_id().clone());
        authority.expected_output_event = Some(expected);
        Ok(ValidatedArtifactRegistrationV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
            registration,
        })
    }

    /// Consumes registration-resume authority and reconstructs the exact
    /// fixture E→B→V proposal from durable CAS-backed registrations.
    pub fn mint_fixture_verification_bundle_from_resume_v3(
        &self,
        authority: FixtureRegistrationResumeAuthorityV3,
        resolver: &impl AuthorityArtifactResolverV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedVerificationBundleV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        fixture_stage_preflight(
            8,
            self,
            basis,
            None,
            [
                FIXTURE_WITNESS_SIZE,
                u64::try_from(authority.fixture_result_bytes.len()).unwrap_or(u64::MAX),
                3 * crate::m4::MAX_RECORD_BYTES as u64,
                8_192,
            ],
        )?;
        let output_registration_id = authority
            .output_registration_id
            .as_ref()
            .ok_or(DomainError::VerificationBundleMismatch)?;
        match &authority.expected_output_event {
            Some(expected) => {
                if expected.envelope.sequence() != authority.expected_sequence
                    || expected.envelope.previous_event_hash() != &authority.tail_hash
                    || authority.expected_sequence.checked_add(1) != Some(self.next_sequence()?)
                {
                    return Err(DomainError::WitnessAdmissionMismatch);
                }
                let observed = self
                    .events
                    .last()
                    .ok_or(DomainError::WitnessAdmissionMismatch)?;
                if observed.envelope.sequence() != expected.envelope.sequence()
                    || observed.envelope.event_hash() != expected.envelope.event_hash()
                    || observed.envelope.canonical_bytes()?
                        != expected.envelope.canonical_bytes()?
                {
                    return Err(DomainError::WitnessAdmissionMismatch);
                }
            }
            None => {
                if authority.basis_digest != basis.basis_digest
                    || authority.tail_hash != self.tail_hash
                    || authority.expected_sequence != self.next_sequence()?
                {
                    return Err(DomainError::WitnessAdmissionMismatch);
                }
            }
        }
        validate_fresh_fixture_scope(self, basis, &authority.scope)?;
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "fixture registration resume bundle mint",
            }
        })?;
        let input = state
            .registrations
            .get(&authority.witness_registration_id)
            .ok_or(DomainError::WitnessAdmissionMismatch)?;
        let output = state
            .registrations
            .get(output_registration_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        if !fixture_registration_matches_scope(input, &authority.scope)
            || !verifier_registration_matches(
                output,
                &authority.scope.claim_id,
                FIXTURE_DESCRIPTOR_ID,
                FIXTURE_PROCEDURE_ID,
                VerifierArtifactRoleV3::Output,
            )
        {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let witness_bytes = resolve_registered_bytes(input, resolver)?;
        validate_fresh_fixture_witness_registration(
            &self.aggregate,
            input,
            &witness_bytes,
            &authority.scope,
        )?;
        let output_bytes = resolve_registered_bytes(output, resolver)?;
        if output_bytes != authority.fixture_result_bytes {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let result =
            validate_fixture_result_for_root(&self.aggregate, &authority.scope, &output_bytes)?;
        let scope = state
            .assessment_scopes
            .get(&authority.scope.claim_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        let proposal = crate::m4::materialize_fixture_replay_v1(
            scope,
            &result,
            input.registration_id().clone(),
            output.registration_id().clone(),
        )
        .map_err(m4_domain_error)?;
        let payloads = vec![
            PersistedPayload::EvidenceRecordedV3(proposal.evidence),
            PersistedPayload::EvidenceBoundV3(proposal.binding),
            PersistedPayload::VerificationRecordedV3(proposal.verification),
        ];
        let trust_digest = trust_digest_for_harness(&authority.scope)?;
        Ok(ValidatedVerificationBundleV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            first_sequence: self.next_sequence()?,
            trust_digests: vec![trust_digest; payloads.len()],
            payloads,
        })
    }

    /// Consumes the authority in one actual execution receipt only after all
    /// durable-state, CAS, and allocation checks have succeeded.
    pub fn admit_external_witness_v3(
        &self,
        receipt: &mut FixtureExecutionReceiptV1,
        witness_registration_id: &StableId,
        resolver: &impl AuthorityArtifactResolverV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ExternalWitnessAdmissionV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        fixture_stage_preflight(4, self, basis, Some(receipt), [FIXTURE_WITNESS_SIZE, 8_192])?;
        if self.next_sequence()?
            != receipt
                .expected_first_sequence
                .checked_add(2)
                .ok_or(DomainError::WitnessAdmissionMismatch)?
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        let root = validate_fixture_receipt_for_log(self, receipt, basis, 2)?;
        if receipt
            .expected_witness_event
            .as_ref()
            .is_none_or(|expected| &expected.registration_id != witness_registration_id)
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "external witness admission",
            }
        })?;
        let registration = state
            .registrations
            .get(witness_registration_id)
            .ok_or_else(|| DomainError::DanglingReference {
                owner: "external witness admission",
                owner_id: root.claim_id.clone(),
                reference: witness_registration_id.clone(),
            })?;
        if !fixture_registration_matches_scope(registration, root) {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        let witness_bytes = resolve_registered_bytes(registration, resolver)?;
        validate_fresh_fixture_witness_registration(
            &self.aggregate,
            registration,
            &witness_bytes,
            root,
        )?;
        let trusted = receipt
            .harness
            .take()
            .ok_or(DomainError::WitnessAdmissionMismatch)?;
        Ok(ExternalWitnessAdmissionV3 {
            harness: trusted,
            basis_digest: basis.basis_digest.clone(),
            tail_hash: self.tail_hash.clone(),
            expected_first_sequence: self.next_sequence()?,
            witness_registration_id: witness_registration_id.clone(),
        })
    }

    /// Consumes one exact witness admission and seals the deterministic
    /// Evidence -> Reproduces Binding -> Passed Verification suffix.
    pub fn mint_fixture_verification_bundle_v3(
        &self,
        admission: ExternalWitnessAdmissionV3,
        output_registration_id: &StableId,
        resolver: &impl AuthorityArtifactResolverV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedVerificationBundleV3> {
        self.require_writable()?;
        basis.validate_for_log(self)?;
        fixture_stage_preflight(
            5,
            self,
            basis,
            None,
            [
                FIXTURE_WITNESS_SIZE,
                crate::m4::MAX_RECORD_BYTES as u64,
                3 * crate::m4::MAX_RECORD_BYTES as u64,
                8_192,
            ],
        )?;
        if admission.basis_digest != basis.basis_digest
            || admission.tail_hash != self.tail_hash
            || admission.expected_first_sequence != self.next_sequence()?
        {
            return Err(DomainError::WitnessAdmissionMismatch);
        }
        let root = &admission.harness.scope;
        validate_fresh_fixture_scope(self, basis, root)?;
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "fixture verification bundle mint",
            }
        })?;
        let input = state
            .registrations
            .get(&admission.witness_registration_id)
            .ok_or(DomainError::WitnessAdmissionMismatch)?;
        let output = state
            .registrations
            .get(output_registration_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        if !fixture_registration_matches_scope(input, root)
            || !verifier_registration_matches(
                output,
                &root.claim_id,
                FIXTURE_DESCRIPTOR_ID,
                FIXTURE_PROCEDURE_ID,
                VerifierArtifactRoleV3::Output,
            )
        {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let witness_bytes = resolve_registered_bytes(input, resolver)?;
        validate_fresh_fixture_witness_registration(&self.aggregate, input, &witness_bytes, root)?;
        let output_bytes = resolve_registered_bytes(output, resolver)?;
        let result = validate_fixture_result_for_root(&self.aggregate, root, &output_bytes)?;
        let scope = state
            .assessment_scopes
            .get(&root.claim_id)
            .ok_or(DomainError::VerificationBundleMismatch)?;
        let proposal = crate::m4::materialize_fixture_replay_v1(
            scope,
            &result,
            input.registration_id().clone(),
            output.registration_id().clone(),
        )
        .map_err(m4_domain_error)?;
        let payloads = vec![
            PersistedPayload::EvidenceRecordedV3(proposal.evidence),
            PersistedPayload::EvidenceBoundV3(proposal.binding),
            PersistedPayload::VerificationRecordedV3(proposal.verification),
        ];
        let proposal_staging = payloads.iter().try_fold(0_u64, |mut total, payload| {
            v3_add(
                &mut total,
                v3_payload_staging_bytes(payload)?,
                "event-v3 fixture proposal staging",
            )?;
            Ok(total)
        })?;
        ensure_v3_working_peak(
            self.retained_bytes_v3()?,
            [basis.retained_bytes()?, proposal_staging],
        )?;
        let trust_digest = trust_digest_for_harness(root)?;
        let trust_digests = vec![trust_digest; payloads.len()];
        Ok(ValidatedVerificationBundleV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            first_sequence: self.next_sequence()?,
            payloads,
            trust_digests,
        })
    }

    pub fn mint_static_verification_bundle_v3(
        &self,
        claim_id: &StableId,
        input_registration_id: &StableId,
        output_registration_id: &StableId,
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedVerificationBundleV3> {
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "static verification bundle mint",
            }
        })?;
        let input_size = state
            .registrations
            .get(input_registration_id)
            .ok_or(DomainError::VerificationBundleMismatch)?
            .size();
        let output_size = state
            .registrations
            .get(output_registration_id)
            .ok_or(DomainError::VerificationBundleMismatch)?
            .size();
        ensure_v3_working_peak(state.retained_bytes()?, [input_size, output_size])?;
        let proposal = static_proposal_for_registrations(
            &self.aggregate,
            state,
            resolver,
            input_registration_id,
            output_registration_id,
        )?;
        if proposal.verification().claim_id() != claim_id {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let mut payloads = Vec::new();
        if let Some(evidence) = proposal.evidence() {
            payloads.push(PersistedPayload::EvidenceRecordedV3(evidence.clone()));
        }
        if let Some(binding) = proposal.binding() {
            payloads.push(PersistedPayload::EvidenceBoundV3(binding.clone()));
        }
        payloads.push(PersistedPayload::VerificationRecordedV3(
            proposal.verification().clone(),
        ));
        let mut proposal_staging = 0_u64;
        for payload in &payloads {
            v3_add(
                &mut proposal_staging,
                v3_payload_staging_bytes(payload)?,
                "event-v3 verification proposal staging",
            )?;
        }
        ensure_v3_working_peak(state.retained_bytes()?, [proposal_staging])?;
        let digest = static_trust_digest(roots)?;
        let trust_digests = vec![digest; payloads.len()];
        Ok(ValidatedVerificationBundleV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            first_sequence: self.next_sequence()?,
            payloads,
            trust_digests,
        })
    }

    pub fn append_verification_bundle_v3(
        &mut self,
        bundle: ValidatedVerificationBundleV3,
        basis: &mut AuthorityReplayBasisV3,
    ) -> Result<VerificationBundleReceiptV3> {
        if bundle.run_id != self.run_id
            || bundle.genesis_hash != self.genesis_hash
            || bundle.tail_hash != self.tail_hash
            || bundle.first_sequence != self.next_sequence()?
            || bundle.payloads.len() != bundle.trust_digests.len()
        {
            return Err(DomainError::VerificationBundleMismatch);
        }
        let verification_id = bundle
            .payloads
            .iter()
            .find_map(|payload| match payload {
                PersistedPayload::VerificationRecordedV3(value) => Some(value.id().clone()),
                _ => None,
            })
            .ok_or(DomainError::VerificationBundleMismatch)?;
        self.preflight_v3_outer_transaction(basis, &bundle.payloads)?;
        basis.validate_for_log(self)?;
        mark_v3_transaction_allocation_seam();
        let mut next = self.clone();
        let mut entries = basis.entries.clone();
        let mut event_ids = Vec::new();
        entries
            .try_reserve(bundle.payloads.len())
            .map_err(|_| DomainError::Incomplete {
                operation: "V3 authority replay entries",
                limit: basis.entries.len().saturating_add(bundle.payloads.len()),
                observed: basis.entries.len().saturating_add(bundle.payloads.len()),
            })?;
        event_ids
            .try_reserve_exact(bundle.payloads.len())
            .map_err(|_| DomainError::Incomplete {
                operation: "V3 verification bundle event IDs",
                limit: bundle.payloads.len(),
                observed: bundle.payloads.len(),
            })?;
        for (payload, trust_binding_digest) in bundle.payloads.into_iter().zip(bundle.trust_digests)
        {
            let sequence = next.next_sequence()?;
            let actor = payload.actor().to_owned();
            let identity = authority_record_identity(&payload)?
                .ok_or(DomainError::VerificationBundleMismatch)?;
            let envelope = EventEnvelope::new(
                next.version,
                next.run_id.clone(),
                next.genesis_hash.clone(),
                sequence,
                actor,
                sequence,
                next.tail_hash.clone(),
                payload,
            )?;
            let predecessor_event_hash = envelope.previous_event_hash().clone();
            next.append_envelope(envelope, None, None, None, None, None, None, true)?;
            let event = next.events.last().ok_or_else(|| {
                DomainError::EventSequence("bundle append did not retain its event".to_owned())
            })?;
            event_ids.push(event.envelope.id().clone());
            entries.push(AuthorityReplayEntryV3 {
                event_sequence: sequence,
                event_id: event.envelope.id().clone(),
                payload_kind: identity.0.to_owned(),
                record_id: identity.1,
                record_body_hash: identity.2,
                predecessor_event_hash,
                trust_binding_digest,
            });
        }
        let next_basis = basis.advanced_for_log(&next, entries)?;
        *self = next;
        *basis = next_basis;
        Ok(VerificationBundleReceiptV3 {
            event_ids,
            verification_id,
        })
    }

    /// Reconstructs narrowly scoped authority for a partially durable
    /// verification bundle. Stage zero is intentionally refused: fresh
    /// execution authority cannot be recreated from a store marker.
    #[allow(clippy::too_many_arguments)]
    pub fn recover_verification_bundle_resume_authority_v3(
        pre_bundle_log: &EventLog,
        pre_bundle_basis: &AuthorityReplayBasisV3,
        current_log: &EventLog,
        current_basis: &AuthorityReplayBasisV3,
        planned_envelopes: &[EventEnvelope],
        resolver: &impl AuthorityArtifactResolverV3,
        roots: &AuthorityTrustRootsV3,
    ) -> Result<VerificationBundleResumeAuthorityV3> {
        pre_bundle_log
            .require_writable()
            .map_err(bundle_resume_mismatch)?;
        current_log
            .require_writable()
            .map_err(bundle_resume_mismatch)?;
        pre_bundle_basis
            .validate_for_log(pre_bundle_log)
            .map_err(bundle_resume_mismatch)?;
        current_basis
            .validate_for_log(current_log)
            .map_err(bundle_resume_mismatch)?;
        validate_repository_trust_root(&pre_bundle_log.aggregate, roots)
            .map_err(bundle_resume_mismatch)?;
        validate_repository_trust_root(&current_log.aggregate, roots)
            .map_err(bundle_resume_mismatch)?;
        if pre_bundle_basis.policy_revision_hash != roots.policy_revision_hash
            || current_basis.policy_revision_hash != roots.policy_revision_hash
            || pre_bundle_log.run_id != current_log.run_id
            || pre_bundle_log.genesis_hash != current_log.genesis_hash
            || planned_envelopes.len() < 2
            || planned_envelopes.len() > 3
        {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        let pre_count = pre_bundle_log.events.len();
        let durable_stage = current_log
            .events
            .len()
            .checked_sub(pre_count)
            .ok_or(DomainError::BundleResumeAuthorityMismatch)?;
        if durable_stage == planned_envelopes.len() {
            return Err(DomainError::AlreadyComplete);
        }
        if durable_stage == 0 || durable_stage > planned_envelopes.len() {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        let current_envelopes_projected =
            current_log
                .envelopes()
                .try_fold(0_u64, |mut total, envelope| {
                    v3_add(
                        &mut total,
                        u64::try_from(size_of::<EventEnvelope>() + envelope.allocated_bytes())
                            .unwrap_or(u64::MAX),
                        "verification bundle recovery current envelopes",
                    )?;
                    Ok(total)
                })?;
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            0,
            [current_envelopes_projected],
        )?;

        let mut current_envelopes = Vec::new();
        current_envelopes
            .try_reserve_exact(current_log.events.len())
            .map_err(|_| {
                v3_memory_error(
                    "verification bundle recovery current envelopes",
                    current_envelopes_projected,
                )
            })?;
        current_envelopes.extend(current_log.envelopes().cloned());
        let current_envelopes_owned = envelope_slice_owned_bytes(&current_envelopes)?;
        let same_canonical_envelope =
            |observed: &EventEnvelope, expected: &EventEnvelope| -> Result<bool> {
                let observed_canonical = crate::canonical::canonical_json_count_bounded(
                    observed,
                    crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
                    "verification bundle recovery observed envelope",
                )?;
                let expected_canonical = crate::canonical::canonical_json_count_bounded(
                    expected,
                    crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
                    "verification bundle recovery expected envelope",
                )?;
                preflight_verification_bundle_recovery(
                    pre_bundle_log,
                    pre_bundle_basis,
                    current_log,
                    current_basis,
                    planned_envelopes,
                    roots,
                    0,
                    [
                        current_envelopes_owned,
                        observed_canonical,
                        expected_canonical,
                    ],
                )?;
                Ok(observed.id() == expected.id()
                    && observed.event_hash() == expected.event_hash()
                    && observed.canonical_bytes()? == expected.canonical_bytes()?)
            };
        for (observed, expected) in current_envelopes
            .iter()
            .take(pre_count)
            .zip(pre_bundle_log.envelopes())
        {
            if !same_canonical_envelope(observed, expected)? {
                return Err(DomainError::BundleResumeAuthorityMismatch);
            }
        }
        for (observed, expected) in current_envelopes[pre_count..]
            .iter()
            .zip(&planned_envelopes[..durable_stage])
        {
            if !same_canonical_envelope(observed, expected)? {
                return Err(DomainError::BundleResumeAuthorityMismatch);
            }
        }

        let payloads_projected = planned_envelopes.iter().try_fold(
            u64::try_from(
                planned_envelopes
                    .len()
                    .saturating_mul(size_of::<PersistedPayload>()),
            )
            .unwrap_or(u64::MAX),
            |mut total, envelope| {
                v3_add(
                    &mut total,
                    u64::try_from(envelope.payload.get().len()).unwrap_or(u64::MAX),
                    "verification bundle recovery decoded payloads",
                )?;
                Ok(total)
            },
        )?;
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            0,
            [current_envelopes_owned, payloads_projected],
        )?;
        let mut payloads = Vec::new();
        payloads
            .try_reserve_exact(planned_envelopes.len())
            .map_err(|_| {
                v3_memory_error(
                    "verification bundle recovery decoded payloads",
                    payloads_projected,
                )
            })?;
        for envelope in planned_envelopes {
            payloads.push(
                decode_canonical_payload(EventContractVersion::V3, envelope.payload.get())
                    .map_err(bundle_resume_mismatch)?,
            );
        }
        let verification_id =
            validate_verification_bundle_plan_shape(&payloads).map_err(bundle_resume_mismatch)?;
        let claim_id = match payloads.last() {
            Some(PersistedPayload::VerificationRecordedV3(value)) => value.claim_id(),
            _ => return Err(DomainError::BundleResumeAuthorityMismatch),
        };
        let raw_registration = claim_raw_registration(pre_bundle_log, claim_id)?;
        let raw_cas_bytes = raw_registration.size();
        let payloads_owned = payload_vec_owned_bytes(&payloads)?;
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [current_envelopes_owned, payloads_owned],
        )?;
        let raw_bytes = match resolve_registered_bytes(raw_registration, resolver) {
            Ok(bytes) => bytes,
            Err(incomplete @ DomainError::Incomplete { .. }) => return Err(incomplete),
            Err(_) => {
                return Err(DomainError::ClaimRawClosureMissing {
                    claim_id: claim_id.clone(),
                    registration_id: raw_registration.registration_id().clone(),
                });
            }
        };

        let complete_envelopes_owned = envelope_slice_owned_bytes(&current_envelopes[..pre_count])?
            .checked_add(envelope_slice_owned_bytes(planned_envelopes)?)
            .ok_or_else(|| {
                v3_memory_error("verification bundle recovery complete envelopes", u64::MAX)
            })?;
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
            ],
        )?;
        let mut complete_envelopes = current_envelopes[..pre_count].to_vec();
        complete_envelopes.extend(planned_envelopes.iter().cloned());
        let genesis_snapshot_owned =
            RunGenesisSnapshot::projected_owned_bytes(&pre_bundle_log.initial)?;
        let genesis_canonical_count = crate::canonical::canonical_json_count_bounded(
            &BorrowedRunGenesisSnapshot(&pre_bundle_log.initial),
            crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
            "verification bundle recovery genesis canonical count",
        )?;
        let genesis_peak = preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
                genesis_snapshot_owned,
                genesis_canonical_count,
            ],
        )?;
        ensure_recovery_genesis_test_limit(genesis_peak)?;
        mark_recovery_genesis_allocation_seam();
        let genesis_snapshot = pre_bundle_log.run_genesis_snapshot()?;
        if genesis_snapshot.owned_bytes()? != genesis_snapshot_owned {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        let genesis_bytes = genesis_snapshot.canonical_bytes()?;
        if u64::try_from(genesis_bytes.len()).unwrap_or(u64::MAX) != genesis_canonical_count {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        drop(genesis_snapshot);
        let genesis_owned = u64::try_from(genesis_bytes.capacity()).unwrap_or(u64::MAX);
        let replay_limits = EventReplayLimits::new(
            u64::try_from(complete_envelopes.len()).unwrap_or(u64::MAX),
            u64::MAX,
        );
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
                genesis_owned,
                pre_bundle_log.retained_bytes_v3()?,
                pre_bundle_basis.retained_bytes()?,
            ],
        )?;
        let (replayed_pre_log, replayed_pre_basis) = EventLog::replay_validated_v3_prefix(
            pre_bundle_log.run_id.clone(),
            &genesis_bytes,
            &current_envelopes[..pre_count],
            resolver,
            roots,
            EventReplayLimits::new(u64::try_from(pre_count).unwrap_or(u64::MAX), u64::MAX),
        )
        .map_err(bundle_resume_mismatch)?;
        if !same_authority_basis(&replayed_pre_basis, pre_bundle_basis) {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
                genesis_owned,
                replayed_pre_log.retained_bytes_v3()?,
                replayed_pre_basis.retained_bytes()?,
                current_log.retained_bytes_v3()?,
                current_basis.retained_bytes()?,
            ],
        )?;
        let (replayed_current_log, replayed_current_basis) = EventLog::replay_validated_v3_prefix(
            current_log.run_id.clone(),
            &genesis_bytes,
            &current_envelopes,
            resolver,
            roots,
            EventReplayLimits::new(
                u64::try_from(current_envelopes.len()).unwrap_or(u64::MAX),
                u64::MAX,
            ),
        )
        .map_err(bundle_resume_mismatch)?;
        if !same_authority_basis(&replayed_current_basis, current_basis) {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
                genesis_owned,
                replayed_pre_log.retained_bytes_v3()?,
                replayed_pre_basis.retained_bytes()?,
                replayed_current_log.retained_bytes_v3()?,
                replayed_current_basis.retained_bytes()?,
                current_log.retained_bytes_v3()?,
                current_basis.retained_bytes()?,
            ],
        )?;
        let (complete_log, complete_basis) = EventLog::replay_validated_v3_prefix(
            pre_bundle_log.run_id.clone(),
            &genesis_bytes,
            &complete_envelopes,
            resolver,
            roots,
            replay_limits,
        )
        .map_err(bundle_resume_mismatch)?;
        let first_sequence = pre_bundle_log.next_sequence()?;
        for (index, envelope) in planned_envelopes.iter().enumerate() {
            let expected_sequence = first_sequence
                .checked_add(u64::try_from(index).unwrap_or(u64::MAX))
                .ok_or_else(|| DomainError::EventSequence("bundle sequence overflow".to_owned()))?;
            if envelope.sequence() != expected_sequence
                || (index == 0 && envelope.previous_event_hash() != pre_bundle_log.tail_hash())
                || (index > 0
                    && envelope.previous_event_hash() != planned_envelopes[index - 1].event_hash())
            {
                return Err(DomainError::BundleResumeAuthorityMismatch);
            }
        }
        let planned_end = first_sequence
            .checked_add(u64::try_from(planned_envelopes.len()).unwrap_or(u64::MAX))
            .ok_or_else(|| DomainError::EventSequence("bundle sequence overflow".to_owned()))?;
        let planned_entries_owned = complete_basis
            .entries
            .iter()
            .filter(|entry| {
                entry.event_sequence >= first_sequence && entry.event_sequence < planned_end
            })
            .try_fold(0_u64, |mut total, entry| {
                v3_add(
                    &mut total,
                    authority_entry_owned_bytes(entry)?,
                    "verification bundle recovery planned entries",
                )?;
                Ok(total)
            })?;
        let replay_outputs_owned = [
            replayed_pre_log.retained_bytes_v3()?,
            replayed_pre_basis.retained_bytes()?,
            replayed_current_log.retained_bytes_v3()?,
            replayed_current_basis.retained_bytes()?,
            complete_log.retained_bytes_v3()?,
            complete_basis.retained_bytes()?,
        ]
        .into_iter()
        .try_fold(0_u64, |mut total, bytes| {
            v3_add(
                &mut total,
                bytes,
                "verification bundle recovery replay outputs",
            )?;
            Ok(total)
        })?;
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
                genesis_owned,
                replay_outputs_owned,
                planned_entries_owned,
            ],
        )?;
        let mut planned_entries = Vec::new();
        planned_entries
            .try_reserve_exact(planned_envelopes.len())
            .map_err(|_| {
                v3_memory_error(
                    "verification bundle recovery planned entries",
                    planned_entries_owned,
                )
            })?;
        planned_entries.extend(
            complete_basis
                .entries
                .iter()
                .filter(|entry| {
                    entry.event_sequence >= first_sequence && entry.event_sequence < planned_end
                })
                .cloned(),
        );
        if planned_entries.len() != planned_envelopes.len()
            || planned_entries
                .iter()
                .zip(planned_envelopes)
                .any(|(entry, envelope)| {
                    entry.event_id != *envelope.id()
                        || entry.event_sequence != envelope.sequence()
                        || entry.predecessor_event_hash != *envelope.previous_event_hash()
                })
        {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        let bundle_canonical_size = crate::canonical::canonical_json_count_bounded(
            &planned_envelopes,
            crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
            "verification bundle recovery canonical bundle",
        )?;
        preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            raw_cas_bytes,
            [
                current_envelopes_owned,
                payloads_owned,
                complete_envelopes_owned,
                genesis_owned,
                replay_outputs_owned,
                planned_entries_owned,
                bundle_canonical_size,
            ],
        )?;
        let bundle_canonical_bytes = canonical_json(&planned_envelopes)?;
        let bundle_digest = ContentHash::sha256(&bundle_canonical_bytes);
        drop(bundle_canonical_bytes);
        drop(raw_bytes);
        drop(genesis_bytes);
        drop(current_envelopes);
        drop(complete_envelopes);
        drop(replayed_pre_log);
        drop(replayed_pre_basis);
        drop(replayed_current_log);
        drop(replayed_current_basis);
        drop(complete_log);
        drop(complete_basis);

        let projected_token = projected_verification_bundle_resume_allocated_bytes(
            &current_log.run_id,
            &current_log.genesis_hash,
            &pre_bundle_log.tail_hash,
            &bundle_digest,
            planned_envelopes,
            durable_stage,
            &current_log.tail_hash,
            &current_basis.basis_digest,
            &payloads,
            &planned_entries,
            &verification_id,
        )?;
        let token_peak = preflight_verification_bundle_recovery(
            pre_bundle_log,
            pre_bundle_basis,
            current_log,
            current_basis,
            planned_envelopes,
            roots,
            0,
            [payloads_owned, planned_entries_owned, projected_token],
        )?;
        ensure_resume_token_test_limit(token_peak)?;
        mark_resume_token_allocation_seam();
        let mut planned_event_ids = Vec::new();
        let mut planned_event_hashes = Vec::new();
        let mut missing_envelopes = Vec::new();
        planned_event_ids
            .try_reserve_exact(planned_envelopes.len())
            .map_err(|_| v3_memory_error("verification bundle recovery token ids", u64::MAX))?;
        planned_event_hashes
            .try_reserve_exact(planned_envelopes.len())
            .map_err(|_| v3_memory_error("verification bundle recovery token hashes", u64::MAX))?;
        missing_envelopes
            .try_reserve_exact(planned_envelopes.len() - durable_stage)
            .map_err(|_| {
                v3_memory_error("verification bundle recovery token envelopes", u64::MAX)
            })?;
        planned_event_ids.extend(
            planned_envelopes
                .iter()
                .map(|envelope| envelope.id().clone()),
        );
        planned_event_hashes.extend(
            planned_envelopes
                .iter()
                .map(|envelope| envelope.event_hash().clone()),
        );
        missing_envelopes.extend_from_slice(&planned_envelopes[durable_stage..]);
        let missing_count = planned_envelopes.len() - durable_stage;
        let mut missing_payloads = Vec::new();
        let mut missing_entries = Vec::new();
        missing_payloads
            .try_reserve_exact(missing_count)
            .map_err(|_| {
                v3_memory_error("verification bundle recovery token payloads", u64::MAX)
            })?;
        missing_entries
            .try_reserve_exact(missing_count)
            .map_err(|_| v3_memory_error("verification bundle recovery token entries", u64::MAX))?;
        missing_payloads.extend(payloads.into_iter().skip(durable_stage));
        missing_entries.extend(planned_entries.into_iter().skip(durable_stage));
        let authority = VerificationBundleResumeAuthorityV3 {
            run_id: current_log.run_id.clone(),
            genesis_hash: current_log.genesis_hash.clone(),
            pre_tail_hash: pre_bundle_log.tail_hash.clone(),
            first_sequence,
            bundle_digest,
            planned_event_ids,
            planned_event_hashes,
            durable_stage,
            current_tail_hash: current_log.tail_hash.clone(),
            current_sequence: current_log.next_sequence()?,
            current_basis_digest: current_basis.basis_digest.clone(),
            missing_envelopes,
            missing_payloads,
            missing_entries,
            verification_id,
        };
        debug_assert_eq!(
            verification_bundle_resume_allocated_bytes(&authority)?,
            projected_token
        );
        Ok(authority)
    }

    /// Atomically appends only the missing suffix sealed by a roots-rebuilt
    /// resume authority. The token is consumed even when validation fails.
    pub fn resume_verification_bundle_v3(
        &mut self,
        basis: &mut AuthorityReplayBasisV3,
        authority: VerificationBundleResumeAuthorityV3,
    ) -> Result<VerificationBundleReceiptV3> {
        ensure_v3_working_peak(
            self.retained_bytes_v3()?,
            [
                basis.retained_bytes()?,
                verification_bundle_resume_allocated_bytes(&authority)?,
                self.retained_bytes_v3()?,
                basis.retained_bytes()?,
            ],
        )?;
        if authority.run_id != self.run_id
            || authority.genesis_hash != self.genesis_hash
            || authority.current_tail_hash != self.tail_hash
            || authority.current_sequence != self.next_sequence()?
            || authority.current_basis_digest != basis.basis_digest
            || authority.durable_stage == 0
            || authority.durable_stage >= authority.planned_event_ids.len()
            || authority.planned_event_ids.len() != authority.planned_event_hashes.len()
            || authority.missing_envelopes.len() != authority.missing_payloads.len()
            || authority.missing_envelopes.len() != authority.missing_entries.len()
            || authority.bundle_digest.as_str().is_empty()
            || authority.pre_tail_hash.as_str().is_empty()
            || authority
                .first_sequence
                .checked_add(u64::try_from(authority.durable_stage).unwrap_or(u64::MAX))
                != Some(authority.current_sequence)
        {
            return Err(DomainError::BundleResumeAuthorityMismatch);
        }
        basis
            .validate_for_log(self)
            .map_err(bundle_resume_mismatch)?;
        for (offset, envelope) in authority.missing_envelopes.iter().enumerate() {
            let index = authority.durable_stage + offset;
            if envelope.id() != &authority.planned_event_ids[index]
                || envelope.event_hash() != &authority.planned_event_hashes[index]
            {
                return Err(DomainError::BundleResumeAuthorityMismatch);
            }
        }
        self.preflight_v3_outer_transaction(basis, &authority.missing_payloads)
            .map_err(bundle_resume_mismatch)?;
        let mut next = self.clone();
        let mut entries = basis.entries.clone();
        for ((envelope, payload), entry) in authority
            .missing_envelopes
            .into_iter()
            .zip(authority.missing_payloads)
            .zip(authority.missing_entries)
        {
            if envelope.sequence() != next.next_sequence()?
                || envelope.previous_event_hash() != next.tail_hash()
                || entry.event_id != *envelope.id()
                || entry.event_sequence != envelope.sequence()
                || entry.predecessor_event_hash != *envelope.previous_event_hash()
                || authority_record_identity(&payload)?.is_none()
            {
                return Err(DomainError::BundleResumeAuthorityMismatch);
            }
            next.append_envelope(envelope, None, None, None, None, None, None, true)
                .map_err(bundle_resume_mismatch)?;
            entries.push(entry);
        }
        let next_basis = basis
            .advanced_for_log(&next, entries)
            .map_err(bundle_resume_mismatch)?;
        *self = next;
        *basis = next_basis;
        Ok(VerificationBundleReceiptV3 {
            event_ids: authority.planned_event_ids,
            verification_id: authority.verification_id,
        })
    }

    pub fn mint_decision_v3(
        &self,
        claim_id: &StableId,
        input: DecisionInputV3,
        roots: &AuthorityTrustRootsV3,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedDecisionV3> {
        basis.validate_for_log(self)?;
        validate_repository_trust_root(&self.aggregate, roots)?;
        if basis.policy_revision_hash != roots.policy_revision_hash {
            return Err(DomainError::AuthorityPolicyMismatch);
        }
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "decision mint",
            }
        })?;
        let scope = state.assessment_scopes.get(claim_id).ok_or_else(|| {
            DomainError::DanglingReference {
                owner: "v3 decision claim",
                owner_id: claim_id.clone(),
                reference: claim_id.clone(),
            }
        })?;
        let assessment = state
            .assessments
            .get(claim_id)
            .expect("assessment and scope are inserted atomically");
        let mut input_staging = 0_u64;
        for capacity in [
            input.actor.capacity(),
            input.authority_id.capacity(),
            input.rationale.capacity(),
            input.issued_at.capacity(),
        ] {
            v3_add(
                &mut input_staging,
                u64::try_from(capacity).unwrap_or(u64::MAX),
                "event-v3 decision input staging",
            )?;
        }
        if let Some(expires_at) = &input.expires_at {
            v3_add(
                &mut input_staging,
                u64::try_from(expires_at.capacity()).unwrap_or(u64::MAX),
                "event-v3 decision input staging",
            )?;
        }
        ensure_v3_working_peak(
            state.retained_bytes()?,
            [
                assessment.retained_bytes().map_err(m4_domain_error)?,
                input_staging,
            ],
        )?;
        let decision = assessment
            .mint_decision_from_scope(
                scope,
                roots.policy_revision_hash.clone(),
                input.outcome,
                input.actor,
                input.authority_id,
                input.rationale,
                input.issued_at,
                input.expires_at,
            )
            .map_err(m4_domain_error)?;
        let grant = roots
            .human_grant_for(&decision)
            .ok_or(DomainError::HumanTrustRootMissing)?;
        Ok(ValidatedDecisionV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
            decision,
            trust_digest: trust_digest_for_human(grant)?,
        })
    }

    pub fn append_decision_v3(
        &mut self,
        validated: ValidatedDecisionV3,
        basis: &mut AuthorityReplayBasisV3,
    ) -> Result<&Event> {
        if validated.run_id != self.run_id
            || validated.genesis_hash != self.genesis_hash
            || validated.tail_hash != self.tail_hash
            || validated.sequence != self.next_sequence()?
            || validated.decision.policy_revision_hash() != &basis.policy_revision_hash
        {
            return Err(DomainError::DecisionAdmissionMismatch);
        }
        let payload = PersistedPayload::DecisionRecordedV3(validated.decision);
        self.preflight_v3_outer_transaction(basis, std::slice::from_ref(&payload))?;
        basis.validate_for_log(self)?;
        mark_v3_transaction_allocation_seam();
        let identity =
            authority_record_identity(&payload)?.ok_or(DomainError::DecisionAdmissionMismatch)?;
        let actor = payload.actor().to_owned();
        let envelope = EventEnvelope::new(
            self.version,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            validated.sequence,
            actor,
            validated.sequence,
            self.tail_hash.clone(),
            payload,
        )?;
        let predecessor_event_hash = envelope.previous_event_hash().clone();
        let mut next = self.clone();
        next.append_envelope(envelope, None, None, None, None, None, None, true)?;
        let event = next.events.last().ok_or_else(|| {
            DomainError::EventSequence("decision append did not retain its event".to_owned())
        })?;
        let mut entries = basis.entries.clone();
        entries
            .try_reserve(1)
            .map_err(|_| DomainError::Incomplete {
                operation: "V3 authority replay entries",
                limit: basis.entries.len().saturating_add(1),
                observed: basis.entries.len().saturating_add(1),
            })?;
        entries.push(AuthorityReplayEntryV3 {
            event_sequence: validated.sequence,
            event_id: event.envelope.id().clone(),
            payload_kind: identity.0.to_owned(),
            record_id: identity.1,
            record_body_hash: identity.2,
            predecessor_event_hash,
            trust_binding_digest: validated.trust_digest,
        });
        let next_basis = basis.advanced_for_log(&next, entries)?;
        *self = next;
        *basis = next_basis;
        self.events.last().ok_or_else(|| {
            DomainError::EventSequence("decision append was not retained".to_owned())
        })
    }

    pub fn mint_finding_v3(
        &self,
        claim_id: &StableId,
        projection_descriptor_id: &str,
        basis: &AuthorityReplayBasisV3,
    ) -> Result<ValidatedFindingV3> {
        basis.validate_for_log(self)?;
        if projection_descriptor_id != crate::FINDING_PROJECTION_ID {
            return Err(DomainError::Validation(
                "unsupported M4 finding projection descriptor".to_owned(),
            ));
        }
        let state = self.v3_aggregate.as_ref().ok_or({
            DomainError::EventV3AuthorityReplayRequired {
                operation: "finding mint",
            }
        })?;
        let scope = state.assessment_scopes.get(claim_id).ok_or_else(|| {
            DomainError::DanglingReference {
                owner: "v3 finding claim",
                owner_id: claim_id.clone(),
                reference: claim_id.clone(),
            }
        })?;
        let source_assessment = state
            .assessments
            .get(claim_id)
            .expect("assessment and scope are inserted atomically");
        ensure_v3_working_peak(
            state.retained_bytes()?,
            [source_assessment
                .retained_bytes()
                .map_err(m4_domain_error)?],
        )?;
        let mut assessment = source_assessment.clone();
        let finding = assessment
            .project_finding_from_scope(scope)
            .map_err(m4_domain_error)?;
        Ok(ValidatedFindingV3 {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
            finding,
        })
    }

    pub fn append_finding_v3(
        &mut self,
        validated: ValidatedFindingV3,
        basis: &mut AuthorityReplayBasisV3,
    ) -> Result<&Event> {
        if validated.run_id != self.run_id
            || validated.genesis_hash != self.genesis_hash
            || validated.tail_hash != self.tail_hash
            || validated.sequence != self.next_sequence()?
        {
            return Err(DomainError::AuthorityReplayBasisMismatch);
        }
        let payload = PersistedPayload::FindingRecordedV3(validated.finding);
        self.preflight_v3_outer_transaction(basis, std::slice::from_ref(&payload))?;
        basis.validate_for_log(self)?;
        mark_v3_transaction_allocation_seam();
        let actor = payload.actor().to_owned();
        let envelope = EventEnvelope::new(
            self.version,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            validated.sequence,
            actor,
            validated.sequence,
            self.tail_hash.clone(),
            payload,
        )?;
        let mut next = self.clone();
        next.append_envelope(envelope, None, None, None, None, None, None, true)?;
        let next_basis = basis.advanced_for_log(&next, basis.entries.clone())?;
        *self = next;
        *basis = next_basis;
        self.events
            .last()
            .ok_or_else(|| DomainError::EventSequence("finding append was not retained".to_owned()))
    }

    /// Initializes the legacy hash boundary used only while importing a
    /// pre-existing v1 prefix. The returned log is read-only: v1 event minting
    /// is available only to crate-local test scaffolding. New callers must use
    /// [`Self::new_v2`].
    pub fn new_v1_for_import(run_id: StableId, initial: ReviewAggregate) -> Result<Self> {
        let mut log = Self::new_with_version(EventContractVersion::V1, run_id, initial)?;
        log.read_only = true;
        Ok(log)
    }

    /// Builds an editable v1 log exclusively for crate-local compatibility
    /// tests. This cannot be reached through the public library API.
    #[cfg(test)]
    pub(crate) fn new_v1_for_test(run_id: StableId, initial: ReviewAggregate) -> Result<Self> {
        Self::new_with_version(EventContractVersion::V1, run_id, initial)
    }

    fn new_with_version(
        version: EventContractVersion,
        run_id: StableId,
        initial: ReviewAggregate,
    ) -> Result<Self> {
        if matches!(version, EventContractVersion::V4 | EventContractVersion::V5) {
            return Err(DomainError::Validation(
                "event-v4/v5 construction requires a versioned bootstrap".to_owned(),
            ));
        }
        if run_id.kind() != "run" {
            return Err(DomainError::EventSequence(
                "event stream requires a run ID even when empty".to_owned(),
            ));
        }
        let v3_canonical_count = (version == EventContractVersion::V3)
            .then(|| preflight_v3_initial(&initial))
            .transpose()?;
        #[cfg(test)]
        if version == EventContractVersion::V3 {
            V3_TEST_GENESIS_ALLOCATION_SEAMS.with(|value| value.set(value.get() + 1));
        }
        initial.validate()?;
        initial.validate_pristine_for_event_log()?;
        let mut v3_genesis_hash = None;
        if matches!(version, EventContractVersion::V2 | EventContractVersion::V3) {
            let snapshot = if version == EventContractVersion::V3 {
                RunGenesisSnapshot::from_aggregate_v3(&initial)?
            } else {
                RunGenesisSnapshot::from_aggregate(&initial)?
            };
            let bytes = if version == EventContractVersion::V3 {
                encode_exact_compact_json(
                    &BorrowedRunGenesisSnapshot(&initial),
                    "event-v3 borrowed genesis canonical bytes",
                )?
            } else {
                snapshot.canonical_bytes()?
            };
            if let Some(expected) = v3_canonical_count {
                if u64::try_from(bytes.len()).unwrap_or(u64::MAX) != expected {
                    return Err(DomainError::Validation(
                        "event-v3 canonical count disagrees with encoded genesis".to_owned(),
                    ));
                }
                v3_genesis_hash = Some(ContentHash::sha256(&bytes));
            }
            let rebuilt = if version == EventContractVersion::V3 {
                RunGenesisSnapshot::from_canonical_bytes_v3(&bytes)?.rebuild_aggregate()?
            } else {
                RunGenesisSnapshot::from_canonical_bytes(&bytes)?.rebuild_aggregate()?
            };
            let reconstructed = if version == EventContractVersion::V3 {
                RunGenesisSnapshot::from_aggregate_v3(&rebuilt)?.canonical_bytes_v3()?
            } else {
                canonical_json(&rebuilt)?
            };
            let supplied = if version == EventContractVersion::V3 {
                bytes.clone()
            } else {
                canonical_json(&initial)?
            };
            if reconstructed != supplied {
                return Err(DomainError::Validation(
                    "typed genesis snapshot does not reconstruct the supplied aggregate".to_owned(),
                ));
            }
        }
        let genesis_hash = match version {
            EventContractVersion::V1 => ContentHash::sha256(&canonical_json(&initial)?),
            EventContractVersion::V2 => {
                RunGenesisSnapshot::from_aggregate(&initial)?.canonical_hash()?
            }
            EventContractVersion::V3 => v3_genesis_hash.ok_or_else(|| {
                DomainError::Validation("missing preflighted v3 genesis hash".to_owned())
            })?,
            EventContractVersion::V4 | EventContractVersion::V5 => {
                unreachable!("versioned bootstrap rejected above")
            }
        };
        let tail_hash = event_chain_genesis_hash(&run_id, &genesis_hash)?;
        Ok(Self {
            version,
            read_only: false,
            run_id,
            genesis_hash,
            aggregate: initial.clone(),
            v3_aggregate: (version == EventContractVersion::V3).then(V3RunAggregate::default),
            initial,
            events: Vec::new(),
            tail_hash,
        })
    }

    /// Mints exact evidence authority only through a parsed ProgramSpace's
    /// snapshot admission and this log's run/genesis boundary. Stale evidence
    /// may still be retained for audit, but cannot later satisfy fresh sign-off.
    pub fn admit_evidence(
        &self,
        snapshot_admission: &EvidenceSnapshotAdmission,
        evidence: &Evidence,
    ) -> Result<EvidenceAdmission> {
        self.require_writable()?;
        if evidence.snapshot_id() == self.aggregate.program().snapshot_id()
            && evidence
                .target_ids()
                .iter()
                .any(|target| !self.aggregate.program().known_ids().contains(target))
        {
            return Err(DomainError::DanglingReference {
                owner: "evidence",
                owner_id: evidence.id().clone(),
                reference: evidence
                    .target_ids()
                    .iter()
                    .find(|target| !self.aggregate.program().known_ids().contains(*target))
                    .expect("target existence was checked")
                    .clone(),
            });
        }
        snapshot_admission.admit_for_event_log(
            self.run_id.clone(),
            self.genesis_hash.clone(),
            self.tail_hash.clone(),
            self.next_sequence()?,
            evidence,
        )
    }

    /// Mints exact authority for a binding after validating its current claim,
    /// evidence, target, property, context, and mode connection.
    pub fn admit_evidence_binding(
        &self,
        binding: &EvidenceBinding,
    ) -> Result<EvidenceBindingAdmission> {
        self.require_writable()?;
        self.aggregate.validate_binding_for_event(binding)?;
        EvidenceBindingAdmission::new(
            self.run_id.clone(),
            self.genesis_hash.clone(),
            self.tail_hash.clone(),
            self.next_sequence()?,
            binding,
        )
    }

    /// Mints exact authority for a canonical passed/failed verification after
    /// deriving freshness from the aggregate's evidence records.
    pub fn admit_verification(&self, verification: Verification) -> Result<VerificationAdmission> {
        self.require_writable()?;
        let verification = self.aggregate.normalize_verification(verification)?;
        self.aggregate
            .validate_verification_for_event(&verification)?;
        VerificationAdmission::new(
            self.run_id.clone(),
            self.genesis_hash.clone(),
            self.tail_hash.clone(),
            self.next_sequence()?,
            &verification,
        )
    }

    /// Mints an authenticated human admission bound to this exact current
    /// aggregate closure, obligation universe, and immutable genesis.
    pub fn admit_decision(
        &self,
        human: &TrustedHumanAdmission,
        decision: &Decision,
    ) -> Result<DecisionAdmission> {
        self.require_writable()?;
        let closure_digest = self
            .aggregate
            .decision_closure_digest(&self.genesis_hash, decision)?;
        human.admit_decision_for_event_log(
            self.stream_position()?,
            self.aggregate.universe().id().clone(),
            closure_digest,
            decision,
        )
    }

    /// Appends one locally admitted command atomically.
    pub fn append(&mut self, command: EventCommand) -> Result<&Event> {
        self.require_writable()?;
        let (payload, admission) = self.normalized_payload(command)?;
        if !payload.allowed_in(self.version) {
            return Err(DomainError::EventSequence(
                "command payload is not admitted by this event contract version".to_owned(),
            ));
        }
        if matches!(
            &payload,
            PersistedPayload::ArtifactRegisteredV3(registration)
                if artifact_source_v3_is_authority_significant(registration.source())
        ) {
            return Err(DomainError::Validation(
                "authority-significant v3 registration append requires a sealed authority admission"
                    .to_owned(),
            ));
        }
        let sequence = self.next_sequence()?;
        validate_stream_payload_position(self.version, sequence, &payload)?;
        reject_v2_legacy_execution_payload(self.version, &payload)?;
        validate_v2_completed_transition(self.version, &self.aggregate, &payload)?;
        reject_duplicate_d1_record(&self.aggregate, &payload)?;
        payload.validate_for_enclosing_run(&self.run_id)?;
        match (&payload, &admission) {
            (
                PersistedPayload::EvidenceRecorded(evidence),
                CommandAdmission::Evidence(capability),
            ) if capability.matches(
                &self.run_id,
                &self.genesis_hash,
                &self.tail_hash,
                sequence,
                evidence,
            ) => {}
            (PersistedPayload::EvidenceRecorded(_), _) => {
                return Err(DomainError::Validation(
                    "recording evidence requires an exact snapshot-bound run admission".to_owned(),
                ));
            }
            (PersistedPayload::EvidenceBound(binding), CommandAdmission::Binding(capability))
                if capability.matches(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    sequence,
                    binding,
                ) => {}
            (PersistedPayload::EvidenceBound(_), _) => {
                return Err(DomainError::Validation(
                    "recording an evidence binding requires an exact run/genesis-bound admission"
                        .to_owned(),
                ));
            }
            (
                PersistedPayload::VerificationRecorded(verification),
                CommandAdmission::Verification(capability),
            ) if capability.matches(
                &self.run_id,
                &self.genesis_hash,
                &self.tail_hash,
                sequence,
                verification,
            ) => {}
            (PersistedPayload::VerificationRecorded(_), _) => {
                return Err(DomainError::Validation(
                    "recording a verification requires an exact run/genesis-bound admission"
                        .to_owned(),
                ));
            }
            (
                PersistedPayload::DecisionRecorded(decision),
                CommandAdmission::Decision(capability),
            ) if self.decision_admission_matches(decision, capability)? => {}
            (PersistedPayload::DecisionRecorded(_), _) => {
                return Err(DomainError::Validation(
                    "recording a decision requires an exact run-bound trusted admission".to_owned(),
                ));
            }
            (
                PersistedPayload::ContextEnvelopeProjected(envelope),
                CommandAdmission::ContextProjection(capability),
            ) if capability.matches(envelope, &self.aggregate)? => {}
            (PersistedPayload::ContextEnvelopeProjected(_), _) => {
                return Err(DomainError::Validation(
                    "recording a context envelope requires a byte-reverified builder result"
                        .to_owned(),
                ));
            }
            (
                PersistedPayload::ReviewExecutionRecorded(recorded),
                CommandAdmission::ReviewerRaw(closure),
            ) if closure.matches(recorded) => {}
            (PersistedPayload::ReviewExecutionRecorded(_), _) => {
                return Err(DomainError::Validation(
                    "recording a D2 execution requires its exact raw byte closure".to_owned(),
                ));
            }
            _ => {}
        }
        if self.version == EventContractVersion::V3 {
            self.preflight_v3_live_append(&payload)?;
        }
        let actor = payload.actor().to_owned();
        let envelope = EventEnvelope::new(
            self.version,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            sequence,
            actor,
            sequence,
            self.tail_hash.clone(),
            payload,
        )?;
        let (
            evidence_admission,
            binding_admission,
            verification_admission,
            decision_admission,
            context_projection_admission,
            reviewer_raw_closure,
        ) = match admission {
            CommandAdmission::Evidence(admission) => {
                (Some(admission), None, None, None, None, None)
            }
            CommandAdmission::Binding(admission) => (None, Some(admission), None, None, None, None),
            CommandAdmission::Verification(admission) => {
                (None, None, Some(admission), None, None, None)
            }
            CommandAdmission::Decision(admission) => {
                (None, None, None, Some(admission), None, None)
            }
            CommandAdmission::ContextProjection(admission) => {
                let payload = decode_canonical_payload(self.version, envelope.payload.get())?;
                let PersistedPayload::ContextEnvelopeProjected(context) = payload else {
                    return Err(DomainError::Validation(
                        "context admission cannot seal a non-context event".to_owned(),
                    ));
                };
                let positioned =
                    PositionedContextProjectionAdmission::seal(&envelope, &context, admission)?;
                (None, None, None, None, Some(positioned), None)
            }
            CommandAdmission::ReviewerRaw(closure) => (None, None, None, None, None, Some(closure)),
            CommandAdmission::None => (None, None, None, None, None, None),
        };
        self.append_envelope(
            envelope,
            evidence_admission,
            binding_admission,
            verification_admission,
            decision_admission,
            context_projection_admission,
            reviewer_raw_closure,
            false,
        )
    }

    /// Replays exact in-process events from the same initial aggregate.
    pub fn replay(
        version: EventContractVersion,
        run_id: StableId,
        initial: ReviewAggregate,
        events: &[Event],
    ) -> Result<Self> {
        let envelopes = events
            .iter()
            .map(|event| event.envelope.clone())
            .collect::<Vec<_>>();
        let evidence = events
            .iter()
            .filter_map(|event| event.evidence_admission.clone())
            .collect::<Vec<_>>();
        let bindings = events
            .iter()
            .filter_map(|event| event.binding_admission.clone())
            .collect::<Vec<_>>();
        let verifications = events
            .iter()
            .filter_map(|event| event.verification_admission.clone())
            .collect::<Vec<_>>();
        let decisions = events
            .iter()
            .filter_map(|event| event.decision_admission.clone())
            .collect::<Vec<_>>();
        let context_projections = events
            .iter()
            .filter_map(|event| event.context_projection_admission.clone())
            .collect::<Vec<_>>();
        let reviewer_raw = events
            .iter()
            .filter_map(|event| event.reviewer_raw_closure.clone())
            .collect::<Vec<_>>();
        Self::replay_envelopes(
            version,
            run_id,
            initial,
            &envelopes,
            &EventAdmissions::new(evidence, decisions)
                .with_trace_admissions(bindings, verifications)
                .with_context_admissions(context_projections)
                .with_reviewer_raw(reviewer_raw),
        )
    }

    /// Replays JSON-imported envelopes only with matching exact host admissions.
    pub fn replay_envelopes(
        version: EventContractVersion,
        run_id: StableId,
        initial: ReviewAggregate,
        envelopes: &[EventEnvelope],
        admissions: &EventAdmissions,
    ) -> Result<Self> {
        Self::replay_envelopes_with_event_capacity(
            version, run_id, initial, envelopes, admissions, 0,
        )
    }

    fn replay_envelopes_with_event_capacity(
        version: EventContractVersion,
        run_id: StableId,
        initial: ReviewAggregate,
        envelopes: &[EventEnvelope],
        admissions: &EventAdmissions,
        event_capacity: usize,
    ) -> Result<Self> {
        if version == EventContractVersion::V3 {
            return Err(DomainError::EventV3AuthorityReplayRequired {
                operation: "event replay",
            });
        }
        let mut log = Self::new_with_version(version, run_id, initial)?;
        if event_capacity != 0 {
            log.events
                .try_reserve_exact(event_capacity)
                .map_err(|_| DomainError::Incomplete {
                    operation: "V2 replay event output capacity",
                    limit: event_capacity,
                    observed: event_capacity,
                })?;
        }
        EventEnvelope::validate_sequence(version, &log.run_id, &log.genesis_hash, envelopes)?;
        if version == EventContractVersion::V2
            && let Some(first) = envelopes.first()
        {
            let bytes = RunGenesisSnapshot::from_aggregate(&log.initial)?.canonical_bytes()?;
            validate_v2_genesis_envelope(&log.run_id, &log.initial, &bytes, first)?;
        }
        for envelope in envelopes {
            let payload = decode_canonical_payload(version, envelope.payload.get())?;
            let admissions = log.admissions_for(envelope, &payload, admissions)?;
            log.append_envelope(
                envelope.clone(),
                admissions.evidence,
                admissions.binding,
                admissions.verification,
                admissions.decision,
                admissions.context_projection,
                admissions.reviewer_raw,
                false,
            )?;
        }
        if version == EventContractVersion::V1 {
            log.read_only = true;
        }
        Ok(log)
    }

    /// Continues a previously replayed prefix with the next imported suffix.
    /// The suffix must preserve this log's run and canonical genesis bindings.
    pub fn resume_envelopes(
        &mut self,
        envelopes: &[EventEnvelope],
        admissions: &EventAdmissions,
    ) -> Result<()> {
        if self.version == EventContractVersion::V3 {
            return Err(DomainError::EventV3AuthorityReplayRequired {
                operation: "event resume",
            });
        }
        self.require_writable()?;
        let mut next = self.clone();
        if next.version == EventContractVersion::V2
            && next.events.is_empty()
            && let Some(first) = envelopes.first()
        {
            let bytes = RunGenesisSnapshot::from_aggregate(&next.initial)?.canonical_bytes()?;
            validate_v2_genesis_envelope(&next.run_id, &next.initial, &bytes, first)?;
        }
        for envelope in envelopes {
            let payload = decode_canonical_payload(next.version, envelope.payload.get())?;
            let admissions = next.admissions_for(envelope, &payload, admissions)?;
            next.append_envelope(
                envelope.clone(),
                admissions.evidence,
                admissions.binding,
                admissions.verification,
                admissions.decision,
                admissions.context_projection,
                admissions.reviewer_raw,
                false,
            )?;
        }
        *self = next;
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn append_envelope(
        &mut self,
        envelope: EventEnvelope,
        evidence_admission: Option<EvidenceAdmission>,
        binding_admission: Option<EvidenceBindingAdmission>,
        verification_admission: Option<VerificationAdmission>,
        decision_admission: Option<DecisionAdmission>,
        context_projection_admission: Option<PositionedContextProjectionAdmission>,
        reviewer_raw_closure: Option<ReviewerRawClosure>,
        v3_authority_validated: bool,
    ) -> Result<&Event> {
        self.append_envelope_internal(
            envelope,
            None,
            evidence_admission,
            binding_admission,
            verification_admission,
            decision_admission,
            context_projection_admission,
            reviewer_raw_closure,
            v3_authority_validated,
            0,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn append_decoded_v3(
        &mut self,
        envelope: EventEnvelope,
        payload: PersistedPayload,
        context_projection_admission: Option<PositionedContextProjectionAdmission>,
        reviewer_raw_closure: Option<ReviewerRawClosure>,
        external_live_bytes: u64,
    ) -> Result<&Event> {
        self.append_envelope_internal(
            envelope,
            Some(payload),
            None,
            None,
            None,
            None,
            context_projection_admission,
            reviewer_raw_closure,
            true,
            external_live_bytes,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn append_envelope_internal(
        &mut self,
        envelope: EventEnvelope,
        decoded_payload: Option<PersistedPayload>,
        evidence_admission: Option<EvidenceAdmission>,
        binding_admission: Option<EvidenceBindingAdmission>,
        verification_admission: Option<VerificationAdmission>,
        decision_admission: Option<DecisionAdmission>,
        context_projection_admission: Option<PositionedContextProjectionAdmission>,
        reviewer_raw_closure: Option<ReviewerRawClosure>,
        v3_authority_validated: bool,
        external_live_bytes: u64,
    ) -> Result<&Event> {
        self.require_writable()?;
        let expected_sequence = self.next_sequence()?;
        let event_admission_bytes = u64::try_from(
            context_projection_admission
                .as_ref()
                .map_or(0, PositionedContextProjectionAdmission::allocated_bytes)
                .saturating_add(
                    reviewer_raw_closure
                        .as_ref()
                        .map_or(0, ReviewerRawClosure::allocated_bytes),
                ),
        )
        .unwrap_or(u64::MAX);
        if decoded_payload.is_some() && self.version == EventContractVersion::V3 {
            envelope.validate_v3_structure_without_payload_decode()?;
        } else {
            envelope.validate()?;
        }
        if EventContractVersion::parse(&envelope.schema)? != self.version
            || envelope.run_id != self.run_id
            || envelope.genesis_hash != self.genesis_hash
            || envelope.sequence != expected_sequence
            || envelope.previous_event_hash != self.tail_hash
        {
            return Err(DomainError::EventSequence(
                "event run ID, genesis hash, and sequence must continue this log".to_owned(),
            ));
        }
        let payload = if let Some(payload) = decoded_payload {
            payload
        } else {
            if self.version == EventContractVersion::V3 {
                self.preflight_v3_encoded_append(
                    &envelope,
                    external_live_bytes,
                    event_admission_bytes,
                    None,
                )?;
            }
            decode_canonical_payload(self.version, envelope.payload.get())?
        };
        if self.version == EventContractVersion::V3 {
            let _append_peak = self.preflight_v3_encoded_append(
                &envelope,
                external_live_bytes,
                event_admission_bytes,
                Some(&payload),
            )?;
            #[cfg(test)]
            if matches!(payload, PersistedPayload::EvidenceBoundV3(_)) {
                V3_TEST_BINDING_APPEND_PEAK.with(|value| value.set(_append_peak));
            }
            record_v3_test_selected_peak(_append_peak);
        }
        validate_stream_payload_position(self.version, expected_sequence, &payload)?;
        reject_v2_legacy_execution_payload(self.version, &payload)?;
        validate_v2_completed_transition(self.version, &self.aggregate, &payload)?;
        reject_duplicate_d1_record(&self.aggregate, &payload)?;
        payload.validate_for_enclosing_run(&self.run_id)?;
        if let PersistedPayload::EvidenceRecorded(evidence) = &payload
            && !evidence_admission.as_ref().is_some_and(|admission| {
                admission.matches(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    expected_sequence,
                    evidence,
                )
            })
        {
            return Err(DomainError::Validation(
                "evidence event lacks an exact snapshot-bound run admission".to_owned(),
            ));
        }
        if let PersistedPayload::EvidenceBound(binding) = &payload
            && !binding_admission.as_ref().is_some_and(|admission| {
                admission.matches(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    expected_sequence,
                    binding,
                )
            })
        {
            return Err(DomainError::Validation(
                "evidence binding event lacks an exact run/genesis-bound admission".to_owned(),
            ));
        }
        if let PersistedPayload::VerificationRecorded(verification) = &payload
            && !verification_admission.as_ref().is_some_and(|admission| {
                admission.matches(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    expected_sequence,
                    verification,
                )
            })
        {
            return Err(DomainError::Validation(
                "verification event lacks an exact run/genesis-bound admission".to_owned(),
            ));
        }
        if let PersistedPayload::DecisionRecorded(decision) = &payload
            && !decision_admission.as_ref().is_some_and(|admission| {
                self.decision_admission_matches(decision, admission)
                    .is_ok_and(|matched| matched)
            })
        {
            return Err(DomainError::Validation(
                "decision event lacks an exact run-bound trusted admission".to_owned(),
            ));
        }
        if let PersistedPayload::ContextEnvelopeProjected(context) = &payload
            && !context_projection_admission
                .as_ref()
                .is_some_and(|admission| {
                    admission
                        .matches(&envelope, context, &self.aggregate)
                        .is_ok_and(|matched| matched)
                })
        {
            return Err(DomainError::Validation(
                "context event lacks its exact byte-reverified admission".to_owned(),
            ));
        }
        if let PersistedPayload::ReviewExecutionRecorded(recorded) = &payload
            && !reviewer_raw_closure
                .as_ref()
                .is_some_and(|closure| closure.matches(recorded))
        {
            return Err(DomainError::Validation(
                "D2 execution event lacks its exact raw byte closure".to_owned(),
            ));
        }
        let retained_log = if self.version == EventContractVersion::V3 {
            let retained = self.retained_bytes_v3()?;
            let aggregate_clone = self.aggregate.retained_bytes_v3()?;
            let v3_clone = self
                .v3_aggregate
                .as_ref()
                .ok_or(DomainError::EventV3AuthorityReplayRequired {
                    operation: "event-v3 append reducer clone",
                })?
                .retained_bytes()?;
            let mut events_clone =
                u64::try_from(self.events.capacity().saturating_mul(size_of::<Event>()))
                    .unwrap_or(u64::MAX);
            for event in &self.events {
                v3_add(
                    &mut events_clone,
                    event.retained_bytes()?,
                    "event-v3 append event shadow",
                )?;
            }
            let shadow_peak = ensure_v3_working_peak(
                retained,
                [
                    external_live_bytes,
                    event_admission_bytes,
                    v3_payload_staging_bytes(&payload)?,
                    aggregate_clone,
                    v3_clone,
                    events_clone,
                    v3_reducer_growth_upper_bound(&payload)?,
                ],
            )?;
            record_v3_test_selected_peak(shadow_peak);
            Some(retained)
        } else {
            None
        };
        #[cfg(test)]
        if self.version == EventContractVersion::V3 {
            V3_TEST_APPEND_SHADOW_SEAMS.with(|value| value.set(value.get() + 1));
            if matches!(payload, PersistedPayload::EvidenceBoundV3(_)) {
                V3_TEST_BINDING_SHADOW_SEAMS.with(|value| value.set(value.get() + 1));
            }
            if V3_TEST_SELECTED_APPEND_KIND.with(|kind| kind.get()) == v3_test_append_kind(&payload)
            {
                V3_TEST_SELECTED_SHADOW_SEAMS.with(|value| value.set(value.get() + 1));
            }
        }
        let mut next = self.aggregate.clone();
        let mut next_v3 = self.v3_aggregate.clone();
        apply_for_log(
            &mut next,
            next_v3.as_mut(),
            &payload,
            envelope.actor(),
            &self.run_id,
            &self.genesis_hash,
            reviewer_raw_closure
                .as_ref()
                .map(ReviewerRawClosure::raw_artifact_size),
            v3_authority_validated,
        )?;
        let event = Event {
            envelope,
            evidence_admission,
            binding_admission,
            verification_admission,
            decision_admission,
            context_projection_admission,
            reviewer_raw_closure,
        };
        let mut next_events = self.events.clone();
        next_events
            .try_reserve_exact(1)
            .map_err(|_| DomainError::Incomplete {
                operation: "event-v3 append event shadow capacity",
                limit: crate::m4::MAX_RETAINED_WORKING_BYTES as usize,
                observed: usize::MAX,
            })?;
        let next_tail_hash = event.envelope.event_hash.clone();
        next_events.push(event);
        if let Some(retained) = retained_log {
            let post_retained = self.retained_bytes_v3_with(
                &next,
                next_v3.as_ref(),
                &next_events,
                &next_tail_hash,
            )?;
            ensure_v3_working_peak(retained, [post_retained])?;
        }
        self.aggregate = next;
        self.v3_aggregate = next_v3;
        self.events = next_events;
        self.tail_hash = next_tail_hash;
        self.events.last().ok_or_else(|| {
            DomainError::EventSequence("append did not retain the committed event".to_owned())
        })
    }

    fn normalized_payload(
        &self,
        command: EventCommand,
    ) -> Result<(PersistedPayload, CommandAdmission)> {
        let payload = match command.payload {
            PersistedPayload::VerificationRecorded(verification) => {
                PersistedPayload::VerificationRecorded(
                    self.aggregate.normalize_verification(verification)?,
                )
            }
            payload => payload,
        };
        Ok((payload, command.admission))
    }

    fn require_writable(&self) -> Result<()> {
        if self.read_only {
            return Err(DomainError::Validation(
                "legacy v1 event logs are import/replay-only and cannot mint or append events"
                    .to_owned(),
            ));
        }
        Ok(())
    }

    fn admissions_for(
        &self,
        event: &EventEnvelope,
        payload: &PersistedPayload,
        admissions: &EventAdmissions,
    ) -> Result<MatchedAdmissions> {
        if let PersistedPayload::ReviewExecutionRecorded(recorded) = payload {
            if self
                .aggregate
                .executions()
                .any(|execution| execution.id() == recorded.execution.id())
            {
                return Err(DomainError::IdCollision {
                    id: recorded.execution.id().clone(),
                });
            }
            if let Some(claim) = recorded.claims.iter().find(|claim| {
                self.aggregate
                    .execution_claims()
                    .any(|existing| existing.id() == claim.id())
            }) {
                return Err(DomainError::IdCollision {
                    id: claim.id().clone(),
                });
            }
        }
        let evidence = match payload {
            PersistedPayload::EvidenceRecorded(evidence) => admissions
                .evidence_for(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    self.next_sequence()?,
                    evidence,
                )
                .ok_or_else(|| {
                    DomainError::Validation(
                        "imported evidence lacks an exact snapshot-bound run admission".to_owned(),
                    )
                })
                .map(Some)?,
            _ => None,
        };
        let binding = match payload {
            PersistedPayload::EvidenceBound(binding) => admissions
                .binding_for(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    self.next_sequence()?,
                    binding,
                )
                .ok_or_else(|| {
                    DomainError::Validation(
                        "imported evidence binding lacks an exact run/genesis-bound admission"
                            .to_owned(),
                    )
                })
                .map(Some)?,
            _ => None,
        };
        let verification = match payload {
            PersistedPayload::VerificationRecorded(verification) => admissions
                .verification_for(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.tail_hash,
                    self.next_sequence()?,
                    verification,
                )
                .ok_or_else(|| {
                    DomainError::Validation(
                        "imported verification lacks an exact run/genesis-bound admission"
                            .to_owned(),
                    )
                })
                .map(Some)?,
            _ => None,
        };
        let decision = match payload {
            PersistedPayload::DecisionRecorded(decision) => {
                let closure = self
                    .aggregate
                    .decision_closure_digest(&self.genesis_hash, decision)?;
                admissions
                    .decision_for(
                        &self.stream_position()?,
                        self.aggregate.universe().id(),
                        &closure,
                        decision,
                    )
                    .ok_or_else(|| {
                        DomainError::Validation(
                            "imported decision lacks an exact run/genesis/closure-bound trusted admission"
                                .to_owned(),
                        )
                    })
                    .map(Some)?
            }
            _ => None,
        };
        let context_projection = match payload {
            PersistedPayload::ContextEnvelopeProjected(context) => admissions
                .context_projection_for(event, context, &self.aggregate)?
                .ok_or_else(|| {
                    DomainError::Validation(
                        "imported context envelope lacks an exact byte-reverified admission"
                            .to_owned(),
                    )
                })
                .map(Some)?,
            _ => None,
        };
        let reviewer_raw = match payload {
            PersistedPayload::ReviewExecutionRecorded(recorded) => admissions
                .reviewer_raw_for(recorded)
                .ok_or_else(|| {
                    DomainError::Validation(
                        "imported D2 execution lacks its exact raw byte closure".to_owned(),
                    )
                })
                .map(Some)?,
            _ => None,
        };
        Ok(MatchedAdmissions {
            evidence,
            binding,
            verification,
            decision,
            context_projection,
            reviewer_raw,
        })
    }

    fn decision_admission_matches(
        &self,
        decision: &Decision,
        admission: &DecisionAdmission,
    ) -> Result<bool> {
        let closure = self
            .aggregate
            .decision_closure_digest(&self.genesis_hash, decision)?;
        Ok(decision.matches_decision_admission(
            &self.stream_position()?,
            self.aggregate.universe().id(),
            &closure,
            admission,
        ))
    }

    #[must_use]
    pub fn aggregate(&self) -> &ReviewAggregate {
        &self.aggregate
    }

    /// Complete read-only event-v3 registration projection.
    pub fn artifact_registrations_v3(&self) -> impl Iterator<Item = &ArtifactRegisteredV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.registrations.values())
    }

    pub fn claim_assessments_v3(&self) -> impl Iterator<Item = &crate::ClaimAssessmentV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.assessments.values())
    }

    #[must_use]
    pub fn claim_assessment_v3(&self, claim_id: &StableId) -> Option<&crate::ClaimAssessmentV3> {
        self.v3_aggregate
            .as_ref()
            .and_then(|aggregate| aggregate.assessments.get(claim_id))
    }

    pub fn evidence_v3(&self) -> impl Iterator<Item = &EvidenceV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.evidence.values())
    }

    pub fn evidence_bindings_v3(&self) -> impl Iterator<Item = &EvidenceBindingV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.bindings.values())
    }

    pub fn verifications_v3(&self) -> impl Iterator<Item = &VerificationV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.verifications.values())
    }

    pub fn decisions_v3(&self) -> impl Iterator<Item = &DecisionV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.decisions.values())
    }

    pub fn findings_v3(&self) -> impl Iterator<Item = &FindingV3> {
        self.v3_aggregate
            .iter()
            .flat_map(|aggregate| aggregate.findings.values())
    }

    #[must_use]
    pub fn initial(&self) -> &ReviewAggregate {
        &self.initial
    }

    /// The canonical typed baseline committed by this v2 or v3 stream.
    pub fn run_genesis_snapshot(&self) -> Result<RunGenesisSnapshot> {
        if !matches!(
            self.version,
            EventContractVersion::V2 | EventContractVersion::V3
        ) {
            return Err(DomainError::Validation(
                "legacy v1 streams do not carry a typed run genesis snapshot".to_owned(),
            ));
        }
        if self.version == EventContractVersion::V3 {
            RunGenesisSnapshot::from_aggregate_v3(&self.initial)
        } else {
            RunGenesisSnapshot::from_aggregate(&self.initial)
        }
    }

    /// Stable run binding required when minting exact replay admissions.
    #[must_use]
    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }

    /// The one schema contract governing this entire stream.
    #[must_use]
    pub const fn event_contract_version(&self) -> EventContractVersion {
        self.version
    }

    #[must_use]
    pub fn genesis_hash(&self) -> &ContentHash {
        &self.genesis_hash
    }

    /// Current chain tip; an empty log uses the deterministic genesis sentinel.
    #[must_use]
    pub fn tail_hash(&self) -> &ContentHash {
        &self.tail_hash
    }

    #[must_use]
    pub fn events(&self) -> &[Event] {
        &self.events
    }

    #[must_use]
    pub fn envelopes(&self) -> impl ExactSizeIterator<Item = &EventEnvelope> {
        self.events.iter().map(Event::envelope)
    }

    fn next_sequence(&self) -> Result<u64> {
        u64::try_from(self.events.len())
            .map_err(|_| DomainError::EventSequence("event count does not fit u64".to_owned()))?
            .checked_add(1)
            .ok_or_else(|| DomainError::EventSequence("event count does not fit u64".to_owned()))
    }

    fn stream_position(&self) -> Result<StreamPosition> {
        Ok(StreamPosition {
            run_id: self.run_id.clone(),
            genesis_hash: self.genesis_hash.clone(),
            tail_hash: self.tail_hash.clone(),
            sequence: self.next_sequence()?,
        })
    }

    fn append_v2_genesis_manifest(&mut self) -> Result<()> {
        let snapshot = RunGenesisSnapshot::from_aggregate(&self.initial)?;
        let bytes = snapshot.canonical_bytes()?;
        let source = ArtifactSource::RunGenesis {
            run_id: self.run_id.clone(),
        };
        let registration_id = ArtifactRegistered::derived_id(
            &self.run_id,
            &self.genesis_hash,
            "application/json",
            ArtifactSensitivity::CanonicalState,
            &source,
        )?;
        let registration = ArtifactRegistered::new(
            self.run_id.clone(),
            registration_id,
            self.genesis_hash.clone(),
            "application/json",
            u64::try_from(bytes.len()).map_err(|_| {
                DomainError::EventSequence("genesis bytes do not fit u64".to_owned())
            })?,
            ArtifactSensitivity::CanonicalState,
            source,
        )?;
        let manifest = RunGenesisManifest::new(
            self.run_id.clone(),
            registration,
            self.initial.program().repository_identity(),
            self.initial.program().snapshot_id().clone(),
            self.initial.program().profile_id(),
            self.initial.program().profile_version(),
        )?;
        let envelope = EventEnvelope::new(
            EventContractVersion::V2,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            1,
            SYSTEM_ACTOR,
            1,
            self.tail_hash.clone(),
            PersistedPayload::RunGenesisManifest(manifest),
        )?;
        self.append_envelope(envelope, None, None, None, None, None, None, false)?;
        let envelope = self
            .events
            .first()
            .ok_or_else(|| {
                DomainError::EventSequence("missing appended v2 genesis event".to_owned())
            })?
            .envelope();
        validate_v2_genesis_envelope(&self.run_id, &self.initial, &bytes, envelope)?;
        Ok(())
    }

    fn append_v3_genesis_manifest(&mut self) -> Result<()> {
        let snapshot = RunGenesisSnapshot::from_aggregate_v3(&self.initial)?;
        let bytes = snapshot.canonical_bytes()?;
        let registration = ArtifactRegisteredV3::new(
            self.run_id.clone(),
            self.genesis_hash.clone(),
            "application/json",
            u64::try_from(bytes.len()).map_err(|_| {
                DomainError::EventSequence("genesis bytes do not fit u64".to_owned())
            })?,
            ArtifactSensitivity::CanonicalState,
            ArtifactSourceV3::RunGenesis {
                run_id: self.run_id.clone(),
            },
        )?;
        let manifest = RunGenesisManifestV3::new(
            self.run_id.clone(),
            registration,
            self.initial.program().repository_identity(),
            self.initial.program().snapshot_id().clone(),
            self.initial.program().profile_id(),
            self.initial.program().profile_version(),
        )?;
        let payload = PersistedPayload::RunGenesisManifestV3(manifest);
        self.preflight_v3_live_append(&payload)?;
        let envelope = EventEnvelope::new(
            EventContractVersion::V3,
            self.run_id.clone(),
            self.genesis_hash.clone(),
            1,
            SYSTEM_ACTOR,
            1,
            self.tail_hash.clone(),
            payload,
        )?;
        self.append_envelope(envelope, None, None, None, None, None, None, false)?;
        let first = self.events.first().ok_or_else(|| {
            DomainError::EventSequence("v3 genesis manifest was not retained".to_owned())
        })?;
        validate_v3_genesis_envelope(&self.run_id, &self.initial, &bytes, first.envelope())?;
        Ok(())
    }
}

fn validate_v3_replay_sequence_without_payload_decode(
    run_id: &StableId,
    genesis_hash: &ContentHash,
    events: &[EventEnvelope],
) -> Result<()> {
    let mut previous_event_hash = event_chain_genesis_hash(run_id, genesis_hash)?;
    for (index, event) in events.iter().enumerate() {
        event.validate_v3_structure_without_payload_decode()?;
        let expected = u64::try_from(index)
            .map_err(|_| DomainError::EventSequence("event count does not fit u64".to_owned()))?
            .checked_add(1)
            .ok_or_else(|| DomainError::EventSequence("event count does not fit u64".to_owned()))?;
        if &event.run_id != run_id
            || &event.genesis_hash != genesis_hash
            || event.sequence != expected
            || event.previous_event_hash != previous_event_hash
        {
            return Err(DomainError::EventSequence(
                "event run IDs, genesis hashes, sequences, and hashes must form one contiguous v3 prefix"
                    .to_owned(),
            ));
        }
        previous_event_hash = event.event_hash.clone();
    }
    Ok(())
}

fn replay_incomplete(operation: &'static str, limit: u64, observed: u64) -> DomainError {
    DomainError::Incomplete {
        operation,
        limit: usize::try_from(limit).unwrap_or(usize::MAX),
        observed: usize::try_from(observed).unwrap_or(usize::MAX),
    }
}

fn replay_add(operation: &'static str, limit: u64, total: u64, next: u64) -> Result<u64> {
    let observed = total
        .checked_add(next)
        .ok_or_else(|| replay_incomplete(operation, limit, u64::MAX))?;
    if observed > limit {
        return Err(replay_incomplete(operation, limit, observed));
    }
    Ok(observed)
}

fn preflight_v2_replay_limits(
    envelopes: &[EventEnvelope],
    limits: EventReplayLimits,
) -> Result<()> {
    if envelopes.is_empty() {
        return Err(DomainError::EventSequence(
            "V2 replay requires the sequence-one genesis manifest".to_owned(),
        ));
    }
    let count = u64::try_from(envelopes.len())
        .map_err(|_| replay_incomplete("V2 replay event count", limits.max_events, u64::MAX))?;
    if count > limits.max_events {
        return Err(replay_incomplete(
            "V2 replay event count",
            limits.max_events,
            count,
        ));
    }
    let mut canonical = 0_u64;
    for envelope in envelopes {
        if envelope.contract_version()? != EventContractVersion::V2 {
            return Err(DomainError::Validation(
                "V2 replay refuses a non-V2 envelope".to_owned(),
            ));
        }
        // Exact canonical serialization is performed before any output-log
        // clone. `max_canonical_bytes` is a byte-stream contract, not a heap
        // or RSS assertion.
        let bytes = envelope.canonical_bytes()?;
        canonical = replay_add(
            "V2 replay canonical bytes",
            limits.max_canonical_bytes,
            canonical,
            u64::try_from(bytes.len()).map_err(|_| {
                replay_incomplete(
                    "V2 replay canonical bytes",
                    limits.max_canonical_bytes,
                    u64::MAX,
                )
            })?,
        )?;
    }
    Ok(())
}

// The event identity intentionally binds every envelope component, including
// its selected schema, so legacy v1 and minted v2 IDs cannot alias.
#[allow(clippy::too_many_arguments)]
fn event_id(
    schema: &str,
    run_id: &StableId,
    genesis_hash: &ContentHash,
    sequence: u64,
    actor: &str,
    logical_time: u64,
    payload_hash: &ContentHash,
    previous_event_hash: &ContentHash,
) -> Result<StableId> {
    let bindings = BTreeMap::from([
        ("actor".to_owned(), Value::String(actor.to_owned())),
        (
            "genesis_hash".to_owned(),
            Value::String(genesis_hash.to_string()),
        ),
        (
            "logical_time".to_owned(),
            Value::Number(serde_json::Number::from(logical_time)),
        ),
        (
            "payload_hash".to_owned(),
            Value::String(payload_hash.to_string()),
        ),
        (
            "previous_event_hash".to_owned(),
            Value::String(previous_event_hash.to_string()),
        ),
        ("run".to_owned(), Value::String(run_id.to_string())),
        ("schema".to_owned(), Value::String(schema.to_owned())),
        (
            "sequence".to_owned(),
            Value::Number(serde_json::Number::from(sequence)),
        ),
    ]);
    StableId::derived("event", &bindings)
}

struct EventHashInput<'a> {
    schema: &'a str,
    id: &'a StableId,
    run_id: &'a StableId,
    genesis_hash: &'a ContentHash,
    sequence: u64,
    actor: &'a str,
    logical_time: u64,
    payload_hash: &'a ContentHash,
    previous_event_hash: &'a ContentHash,
}

fn envelope_hash(input: EventHashInput<'_>) -> Result<ContentHash> {
    let bindings = BTreeMap::from([
        ("actor".to_owned(), Value::String(input.actor.to_owned())),
        ("event_id".to_owned(), Value::String(input.id.to_string())),
        (
            "genesis_hash".to_owned(),
            Value::String(input.genesis_hash.to_string()),
        ),
        (
            "logical_time".to_owned(),
            Value::Number(serde_json::Number::from(input.logical_time)),
        ),
        (
            "payload_hash".to_owned(),
            Value::String(input.payload_hash.to_string()),
        ),
        (
            "previous_event_hash".to_owned(),
            Value::String(input.previous_event_hash.to_string()),
        ),
        ("run".to_owned(), Value::String(input.run_id.to_string())),
        ("schema".to_owned(), Value::String(input.schema.to_owned())),
        (
            "sequence".to_owned(),
            Value::Number(serde_json::Number::from(input.sequence)),
        ),
    ]);
    Ok(ContentHash::sha256(&canonical_json(&bindings)?))
}

fn event_chain_genesis_hash(run_id: &StableId, genesis_hash: &ContentHash) -> Result<ContentHash> {
    let sentinel = BTreeMap::from([
        (
            "domain".to_owned(),
            Value::String("reviewgraphen.event_chain_genesis.v1".to_owned()),
        ),
        (
            "genesis_hash".to_owned(),
            Value::String(genesis_hash.to_string()),
        ),
        ("run".to_owned(), Value::String(run_id.to_string())),
    ]);
    Ok(ContentHash::sha256(&canonical_json(&sentinel)?))
}

fn apply(
    aggregate: &mut ReviewAggregate,
    payload: &PersistedPayload,
    actor: &str,
    expected_run_id: &StableId,
    reviewer_raw_size: Option<u64>,
) -> Result<()> {
    match payload {
        PersistedPayload::ObligationTransition {
            obligation_id,
            next,
        } => aggregate.transition_obligation(obligation_id, *next),
        PersistedPayload::ClaimProposed(claim) => aggregate.add_claim(claim.clone()),
        PersistedPayload::EvidenceRecorded(evidence) => {
            aggregate.add_evidence(evidence.as_ref().clone())
        }
        PersistedPayload::EvidenceBound(binding) => aggregate.bind_evidence(binding.clone()),
        PersistedPayload::VerificationRecorded(verification) => {
            aggregate.add_verification(verification.clone())
        }
        PersistedPayload::DecisionRecorded(decision) => {
            aggregate.record_decision(decision.clone(), actor)
        }
        PersistedPayload::FindingRecorded(finding) => aggregate.add_finding(finding.clone()),
        PersistedPayload::RunGenesisManifest(manifest) => {
            aggregate.record_genesis_manifest(expected_run_id, manifest.clone())
        }
        PersistedPayload::ArtifactRegistered(registration) => {
            aggregate.register_artifact(expected_run_id, registration.clone())
        }
        PersistedPayload::SnapshotSourcesRecorded(sources) => {
            aggregate.record_snapshot_sources(sources.clone())
        }
        PersistedPayload::ReviewPlanRecorded(plan) => aggregate.record_review_plan(plan.clone()),
        PersistedPayload::ContextEnvelopeProjected(envelope) => {
            aggregate.record_context_envelope(envelope.clone())
        }
        PersistedPayload::ReviewExecutionRecorded(recorded) => {
            let expected_raw_size = reviewer_raw_size.ok_or_else(|| {
                DomainError::Validation(
                    "D2 execution requires verified raw bytes; registration metadata is insufficient"
                        .to_owned(),
                )
            })?;
            aggregate.record_execution(
                expected_run_id,
                recorded.execution.clone(),
                recorded.claims.clone(),
                expected_raw_size,
            )
        }
        PersistedPayload::RunGenesisManifestV3(_)
        | PersistedPayload::ArtifactRegisteredV3(_)
        | PersistedPayload::RunGenesisManifestV4(_)
        | PersistedPayload::ArtifactRegisteredV4(_)
        | PersistedPayload::GluingBundleRecordedV4(_)
        | PersistedPayload::EvidenceRecordedV3(_)
        | PersistedPayload::EvidenceBoundV3(_)
        | PersistedPayload::VerificationRecordedV3(_)
        | PersistedPayload::DecisionRecordedV3(_)
        | PersistedPayload::FindingRecordedV3(_)
        | PersistedPayload::IncrementalSourceBoundV5(_)
        | PersistedPayload::ProgramMappingRecordedV5(_)
        | PersistedPayload::ChangeMorphismSealedV5(_)
        | PersistedPayload::ObligationCorrespondenceEntryRecordedV5(_)
        | PersistedPayload::ObligationCorrespondenceSealedV5(_)
        | PersistedPayload::HistoricalRecordAssessedV5(_)
        | PersistedPayload::GluingFreshnessRecordedV5(_)
        | PersistedPayload::StalenessAssessmentSealedV5(_)
        | PersistedPayload::ArtifactRegisteredV5(_)
        | PersistedPayload::PreservationVerifiedV5 { .. }
        | PersistedPayload::PartialRerunActionRecordedV5(_)
        | PersistedPayload::PartialRerunPlanSealedV5(_)
        | PersistedPayload::GluingRerunActionRecordedV5(_)
        | PersistedPayload::GluingRerunPlanSealedV5(_)
        | PersistedPayload::TerminalCompletedV5(_) => Err(DomainError::Validation(
            "event-v3 state requires the versioned aggregate foundation".to_owned(),
        )),
    }
}

// V3 authority validation is deliberately distinct from each legacy
// admission capability; flattening these arguments would create a generic
// caller-controlled admission bag.
#[allow(clippy::too_many_arguments)]
fn apply_for_log(
    aggregate: &mut ReviewAggregate,
    v3_aggregate: Option<&mut V3RunAggregate>,
    payload: &PersistedPayload,
    actor: &str,
    expected_run_id: &StableId,
    genesis_hash: &ContentHash,
    reviewer_raw_size: Option<u64>,
    v3_authority_validated: bool,
) -> Result<()> {
    match payload {
        PersistedPayload::RunGenesisManifestV3(manifest) => {
            let snapshot_id = aggregate.program().snapshot_id().clone();
            v3_aggregate
                .ok_or_else(|| {
                    DomainError::Validation(
                        "v3 genesis manifest cannot enter a legacy aggregate".to_owned(),
                    )
                })?
                .record_genesis_manifest(aggregate, expected_run_id, &snapshot_id, manifest.clone())
        }
        PersistedPayload::ArtifactRegisteredV3(registration) => v3_aggregate
            .ok_or_else(|| {
                DomainError::Validation(
                    "v3 registration cannot enter a legacy aggregate".to_owned(),
                )
            })?
            .register_artifact(
                aggregate,
                expected_run_id,
                registration.clone(),
                v3_authority_validated,
            ),
        PersistedPayload::EvidenceRecordedV3(evidence) => v3_aggregate
            .ok_or_else(|| {
                DomainError::Validation("v3 evidence cannot enter a legacy aggregate".to_owned())
            })?
            .record_evidence(aggregate, evidence.clone()),
        PersistedPayload::EvidenceBoundV3(binding) => v3_aggregate
            .ok_or_else(|| {
                DomainError::Validation("v3 binding cannot enter a legacy aggregate".to_owned())
            })?
            .record_binding(binding.clone()),
        PersistedPayload::VerificationRecordedV3(verification) => v3_aggregate
            .ok_or_else(|| {
                DomainError::Validation(
                    "v3 verification cannot enter a legacy aggregate".to_owned(),
                )
            })?
            .record_verification(verification.clone()),
        PersistedPayload::DecisionRecordedV3(decision) => v3_aggregate
            .ok_or_else(|| {
                DomainError::Validation("v3 decision cannot enter a legacy aggregate".to_owned())
            })?
            .record_decision(decision.clone()),
        PersistedPayload::FindingRecordedV3(finding) => v3_aggregate
            .ok_or_else(|| {
                DomainError::Validation("v3 finding cannot enter a legacy aggregate".to_owned())
            })?
            .record_finding(finding.clone()),
        PersistedPayload::ReviewExecutionRecorded(recorded) => {
            apply(
                aggregate,
                payload,
                actor,
                expected_run_id,
                reviewer_raw_size,
            )?;
            if let Some(v3_aggregate) = v3_aggregate {
                v3_aggregate.initialize_claims(
                    aggregate,
                    expected_run_id,
                    genesis_hash,
                    &recorded.claims,
                )?;
            }
            Ok(())
        }
        _ => apply(
            aggregate,
            payload,
            actor,
            expected_run_id,
            reviewer_raw_size,
        ),
    }
}

/// Test-only roots-bound source fixture reused by the M6 end-to-end test.
/// It exposes replay products, never a mutable journal or authority token.
#[cfg(test)]
pub(crate) struct CompleteM5V4Fixture {
    log: EventLogV4,
    basis: AuthorityReplayBasisV4,
    completed: M5CompletedGluingProfileV4,
    roots_v4: AuthorityTrustRootsV4,
    authority_objects: BTreeMap<ContentHash, Vec<u8>>,
    harnesses: Vec<AuthorityHarnessBindingV3Tuple>,
    human_grants: Vec<AuthorityHumanGrantV3Tuple>,
}

#[cfg(test)]
impl CompleteM5V4Fixture {
    pub(crate) fn from_program_and_sources(
        program: ProgramSpace,
        sources: BTreeMap<StableId, Vec<u8>>,
        run_id: StableId,
    ) -> Result<Self> {
        tests::complete_m5_v4_fixture_from_program_and_sources(program, sources, run_id)
    }

    /// Test-only bridge for the already admitted V4 terminal M5 history.
    /// It rewraps only its sealed payload stream into a new V5 chain and
    /// reconstructs V5 roots/CAS from the exact fixture-owned objects.
    pub(crate) fn into_m6_target_terminal_fixture(self) -> Result<NoM5V5Fixture> {
        tests::complete_m5_into_v5_target_terminal_fixture(self)
    }

    pub(crate) fn selected_source_from_program_and_sources(
        program: ProgramSpace,
        sources: BTreeMap<StableId, Vec<u8>>,
        run_id: StableId,
    ) -> Result<Self> {
        tests::selected_source_m5_v4_fixture_from_program_and_sources(program, sources, run_id)
    }

    /// The compatible M5 branch shares the exact fixture construction and
    /// replay admission path, changing only the caller-selected pair of
    /// double-submit assignments.
    pub(crate) fn successful_from_program_and_sources(
        program: ProgramSpace,
        sources: BTreeMap<StableId, Vec<u8>>,
        run_id: StableId,
    ) -> Result<Self> {
        tests::successful_m5_v4_fixture_from_program_and_sources(program, sources, run_id)
    }

    pub(crate) fn preservation_source_from_program_and_sources(
        program: ProgramSpace,
        sources: BTreeMap<StableId, Vec<u8>>,
        run_id: StableId,
    ) -> Result<Self> {
        tests::preservation_source_m5_v4_fixture_from_program_and_sources(program, sources, run_id)
    }

    pub(crate) fn log(&self) -> &EventLogV4 {
        &self.log
    }

    pub(crate) fn passed_fixture_verification(&self) -> Option<&VerificationV3> {
        self.log
            .v3_aggregate
            .verifications
            .values()
            .find(|verification| {
                verification.outcome() == crate::VerificationOutcomeV3::Passed
                    && verification.descriptor() == crate::VerifierDescriptorV3::FixedFixtureV1
            })
    }

    pub(crate) fn passed_fixture_obligation_id(&self) -> Option<&StableId> {
        let verification = self.passed_fixture_verification()?;
        let claim = self
            .log
            .aggregate
            .execution_claims()
            .find(|claim| claim.id() == verification.claim_id())?;
        (claim.obligation_ids().len() == 1)
            .then(|| claim.obligation_ids().first())
            .flatten()
    }

    pub(crate) fn corrupt_fixture_reviewer_for_test(&mut self, field: &str) -> ExecutionRecord {
        let execution_id = self
            .passed_fixture_verification()
            .and_then(|verification| {
                self.log
                    .aggregate
                    .execution_claims()
                    .find(|claim| claim.id() == verification.claim_id())
            })
            .expect("fixture claim")
            .execution_id()
            .clone();
        self.log
            .aggregate
            .corrupt_execution_descriptor_for_test(&execution_id, field)
    }

    pub(crate) fn restore_fixture_reviewer_for_test(&mut self, execution: ExecutionRecord) {
        self.log.aggregate.restore_execution_for_test(execution);
    }

    pub(crate) fn corrupt_fixture_harness_for_test(
        &mut self,
        field: &str,
    ) -> AuthorityHarnessBindingV3Tuple {
        let root = self.harnesses.first_mut().expect("fixture harness root");
        let original = root.clone();
        match field {
            "harness" => root.harness_id = "harness:tampered".to_owned(),
            "harness_revision" => root.harness_revision = "revision:tampered".to_owned(),
            "harness_source_hash" => {
                root.harness_source_hash = ContentHash::sha256(b"tampered harness source");
            }
            "test" => root.test_artifact_id = StableId::parse("test:tampered").unwrap(),
            "repository" => root.repository_id = StableId::parse("repository:tampered").unwrap(),
            "repository_source_hash" => {
                root.repository_source_hash = ContentHash::sha256(b"tampered repository source");
            }
            "descriptor" => root.descriptor_id = "descriptor:tampered".to_owned(),
            "procedure" => root.procedure_version = "procedure:tampered".to_owned(),
            "witness_hash" => root.result_hash = ContentHash::sha256(b"tampered witness"),
            "witness_media" => root.result_media_type = "application/tampered".to_owned(),
            "witness_size" => root.result_size = root.result_size.saturating_add(1),
            "witness_sensitivity" => {
                root.result_sensitivity = ArtifactSensitivity::WorkspaceSource;
            }
            "policy" => root.policy_revision_hash = ContentHash::sha256(b"tampered policy"),
            "run" => root.run_id = StableId::parse("run:tampered").unwrap(),
            "genesis" => root.genesis_hash = ContentHash::sha256(b"tampered genesis"),
            "snapshot" => root.snapshot_id = StableId::parse("snapshot:tampered").unwrap(),
            "universe" => root.universe_id = StableId::parse("universe:tampered").unwrap(),
            "property" => root.property_id = "property:tampered".to_owned(),
            "claim" => root.claim_id = StableId::parse("claim:tampered").unwrap(),
            "claim_body" => root.claim_body_hash = ContentHash::sha256(b"tampered claim body"),
            "cas" => {
                self.authority_objects
                    .insert(root.result_hash.clone(), b"tampered CAS bytes".to_vec());
            }
            _ => panic!("unknown fixture harness mutation"),
        }
        original
    }

    pub(crate) fn restore_fixture_harness_for_test(
        &mut self,
        root: AuthorityHarnessBindingV3Tuple,
    ) {
        self.harnesses[0] = root;
    }

    pub(crate) fn clear_active_fixture_human_pointers_for_test(&mut self) {
        self.configure_active_fixture_human_pointers_for_test(false, false);
    }

    pub(crate) fn configure_active_fixture_human_pointers_for_test(
        &mut self,
        active_decision: bool,
        current_finding: bool,
    ) {
        let claim_id = self
            .passed_fixture_verification()
            .expect("fixture verification")
            .claim_id()
            .clone();
        self.log
            .v3_aggregate
            .assessments
            .get_mut(&claim_id)
            .expect("fixture assessment")
            .configure_active_human_pointers_for_test(active_decision, current_finding);
    }

    pub(crate) fn fixture_human_history_counts_for_test(&self) -> (usize, usize) {
        (
            self.log.v3_aggregate.decisions.len(),
            self.log.v3_aggregate.findings.len(),
        )
    }

    pub(crate) fn basis(&self) -> &AuthorityReplayBasisV4 {
        &self.basis
    }

    pub(crate) fn completed(&self) -> &M5CompletedGluingProfileV4 {
        &self.completed
    }

    pub(crate) fn program(&self) -> &ProgramSpace {
        self.log.aggregate.program()
    }

    pub(crate) fn run_id(&self) -> &StableId {
        self.log.run_id()
    }

    pub(crate) fn snapshot_id(&self) -> &StableId {
        self.program().snapshot_id()
    }

    pub(crate) fn has_m5_bundle(&self) -> bool {
        self.log.has_gluing_bundle_v4()
    }

    /// M5 is an atomic terminal bundle in a V4 history: a completed fixture
    /// consequently has precisely one such boundary, never a hand-counted
    /// envelope approximation.
    pub(crate) fn m5_event_count(&self) -> usize {
        usize::from(self.log.m5_bundle.is_some())
    }

    pub(crate) fn preservation_bundle_v5(
        &self,
        target_run_id: StableId,
        closure: &crate::IncrementalSourceClosureV5,
        mapping: &crate::M6MappingPhaseV5,
        correspondence: &crate::M6ObligationCorrespondencePhaseV5,
        staleness: &crate::M6StalenessPhaseV5,
        policy_revision_hash: ContentHash,
    ) -> crate::M6Result<crate::PreservationBundleV5> {
        if closure.source_run_id() != self.log.run_id() || closure.target_run_id() != &target_run_id
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "preservation run coordinates differ from the exact source closure",
            ));
        }
        let mut passed = self
            .log
            .v3_aggregate
            .verifications
            .values()
            .filter(|verification| {
                verification.outcome() == crate::VerificationOutcomeV3::Passed
                    && verification.descriptor() == crate::VerifierDescriptorV3::FixedFixtureV1
                    && verification.procedure() == crate::VerifierProcedureV3::DuplicateSubmitV1
            });
        let verification = passed
            .next()
            .ok_or(crate::M6Error::PreservationUnsupported(
                "source has no passed fixture verification",
            ))?;
        if passed.next().is_some() {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture verification is not unique",
            ));
        }
        let claim = self
            .log
            .aggregate
            .execution_claims()
            .find(|claim| {
                claim.id() == verification.claim_id()
                    && claim.property_id() == crate::M4_PROPERTY_ID
                    && claim.polarity() == crate::ClaimPolarity::IssuePresent
            })
            .ok_or(crate::M6Error::PreservationUnsupported(
                "passed source verification is not the issue_present payment fixture",
            ))?;
        let assessment = self.log.claim_assessment_v3(claim.id()).ok_or(
            crate::M6Error::PreservationUnsupported("source fixture claim assessment is absent"),
        )?;
        if assessment.active_decision_id().is_some() || assessment.current_finding_id().is_some() {
            return Err(crate::M6Error::PreservationUnsupported(
                "an active source human decision or current finding requires native target review",
            ));
        }
        let source_obligation_id =
            claim
                .obligation_ids()
                .first()
                .ok_or(crate::M6Error::PreservationUnsupported(
                    "fixture claim lacks its sole obligation",
                ))?;
        if claim.obligation_ids().len() != 1 {
            return Err(crate::M6Error::PreservationUnsupported(
                "fixture claim does not have exactly one obligation",
            ));
        }
        let execution = self
            .log
            .aggregate
            .executions()
            .find(|execution| execution.id() == claim.execution_id())
            .ok_or(crate::M6Error::PreservationUnsupported(
                "fixture claim lacks its reviewer execution",
            ))?;
        if execution.validate_shape().is_err()
            || execution.reviewer_kind() != crate::execution::FAKE_REVIEWER_KIND
            || execution.reviewer_id() != crate::execution::FAKE_REVIEWER_ID
            || execution.provider().is_some()
            || execution.model().is_some()
            || execution.model_revision().is_some()
            || execution.system_prompt_version() != crate::execution::NO_TOOLS_SYSTEM_PROMPT_VERSION
            || execution.prompt_template_version()
                != crate::execution::FIXTURE_PROMPT_TEMPLATE_VERSION
            || !execution.inference_settings().is_empty()
            || execution.tool_policy_version() != crate::execution::NO_TOOLS_POLICY_VERSION
            || execution.tool_call_count() != 0
            || !execution.outcome().is_structured()
            || execution.obligation_ids() != claim.obligation_ids()
            || execution.parsed_claim_ids() != &BTreeSet::from([claim.id().clone()])
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "source reviewer is not the exact deterministic fake/no-tools tuple",
            ));
        }
        let entry = correspondence
            .entries()
            .iter()
            .find(|entry| {
                entry.status() == crate::MappingStatusV5::Preserved
                    && entry.from_obligation_ids()
                        == &BTreeSet::from([source_obligation_id.clone()])
                    && entry.to_obligation_ids().len() == 1
            })
            .ok_or(crate::M6Error::PreservationUnsupported(
                "fixture obligation is not one-to-one preserved",
            ))?;
        let target_obligation_id = entry
            .to_obligation_ids()
            .first()
            .expect("one target")
            .clone();
        let evidence_ids = verification
            .evidence_ids()
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        let binding_ids = self
            .log
            .v3_aggregate
            .bindings
            .values()
            .filter(|binding| {
                binding.claim_id() == claim.id() && evidence_ids.contains(binding.evidence_id())
            })
            .map(|binding| binding.id().clone())
            .collect::<BTreeSet<_>>();
        if evidence_ids.len() != 1 || binding_ids.len() != 1 {
            return Err(crate::M6Error::PreservationUnsupported(
                "source evidence binding closure is not the exact singleton fixture",
            ));
        }
        let evidence_records = self
            .log
            .v3_aggregate
            .evidence
            .values()
            .filter(|evidence| evidence_ids.contains(evidence.id()))
            .collect::<Vec<_>>();
        if evidence_records.len() != evidence_ids.len()
            || evidence_records.iter().any(|evidence| {
                evidence.descriptor() != crate::VerifierDescriptorV3::FixedFixtureV1
                    || evidence.procedure() != crate::VerifierProcedureV3::DuplicateSubmitV1
                    || evidence.input_registration_id() != verification.input_registration_id()
                    || evidence.output_registration_id() != verification.output_registration_id()
            })
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture evidence closure differs from its passed verification",
            ));
        }
        let registrations = self.log.v3_aggregate.registrations.values();
        let input_registration = registrations
            .clone()
            .find(|registration| {
                registration.registration_id() == verification.input_registration_id()
            })
            .ok_or(crate::M6Error::PreservationUnsupported(
                "source fixture input registration is absent",
            ))?;
        let output_registration = registrations
            .clone()
            .find(|registration| {
                registration.registration_id() == verification.output_registration_id()
            })
            .ok_or(crate::M6Error::PreservationUnsupported(
                "source fixture output registration is absent",
            ))?;
        let reviewer_registration = registrations
            .clone()
            .find(|registration| {
                registration.registration_id() == execution.raw_artifact_registration_id()
            })
            .ok_or(crate::M6Error::PreservationUnsupported(
                "source reviewer raw registration is absent",
            ))?;
        let ArtifactSourceV3::ReviewerExecution {
            execution_id,
            reviewer_id,
            run_id: reviewer_run_id,
        } = reviewer_registration.source()
        else {
            return Err(crate::M6Error::PreservationUnsupported(
                "source reviewer raw registration has a wrong role",
            ));
        };
        if execution_id != execution.id()
            || reviewer_id != crate::execution::FAKE_REVIEWER_ID
            || reviewer_run_id != self.log.run_id()
            || reviewer_registration.cas_hash() != execution.raw_artifact_hash()
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "source reviewer raw registration differs from its execution tuple",
            ));
        }
        let ArtifactSourceV3::ExternalHarnessWitness {
            claim_body_hash,
            claim_id,
            descriptor_id,
            genesis_hash,
            harness_id,
            harness_revision,
            harness_source_hash,
            policy_revision_hash: harness_policy_revision_hash,
            procedure_version,
            property_id,
            repository_id,
            repository_source_hash,
            run_id,
            snapshot_id,
            test_artifact_id,
            universe_id,
        } = input_registration.source()
        else {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture input is not the external harness witness",
            ));
        };
        let [harness_root] = self.harnesses.as_slice() else {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture does not have exactly one harness root",
            ));
        };
        let exact_claim_body_hash = claim.body_hash()?;
        if descriptor_id != FIXTURE_DESCRIPTOR_ID
            || procedure_version != FIXTURE_PROCEDURE_ID
            || harness_id != FIXTURE_HARNESS_ID
            || harness_revision != FIXTURE_HARNESS_REVISION
            || harness_source_hash.as_str() != FIXTURE_HARNESS_SOURCE_HASH
            || test_artifact_id.as_str() != FIXTURE_TEST_ARTIFACT_ID
            || property_id != crate::M4_PROPERTY_ID
            || claim_id != claim.id()
            || claim_body_hash != &exact_claim_body_hash
            || run_id != self.log.run_id()
            || genesis_hash != self.log.genesis_hash()
            || snapshot_id != self.snapshot_id()
            || universe_id != self.log.aggregate.universe().id()
            || repository_id != self.program().repository_id()
            || repository_source_hash
                != self.program().repository_source().content_hash().ok_or(
                    crate::M6Error::PreservationUnsupported(
                        "source fixture repository has no accepted content hash",
                    ),
                )?
            || input_registration.cas_hash().as_str() != FIXTURE_WITNESS_HASH
            || input_registration.size() != FIXTURE_WITNESS_SIZE
            || input_registration.media_type() != FIXTURE_MEDIA_TYPE
            || input_registration.sensitivity() != ArtifactSensitivity::CanonicalState
            || harness_root.policy_revision_hash != *harness_policy_revision_hash
            || harness_root.repository_id != *repository_id
            || harness_root.repository_source_hash != *repository_source_hash
            || harness_root.harness_id != *harness_id
            || harness_root.harness_revision != *harness_revision
            || harness_root.harness_source_hash != *harness_source_hash
            || harness_root.test_artifact_id != *test_artifact_id
            || harness_root.descriptor_id != *descriptor_id
            || harness_root.procedure_version != *procedure_version
            || harness_root.result_hash != *input_registration.cas_hash()
            || harness_root.result_size != input_registration.size()
            || harness_root.result_media_type != input_registration.media_type()
            || harness_root.result_sensitivity != input_registration.sensitivity()
            || harness_root.run_id != *run_id
            || harness_root.genesis_hash != *genesis_hash
            || harness_root.snapshot_id != *snapshot_id
            || harness_root.universe_id != *universe_id
            || harness_root.property_id != *property_id
            || harness_root.claim_id != *claim_id
            || harness_root.claim_body_hash != *claim_body_hash
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture harness/repository/test tuple is not exact",
            ));
        }
        let ArtifactSourceV3::VerifierArtifact {
            claim_id: output_claim_id,
            descriptor_id: output_descriptor,
            procedure_version: output_procedure,
            role: VerifierArtifactRoleV3::Output,
            run_id: output_run_id,
        } = output_registration.source()
        else {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture output registration has a wrong role",
            ));
        };
        if output_claim_id != claim.id()
            || output_descriptor != FIXTURE_DESCRIPTOR_ID
            || output_procedure != FIXTURE_PROCEDURE_ID
            || output_run_id != self.log.run_id()
            || [
                reviewer_registration,
                input_registration,
                output_registration,
            ]
            .iter()
            .any(|registration| {
                self.authority_objects
                    .get(registration.cas_hash())
                    .is_none_or(|bytes| {
                        ContentHash::sha256(bytes) != *registration.cas_hash()
                            || u64::try_from(bytes.len()).ok() != Some(registration.size())
                    })
            })
            || self
                .authority_objects
                .get(input_registration.cas_hash())
                .is_none_or(|bytes| bytes.as_slice() != FIXTURE_WITNESS_BYTES)
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture registration roles or CAS bytes are not exact",
            ));
        }
        let obligation_assessment = staleness
            .records()
            .iter()
            .find(|record| {
                record.source_record_kind() == crate::HistoricalRecordKindV5::Obligation
                    && record.source_record_id() == source_obligation_id
            })
            .ok_or(crate::M6Error::PreservationUnsupported(
                "source fixture obligation lacks its historical assessment",
            ))?;
        if obligation_assessment.status()
            != crate::HistoricalAssessmentStatusV5::StructurallyPreserved
            || !obligation_assessment.reasons().is_empty()
            || obligation_assessment.successor_record_ids()
                != &BTreeSet::from([target_obligation_id.clone()])
            || !staleness.is_sealed_preservation_candidate(&target_obligation_id)?
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "source fixture obligation is not the exact sealed preservation candidate",
            ));
        }
        let coordinate_snapshot_pair = |mapping_id: &StableId| {
            mapping
                .mappings()
                .iter()
                .find(|value| value.id() == mapping_id)
                .is_some_and(|value| {
                    value.object_kind() == crate::ProgramObjectKindV5::Snapshot
                        && value.from_ids()
                            == &BTreeSet::from([closure.source_snapshot_id().clone()])
                        && value.to_ids() == &BTreeSet::from([closure.target_snapshot_id().clone()])
                })
        };
        let dependency_mapping_ids = obligation_assessment
            .mapping_ids()
            .iter()
            .filter(|mapping_id| !coordinate_snapshot_pair(mapping_id))
            .cloned()
            .chain(
                entry
                    .source_mapping_ids()
                    .iter()
                    .filter(|mapping_id| !coordinate_snapshot_pair(mapping_id))
                    .cloned(),
            )
            .collect::<BTreeSet<_>>();
        if dependency_mapping_ids.is_empty()
            || dependency_mapping_ids.iter().any(|mapping_id| {
                mapping
                    .mappings()
                    .iter()
                    .find(|mapping| mapping.id() == mapping_id)
                    .is_none_or(|mapping| mapping.status() != crate::MappingStatusV5::Preserved)
            })
        {
            return Err(crate::M6Error::PreservationUnsupported(
                "a direct or indirect fixture dependency mapping is not preserved",
            ));
        }
        let input = crate::PreservationInputV1::new(crate::PreservationInputParamsV1 {
            source_closure_id: closure.id().clone(),
            morphism_id: correspondence.correspondence().morphism_id().clone(),
            correspondence_entry_id: entry.id().clone(),
            source_claim_id: claim.id().clone(),
            source_evidence_ids: evidence_ids,
            source_verification_id: verification.id().clone(),
            target_snapshot_id: closure.target_snapshot_id().clone(),
            target_obligation_id,
            dependency_mapping_ids,
            policy_revision_hash,
        })?;
        crate::PreservationBundleV5::build(target_run_id, self.log.run_id.clone(), input)
    }
}

/// Test-only terminal V5 predecessor.  Construction is restricted to typed
/// ProgramSpace facts plus file bytes whose SHA-256 values are checked against
/// those accepted facts before any source registration is minted.
#[cfg(test)]
pub(crate) struct NoM5V5Fixture {
    log: EventLogV5,
    roots: AuthorityTrustRootsV5,
    sources: BTreeMap<StableId, Vec<u8>>,
    program: ProgramSpace,
}

#[cfg(test)]
#[derive(Clone, Copy)]
pub(crate) enum NoM5V5FixtureTerminalStage {
    ReviewerContext,
    ReviewerCompleted,
    NativeVerification,
    HumanFinding,
}

#[cfg(test)]
impl NoM5V5Fixture {
    pub(crate) fn from_native_m4_fixture_through(
        source: CompleteM5V4Fixture,
        program: ProgramSpace,
        terminal_stage: NoM5V5FixtureTerminalStage,
    ) -> Result<Self> {
        // The bridge is driven by the actual passed native closure, not by a
        // property-name convention.  Successful M5 fixtures intentionally
        // use `payment.at_most_once`; selecting its verification -> claim ->
        // singleton obligation preserves that closed provenance unchanged.
        let passed = source
            .log
            .v3_aggregate
            .verifications
            .values()
            .filter(|verification| verification.outcome() == crate::VerificationOutcomeV3::Passed)
            .collect::<Vec<_>>();
        let [passed_native_verification] = passed.as_slice() else {
            return Err(DomainError::Validation(
                "native target fixture requires exactly one passed verification".to_owned(),
            ));
        };
        let target_payment_claim_id = passed_native_verification.claim_id().clone();
        let target_payment_obligation_id = source
            .log
            .aggregate
            .execution_claims()
            .find(|claim| claim.id() == &target_payment_claim_id)
            .and_then(|claim| {
                (claim.obligation_ids().len() == 1)
                    .then(|| claim.obligation_ids().first())
                    .flatten()
            })
            .cloned()
            .ok_or_else(|| {
                DomainError::Validation(
                    "passed native verification does not close one target obligation".to_owned(),
                )
            })?;
        let mut program_sources = BTreeMap::new();
        for artifact in program
            .artifacts()
            .iter()
            .filter(|artifact| artifact.kind == "file")
        {
            let hash = artifact.content_hash.as_ref().ok_or_else(|| {
                DomainError::Validation("native target file has no content hash".to_owned())
            })?;
            let bytes = source.authority_objects.get(hash).ok_or_else(|| {
                DomainError::Validation("native target file CAS object is absent".to_owned())
            })?;
            program_sources.insert(artifact.id.clone(), bytes.clone());
        }
        let run_id = source.log.run_id().clone();
        let request = RunGenesisBootstrapRequestV4::new(
            run_id,
            source.log.canonical_genesis_bytes().to_vec(),
            program.repository_identity(),
            program.snapshot_id().clone(),
            program.profile_id(),
            program.profile_version(),
        )?;
        let initial_registrations = source
            .log
            .envelopes()
            .iter()
            .skip(1)
            .filter_map(|event| {
                match decode_canonical_payload(EventContractVersion::V4, event.payload.get())
                    .ok()?
                {
                    PersistedPayload::ArtifactRegisteredV3(value)
                        if matches!(value.source(), ArtifactSourceV3::SnapshotIngest { .. }) =>
                    {
                        Some(value)
                    }
                    _ => None,
                }
            })
            .collect::<Vec<_>>();
        let recorded_sources = source
            .log
            .envelopes()
            .iter()
            .find_map(|event| {
                match decode_canonical_payload(EventContractVersion::V4, event.payload.get())
                    .ok()?
                {
                    PersistedPayload::SnapshotSourcesRecorded(value) => Some(value),
                    _ => None,
                }
            })
            .ok_or_else(|| {
                DomainError::Validation("native target sources are absent".to_owned())
            })?;
        let target_plan = source
            .log
            .aggregate
            .review_plans()
            .next()
            .ok_or_else(|| DomainError::Validation("native target plan is absent".to_owned()))?
            .clone();
        let target_log = EventLogV5::from_planned_bootstrap_request(
            request,
            initial_registrations,
            recorded_sources,
            target_plan,
        )?;
        let roots = AuthorityTrustRootsV5::new(
            target_policy_revision_hash_v5(&program)?,
            program.repository_id().clone(),
            program
                .repository_source()
                .content_hash()
                .ok_or(DomainError::AuthorityPolicyMismatch)?
                .clone(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        )?;
        let mut target = Self {
            log: target_log,
            roots,
            sources: program_sources,
            program: program.clone(),
        };
        let mut semantic_start = 1;
        for (index, legacy) in source.log.envelopes().iter().enumerate().skip(1) {
            let payload = decode_canonical_payload(EventContractVersion::V4, legacy.payload.get())?;
            if let PersistedPayload::ReviewPlanRecorded(_) = payload {
                semantic_start = index + 1;
                break;
            }
        }
        for legacy in source.log.envelopes().iter().skip(semantic_start) {
            let payload = decode_canonical_payload(EventContractVersion::V4, legacy.payload.get())?;
            let completes_payment = matches!(
                &payload,
                PersistedPayload::ObligationTransition {
                    obligation_id,
                    next: ObligationLifecycle::Completed,
                } if obligation_id == &target_payment_obligation_id
            );
            let projects_reviewer_context = matches!(
                &payload,
                PersistedPayload::ContextEnvelopeProjected(value)
                    if value.obligation_ids().contains(&target_payment_obligation_id)
            );
            let completes_native_verification = matches!(
                &payload,
                PersistedPayload::VerificationRecordedV3(value)
                    if value.claim_id() == &target_payment_claim_id
                        && value.outcome() == crate::VerificationOutcomeV3::Passed
            );
            let completes_human = matches!(
                &payload,
                PersistedPayload::FindingRecordedV3(value)
                    if value.claim_id() == &target_payment_claim_id
            );
            let sequence = u64::try_from(target.log.envelopes.len())
                .ok()
                .and_then(|value| value.checked_add(1))
                .ok_or_else(|| {
                    DomainError::EventSequence("native target sequence overflow".to_owned())
                })?;
            let envelope = EventEnvelope::new(
                EventContractVersion::V5,
                target.log.run_id.clone(),
                target.log.genesis_hash.clone(),
                sequence,
                payload.actor().to_owned(),
                sequence,
                target.log.tail_hash().clone(),
                payload,
            )?;
            target.log.append_sealed_envelope_v5(envelope)?;
            let complete = match terminal_stage {
                NoM5V5FixtureTerminalStage::ReviewerContext => projects_reviewer_context,
                NoM5V5FixtureTerminalStage::ReviewerCompleted => completes_payment,
                NoM5V5FixtureTerminalStage::NativeVerification => completes_native_verification,
                NoM5V5FixtureTerminalStage::HumanFinding => completes_human,
            };
            if complete {
                break;
            }
        }
        target.roots = AuthorityTrustRootsV5::new(
            target_policy_revision_hash_v5(&program)?,
            program.repository_id().clone(),
            program
                .repository_source()
                .content_hash()
                .ok_or(DomainError::AuthorityPolicyMismatch)?
                .clone(),
            source.harnesses,
            source.human_grants,
            Vec::new(),
        )?;
        for (index, bytes) in source.authority_objects.into_values().enumerate() {
            target.sources.insert(
                StableId::parse(format!("artifact:native-cas-{index}"))?,
                bytes,
            );
        }
        Ok(target)
    }

    pub(crate) fn from_program_and_sources(
        program: ProgramSpace,
        sources: BTreeMap<StableId, Vec<u8>>,
        run_id: StableId,
    ) -> Result<Self> {
        let (universe, obligations) = crate::MvpRulePack::synthesize(&program)?.into_parts();
        let mut aggregate = ReviewAggregate::new(program.clone(), universe, obligations)?;
        let snapshot_id = aggregate.program().snapshot_id().clone();
        let mut registrations = Vec::new();
        let mut entries = Vec::new();
        for artifact in aggregate
            .program()
            .artifacts()
            .iter()
            .filter(|artifact| artifact.kind == "file")
        {
            let bytes = sources.get(&artifact.id).ok_or_else(|| {
                DomainError::Validation(
                    "M6 target fixture lacks accepted file CAS bytes".to_owned(),
                )
            })?;
            let expected = artifact.content_hash.as_ref().ok_or_else(|| {
                DomainError::Validation("M6 target fixture file lacks content hash".to_owned())
            })?;
            if &ContentHash::sha256(bytes) != expected {
                return Err(DomainError::Validation(
                    "M6 target fixture CAS bytes do not equal accepted file hash".to_owned(),
                ));
            }
            let location = artifact.location.as_ref().ok_or_else(|| {
                DomainError::Validation("M6 target fixture file lacks location".to_owned())
            })?;
            let registration = ArtifactRegisteredV3::new(
                run_id.clone(),
                expected.clone(),
                "text/plain",
                u64::try_from(bytes.len()).map_err(|_| {
                    DomainError::Validation("M6 target fixture source is too large".to_owned())
                })?,
                ArtifactSensitivity::WorkspaceSource,
                ArtifactSourceV3::SnapshotIngest {
                    adapter_id: "m6-distinct-s1-fixture".to_owned(),
                    run_id: run_id.clone(),
                    snapshot_id: snapshot_id.clone(),
                },
            )?;
            entries.push(SnapshotSourceRecordEntry::new(
                artifact.id.clone(),
                location.path.clone(),
                expected.clone(),
                registration.registration_id().clone(),
                expected.clone(),
                u64::try_from(bytes.iter().filter(|byte| **byte == b'\n').count())
                    .unwrap_or(u64::MAX)
                    .saturating_add(1),
            )?);
            registrations.push(registration);
        }
        if sources.len() != entries.len() {
            return Err(DomainError::Validation(
                "M6 target fixture source map has an unaccepted file entry".to_owned(),
            ));
        }
        registrations.sort_by(|left, right| left.registration_id().cmp(right.registration_id()));
        entries.sort_by(|left, right| left.path().cmp(right.path()));
        for registration in &registrations {
            aggregate.register_artifact_v3(&run_id, registration.clone())?;
        }
        let recorded_sources = SnapshotSourcesRecorded::new(snapshot_id, entries)?;
        aggregate.record_snapshot_sources(recorded_sources.clone())?;
        let plan = crate::plan(&aggregate, crate::PlanBudget::new(16, 16)?)?;
        let genesis = RunGenesisSnapshot::from_aggregate_v3(&aggregate)?.canonical_bytes_v3()?;
        let request = RunGenesisBootstrapRequestV4::new(
            run_id,
            genesis,
            aggregate.program().repository_identity(),
            aggregate.program().snapshot_id().clone(),
            aggregate.program().profile_id(),
            aggregate.program().profile_version(),
        )?;
        let log = EventLogV5::from_planned_bootstrap_request(
            request,
            registrations,
            recorded_sources,
            plan,
        )?;
        let roots = AuthorityTrustRootsV5::new(
            target_policy_revision_hash_v5(&program)?,
            program.repository_id().clone(),
            program
                .repository_source()
                .content_hash()
                .ok_or(DomainError::AuthorityPolicyMismatch)?
                .clone(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        )?;
        Ok(Self {
            log,
            roots,
            sources,
            program,
        })
    }

    pub(crate) fn log(&self) -> &EventLogV5 {
        &self.log
    }
    pub(crate) fn program(&self) -> &ProgramSpace {
        &self.program
    }
    pub(crate) fn run_id(&self) -> &StableId {
        self.log.run_id()
    }
    pub(crate) fn snapshot_id(&self) -> &StableId {
        self.program().snapshot_id()
    }
    pub(crate) fn m5_event_count(&self) -> usize {
        self.log
            .envelopes
            .iter()
            .filter(|envelope| {
                matches!(
                    decode_canonical_payload(EventContractVersion::V5, envelope.payload.get()),
                    Ok(PersistedPayload::GluingBundleRecordedV4(_))
                )
            })
            .count()
    }

    pub(crate) fn with_terminal<R>(
        &self,
        callback: impl for<'a> FnOnce(
            &V5PreIncrementalStructuralPrefixProjection<'a>,
            &TargetActualRecordInventoryV5<'a>,
            &TargetPredecessorSuppressionProjectionV5,
        ) -> crate::m6::M6Result<R>,
    ) -> crate::m6::M6Result<R> {
        struct Resolver<'a>(&'a BTreeMap<StableId, Vec<u8>>);
        impl AuthorityArtifactResolverV5 for Resolver<'_> {
            fn read_exact(&self, hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                let bytes = self
                    .0
                    .values()
                    .find(|bytes| ContentHash::sha256(bytes) == *hash)
                    .ok_or_else(|| {
                        DomainError::Validation("M6 target fixture CAS object is absent".to_owned())
                    })?;
                if bytes.len() != destination.len() {
                    return Err(DomainError::Validation(
                        "M6 target fixture CAS object size differs".to_owned(),
                    ));
                }
                destination.copy_from_slice(bytes);
                Ok(())
            }
        }
        let structural = self
            .log
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                self.log.run_id(),
                self.log.genesis_hash(),
                self.log.canonical_prefix_bytes_for_store(),
                u64::try_from(self.log.envelopes().len()).map_err(|_| {
                    crate::m6::M6Error::Incomplete {
                        operation: "M6 target fixture event count",
                        limit: usize::MAX,
                        observed: usize::MAX,
                    }
                })?,
                self.log.tail_hash(),
            ))
            .map_err(crate::m6::M6Error::from)?;
        let resolver = Resolver(&self.sources);
        let checkpoint = EventLogV5::certify_plan_authority_checkpoint_v5_with_limits(
            &structural,
            &resolver,
            &self.roots,
            self.log.limits.max_retained_bytes,
            self.log.limits.max_working_bytes,
        )
        .map_err(crate::m6::M6Error::from)?;
        let d2 = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &resolver,
            &self.roots,
        )
        .map_err(crate::m6::M6Error::from)?;
        let m4 = EventLogV5::replay_ordered_m4_authority_prefix_v5(d2, &resolver, &self.roots)
            .map_err(crate::m6::M6Error::from)?;
        let terminal =
            EventLogV5::replay_terminal_pre_incremental_authority_v5(&m4, &resolver, &self.roots)
                .map_err(crate::m6::M6Error::from)?;
        let projection = terminal
            .target_actual_record_projection_v5()
            .map_err(crate::m6::M6Error::from)?;
        let inventory = projection
            .materialize_inventory_v5()
            .map_err(crate::m6::M6Error::from)?;
        let suppression = projection
            .suppression_projection_from_inventory_v5(&inventory)
            .map_err(crate::m6::M6Error::from)?;
        callback(&structural.projection(), &inventory, &suppression)
    }

    pub(crate) fn seal_partial_rerun_plan_v5(
        &self,
        staleness: &crate::M6StalenessPhaseV5,
        preservation: &crate::M6PreservationPhaseV5,
    ) -> crate::m6::M6Result<(Vec<crate::PartialRerunActionV5>, crate::PartialRerunPlanV5)> {
        struct Resolver<'a>(&'a BTreeMap<StableId, Vec<u8>>);
        impl AuthorityArtifactResolverV5 for Resolver<'_> {
            fn read_exact(&self, hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                let bytes = self
                    .0
                    .values()
                    .find(|bytes| ContentHash::sha256(bytes) == *hash)
                    .ok_or_else(|| {
                        DomainError::Validation("M6 target fixture CAS object is absent".to_owned())
                    })?;
                if bytes.len() != destination.len() {
                    return Err(DomainError::Validation(
                        "M6 target fixture CAS object size differs".to_owned(),
                    ));
                }
                destination.copy_from_slice(bytes);
                Ok(())
            }
        }
        let structural = self
            .log
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                self.log.run_id(),
                self.log.genesis_hash(),
                self.log.canonical_prefix_bytes_for_store(),
                u64::try_from(self.log.envelopes().len()).map_err(|_| {
                    crate::m6::M6Error::Incomplete {
                        operation: "M6 target fixture event count",
                        limit: usize::MAX,
                        observed: usize::MAX,
                    }
                })?,
                self.log.tail_hash(),
            ))
            .map_err(crate::m6::M6Error::from)?;
        let resolver = Resolver(&self.sources);
        let checkpoint = EventLogV5::certify_plan_authority_checkpoint_v5_with_limits(
            &structural,
            &resolver,
            &self.roots,
            self.log.limits.max_retained_bytes,
            self.log.limits.max_working_bytes,
        )
        .map_err(crate::m6::M6Error::from)?;
        let d2 = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &resolver,
            &self.roots,
        )
        .map_err(crate::m6::M6Error::from)?;
        let m4 = EventLogV5::replay_ordered_m4_authority_prefix_v5(d2, &resolver, &self.roots)
            .map_err(crate::m6::M6Error::from)?;
        let terminal =
            EventLogV5::replay_terminal_pre_incremental_authority_v5(&m4, &resolver, &self.roots)
                .map_err(crate::m6::M6Error::from)?;
        terminal.seal_partial_rerun_plan_v5(staleness, preservation)
    }

    pub(crate) fn seal_partial_rerun_phase_v5(
        &self,
        staleness: &crate::M6StalenessPhaseV5,
        preservation: &crate::M6PreservationPhaseV5,
    ) -> crate::m6::M6Result<SealedPartialRerunPhaseV5> {
        self.seal_partial_rerun_phase_for_log_v5(&self.log, staleness, preservation)
    }

    pub(crate) fn seal_partial_rerun_phase_for_log_v5(
        &self,
        event_log: &EventLogV5,
        staleness: &crate::M6StalenessPhaseV5,
        preservation: &crate::M6PreservationPhaseV5,
    ) -> crate::m6::M6Result<SealedPartialRerunPhaseV5> {
        struct Resolver<'a>(&'a BTreeMap<StableId, Vec<u8>>);
        impl AuthorityArtifactResolverV5 for Resolver<'_> {
            fn read_exact(&self, hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                let bytes = self
                    .0
                    .values()
                    .find(|bytes| ContentHash::sha256(bytes) == *hash)
                    .ok_or_else(|| {
                        DomainError::Validation("M6 target fixture CAS object is absent".to_owned())
                    })?;
                if bytes.len() != destination.len() {
                    return Err(DomainError::Validation(
                        "M6 target fixture CAS object size differs".to_owned(),
                    ));
                }
                destination.copy_from_slice(bytes);
                Ok(())
            }
        }
        let predecessor_count = usize::try_from(staleness.target_predecessor_event_count())
            .map_err(|_| crate::m6::M6Error::Incomplete {
                operation: "M6 target fixture predecessor event count",
                limit: usize::MAX,
                observed: usize::MAX,
            })?;
        let predecessor_envelopes = event_log.envelopes.get(..predecessor_count).ok_or(
            crate::m6::M6Error::InvalidHistoricalTopology(
                "M6 target fixture caller log is shorter than the pinned predecessor",
            ),
        )?;
        let (predecessor_log, _) = EventLogV5::replay_confirmed_v5_prefix(
            event_log.run_id.clone(),
            event_log.canonical_genesis_bytes.clone(),
            predecessor_envelopes.to_vec(),
            event_log.limits,
        )?;
        if predecessor_log.run_id() != self.log.run_id()
            || predecessor_log.genesis_hash() != self.log.genesis_hash()
            || predecessor_log.tail_hash() != staleness.target_predecessor_tail_hash()
            || u64::try_from(predecessor_log.envelopes.len()).unwrap_or(u64::MAX)
                != staleness.target_predecessor_event_count()
        {
            return Err(crate::m6::M6Error::InvalidHistoricalTopology(
                "M6 target fixture caller predecessor differs from the pinned staleness prefix",
            ));
        }
        let structural = predecessor_log
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                predecessor_log.run_id(),
                predecessor_log.genesis_hash(),
                predecessor_log.canonical_prefix_bytes_for_store(),
                u64::try_from(predecessor_log.envelopes.len()).map_err(|_| {
                    crate::m6::M6Error::Incomplete {
                        operation: "M6 target fixture event count",
                        limit: usize::MAX,
                        observed: usize::MAX,
                    }
                })?,
                predecessor_log.tail_hash(),
            ))
            .map_err(crate::m6::M6Error::from)?;
        let resolver = Resolver(&self.sources);
        let checkpoint = EventLogV5::certify_plan_authority_checkpoint_v5_with_limits(
            &structural,
            &resolver,
            &self.roots,
            predecessor_log.limits.max_retained_bytes,
            predecessor_log.limits.max_working_bytes,
        )
        .map_err(crate::m6::M6Error::from)?;
        let d2 = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &resolver,
            &self.roots,
        )
        .map_err(crate::m6::M6Error::from)?;
        let m4 = EventLogV5::replay_ordered_m4_authority_prefix_v5(d2, &resolver, &self.roots)
            .map_err(crate::m6::M6Error::from)?;
        let terminal =
            EventLogV5::replay_terminal_pre_incremental_authority_v5(&m4, &resolver, &self.roots)
                .map_err(crate::m6::M6Error::from)?;
        terminal.seal_partial_rerun_phase_v5(event_log, staleness, preservation)
    }

    pub(crate) fn with_terminal_persistence<R>(
        &self,
        callback: impl for<'a> FnOnce(
            EventLogV5,
            PreIncrementalAuthorityReplayBasisV5,
        ) -> crate::m6::M6Result<R>,
    ) -> crate::m6::M6Result<R> {
        self.with_terminal(|_, _, _| {
            struct Resolver<'a>(&'a BTreeMap<StableId, Vec<u8>>);
            impl AuthorityArtifactResolverV5 for Resolver<'_> {
                fn read_exact(&self, hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                    let bytes = self
                        .0
                        .values()
                        .find(|bytes| ContentHash::sha256(bytes) == *hash)
                        .ok_or_else(|| {
                            DomainError::Validation(
                                "M6 target fixture CAS object is absent".to_owned(),
                            )
                        })?;
                    if bytes.len() != destination.len() {
                        return Err(DomainError::Validation(
                            "M6 target fixture CAS object size differs".to_owned(),
                        ));
                    }
                    destination.copy_from_slice(bytes);
                    Ok(())
                }
            }

            let (log, _) = EventLogV5::replay_confirmed_v5_prefix(
                self.log.run_id.clone(),
                self.log.canonical_genesis_bytes.clone(),
                self.log.envelopes.clone(),
                self.log.limits,
            )?;
            let structural = log.replay_pre_incremental_structural_prefix_for_store(
                V5StructuralPrefixCoordinates::new(
                    log.run_id(),
                    log.genesis_hash(),
                    log.canonical_prefix_bytes_for_store(),
                    u64::try_from(log.envelopes.len()).unwrap_or(u64::MAX),
                    log.tail_hash(),
                ),
            )?;
            let checkpoint = EventLogV5::certify_plan_authority_checkpoint_v5_with_limits(
                &structural,
                &Resolver(&self.sources),
                &self.roots,
                log.limits.max_retained_bytes,
                log.limits.max_working_bytes,
            )?;
            let d2 = EventLogV5::replay_certified_d2_authority_prefix_v5(
                &checkpoint,
                &Resolver(&self.sources),
                &self.roots,
            )?;
            let terminal = EventLogV5::replay_ordered_m4_authority_prefix_v5(
                d2,
                &Resolver(&self.sources),
                &self.roots,
            )?;
            let selected = EventLogV5::replay_terminal_pre_incremental_authority_v5(
                &terminal,
                &Resolver(&self.sources),
                &self.roots,
            )?;
            let basis = match selected.inner {
                ReplayedV5TerminalPredecessorInnerV5::WithoutM5 { basis, .. }
                | ReplayedV5TerminalPredecessorInnerV5::WithM5InputPrefix { basis, .. } => basis,
            };
            callback(log, basis)
        })
    }
}

