    #[test]
    fn v5_plan_authority_checkpoint_never_mints_a_full_predecessor_basis() {
        let (v4, _basis, roots_v4, resolver, _session, _claim, _input, _output) =
            static_v4_bundle_base();
        let mut v5 = rewrap_v4_prefix_as_v5(&v4);
        let plan_count = v5
            .envelopes
            .iter()
            .position(|envelope| {
                matches!(
                    decode_canonical_payload(EventContractVersion::V5, envelope.payload.get()),
                    Ok(PersistedPayload::ReviewPlanRecorded(_))
                )
            })
            .expect("plan envelope")
            + 1;
        v5.envelopes.truncate(plan_count);
        v5.canonical_prefix_bytes = v5
            .envelopes
            .iter()
            .map(|envelope| {
                envelope
                    .canonical_line_bytes_v5
                    .expect("V5 line accounting")
            })
            .sum();
        let AuthorityTrustRootsV4 {
            policy_revision_hash: _,
            repository_id,
            repository_source_hash,
            harnesses,
            human_grants,
            allowed_gluing_input_bindings: _,
        } = roots_v4;
        let roots = AuthorityTrustRootsV5::new(
            target_policy_revision_hash_v5(v4.aggregate.program()).expect("derived V5 policy"),
            repository_id,
            repository_source_hash,
            harnesses,
            human_grants,
            Vec::new(),
        )
        .expect("V5 roots");
        struct Resolver(BTreeMap<ContentHash, Vec<u8>>);
        impl AuthorityArtifactResolverV5 for Resolver {
            fn read_exact(&self, hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                let bytes = self.0.get(hash).ok_or_else(|| {
                    DomainError::Validation("missing V5 basis test CAS".to_owned())
                })?;
                if bytes.len() != destination.len() {
                    return Err(DomainError::Validation("V5 basis test CAS size".to_owned()));
                }
                destination.copy_from_slice(bytes);
                Ok(())
            }
        }
        let structural = v5
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                v5.run_id(),
                v5.genesis_hash(),
                v5.canonical_prefix_bytes_for_store(),
                u64::try_from(v5.envelopes.len()).unwrap(),
                v5.tail_hash(),
            ))
            .expect("basis structural");
        let state = EventLogV5::replay_plan_authority_prefix_v5(
            &structural,
            &Resolver(resolver.objects),
            &roots,
        )
        .expect("basis state");
        assert_eq!(state.plan_event_count, structural.predecessor_event_count);
        assert_eq!(state.plan_tail_hash, structural.tail_hash);
        assert_eq!(
            state.structural.predecessor_event_count,
            state.plan_event_count
        );

        #[derive(Serialize)]
        struct PositionOracle<'a> {
            schema: &'a str,
            run_id: &'a StableId,
            genesis_hash: &'a ContentHash,
            event_id: &'a StableId,
            event_sequence: u64,
            predecessor_event_hash: &'a ContentHash,
            v3_trust_binding_digest: &'a ContentHash,
        }
        let event_id = id("event:v5-position-oracle");
        let predecessor = ContentHash::sha256(b"position predecessor");
        let trust = ContentHash::sha256(b"position trust");
        let actual = v5_authority_position_digest(
            v5.run_id(),
            v5.genesis_hash(),
            &event_id,
            9,
            &predecessor,
            &trust,
        )
        .expect("position digest");
        let expected = ContentHash::sha256(
            &canonical_json(&PositionOracle {
                schema: "reviewgraphen.authority_position.v5",
                run_id: v5.run_id(),
                genesis_hash: v5.genesis_hash(),
                event_id: &event_id,
                event_sequence: 9,
                predecessor_event_hash: &predecessor,
                v3_trust_binding_digest: &trust,
            })
            .unwrap(),
        );
        assert_eq!(actual, expected);
    }

    #[test]
    fn v5_authority_position_and_basis_have_fixed_literal_canonical_oracles() {
        let run_id = id("run:fixed");
        let event_id = id("event:fixed");
        let genesis_hash = ContentHash::sha256(b"basis genesis");
        let predecessor_hash = ContentHash::sha256(b"position predecessor");
        let trust_hash = ContentHash::sha256(b"position trust");
        let position_literal = b"{\"event_id\":\"event:fixed\",\"event_sequence\":9,\"genesis_hash\":\"sha256:fda9f1c527fa660658760fc64e7431235367012d93245f239462ee648ba36d6b\",\"predecessor_event_hash\":\"sha256:b46fd1b5b17a27f0fcc30044ad453dd742ff450ab50fdc6fd797e2964cbc5190\",\"run_id\":\"run:fixed\",\"schema\":\"reviewgraphen.authority_position.v5\",\"v3_trust_binding_digest\":\"sha256:e4539fde550366c863d499006c27e528b53877091a5d4993a14f53e06a487ab4\"}";
        let actual_position = v5_authority_position_digest(
            &run_id,
            &genesis_hash,
            &event_id,
            9,
            &predecessor_hash,
            &trust_hash,
        )
        .expect("position digest");
        assert_eq!(
            actual_position.to_string(),
            "sha256:a447dcd8f4fb18a346200a2a9a62f5cd1adf51d0e17fb2d71a087ec58d6dd887"
        );
        #[derive(Serialize)]
        struct Position<'a> {
            schema: &'a str,
            run_id: &'a StableId,
            genesis_hash: &'a ContentHash,
            event_id: &'a StableId,
            event_sequence: u64,
            predecessor_event_hash: &'a ContentHash,
            v3_trust_binding_digest: &'a ContentHash,
        }
        assert_eq!(
            canonical_json(&Position {
                schema: "reviewgraphen.authority_position.v5",
                run_id: &run_id,
                genesis_hash: &genesis_hash,
                event_id: &event_id,
                event_sequence: 9,
                predecessor_event_hash: &predecessor_hash,
                v3_trust_binding_digest: &trust_hash,
            })
            .unwrap(),
            position_literal
        );

        let policy_hash = ContentHash::sha256(b"basis policy");
        let tail_hash = ContentHash::sha256(b"basis tail");
        let basis_literal = b"{\"gluing_input_entries\":[],\"inherited_m4_entries\":[],\"policy_revision_hash\":\"sha256:4f75ba05f3489e9b80955975bdf022ba5e6be927b8325eaeb3a1f2e03a27362b\",\"schema\":\"reviewgraphen.pre_incremental_authority_replay_basis.v5\",\"target_confirmed_event_count\":8,\"target_confirmed_tail_hash\":\"sha256:988ac03fea1d175c34e50a347c87b09c8f699c5831dd84132d68b47e5b1cfaff\",\"target_genesis_hash\":\"sha256:fda9f1c527fa660658760fc64e7431235367012d93245f239462ee648ba36d6b\",\"target_next_sequence\":9,\"target_run_id\":\"run:fixed\"}";
        #[derive(Serialize)]
        struct Basis<'a> {
            schema: &'a str,
            target_run_id: &'a StableId,
            target_genesis_hash: &'a ContentHash,
            target_confirmed_tail_hash: &'a ContentHash,
            target_confirmed_event_count: u64,
            target_next_sequence: u64,
            policy_revision_hash: &'a ContentHash,
            inherited_m4_entries: &'a [AuthorityReplayEntryV3AtV5],
            gluing_input_entries: &'a [GluingInputReplayEntryV5],
        }
        let empty_inherited = Vec::new();
        let empty_gluing = Vec::new();
        let canonical_basis = canonical_json(&Basis {
            schema: "reviewgraphen.pre_incremental_authority_replay_basis.v5",
            target_run_id: &run_id,
            target_genesis_hash: &genesis_hash,
            target_confirmed_tail_hash: &tail_hash,
            target_confirmed_event_count: 8,
            target_next_sequence: 9,
            policy_revision_hash: &policy_hash,
            inherited_m4_entries: &empty_inherited,
            gluing_input_entries: &empty_gluing,
        })
        .unwrap();
        assert_eq!(canonical_basis, basis_literal);
        assert_eq!(
            ContentHash::sha256(&canonical_basis).to_string(),
            "sha256:34c774a7b2d018bac973010d1c0d0f36d97787731f9a10ead86ae666f390ad6b"
        );

        let position_digest = |run: &StableId,
                               genesis: &ContentHash,
                               event: &StableId,
                               sequence: u64,
                               predecessor: &ContentHash,
                               trust: &ContentHash| {
            ContentHash::sha256(
                &canonical_json(&Position {
                    schema: "reviewgraphen.authority_position.v5",
                    run_id: run,
                    genesis_hash: genesis,
                    event_id: event,
                    event_sequence: sequence,
                    predecessor_event_hash: predecessor,
                    v3_trust_binding_digest: trust,
                })
                .unwrap(),
            )
        };
        let fixed_position = position_digest(
            &run_id,
            &genesis_hash,
            &event_id,
            9,
            &predecessor_hash,
            &trust_hash,
        );
        for changed in [
            position_digest(
                &id("run:other"),
                &genesis_hash,
                &event_id,
                9,
                &predecessor_hash,
                &trust_hash,
            ),
            position_digest(
                &run_id,
                &ContentHash::sha256(b"other genesis"),
                &event_id,
                9,
                &predecessor_hash,
                &trust_hash,
            ),
            position_digest(
                &run_id,
                &genesis_hash,
                &id("event:other"),
                9,
                &predecessor_hash,
                &trust_hash,
            ),
            position_digest(
                &run_id,
                &genesis_hash,
                &event_id,
                10,
                &predecessor_hash,
                &trust_hash,
            ),
            position_digest(
                &run_id,
                &genesis_hash,
                &event_id,
                9,
                &ContentHash::sha256(b"other predecessor"),
                &trust_hash,
            ),
            position_digest(
                &run_id,
                &genesis_hash,
                &event_id,
                9,
                &predecessor_hash,
                &ContentHash::sha256(b"other trust"),
            ),
        ] {
            assert_ne!(fixed_position, changed);
        }
        let inherited_dummy = vec![AuthorityReplayEntryV3AtV5 {
            event_sequence: 1,
            event_id: id("event:inherited"),
            payload_kind: "evidence_recorded".to_owned(),
            record_id: id("evidence:inherited"),
            record_body_hash: ContentHash::sha256(b"record body"),
            predecessor_event_hash: ContentHash::sha256(b"record predecessor"),
            v3_trust_binding_digest: ContentHash::sha256(b"record trust"),
            v5_position_digest: ContentHash::sha256(b"record position"),
        }];
        let gluing_dummy = vec![GluingInputReplayEntryV5 {
            event_sequence: 2,
            event_id: id("event:gluing"),
            registration_id: id("registration:gluing"),
            registration_body_hash: ContentHash::sha256(b"gluing body"),
            predecessor_event_hash: ContentHash::sha256(b"gluing predecessor"),
            trust_binding_digest: ContentHash::sha256(b"gluing trust"),
            v5_position_digest: ContentHash::sha256(b"gluing position"),
        }];
        let basis_digest = |run: &StableId,
                            genesis: &ContentHash,
                            tail: &ContentHash,
                            count: u64,
                            next: u64,
                            policy: &ContentHash,
                            inherited: &[AuthorityReplayEntryV3AtV5],
                            gluing: &[GluingInputReplayEntryV5]| {
            ContentHash::sha256(
                &canonical_json(&Basis {
                    schema: "reviewgraphen.pre_incremental_authority_replay_basis.v5",
                    target_run_id: run,
                    target_genesis_hash: genesis,
                    target_confirmed_tail_hash: tail,
                    target_confirmed_event_count: count,
                    target_next_sequence: next,
                    policy_revision_hash: policy,
                    inherited_m4_entries: inherited,
                    gluing_input_entries: gluing,
                })
                .unwrap(),
            )
        };
        let fixed_basis = basis_digest(
            &run_id,
            &genesis_hash,
            &tail_hash,
            8,
            9,
            &policy_hash,
            &empty_inherited,
            &empty_gluing,
        );
        for changed in [
            basis_digest(
                &id("run:other"),
                &genesis_hash,
                &tail_hash,
                8,
                9,
                &policy_hash,
                &empty_inherited,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &ContentHash::sha256(b"other genesis"),
                &tail_hash,
                8,
                9,
                &policy_hash,
                &empty_inherited,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &genesis_hash,
                &ContentHash::sha256(b"other tail"),
                8,
                9,
                &policy_hash,
                &empty_inherited,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &genesis_hash,
                &tail_hash,
                7,
                9,
                &policy_hash,
                &empty_inherited,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &genesis_hash,
                &tail_hash,
                8,
                10,
                &policy_hash,
                &empty_inherited,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &genesis_hash,
                &tail_hash,
                8,
                9,
                &ContentHash::sha256(b"other policy"),
                &empty_inherited,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &genesis_hash,
                &tail_hash,
                8,
                9,
                &policy_hash,
                &inherited_dummy,
                &empty_gluing,
            ),
            basis_digest(
                &run_id,
                &genesis_hash,
                &tail_hash,
                8,
                9,
                &policy_hash,
                &empty_inherited,
                &gluing_dummy,
            ),
        ] {
            assert_ne!(fixed_basis, changed);
        }
    }

    #[test]
    fn v5_structural_prefix_is_tail_bound_and_excludes_later_envelopes() {
        let mut complete = complete_planned_v5();
        let predecessor_count = u64::try_from(complete.envelopes.len()).unwrap();
        let predecessor_offset = complete.canonical_prefix_bytes_for_store();
        let predecessor_tail = complete.tail_hash().clone();
        let obligation_id = complete
            .replay_pre_incremental_state_for_store()
            .expect("planned target")
            .projection()
            .universe()
            .obligation_ids()
            .iter()
            .next()
            .expect("fixture obligation")
            .clone();
        let sequence = u64::try_from(complete.envelopes.len()).unwrap() + 1;
        let transition = EventEnvelope::new(
            EventContractVersion::V5,
            complete.run_id.clone(),
            complete.genesis_hash.clone(),
            sequence,
            SYSTEM_ACTOR,
            sequence,
            complete.tail_hash().clone(),
            PersistedPayload::ObligationTransition {
                obligation_id,
                next: ObligationLifecycle::Planned,
            },
        )
        .unwrap();
        complete.append_sealed_envelope_v5(transition).unwrap();

        let state = complete
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                complete.run_id(),
                complete.genesis_hash(),
                predecessor_offset,
                predecessor_count,
                &predecessor_tail,
            ))
            .expect("structural target predecessor");
        let projection = state.projection();
        assert_eq!(projection.tail_hash(), &predecessor_tail);
        assert_eq!(projection.predecessor_offset(), predecessor_offset);
        assert_eq!(projection.predecessor_event_count(), predecessor_count);
        assert_eq!(
            projection.accounting().canonical_prefix_bytes,
            predecessor_offset
        );
        assert_eq!(projection.accounting().event_count, predecessor_count);
        assert!(projection.accounting().retained_envelope_bytes > 0);
        assert!(complete.replay_pre_incremental_state_for_store().is_err());
    }

    #[test]
    fn v5_structural_prefix_refuses_count_or_tail_mismatch() {
        let complete = complete_planned_v5();
        let count = u64::try_from(complete.envelopes.len()).unwrap();
        let offset = complete.canonical_prefix_bytes_for_store();
        let tail = complete.tail_hash().clone();
        assert!(
            complete
                .replay_pre_incremental_structural_prefix_for_store(
                    V5StructuralPrefixCoordinates::new(
                        complete.run_id(),
                        complete.genesis_hash(),
                        offset,
                        count - 1,
                        &tail,
                    ),
                )
                .is_err()
        );
        assert!(
            complete
                .replay_pre_incremental_structural_prefix_for_store(
                    V5StructuralPrefixCoordinates::new(
                        complete.run_id(),
                        complete.genesis_hash(),
                        offset - 1,
                        count,
                        &tail,
                    ),
                )
                .is_err()
        );
    }

    #[test]
    fn v5_structural_prefix_accepts_closed_inherited_m4_and_v4_positions() {
        let (policy_probe, _, _, _, _, _) = static_boundary_base();
        let v5_policy = target_policy_revision_hash_v5(policy_probe.aggregate.program())
            .expect("derived native V5 policy");
        let (v4, basis, roots, mut resolver, session, claim_id, input_id, output_id) =
            static_v4_bundle_base_with_policy(v5_policy.clone());
        let bundle = v4
            .mint_verification_bundle_v4(
                VerificationBundleRequestV4::static_fact(claim_id, input_id, output_id),
                None,
                &resolver,
                &roots,
                &basis,
            )
            .expect("complete inherited M4 bundle");
        let m4_envelopes = bundle
            .envelopes(&v4, &basis, &session)
            .expect("inherited M4 envelopes")
            .to_vec();
        assert!(matches!(m4_envelopes.len(), 2 | 3));

        let mut v5 = rewrap_v4_prefix_as_v5(&v4);
        let base_structural = v5
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                v5.run_id(),
                v5.genesis_hash(),
                v5.canonical_prefix_bytes_for_store(),
                u64::try_from(v5.envelopes.len()).expect("base V5 event count"),
                v5.tail_hash(),
            ))
            .expect("base V5 structural prefix");
        let first_deferred_count = base_structural
            .plan_event_count
            .checked_add(base_structural.d2_accounting.d2_prefix_events)
            .and_then(|value| value.checked_add(1))
            .expect("first inherited semantic count");
        let first_deferred_index = usize::try_from(first_deferred_count - 1).unwrap();
        let first_deferred_envelope = &v5.envelopes[first_deferred_index];
        let first_deferred_offset = v5.envelopes[..=first_deferred_index]
            .iter()
            .try_fold(0_u64, |total, envelope| {
                total.checked_add(
                    u64::try_from(
                        envelope
                            .canonical_bytes()
                            .expect("canonical V5 event")
                            .len()
                            + 1,
                    )
                    .unwrap(),
                )
            })
            .expect("first inherited semantic offset");
        let first_deferred = v5
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                v5.run_id(),
                v5.genesis_hash(),
                first_deferred_offset,
                first_deferred_count,
                first_deferred_envelope.event_hash(),
            ))
            .expect("first inherited semantic structural prefix");
        let PersistedPayload::ArtifactRegisteredV3(first_registration) = decode_canonical_payload(
            EventContractVersion::V5,
            first_deferred_envelope.payload.get(),
        )
        .expect("first inherited semantic payload") else {
            panic!("fixture first inherited semantic record must be a V3 registration");
        };
        assert_eq!(first_deferred.d2_accounting.deferred_semantic_events, 1);
        assert_eq!(
            first_deferred.d2_accounting.max_m4_cas_bytes,
            first_registration.size(),
            "the first non-D2 registration is accounted before the prefix stops"
        );
        let plan = v4.aggregate.review_plans().next().expect("V4 plan");
        let plan_id = plan.id().clone();
        let (later_d2_obligation, later_context, later_sources) = plan
            .waves()
            .iter()
            .flat_map(|wave| wave.obligation_ids())
            .filter(|candidate| {
                v4.aggregate
                    .obligation(candidate)
                    .is_some_and(|obligation| {
                        obligation
                            .lifecycle()
                            .can_transition_to(ObligationLifecycle::Planned)
                            || obligation
                                .lifecycle()
                                .can_transition_to(ObligationLifecycle::InProgress)
                    })
            })
            .find_map(|candidate| {
                let mut session = crate::prepare_context(&v4.aggregate, candidate.clone()).ok()?;
                let mut sources = BTreeMap::new();
                while let Some(request) = session.next_source_request().ok()? {
                    let hash = v4
                        .aggregate
                        .program()
                        .artifact(request.artifact_id())?
                        .content_hash
                        .as_ref()?;
                    let bytes = resolver.objects.get(hash)?.clone();
                    session.submit_source(&request, &bytes).ok()?;
                    sources.insert(request.artifact_id().clone(), bytes);
                }
                let built = session.finish().ok()?;
                (!built.envelope().normalized_included_source_ids().is_empty())
                    .then(|| (candidate.clone(), built, sources))
            })
            .expect("source-grounded later D2 obligation");
        let current_lifecycle = v4
            .aggregate
            .obligation(&later_d2_obligation)
            .expect("later D2 obligation")
            .lifecycle();
        let later_context_envelope = later_context.envelope().clone();
        let context_command = EventCommand::context_envelope_projected(later_context);
        let later_wave = plan
            .waves()
            .iter()
            .find(|wave| wave.obligation_ids().contains(&later_d2_obligation))
            .expect("later D2 wave");
        let execution_input = crate::ExecutionRecordInput::fake(
            plan_id.clone(),
            later_wave.id().clone(),
            later_d2_obligation.clone(),
            later_context_envelope.id().clone(),
            later_context_envelope.snapshot_id().clone(),
            1,
        )
        .expect("later D2 execution input");
        let later_execution_id = execution_input.execution_id().expect("later execution ID");
        let later_raw = format!(
            "{{\"attempt\":1,\"fixture\":true,\"padding\":\"{}\",\"version\":3}}",
            "x".repeat(200_000)
        )
        .into_bytes();
        let later_registration = ArtifactRegisteredV3::new(
            v4.run_id().clone(),
            ContentHash::sha256(&later_raw),
            "application/json",
            u64::try_from(later_raw.len()).unwrap(),
            ArtifactSensitivity::Sensitive,
            ArtifactSourceV3::ReviewerExecution {
                execution_id: later_execution_id.clone(),
                reviewer_id: crate::execution::FAKE_REVIEWER_ID.to_owned(),
                run_id: v4.run_id().clone(),
            },
        )
        .expect("later D2 reviewer registration");
        resolver
            .objects
            .insert(ContentHash::sha256(&later_raw), later_raw.clone());
        append_v5_payload_for_structural_test(
            &mut v5,
            PersistedPayload::ArtifactRegisteredV3(later_registration.clone()),
        );
        for envelope in &m4_envelopes {
            append_v5_payload_for_structural_test(
                &mut v5,
                decode_canonical_payload(EventContractVersion::V4, envelope.payload.get())
                    .expect("M4 payload"),
            );
        }
        if current_lifecycle == ObligationLifecycle::Generated {
            append_v5_payload_for_structural_test(
                &mut v5,
                PersistedPayload::ObligationTransition {
                    obligation_id: later_d2_obligation.clone(),
                    next: ObligationLifecycle::Planned,
                },
            );
        }
        append_v5_payload_for_structural_test(
            &mut v5,
            PersistedPayload::ObligationTransition {
                obligation_id: later_d2_obligation.clone(),
                next: ObligationLifecycle::InProgress,
            },
        );
        append_v5_payload_for_structural_test(&mut v5, context_command.payload);
        let later_obligation = v4
            .aggregate
            .obligation(&later_d2_obligation)
            .expect("later obligation body");
        let later_claim = crate::ExecutionClaimInputV2::new(
            later_obligation.property_id(),
            later_obligation.normalized_target_refs().clone(),
            ClaimPolarity::IssueAbsent,
            "late V5 D2 structured claim",
            later_context_envelope
                .normalized_included_source_ids()
                .clone(),
            BTreeSet::new(),
            BTreeSet::new(),
            Some(1.0),
        )
        .expect("later claim input");
        let source_buffers = later_sources.values().collect::<Vec<_>>();
        let later_bundle = ValidatedExecutionBundle::fake_v3(
            execution_input,
            &later_registration,
            later_raw.clone(),
            source_buffers,
            vec![later_claim],
            crate::ExecutionOutcome::Structured,
        )
        .expect("later D2 bundle");
        let execution_command = EventCommand::review_execution_recorded(later_bundle);
        append_v5_payload_for_structural_test(&mut v5, execution_command.payload);
        append_v5_payload_for_structural_test(
            &mut v5,
            PersistedPayload::ObligationTransition {
                obligation_id: later_d2_obligation.clone(),
                next: ObligationLifecycle::Completed,
            },
        );
        let (payment, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_PAYMENT_CONTEXT_ID,
            crate::AssignmentValueV4::Required,
            BTreeSet::new(),
        );
        let (ui, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_UI_CONTEXT_ID,
            crate::AssignmentValueV4::Satisfied,
            BTreeSet::new(),
        );
        append_v5_payload_for_structural_test(
            &mut v5,
            PersistedPayload::ArtifactRegisteredV4(payment),
        );
        append_v5_payload_for_structural_test(&mut v5, PersistedPayload::ArtifactRegisteredV4(ui));

        let structural = v5
            .replay_pre_incremental_structural_prefix_for_store(V5StructuralPrefixCoordinates::new(
                v5.run_id(),
                v5.genesis_hash(),
                v5.canonical_prefix_bytes_for_store(),
                u64::try_from(v5.envelopes.len()).expect("V5 event count"),
                v5.tail_hash(),
            ))
            .expect("closed plan/M4/V4 structural prefix");
        assert_eq!(
            structural.d2_accounting.m4_authority_entries,
            u64::try_from(m4_envelopes.len()).unwrap(),
            "the first inherited Evidence record is included in M4 accounting"
        );
        assert_eq!(
            structural.d2_accounting.max_reviewer_cas_bytes, 40,
            "the contiguous D2 reviewer raw remains visible to M4 accounting"
        );
        assert_eq!(
            structural.d2_accounting.max_m4_cas_bytes,
            u64::try_from(later_raw.len()).unwrap(),
            "the large post-M4 reviewer raw controls the integrated CAS phase"
        );
        // The opaque backing still does not expose these inherited records as
        // accepted state; Core-only M6 projections expose only the plan facts.
        assert_eq!(structural.projection().plan().id(), &plan_id);

        struct NativeV5Resolver(BTreeMap<ContentHash, Vec<u8>>);
        impl AuthorityArtifactResolverV5 for NativeV5Resolver {
            fn read_exact(&self, cas_hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                let bytes = self.0.get(cas_hash).ok_or_else(|| {
                    DomainError::Validation("missing native V5 test CAS object".to_owned())
                })?;
                if bytes.len() != destination.len() {
                    return Err(DomainError::Validation(
                        "native V5 test CAS object length mismatch".to_owned(),
                    ));
                }
                destination.copy_from_slice(bytes);
                Ok(())
            }
        }
        let AuthorityTrustRootsV4 {
            policy_revision_hash,
            repository_id,
            repository_source_hash,
            harnesses,
            human_grants,
            allowed_gluing_input_bindings: _,
        } = roots;
        assert_eq!(policy_revision_hash, v5_policy);
        let v5_roots = AuthorityTrustRootsV5::new(
            v5_policy,
            repository_id,
            repository_source_hash,
            harnesses,
            human_grants,
            Vec::new(),
        )
        .expect("native V5 authority roots");
        let v5_resolver = NativeV5Resolver(resolver.objects);
        let checkpoint = EventLogV5::certify_plan_authority_checkpoint_v5_with_limits(
            &structural,
            &v5_resolver,
            &v5_roots,
            v5.limits.max_retained_bytes,
            v5.limits.max_working_bytes,
        )
        .expect("native V5 plan checkpoint");
        let d2 = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &v5_resolver,
            &v5_roots,
        )
        .expect("native V5 D2 prefix");
        let continuation =
            EventLogV5::replay_ordered_m4_authority_prefix_v5(d2, &v5_resolver, &v5_roots)
                .expect("native V5 ordered M4 replay");
        let exact_m4_working = V5_TEST_M4_EXACT_WORKING.with(std::cell::Cell::get);
        assert!(exact_m4_working > 0);
        let d2_for_exact_working = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &v5_resolver,
            &v5_roots,
        )
        .expect("native V5 D2 prefix for exact M4 working limit");
        EventLogV5::replay_ordered_m4_authority_prefix_v5_with_limits(
            d2_for_exact_working,
            &v5_resolver,
            &v5_roots,
            v5.limits.max_retained_bytes,
            exact_m4_working,
        )
        .expect("native V5 ordered M4 replay at exact working limit");
        assert_eq!(continuation.inherited_m4_entries.len(), m4_envelopes.len());
        assert_eq!(continuation.v3_aggregate.evidence.len(), 1);
        assert_eq!(continuation.v3_aggregate.verifications.len(), 1);
        assert_eq!(
            continuation
                .aggregate
                .obligation(&later_d2_obligation)
                .expect("later D2 obligation")
                .lifecycle(),
            ObligationLifecycle::Completed
        );
        assert!(
            continuation
                .d2_trace
                .iter()
                .any(|trace| trace.record_id == later_d2_obligation)
        );
        assert!(
            continuation
                .aggregate
                .context_envelope(later_context_envelope.id())
                .is_some()
        );
        assert!(
            continuation
                .aggregate
                .executions()
                .any(|execution| execution.id() == &later_execution_id)
        );
        assert!(
            continuation
                .v3_aggregate
                .registrations
                .contains_key(later_registration.registration_id())
        );
        assert!(
            continuation
                .deferred_registration_closures
                .iter()
                .any(|(_, id)| id == later_registration.registration_id())
        );
        assert!(
            continuation
                .d2_trace
                .windows(2)
                .all(|pair| { pair[0].event_sequence < pair[1].event_sequence })
        );
        assert!(matches!(
            decode_canonical_payload(
                EventContractVersion::V5,
                v5.envelopes[usize::try_from(continuation.consumed_through_event).unwrap()]
                    .payload
                    .get(),
            ),
            Ok(PersistedPayload::ArtifactRegisteredV4(_))
        ));
        validate_v5_m5_continuation(&continuation, &v5_roots).expect("native V5 M5 handoff");
        struct TamperedLateRawResolver<'a> {
            delegate: &'a NativeV5Resolver,
            target: ContentHash,
        }
        impl AuthorityArtifactResolverV5 for TamperedLateRawResolver<'_> {
            fn read_exact(&self, cas_hash: &ContentHash, destination: &mut [u8]) -> Result<()> {
                if cas_hash == &self.target {
                    destination.fill(b'x');
                    return Ok(());
                }
                self.delegate.read_exact(cas_hash, destination)
            }
        }
        let structural_tail_before_failure = structural.tail_hash.clone();
        let d2_for_tampered_raw = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &v5_resolver,
            &v5_roots,
        )
        .expect("native V5 D2 prefix for late raw failure");
        assert!(
            EventLogV5::replay_ordered_m4_authority_prefix_v5(
                d2_for_tampered_raw,
                &TamperedLateRawResolver {
                    delegate: &v5_resolver,
                    target: later_registration.cas_hash().clone(),
                },
                &v5_roots,
            )
            .is_err()
        );
        assert_eq!(structural.tail_hash, structural_tail_before_failure);
        let d2_for_short_working = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &v5_resolver,
            &v5_roots,
        )
        .expect("native V5 D2 prefix for M4 working refusal");
        V5_TEST_M4_AUTHORITY_MATERIALIZATIONS.with(|value| value.set(0));
        V5_TEST_M4_CAS_READS.with(|value| value.set(0));
        assert!(matches!(
            EventLogV5::replay_ordered_m4_authority_prefix_v5_with_limits(
                d2_for_short_working,
                &v5_resolver,
                &v5_roots,
                v5.limits.max_retained_bytes,
                exact_m4_working - 1,
            ),
            Err(DomainError::Incomplete {
                operation: "V5 M4 sealed actual working reservation",
                ..
            })
        ));
        assert_eq!(
            V5_TEST_M4_AUTHORITY_MATERIALIZATIONS.with(std::cell::Cell::get),
            0
        );
        assert_eq!(V5_TEST_M4_CAS_READS.with(std::cell::Cell::get), 0);
        let d2_for_context_limit = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &v5_resolver,
            &v5_roots,
        )
        .expect("native V5 D2 prefix for late context limit");
        V5_TEST_M4_CONTEXT_SESSION_SEALS.with(|value| value.set(0));
        V5_TEST_M4_CONTEXT_SOURCE_REQUESTS.with(|value| value.set(0));
        V5_TEST_M4_FORCED_CONTEXT_WORKING_OVERHEAD.with(|value| value.set(u64::MAX));
        let context_limit_result = EventLogV5::replay_ordered_m4_authority_prefix_v5(
            d2_for_context_limit,
            &v5_resolver,
            &v5_roots,
        );
        V5_TEST_M4_FORCED_CONTEXT_WORKING_OVERHEAD.with(|value| value.set(0));
        assert!(matches!(
            context_limit_result,
            Err(DomainError::Incomplete {
                operation: "V5 M4 sealed later D2 context working phase",
                ..
            })
        ));
        assert_eq!(
            V5_TEST_M4_CONTEXT_SESSION_SEALS.with(std::cell::Cell::get),
            1
        );
        assert_eq!(
            V5_TEST_M4_CONTEXT_SOURCE_REQUESTS.with(std::cell::Cell::get),
            0
        );
        assert_eq!(structural.tail_hash, structural_tail_before_failure);
        let exact_retained = V5_TEST_M4_EXACT_RETAINED.with(std::cell::Cell::get);
        assert!(exact_retained > 0);
        let d2_for_short_limit = EventLogV5::replay_certified_d2_authority_prefix_v5(
            &checkpoint,
            &v5_resolver,
            &v5_roots,
        )
        .expect("native V5 D2 prefix for exact retained refusal");
        V5_TEST_M4_AUTHORITY_MATERIALIZATIONS.with(|value| value.set(0));
        V5_TEST_M4_CAS_READS.with(|value| value.set(0));
        assert!(matches!(
            EventLogV5::replay_ordered_m4_authority_prefix_v5_with_limits(
                d2_for_short_limit,
                &v5_resolver,
                &v5_roots,
                exact_retained - 1,
                v5.limits.max_working_bytes,
            ),
            Err(DomainError::Incomplete {
                operation: "V5 M4 exact provisional retained preflight",
                ..
            })
        ));
        assert_eq!(
            V5_TEST_M4_AUTHORITY_MATERIALIZATIONS.with(std::cell::Cell::get),
            0
        );
        assert_eq!(V5_TEST_M4_CAS_READS.with(std::cell::Cell::get), 0);

        // M5's atomic body is intentionally not semantically parsed by this
        // structural FSM. The direct state-machine case proves only the
        // allowed 2-registration -> one-bundle position; envelope admission
        // separately preflights the frozen raw M5 DTO.
        let mut phase = V5StructuralPostPlanPhase::Inherited {
            m4_bundle: V5StructuralM4BundlePhase::Idle,
        };
        let mut registration_ids = BTreeSet::new();
        let first = decode_canonical_payload(
            EventContractVersion::V5,
            v5.envelopes[v5.envelopes.len() - 2].payload.get(),
        )
        .expect("first V4 registration");
        let second = decode_canonical_payload(
            EventContractVersion::V5,
            v5.envelopes[v5.envelopes.len() - 1].payload.get(),
        )
        .expect("second V4 registration");
        advance_v5_structural_post_plan(&mut phase, &mut registration_ids, &first)
            .expect("first registration position");
        advance_v5_structural_post_plan(&mut phase, &mut registration_ids, &second)
            .expect("second registration position");
        let raw_bundle = PersistedPayload::GluingBundleRecordedV4(
            raw_payload(br#"{}"#.to_vec()).expect("syntactic raw M5 body"),
        );
        advance_v5_structural_post_plan(&mut phase, &mut registration_ids, &raw_bundle)
            .expect("one M5 bundle position");
        assert_eq!(phase, V5StructuralPostPlanPhase::M5BundleRecorded);
    }

    #[test]
    fn v5_post_d2_structural_suffix_rejects_early_and_intermediate_payloads() {
        let scope = StableId::parse("gluing-rerun-scope-v5:structural-suffix").expect("scope ID");
        let action = crate::GluingRerunActionV5::derive(
            scope,
            crate::GluingRerunSubjectKindV5::GluingContext,
            StableId::parse(crate::DOUBLE_SUBMIT_PAYMENT_CONTEXT_ID).expect("payment context"),
            crate::GluingRerunActionKindV5::RegisterGluingInput,
            Vec::new(),
        )
        .expect("minimal gluing action");
        let payload = PersistedPayload::GluingRerunActionRecordedV5(action);

        let mut phase = initial_v5_structural_post_d2_phase();
        assert!(advance_v5_structural_post_d2(&mut phase, &payload).is_err());

        phase = V5StructuralPostD2Phase::AfterPartialSeal {
            inherited: V5StructuralPostPlanPhase::Inherited {
                m4_bundle: V5StructuralM4BundlePhase::Idle,
            },
            v4_registration_ids: BTreeSet::new(),
        };
        advance_v5_structural_post_d2(&mut phase, &payload)
            .expect("first gluing action follows the partial seal");
        assert!(matches!(
            phase,
            V5StructuralPostD2Phase::GluingActions { .. }
        ));
        assert!(
            advance_v5_structural_post_d2(
                &mut phase,
                &PersistedPayload::ObligationTransition {
                    obligation_id: StableId::parse("obligation:unrelated").expect("obligation ID"),
                    next: ObligationLifecycle::Completed,
                },
            )
            .is_err()
        );

        phase = V5StructuralPostD2Phase::AfterPartialSeal {
            inherited: V5StructuralPostPlanPhase::Inherited {
                m4_bundle: V5StructuralM4BundlePhase::Idle,
            },
            v4_registration_ids: BTreeSet::new(),
        };
        assert!(
            advance_v5_structural_post_d2(
                &mut phase,
                &PersistedPayload::GluingBundleRecordedV4(
                    raw_payload(br#"{}"#.to_vec()).expect("syntactic inherited M5 raw body"),
                ),
            )
            .is_err()
        );
    }

    #[test]
    fn v5_post_d2_terminal_suffix_accepts_required_and_no_gluing_routes() {
        let (v4, basis, roots, resolver, session, claim_id, input_id, output_id) =
            static_v4_bundle_base();
        let plan_id = v4
            .aggregate
            .review_plans()
            .next()
            .expect("plan")
            .id()
            .clone();
        let (payment, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_PAYMENT_CONTEXT_ID,
            crate::AssignmentValueV4::Required,
            BTreeSet::new(),
        );
        let (ui, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_UI_CONTEXT_ID,
            crate::AssignmentValueV4::Satisfied,
            BTreeSet::new(),
        );
        let bundle = PersistedPayload::GluingBundleRecordedV4(
            raw_payload(br#"{}"#.to_vec()).expect("syntactic raw M5 body"),
        );
        let native_bundle = v4
            .mint_verification_bundle_v4(
                VerificationBundleRequestV4::static_fact(claim_id, input_id, output_id),
                None,
                &resolver,
                &roots,
                &basis,
            )
            .expect("native M4 bundle");
        let native = native_bundle
            .envelopes(&v4, &basis, &session)
            .expect("native M4 envelopes");
        let native_payloads = native
            .iter()
            .map(|envelope| {
                decode_canonical_payload(EventContractVersion::V4, envelope.payload.get())
            })
            .collect::<Result<Vec<_>>>()
            .expect("native M4 payloads");
        let registration = v4
            .envelopes
            .iter()
            .find_map(|envelope| {
                match decode_canonical_payload(EventContractVersion::V4, envelope.payload.get())
                    .expect("V4 payload")
                {
                    PersistedPayload::ArtifactRegisteredV3(registration) => Some(registration),
                    _ => None,
                }
            })
            .expect("native V3 registration");
        for _no_gluing_required in [false, true] {
            let mut phase = V5StructuralPostD2Phase::AfterPartialSeal {
                inherited: V5StructuralPostPlanPhase::Inherited {
                    m4_bundle: V5StructuralM4BundlePhase::Idle,
                },
                v4_registration_ids: BTreeSet::new(),
            };
            // The same terminal vocabulary is deliberately structural-only:
            // roots-bound partial state decides whether the first route had a
            // second seal; raw replay must not infer that authority bit.
            advance_v5_structural_post_d2(
                &mut phase,
                &PersistedPayload::ArtifactRegisteredV3(registration.clone()),
            )
            .expect("terminal native V3 registration");
            for payload in &native_payloads {
                advance_v5_structural_post_d2(&mut phase, payload).expect("terminal native E/B/V");
            }
            advance_v5_structural_post_d2(
                &mut phase,
                &PersistedPayload::ArtifactRegisteredV4(payment.clone()),
            )
            .expect("first terminal V4 registration");
            advance_v5_structural_post_d2(
                &mut phase,
                &PersistedPayload::ArtifactRegisteredV4(ui.clone()),
            )
            .expect("second terminal V4 registration");
            advance_v5_structural_post_d2(&mut phase, &bundle).expect("one terminal M5 bundle");
            assert!(
                advance_v5_structural_post_d2(
                    &mut phase,
                    &PersistedPayload::ArtifactRegisteredV4(payment.clone()),
                )
                .is_err()
            );
        }

        // A predecessor's trusted V4 inputs are not contiguous members of
        // the new post-D2 suffix.  Both one- and two-input predecessor
        // shapes must therefore restart native M4 at Idle, preserve the
        // registration union for the eventual M5 count, and reject duplicate
        // or third registrations by that union rather than suffix count.
        for (predecessor, fresh) in [
            (vec![payment.clone()], Some(ui.clone())),
            (vec![payment.clone(), ui.clone()], None),
        ] {
            let mut inherited =
                post_d2_terminal_suffix_initial_phase(V5StructuralPostPlanPhase::V4Registrations {
                    count: u8::try_from(predecessor.len()).unwrap(),
                });
            let mut ids = predecessor
                .iter()
                .map(|registration| registration.id().clone())
                .collect::<BTreeSet<_>>();
            advance_v5_post_d2_terminal_gate(
                &mut inherited,
                &mut ids,
                &PersistedPayload::ArtifactRegisteredV3(registration.clone()),
            )
            .expect("post-seal native V3 after suppressed inputs");
            for payload in &native_payloads {
                advance_v5_post_d2_terminal_gate(&mut inherited, &mut ids, payload)
                    .expect("post-seal native M4 after suppressed inputs");
            }
            if let Some(fresh) = fresh {
                advance_v5_post_d2_terminal_gate(
                    &mut inherited,
                    &mut ids,
                    &PersistedPayload::ArtifactRegisteredV4(fresh),
                )
                .expect("one remaining post-seal V4 input");
            }
            advance_v5_post_d2_terminal_gate(&mut inherited, &mut ids, &bundle)
                .expect("M5 follows exactly two unioned V4 inputs");
        }
    }

    #[test]
    fn v5_post_d2_structural_prefix_preserves_zero_one_two_v4_inputs() {
        let (v4, _basis, _roots, _resolver, _session, _claim_id, _input_id, _output_id) =
            static_v4_bundle_base();
        let plan_id = v4
            .aggregate
            .review_plans()
            .next()
            .expect("plan")
            .id()
            .clone();
        let (payment, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_PAYMENT_CONTEXT_ID,
            crate::AssignmentValueV4::Required,
            BTreeSet::new(),
        );
        let (ui, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_UI_CONTEXT_ID,
            crate::AssignmentValueV4::Satisfied,
            BTreeSet::new(),
        );
        for prefix in [
            Vec::new(),
            vec![payment.clone()],
            vec![payment.clone(), ui.clone()],
        ] {
            let mut phase = initial_v5_structural_post_d2_phase();
            for registration in &prefix {
                advance_v5_structural_post_d2(
                    &mut phase,
                    &PersistedPayload::ArtifactRegisteredV4(registration.clone()),
                )
                .expect("legal inherited V4 prefix");
            }
            let V5StructuralPostD2Phase::BeforePartialSeal {
                inherited,
                v4_registration_ids,
            } = phase
            else {
                panic!("pre-partial structural phase must retain inherited input state")
            };
            match prefix.len() {
                0 => assert_eq!(
                    inherited,
                    V5StructuralPostPlanPhase::Inherited {
                        m4_bundle: V5StructuralM4BundlePhase::Idle,
                    }
                ),
                1 | 2 => assert_eq!(
                    inherited,
                    V5StructuralPostPlanPhase::V4Registrations {
                        count: u8::try_from(prefix.len()).unwrap(),
                    }
                ),
                _ => unreachable!(),
            }
            assert_eq!(v4_registration_ids.len(), prefix.len());
        }
        let mut duplicate = initial_v5_structural_post_d2_phase();
        advance_v5_structural_post_d2(
            &mut duplicate,
            &PersistedPayload::ArtifactRegisteredV4(payment.clone()),
        )
        .expect("first V4 input");
        assert!(
            advance_v5_structural_post_d2(
                &mut duplicate,
                &PersistedPayload::ArtifactRegisteredV4(payment.clone()),
            )
            .is_err()
        );
        // A fresh two-input prefix exercises the third and bundle-order
        // rejections without fabricating any roots authority.
        let mut ordered = initial_v5_structural_post_d2_phase();
        assert!(
            advance_v5_structural_post_d2(
                &mut ordered,
                &PersistedPayload::GluingBundleRecordedV4(
                    raw_payload(br#"{}"#.to_vec()).expect("raw M5")
                ),
            )
            .is_err()
        );
        advance_v5_structural_post_d2(
            &mut ordered,
            &PersistedPayload::ArtifactRegisteredV4(payment.clone()),
        )
        .expect("first V4 input");
        advance_v5_structural_post_d2(&mut ordered, &PersistedPayload::ArtifactRegisteredV4(ui))
            .expect("second V4 input");
        assert!(
            advance_v5_structural_post_d2(
                &mut ordered,
                &PersistedPayload::ArtifactRegisteredV4(payment),
            )
            .is_err()
        );
    }

    #[test]
    fn v5_structural_post_plan_state_machine_refuses_partial_and_late_members() {
        let (v4, basis, roots, resolver, session, claim_id, input_id, output_id) =
            static_v4_bundle_base();
        let bundle = v4
            .mint_verification_bundle_v4(
                VerificationBundleRequestV4::static_fact(claim_id, input_id, output_id),
                None,
                &resolver,
                &roots,
                &basis,
            )
            .expect("M4 bundle");
        let m4 = bundle
            .envelopes(&v4, &basis, &session)
            .expect("M4 envelopes")
            .to_vec();
        let evidence = decode_canonical_payload(EventContractVersion::V4, m4[0].payload.get())
            .expect("evidence payload");
        let binding = decode_canonical_payload(EventContractVersion::V4, m4[1].payload.get())
            .expect("binding payload");

        let mut partial = rewrap_v4_prefix_as_v5(&v4);
        append_v5_payload_for_structural_test(&mut partial, evidence.clone());
        assert!(
            partial
                .replay_pre_incremental_structural_prefix_for_store(
                    V5StructuralPrefixCoordinates::new(
                        partial.run_id(),
                        partial.genesis_hash(),
                        partial.canonical_prefix_bytes_for_store(),
                        u64::try_from(partial.envelopes.len()).expect("partial count"),
                        partial.tail_hash(),
                    ),
                )
                .is_err()
        );

        let mut phase = V5StructuralPostPlanPhase::Inherited {
            m4_bundle: V5StructuralM4BundlePhase::Idle,
        };
        let mut ids = BTreeSet::new();
        assert!(advance_v5_structural_post_plan(&mut phase, &mut ids, &binding).is_err());

        let plan_id = v4
            .aggregate
            .review_plans()
            .next()
            .expect("plan")
            .id()
            .clone();
        let (registration, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_PAYMENT_CONTEXT_ID,
            crate::AssignmentValueV4::Required,
            BTreeSet::new(),
        );
        let first = PersistedPayload::ArtifactRegisteredV4(registration.clone());
        advance_v5_structural_post_plan(&mut phase, &mut ids, &first)
            .expect("first V4 registration");
        assert!(advance_v5_structural_post_plan(&mut phase, &mut ids, &first).is_err());
        let (second_registration, _, _) = v4_gluing_registration(
            &v4,
            &v4.aggregate,
            &plan_id,
            crate::DOUBLE_SUBMIT_UI_CONTEXT_ID,
            crate::AssignmentValueV4::Satisfied,
            BTreeSet::new(),
        );
        advance_v5_structural_post_plan(
            &mut phase,
            &mut ids,
            &PersistedPayload::ArtifactRegisteredV4(second_registration),
        )
        .expect("second V4 registration");
        assert!(advance_v5_structural_post_plan(&mut phase, &mut ids, &evidence).is_err());
        advance_v5_structural_post_plan(
            &mut phase,
            &mut ids,
            &PersistedPayload::GluingBundleRecordedV4(
                raw_payload(br#"{}"#.to_vec()).expect("syntactic raw M5 body"),
            ),
        )
        .expect("M5 bundle position");
        assert!(advance_v5_structural_post_plan(&mut phase, &mut ids, &first).is_err());
    }

    #[test]
    fn v5_pre_incremental_retained_oracle_charges_registration_spare_capacity() {
        let complete = complete_planned_v5();
        let mut state = complete
            .replay_pre_incremental_state_for_store()
            .expect("complete target replay");
        let before_capacity = state.registrations.capacity();
        let before = state.projection().retained_bytes_for_m6().unwrap();
        state.registrations.reserve(32);
        let after_capacity = state.registrations.capacity();
        let after = state.projection().retained_bytes_for_m6().unwrap();
        assert!(after_capacity > before_capacity);
        assert_eq!(
            after - before,
            (after_capacity - before_capacity) * std::mem::size_of::<ArtifactRegisteredV3>()
        );
    }

    #[test]
    fn v5_structural_prefix_retained_oracle_charges_live_envelope_capacity() {
        let mut complete = complete_planned_v5();
        let before_capacity = complete.envelopes.capacity();
        let before = {
            let state = complete
                .replay_pre_incremental_structural_prefix_for_store(
                    V5StructuralPrefixCoordinates::new(
                        complete.run_id(),
                        complete.genesis_hash(),
                        complete.canonical_prefix_bytes_for_store(),
                        u64::try_from(complete.envelopes.len()).unwrap(),
                        complete.tail_hash(),
                    ),
                )
                .unwrap();
            let observed = state.projection().retained_bytes_for_m6().unwrap();
            let expected = state
                .pre_incremental
                .projection()
                .retained_bytes_for_m6()
                .unwrap()
                + (size_of::<ReplayedV5PreIncrementalStructuralPrefixState>()
                    - size_of::<ReplayedV5PreIncrementalState>())
                + state.genesis_hash.allocated_bytes()
                + state.tail_hash.allocated_bytes()
                + usize::try_from(complete.full_resident_bytes_for_structural_store().unwrap())
                    .unwrap();
            assert_eq!(
                observed, expected,
                "every live and outer allocation is charged once"
            );
            observed
        };
        complete.envelopes.reserve(32);
        let after_capacity = complete.envelopes.capacity();
        let after = {
            let state = complete
                .replay_pre_incremental_structural_prefix_for_store(
                    V5StructuralPrefixCoordinates::new(
                        complete.run_id(),
                        complete.genesis_hash(),
                        complete.canonical_prefix_bytes_for_store(),
                        u64::try_from(complete.envelopes.len()).unwrap(),
                        complete.tail_hash(),
                    ),
                )
                .unwrap();
            state.projection().retained_bytes_for_m6().unwrap()
        };
        assert!(after_capacity > before_capacity);
        assert_eq!(
            after - before,
            (after_capacity - before_capacity) * std::mem::size_of::<EventEnvelope>()
        );
    }

    #[test]
    fn v5_bootstrap_is_homogeneous_and_rejects_v4_upcast() {
        let v5 = EventLogV5::from_bootstrap_request(v4_bootstrap_request()).expect("v5 bootstrap");
        assert_eq!(v5.envelopes().len(), 1);
        assert_eq!(
            v5.envelopes()[0].contract_version().expect("v5 contract"),
            EventContractVersion::V5
        );
        EventEnvelope::validate_v5_stream(
            v5.run_id(),
            v5.canonical_genesis_bytes(),
            v5.envelopes(),
        )
        .expect("v5 genesis validates");

        let v4 = EventLogV4::from_bootstrap_request(v4_bootstrap_request()).expect("v4 bootstrap");
        let error = EventLogV5::replay_confirmed_v5_prefix(
            v4.run_id().clone(),
            v4.canonical_genesis_bytes().to_vec(),
            v4.envelopes().to_vec(),
            v5_replay_limits(16, 1024 * 1024),
        )
        .expect_err("a v4 prefix is not an upcastable v5 prefix");
        assert!(matches!(
            error,
            DomainError::Validation(_) | DomainError::EventSequence(_)
        ));
    }

    #[test]
    fn v5_replay_rechecks_hash_chain_and_sealed_append_prefix() {
        let mut log =
            EventLogV5::from_bootstrap_request(v4_bootstrap_request()).expect("v5 bootstrap");
        let obligation_id = aggregate()
            .obligations()
            .next()
            .expect("fixture obligation")
            .id()
            .clone();
        let appended = EventEnvelope::new(
            EventContractVersion::V5,
            log.run_id().clone(),
            log.genesis_hash().clone(),
            2,
            SYSTEM_ACTOR,
            2,
            log.tail_hash().clone(),
            PersistedPayload::ObligationTransition {
                obligation_id,
                next: ObligationLifecycle::Planned,
            },
        )
        .expect("sealed v5 envelope");
        log.append_sealed_envelope_v5(appended).expect("v5 append");

        let (replayed, accounting) = EventLogV5::replay_confirmed_v5_prefix(
            log.run_id().clone(),
            log.canonical_genesis_bytes().to_vec(),
            log.envelopes().to_vec(),
            v5_replay_limits(16, 1024 * 1024),
        )
        .expect("replay exact v5 prefix");
        assert_eq!(replayed.tail_hash(), log.tail_hash());
        assert_eq!(replayed.envelopes().len(), 2);
        assert_eq!(
            accounting.canonical_prefix_bytes(),
            log.envelopes()
                .iter()
                .map(|event| event.canonical_line_bytes_v5.expect("V5 line bytes"))
                .sum::<u64>()
        );
        let exact_prefix_bytes = accounting.canonical_prefix_bytes();
        EventLogV5::replay_confirmed_v5_prefix(
            log.run_id().clone(),
            log.canonical_genesis_bytes().to_vec(),
            log.envelopes().to_vec(),
            v5_replay_limits(2, exact_prefix_bytes),
        )
        .expect("multi-event LF-inclusive prefix exact limit");
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                log.run_id().clone(),
                log.canonical_genesis_bytes().to_vec(),
                log.envelopes().to_vec(),
                v5_replay_limits(2, exact_prefix_bytes - 1),
            )
            .is_err()
        );

        let mut tampered = log.envelopes().to_vec();
        tampered[1].previous_event_hash = ContentHash::sha256(b"not-the-v5-genesis");
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                log.run_id().clone(),
                log.canonical_genesis_bytes().to_vec(),
                tampered,
                v5_replay_limits(16, 1024 * 1024),
            )
            .is_err()
        );
    }

    #[test]
    fn v5_bootstrap_and_replay_are_deterministic_at_exact_limits() {
        let left =
            EventLogV5::from_bootstrap_request(v4_bootstrap_request()).expect("left v5 bootstrap");
        let right =
            EventLogV5::from_bootstrap_request(v4_bootstrap_request()).expect("right v5 bootstrap");
        assert_eq!(left.run_id(), right.run_id());
        assert_eq!(left.genesis_hash(), right.genesis_hash());
        assert_eq!(left.tail_hash(), right.tail_hash());
        assert_eq!(
            left.envelopes()[0].canonical_bytes().expect("left bytes"),
            right.envelopes()[0].canonical_bytes().expect("right bytes")
        );

        let exact_bytes = left.envelopes()[0]
            .canonical_line_bytes_v5
            .expect("validated V5 line bytes include LF");
        let (_, unlimited_accounting) = EventLogV5::replay_confirmed_v5_prefix(
            left.run_id().clone(),
            left.canonical_genesis_bytes().to_vec(),
            left.envelopes().to_vec(),
            v5_replay_limits(1, exact_bytes),
        )
        .expect("exact replay limits are admitted");
        assert_eq!(unlimited_accounting.canonical_prefix_bytes(), exact_bytes);
        let exact_limits = EventReplayLimitsV5::new(
            1,
            exact_bytes,
            unlimited_accounting.retained_bytes(),
            unlimited_accounting.working_bytes(),
        )
        .expect("exact V5 limits");
        EventLogV5::replay_confirmed_v5_prefix(
            left.run_id().clone(),
            left.canonical_genesis_bytes().to_vec(),
            left.envelopes().to_vec(),
            exact_limits,
        )
        .expect("exact retained and working limits are admitted");
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                left.run_id().clone(),
                left.canonical_genesis_bytes().to_vec(),
                left.envelopes().to_vec(),
                EventReplayLimitsV5::new(
                    0,
                    exact_bytes,
                    unlimited_accounting.retained_bytes(),
                    unlimited_accounting.working_bytes(),
                )
                .expect("event-count V5 limits"),
            )
            .is_err()
        );
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                left.run_id().clone(),
                left.canonical_genesis_bytes().to_vec(),
                left.envelopes().to_vec(),
                EventReplayLimitsV5::new(
                    1,
                    exact_bytes - 1,
                    unlimited_accounting.retained_bytes(),
                    unlimited_accounting.working_bytes(),
                )
                .expect("canonical-byte V5 limits"),
            )
            .is_err()
        );
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                left.run_id().clone(),
                left.canonical_genesis_bytes().to_vec(),
                left.envelopes().to_vec(),
                EventReplayLimitsV5::new(
                    1,
                    exact_bytes,
                    unlimited_accounting.retained_bytes() - 1,
                    unlimited_accounting.working_bytes(),
                )
                .expect("retained-byte V5 limits"),
            )
            .is_err()
        );
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                left.run_id().clone(),
                left.canonical_genesis_bytes().to_vec(),
                left.envelopes().to_vec(),
                EventReplayLimitsV5::new(
                    1,
                    exact_bytes,
                    unlimited_accounting.retained_bytes(),
                    unlimited_accounting.working_bytes() - 1,
                )
                .expect("working-byte V5 limits"),
            )
            .is_err()
        );
    }

    #[test]
    fn v5_replay_refuses_foreign_genesis_run_and_order_and_legacy_constructor() {
        let log = EventLogV5::from_bootstrap_request(v4_bootstrap_request()).expect("v5 bootstrap");
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                id("run:v5-foreign"),
                log.canonical_genesis_bytes().to_vec(),
                log.envelopes().to_vec(),
                v5_replay_limits(16, 1024 * 1024),
            )
            .is_err()
        );

        let mut wrong_genesis = log.canonical_genesis_bytes().to_vec();
        wrong_genesis[0] = b'[';
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                log.run_id().clone(),
                wrong_genesis,
                log.envelopes().to_vec(),
                v5_replay_limits(16, 1024 * 1024),
            )
            .is_err()
        );

        let mut wrong_order = log.envelopes().to_vec();
        wrong_order[0].sequence = 2;
        assert!(
            EventLogV5::replay_confirmed_v5_prefix(
                log.run_id().clone(),
                log.canonical_genesis_bytes().to_vec(),
                wrong_order,
                v5_replay_limits(16, 1024 * 1024),
            )
            .is_err()
        );

        assert!(
            EventLog::new_with_version(EventContractVersion::V5, id("run:v5-legacy"), aggregate())
                .is_err()
        );
    }

    #[test]
    fn v5_ingress_is_structurally_detected_before_serde_and_counts_mandatory_lf() {
        let log = EventLogV5::from_bootstrap_request(v4_bootstrap_request()).expect("v5 bootstrap");
        let body = log.envelopes()[0]
            .canonical_bytes()
            .expect("canonical v5 genesis envelope");
        assert!(top_level_schema_mentions_v5(&body).expect("structural V5 discriminator"));
        let parsed = EventEnvelope::from_json_slice(&body).expect("V5 envelope ingress");
        assert_eq!(
            parsed.canonical_line_bytes_v5,
            Some(u64::try_from(body.len() + 1).expect("V5 line length"))
        );

        let mut exact = body.clone();
        exact.resize(MAX_D1_EVENT_LINE_BYTES - 1, b' ');
        EventEnvelope::from_json_slice(&exact).expect("exact V5 JSONL ingress including LF");
        let mut plus_one = exact;
        plus_one.push(b' ');
        assert!(matches!(
            EventEnvelope::from_json_slice(&plus_one),
            Err(DomainError::Incomplete {
                operation: "event-v5 canonical JSONL",
                limit: MAX_D1_EVENT_LINE_BYTES,
                observed,
            })
            if observed == MAX_D1_EVENT_LINE_BYTES + 1
        ));

        let mut malformed_oversized = br#"{"schema":"reviewgraphen.review_event.v5","x":"#.to_vec();
        malformed_oversized.resize(MAX_D1_EVENT_LINE_BYTES, b'x');
        assert!(matches!(
            EventEnvelope::from_json_slice(&malformed_oversized),
            Err(DomainError::Incomplete {
                operation: "event-v5 canonical JSONL",
                ..
            })
        ));
    }

