    #[test]
    fn fixture_attempt_inspection_tracks_registration_and_completion_stages() {
        let (log, basis, claim_id, resolver) = fixture_stage_base();
        let roots = fixture_stage_roots(&log, claim_id.clone());
        let expected = log
            .expect_fixture_verification_attempt_v3(&claim_id, &roots, &basis)
            .unwrap();
        assert_eq!(
            log.inspect_verification_attempt_v3(&expected, &resolver, &roots, &basis)
                .unwrap(),
            VerificationAttemptStageV3::Ready
        );

        let (log, basis, claim_id, resolver, _receipt, _) = fixture_through_witness_registration();
        let roots = fixture_stage_roots(&log, claim_id.clone());
        let expected = log
            .expect_fixture_verification_attempt_v3(&claim_id, &roots, &basis)
            .unwrap();
        assert_eq!(
            log.inspect_verification_attempt_v3(&expected, &resolver, &roots, &basis)
                .unwrap(),
            VerificationAttemptStageV3::WitnessRegistered
        );

        let (mut log, mut basis, claim_id, resolver, mut receipt, witness_id, output_id) =
            fixture_through_output_registration();
        let roots = fixture_stage_roots(&log, claim_id.clone());
        let expected = log
            .expect_fixture_verification_attempt_v3(&claim_id, &roots, &basis)
            .unwrap();
        assert_eq!(
            log.inspect_verification_attempt_v3(&expected, &resolver, &roots, &basis)
                .unwrap(),
            VerificationAttemptStageV3::OutputRegistered
        );
        let admission = log
            .admit_external_witness_v3(&mut receipt, &witness_id, &resolver, &basis)
            .unwrap();
        let bundle = log
            .mint_fixture_verification_bundle_v3(admission, &output_id, &resolver, &basis)
            .unwrap();
        log.append_verification_bundle_v3(bundle, &mut basis)
            .unwrap();
        let expected = log
            .expect_fixture_verification_attempt_v3(&claim_id, &roots, &basis)
            .unwrap();
        assert_eq!(
            log.inspect_verification_attempt_v3(&expected, &resolver, &roots, &basis)
                .unwrap(),
            VerificationAttemptStageV3::Complete
        );
    }

    #[test]
    fn fixture_registration_resume_preflight_is_exact_and_precedes_token_allocation() {
        let (log, basis, claim_id, resolver, receipt, witness_id) =
            fixture_through_witness_registration();
        let roots = fixture_stage_roots(&log, claim_id.clone());
        let root = roots
            .harness_for_source(
                log.v3_aggregate
                    .as_ref()
                    .unwrap()
                    .registrations
                    .get(&witness_id)
                    .unwrap(),
            )
            .unwrap();
        let exact = log.retained_bytes_v3().unwrap()
            + basis.retained_bytes().unwrap()
            + fixture_scope_allocated_bytes(root).unwrap()
            + receipt.fixture_result_bytes().len() as u64
            + 8_192;
        V3_TEST_FIXTURE_STAGE_KIND.with(|value| value.set(6));
        V3_TEST_FIXTURE_STAGE_ALLOCATION_SEAMS.with(|value| value.set(0));
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact)));
        log.recover_fixture_registration_resume_authority_v3(&claim_id, &resolver, &roots, &basis)
            .unwrap();
        assert_eq!(
            V3_TEST_FIXTURE_STAGE_ALLOCATION_SEAMS.with(|value| value.get()),
            1
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact - 1)));
        V3_TEST_FIXTURE_STAGE_ALLOCATION_SEAMS.with(|value| value.set(0));
        assert!(matches!(
            log.recover_fixture_registration_resume_authority_v3(
                &claim_id, &resolver, &roots, &basis,
            ),
            Err(DomainError::Incomplete { .. })
        ));
        assert_eq!(
            V3_TEST_FIXTURE_STAGE_ALLOCATION_SEAMS.with(|value| value.get()),
            0
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_FIXTURE_STAGE_KIND.with(|value| value.set(0));
    }

    fn verification_bundle_transaction_exact(
        log: &EventLog,
        basis: &AuthorityReplayBasisV3,
        bundle: &ValidatedVerificationBundleV3,
    ) -> u64 {
        let sealed_payload_bytes = u64::try_from(
            bundle
                .payloads
                .len()
                .saturating_mul(size_of::<PersistedPayload>()),
        )
        .unwrap()
            + bundle
                .payloads
                .iter()
                .map(|payload| v3_payload_staging_bytes(payload).unwrap())
                .sum::<u64>();
        let canonical_payload_bytes = bundle
            .payloads
            .iter()
            .map(|payload| u64::try_from(payload_canonical_bytes(payload).unwrap().len()).unwrap())
            .sum::<u64>();
        let trust_digest_bytes = u64::try_from(
            bundle
                .payloads
                .len()
                .saturating_mul(size_of::<ContentHash>() + 71),
        )
        .unwrap();
        let reducer_growth_bytes = bundle
            .payloads
            .iter()
            .map(|payload| v3_reducer_growth_upper_bound(payload).unwrap())
            .sum::<u64>();
        log.retained_bytes_v3()
            .unwrap()
            .checked_mul(2)
            .and_then(|value| {
                basis
                    .retained_bytes()
                    .unwrap()
                    .checked_mul(2)
                    .and_then(|basis_bytes| value.checked_add(basis_bytes))
            })
            .and_then(|value| value.checked_add(sealed_payload_bytes))
            .and_then(|value| value.checked_add(canonical_payload_bytes))
            .and_then(|value| value.checked_add(trust_digest_bytes))
            .and_then(|value| value.checked_add(log.aggregate.retained_bytes_v3().unwrap()))
            .and_then(|value| {
                value.checked_add(log.v3_aggregate.as_ref().unwrap().retained_bytes().unwrap())
            })
            .and_then(|value| value.checked_add(event_vector_retained(&log.events).unwrap()))
            .and_then(|value| value.checked_add(reducer_growth_bytes))
            .unwrap()
    }

    fn assert_selected_replay_append_boundary(
        log: &EventLog,
        genesis: &[u8],
        envelopes: &[EventEnvelope],
        resolver: &AuthorityTestResolver,
        roots: &AuthorityTrustRootsV3,
        selected_kind: u8,
    ) {
        let end = envelopes
            .iter()
            .position(|event| {
                let payload =
                    decode_canonical_payload(EventContractVersion::V3, event.payload.get())
                        .unwrap();
                v3_test_append_kind(&payload) == selected_kind
            })
            .unwrap()
            + 1;
        let prefix = &envelopes[..end];
        V3_TEST_SELECTED_APPEND_KIND.with(|value| value.set(selected_kind));
        V3_TEST_SELECTED_APPEND_PEAK.with(|value| value.set(0));
        EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            genesis,
            prefix,
            resolver,
            roots,
            EventReplayLimits::new(prefix.len() as u64, u64::MAX),
        )
        .unwrap();
        let exact = V3_TEST_SELECTED_APPEND_PEAK.with(|value| value.get());
        assert!(exact > 0);

        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact)));
        V3_TEST_SELECTED_SHADOW_SEAMS.with(|value| value.set(0));
        EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            genesis,
            prefix,
            resolver,
            roots,
            EventReplayLimits::new(prefix.len() as u64, u64::MAX),
        )
        .unwrap();
        assert_eq!(V3_TEST_SELECTED_SHADOW_SEAMS.with(|value| value.get()), 1);

        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact - 1)));
        V3_TEST_SELECTED_SHADOW_SEAMS.with(|value| value.set(0));
        let below = EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            genesis,
            prefix,
            resolver,
            roots,
            EventReplayLimits::new(prefix.len() as u64, u64::MAX),
        );
        assert!(matches!(below, Err(DomainError::Incomplete { .. })));
        assert_eq!(V3_TEST_SELECTED_SHADOW_SEAMS.with(|value| value.get()), 0);
        let decoded = V3_TEST_REPLAY_PAYLOAD_DECODE_COUNT.with(|value| value.get());
        assert!(decoded <= prefix.len() as u64);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_SELECTED_APPEND_KIND.with(|value| value.set(0));
    }

    fn authority_roots_for_claim(
        log: &EventLog,
        claim_id: StableId,
        policy: ContentHash,
    ) -> AuthorityTrustRootsV3 {
        AuthorityTrustRootsV3::new(
            policy.clone(),
            log.aggregate().program().repository_id().clone(),
            log.aggregate()
                .program()
                .repository_source()
                .content_hash()
                .unwrap()
                .clone(),
            Vec::new(),
            vec![HumanTrustGrantInputV3 {
                policy_revision_hash: policy,
                actor: "human:reviewer".to_owned(),
                authority_id: "review-board".to_owned(),
                capabilities: BTreeSet::from([
                    HumanAuthorityCapabilityV3::RejectFinding,
                    HumanAuthorityCapabilityV3::DeferFinding,
                ]),
                run_id: log.run_id().clone(),
                snapshot_id: log.aggregate().program().snapshot_id().clone(),
                universe_id: log.aggregate().universe().id().clone(),
                property_ids: BTreeSet::from([M4_PROPERTY_ID.to_owned()]),
                claim_ids: BTreeSet::from([claim_id]),
                valid_from: "2026-01-01T00:00:00Z".to_owned(),
                valid_until: "2027-01-01T00:00:00Z".to_owned(),
            }],
        )
        .unwrap()
    }

    fn static_registration_heap_oracle(
        log: &EventLog,
        claim_id: &StableId,
        media_type: &str,
    ) -> u64 {
        (log.run_id.as_str().len()
            + "registration:".len()
            + "sha256:".len()
            + 64
            + "sha256:".len()
            + 64
            + media_type.len()
            + claim_id.as_str().len()
            + STATIC_DESCRIPTOR_ID.len()
            + STATIC_PROCEDURE_ID.len()
            + log.run_id.as_str().len()) as u64
    }

    fn static_expected_oracle(
        log: &EventLog,
        basis: &AuthorityReplayBasisV3,
        claim_id: &StableId,
        input_size: u64,
        output_size: u64,
    ) -> u64 {
        size_of::<ExpectedVerificationAttemptV3>() as u64
            + log.run_id.as_str().len() as u64
            + log.genesis_hash.as_str().len() as u64
            + claim_id.as_str().len() as u64
            + basis.basis_digest.as_str().len() as u64
            + log.tail_hash.as_str().len() as u64
            + static_registration_heap_oracle(log, claim_id, STATIC_INPUT_MEDIA_TYPE)
            + static_registration_heap_oracle(log, claim_id, STATIC_OUTPUT_MEDIA_TYPE)
            + input_size
            + output_size
    }

    fn static_boundary_base() -> (
        EventLog,
        AuthorityReplayBasisV3,
        AuthorityTrustRootsV3,
        StableId,
        crate::StaticFactEvaluationV1,
        AuthorityTestResolver,
    ) {
        static_boundary_base_with_policy(ContentHash::sha256(b"static expectation boundary policy"))
    }

    fn static_boundary_base_with_policy(
        policy_revision_hash: ContentHash,
    ) -> (
        EventLog,
        AuthorityReplayBasisV3,
        AuthorityTrustRootsV3,
        StableId,
        crate::StaticFactEvaluationV1,
        AuthorityTestResolver,
    ) {
        static_boundary_base_with_policy_and_polarity(
            policy_revision_hash,
            ClaimPolarity::IssuePresent,
        )
    }

    fn static_boundary_base_with_policy_and_polarity(
        policy_revision_hash: ContentHash,
        polarity: ClaimPolarity,
    ) -> (
        EventLog,
        AuthorityReplayBasisV3,
        AuthorityTrustRootsV3,
        StableId,
        crate::StaticFactEvaluationV1,
        AuthorityTestResolver,
    ) {
        let (mut log, _, plan, obligation_id, envelope, sources) = d2_v3_m4_log();
        let (_, claim_id) = append_d2_attempt_v3_with_polarity(
            &mut log,
            &plan,
            &obligation_id,
            &envelope,
            &sources,
            polarity,
        );
        let claim = log
            .aggregate()
            .execution_claims()
            .find(|claim| claim.id() == &claim_id)
            .unwrap();
        let obligation = log.aggregate().obligation(&obligation_id).unwrap();
        let evaluation =
            crate::evaluate_static_fact_v1(log.aggregate().program(), obligation, claim).unwrap();
        let roots = authority_roots_for_claim(&log, claim_id.clone(), policy_revision_hash);
        let basis = log.fresh_authority_basis_v3(&roots).unwrap();
        let mut resolver = AuthorityTestResolver::default();
        for bytes in sources.values() {
            resolver.insert(bytes.clone());
        }
        (log, basis, roots, claim_id, evaluation, resolver)
    }

    #[test]
    fn static_fresh_seal_preflight_is_exact_before_expected_allocation() {
        let (log, basis, _roots, claim_id, evaluation, resolver) = static_boundary_base();
        let claim = log
            .aggregate()
            .execution_claims()
            .find(|claim| claim.id() == &claim_id)
            .unwrap();
        let obligation_id = claim.obligation_ids().first().unwrap();
        let obligation = log.aggregate().obligation(obligation_id).unwrap();
        let input_size = evaluation.input().canonical_bytes().unwrap().len() as u64;
        let output_size = evaluation.result().canonical_bytes().unwrap().len() as u64;
        let evaluation_bytes = crate::m4::static_evaluation_test_oracle_bytes(&evaluation);
        let reconstruction = crate::m4::static_reconstruction_test_oracle_bytes(
            log.aggregate().program(),
            obligation,
            claim,
        );
        let downstream = input_size
            + output_size
            + static_registration_heap_oracle(&log, &claim_id, STATIC_INPUT_MEDIA_TYPE)
            + static_registration_heap_oracle(&log, &claim_id, STATIC_OUTPUT_MEDIA_TYPE)
            + MAX_V3_REGISTRATION_IDENTITY_BYTES as u64
            + static_expected_oracle(&log, &basis, &claim_id, input_size, output_size);
        let exact = log.retained_bytes_v3().unwrap()
            + basis.retained_bytes().unwrap()
            + evaluation_bytes
            + reconstruction
            + downstream;
        let events_before = log.envelopes().count();
        let basis_before = basis.basis_digest().clone();
        let objects_before = resolver.objects.len();
        let reads_before = resolver.reads.get();

        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(1));
        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        crate::m4::reset_static_reconstruction_allocation_seams();
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact)));
        log.seal_static_verification_attempt_v3(&claim_id, &evaluation, &basis)
            .unwrap();
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            1
        );
        assert!(crate::m4::static_reconstruction_allocation_seams() > 0);

        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        crate::m4::reset_static_reconstruction_allocation_seams();
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact - 1)));
        assert!(matches!(
            log.seal_static_verification_attempt_v3(&claim_id, &evaluation, &basis),
            Err(DomainError::Incomplete { .. })
        ));
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            0
        );
        assert_eq!(crate::m4::static_reconstruction_allocation_seams(), 0);
        assert_eq!(log.envelopes().count(), events_before);
        assert_eq!(basis.basis_digest(), &basis_before);
        assert_eq!(resolver.objects.len(), objects_before);
        assert_eq!(resolver.reads.get(), reads_before);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(0));
    }

    #[test]
    fn static_durable_inspect_preflight_is_exact_before_cas_allocation() {
        let (mut log, mut basis, roots, claim_id, evaluation, mut resolver) =
            static_boundary_base();
        let input_bytes = evaluation.input().canonical_bytes().unwrap();
        let input_hash = resolver.insert(input_bytes.clone());
        let input = log
            .prepare_static_verifier_artifact_registration_v3(
                claim_id.clone(),
                VerifierArtifactRoleV3::Input,
                input_hash,
                input_bytes.len() as u64,
                &resolver,
                &roots,
                &basis,
            )
            .unwrap();
        log.append_authority_registration_v3(input, &mut basis)
            .unwrap();
        let record_bound = crate::m4::MAX_RECORD_BYTES as u64;
        let decoded_input = size_of::<crate::StaticFactInputV1>() as u64
            + (6 * crate::m4::MAX_EVIDENCE_SUBJECTS
                * (size_of::<StableId>() + crate::m4::MAX_TRACE_BYTES)) as u64
            + (6 * crate::m4::MAX_TRACE_BYTES) as u64;
        let result_bound = size_of::<crate::StaticFactResultV1>() as u64
            + (2 * crate::m4::MAX_TRACE_BYTES
                + size_of::<String>()
                + crate::m4::MAX_LIMITATION_BYTES) as u64;
        let claim = log
            .aggregate()
            .execution_claims()
            .find(|claim| claim.id() == &claim_id)
            .unwrap();
        let obligation = log
            .aggregate()
            .obligation(claim.obligation_ids().first().unwrap())
            .unwrap();
        let reconstruction = crate::m4::static_reconstruction_test_oracle_bytes(
            log.aggregate().program(),
            obligation,
            claim,
        );
        let exact = log.retained_bytes_v3().unwrap()
            + basis.retained_bytes().unwrap()
            + input_bytes.len() as u64
            + decoded_input
            + reconstruction
            + result_bound
            + record_bound
            + static_expected_oracle(
                &log,
                &basis,
                &claim_id,
                input_bytes.len() as u64,
                record_bound,
            )
            + MAX_V3_REGISTRATION_IDENTITY_BYTES as u64;
        let events_before = log.envelopes().count();
        let basis_before = basis.basis_digest().clone();
        let objects_before = resolver.objects.len();

        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(2));
        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        crate::m4::reset_static_reconstruction_allocation_seams();
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact)));
        assert!(matches!(
            log.inspect_static_verification_attempt_v3(&claim_id, &resolver, &roots, &basis)
                .unwrap(),
            StaticVerificationAttemptInspectionV3::Existing { .. }
        ));
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            1
        );
        assert!(crate::m4::static_reconstruction_allocation_seams() > 0);

        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        crate::m4::reset_static_reconstruction_allocation_seams();
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(exact - 1)));
        let reads_before = resolver.reads.get();
        assert!(matches!(
            log.inspect_static_verification_attempt_v3(&claim_id, &resolver, &roots, &basis),
            Err(DomainError::Incomplete { .. })
        ));
        assert_eq!(resolver.reads.get(), reads_before);
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            0
        );
        assert_eq!(crate::m4::static_reconstruction_allocation_seams(), 0);
        assert_eq!(log.envelopes().count(), events_before);
        assert_eq!(basis.basis_digest(), &basis_before);
        assert_eq!(resolver.objects.len(), objects_before);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(0));
    }

    #[test]
    fn v3_static_decision_finding_and_roots_bound_replay_are_exact() {
        let (mut log, _initial, plan, obligation_id, envelope, sources) = d2_v3_m4_log();
        let (_, claim_id) = append_d2_attempt_v3_with_polarity(
            &mut log,
            &plan,
            &obligation_id,
            &envelope,
            &sources,
            ClaimPolarity::IssuePresent,
        );
        let claim = log
            .aggregate()
            .execution_claims()
            .find(|claim| claim.id() == &claim_id)
            .unwrap();
        let obligation = log.aggregate().obligation(&obligation_id).unwrap();
        let evaluation =
            crate::evaluate_static_fact_v1(log.aggregate().program(), obligation, claim).unwrap();
        assert_eq!(
            evaluation.result().applicability(),
            crate::StaticApplicabilityV1::Unique
        );
        let input_bytes = evaluation.input().canonical_bytes().unwrap();
        let output_bytes = evaluation.result().canonical_bytes().unwrap();
        let mut resolver = AuthorityTestResolver::default();
        for bytes in sources.values() {
            resolver.insert(bytes.clone());
        }
        resolver.insert(br#"{"attempt":1,"fixture":true,"version":3}"#.to_vec());
        let input_hash = resolver.insert(input_bytes.clone());
        let output_hash = resolver.insert(output_bytes.clone());
        let policy = ContentHash::sha256(b"authority policy");
        let roots = authority_roots_for_claim(&log, claim_id.clone(), policy.clone());
        let mut basis = log.fresh_authority_basis_v3(&roots).unwrap();

        let fresh_events = log.envelopes().count();
        let fresh_basis = basis.basis_digest().clone();
        let fresh_objects = resolver.objects.len();
        let fresh_reads = resolver.reads.get();
        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(1));
        V3_TEST_STATIC_EXPECTATION_PEAK.with(|value| value.set(0));
        log.seal_static_verification_attempt_v3(&claim_id, &evaluation, &basis)
            .unwrap();
        let fresh_exact = V3_TEST_STATIC_EXPECTATION_PEAK.with(|value| value.get());
        assert!(fresh_exact > 0);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(fresh_exact)));
        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        log.seal_static_verification_attempt_v3(&claim_id, &evaluation, &basis)
            .unwrap();
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            1
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(fresh_exact - 1)));
        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        assert!(matches!(
            log.seal_static_verification_attempt_v3(&claim_id, &evaluation, &basis),
            Err(DomainError::Incomplete { .. })
        ));
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            0
        );
        assert_eq!(log.envelopes().count(), fresh_events);
        assert_eq!(basis.basis_digest(), &fresh_basis);
        assert_eq!(resolver.objects.len(), fresh_objects);
        assert_eq!(resolver.reads.get(), fresh_reads);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(0));

        let input = log
            .prepare_static_verifier_artifact_registration_v3(
                claim_id.clone(),
                VerifierArtifactRoleV3::Input,
                input_hash.clone(),
                u64::try_from(input_bytes.len()).unwrap(),
                &resolver,
                &roots,
                &basis,
            )
            .unwrap();
        let input_registration_id = input.registration_id().clone();
        log.append_authority_registration_v3(input, &mut basis)
            .unwrap();
        crate::m4::reset_static_evaluator_calls();
        let durable_events = log.envelopes().count();
        let durable_basis = basis.basis_digest().clone();
        let durable_objects = resolver.objects.len();
        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(2));
        V3_TEST_STATIC_EXPECTATION_PEAK.with(|value| value.set(0));
        assert!(matches!(
            log.inspect_static_verification_attempt_v3(&claim_id, &resolver, &roots, &basis,)
                .unwrap(),
            StaticVerificationAttemptInspectionV3::Existing {
                stage: VerificationAttemptStageV3::InputRegistered,
                ..
            }
        ));
        let durable_exact = V3_TEST_STATIC_EXPECTATION_PEAK.with(|value| value.get());
        assert!(durable_exact > 0);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(durable_exact)));
        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        assert!(matches!(
            log.inspect_static_verification_attempt_v3(&claim_id, &resolver, &roots, &basis,)
                .unwrap(),
            StaticVerificationAttemptInspectionV3::Existing {
                stage: VerificationAttemptStageV3::InputRegistered,
                ..
            }
        ));
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            1
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(durable_exact - 1)));
        V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.set(0));
        let reads_before_refusal = resolver.reads.get();
        assert!(matches!(
            log.inspect_static_verification_attempt_v3(&claim_id, &resolver, &roots, &basis,),
            Err(DomainError::Incomplete { .. })
        ));
        assert_eq!(resolver.reads.get(), reads_before_refusal);
        assert_eq!(
            V3_TEST_STATIC_EXPECTATION_ALLOCATION_SEAMS.with(|value| value.get()),
            0
        );
        assert_eq!(log.envelopes().count(), durable_events);
        assert_eq!(basis.basis_digest(), &durable_basis);
        assert_eq!(resolver.objects.len(), durable_objects);
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_STATIC_EXPECTATION_KIND.with(|value| value.set(0));
        assert_eq!(crate::m4::static_evaluator_calls(), 0);
        let output = log
            .prepare_static_verifier_artifact_registration_v3(
                claim_id.clone(),
                VerifierArtifactRoleV3::Output,
                output_hash.clone(),
                u64::try_from(output_bytes.len()).unwrap(),
                &resolver,
                &roots,
                &basis,
            )
            .unwrap();
        let output_registration_id = output.registration_id().clone();
        log.append_authority_registration_v3(output, &mut basis)
            .unwrap();

        let bundle = log
            .mint_static_verification_bundle_v3(
                &claim_id,
                &input_registration_id,
                &output_registration_id,
                &resolver,
                &roots,
                &basis,
            )
            .unwrap();
        assert_eq!(crate::m4::static_evaluator_calls(), 0);
        let bundle_exact = verification_bundle_transaction_exact(&log, &basis, &bundle);
        let events_before = log.envelopes().count();
        let basis_before = basis.basis_digest().clone();
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(bundle_exact - 1)));
        V3_TEST_TRANSACTION_ALLOCATION_SEAMS.with(|value| value.set(0));
        assert!(matches!(
            log.preflight_v3_outer_transaction(&basis, &bundle.payloads),
            Err(DomainError::Incomplete { .. })
        ));
        assert!(matches!(
            log.append_verification_bundle_v3(bundle, &mut basis),
            Err(DomainError::Incomplete { .. })
        ));
        assert_eq!(log.envelopes().count(), events_before);
        assert_eq!(basis.basis_digest(), &basis_before);
        assert_eq!(
            V3_TEST_TRANSACTION_ALLOCATION_SEAMS.with(|value| value.get()),
            0
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        let bundle = log
            .mint_static_verification_bundle_v3(
                &claim_id,
                &input_registration_id,
                &output_registration_id,
                &resolver,
                &roots,
                &basis,
            )
            .unwrap();
        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(bundle_exact)));
        let receipt = log
            .append_verification_bundle_v3(bundle, &mut basis)
            .unwrap();
        assert_eq!(
            V3_TEST_TRANSACTION_ALLOCATION_SEAMS.with(|value| value.get()),
            1
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        assert_eq!(receipt.event_ids().len(), 3);
        let assessment = log.claim_assessment_v3(&claim_id).unwrap();
        assert_eq!(
            assessment.disposition(),
            crate::AssessmentDispositionV3::Proposed
        );
        assert_eq!(assessment.verification_ids().len(), 1);

        let stale_finding = log
            .mint_finding_v3(&claim_id, crate::FINDING_PROJECTION_ID, &basis)
            .unwrap();
        let decision = log
            .mint_decision_v3(
                &claim_id,
                DecisionInputV3::new(
                    crate::DecisionOutcomeV3::Reject,
                    "human:reviewer",
                    "review-board",
                    "confirmed policy rejection",
                    "2026-08-10T00:00:00Z",
                    None,
                ),
                &roots,
                &basis,
            )
            .unwrap();
        log.append_decision_v3(decision, &mut basis).unwrap();
        assert!(matches!(
            log.append_finding_v3(stale_finding, &mut basis),
            Err(DomainError::AuthorityReplayBasisMismatch)
        ));
        let finding = log
            .mint_finding_v3(&claim_id, crate::FINDING_PROJECTION_ID, &basis)
            .unwrap();
        let finding_id = finding.finding.id().clone();
        let v3_entries_before_finding = basis.entries.len();
        log.append_finding_v3(finding, &mut basis).unwrap();
        assert_eq!(basis.entries.len(), v3_entries_before_finding);
        assert_eq!(
            log.claim_assessment_v3(&claim_id).unwrap().disposition(),
            crate::AssessmentDispositionV3::Rejected
        );

        let genesis = log
            .run_genesis_snapshot()
            .unwrap()
            .canonical_bytes()
            .unwrap();
        let envelopes = log.envelopes().cloned().collect::<Vec<_>>();
        let v4 = EventLogV4::from_bootstrap_request(
            RunGenesisBootstrapRequestV4::new(
                log.run_id().clone(),
                genesis.clone(),
                log.aggregate().program().repository_identity(),
                log.aggregate().program().snapshot_id().clone(),
                log.aggregate().program().profile_id(),
                log.aggregate().program().profile_version(),
            )
            .unwrap(),
        )
        .unwrap();
        let v4_envelopes = rewrap_v3_suffix_as_v4(&log, &v4);
        assert!(matches!(
            decode_canonical_payload(
                EventContractVersion::V4,
                v4_envelopes.last().unwrap().payload.get(),
            )
            .unwrap(),
            PersistedPayload::FindingRecordedV3(_)
        ));
        let v4_human_grants = roots
            .human_grants
            .iter()
            .map(|grant| {
                let grant = &grant.0;
                AuthorityHumanGrantV3Tuple {
                    policy_revision_hash: grant.policy_revision_hash.clone(),
                    actor: grant.actor.clone(),
                    authority_id: grant.authority_id.clone(),
                    capabilities: grant.capabilities.clone(),
                    run_id: grant.run_id.clone(),
                    snapshot_id: grant.snapshot_id.clone(),
                    universe_id: grant.universe_id.clone(),
                    property_ids: grant.property_ids.clone(),
                    claim_ids: grant.claim_ids.clone(),
                    valid_from: grant.valid_from.clone(),
                    valid_until: grant.valid_until.clone(),
                }
            })
            .collect();
        let v4_roots = AuthorityTrustRootsV4::new(
            policy.clone(),
            log.aggregate().program().repository_id().clone(),
            log.aggregate()
                .program()
                .repository_source()
                .content_hash()
                .unwrap()
                .clone(),
            Vec::new(),
            v4_human_grants,
            Vec::new(),
        )
        .unwrap();
        let v4_resolver = V4CasResolver {
            objects: resolver.objects.clone(),
        };
        let v4_prefix_without_finding = &v4_envelopes[..v4_envelopes.len() - 1];
        let (_, v4_basis_without_finding) = EventLogV4::replay_confirmed_v4_prefix(
            v4.run_id().clone(),
            v4.canonical_genesis_bytes(),
            v4_prefix_without_finding,
            &v4_resolver,
            &v4_roots,
            EventReplayLimits::new(v4_prefix_without_finding.len() as u64, u64::MAX),
        )
        .unwrap();
        let (v4_with_finding, v4_basis_with_finding) = EventLogV4::replay_confirmed_v4_prefix(
            v4.run_id().clone(),
            v4.canonical_genesis_bytes(),
            &v4_envelopes,
            &v4_resolver,
            &v4_roots,
            EventReplayLimits::new(v4_envelopes.len() as u64, u64::MAX),
        )
        .unwrap();
        assert_eq!(v4_basis_without_finding.inherited_m4_entry_count(), 4);
        assert_eq!(
            v4_basis_with_finding.inherited_m4_entry_count(),
            v4_basis_without_finding.inherited_m4_entry_count(),
            "a V4 finding is aggregate state, not an inherited authority basis entry",
        );
        assert!(
            v4_with_finding
                .v3_aggregate
                .findings
                .contains_key(&finding_id)
        );
        assert_selected_replay_append_boundary(&log, &genesis, &envelopes, &resolver, &roots, 1);
        assert_selected_replay_append_boundary(&log, &genesis, &envelopes, &resolver, &roots, 2);
        let binding_end = envelopes
            .iter()
            .position(|event| {
                matches!(
                    decode_canonical_payload(EventContractVersion::V3, event.payload.get())
                        .unwrap(),
                    PersistedPayload::EvidenceBoundV3(_)
                )
            })
            .unwrap()
            + 1;
        let binding_prefix = &envelopes[..binding_end];
        V3_TEST_BINDING_APPEND_PEAK.with(|value| value.set(0));
        EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            &genesis,
            binding_prefix,
            &resolver,
            &roots,
            EventReplayLimits::new(binding_prefix.len() as u64, u64::MAX),
        )
        .unwrap();
        let binding_peak = V3_TEST_BINDING_APPEND_PEAK.with(|value| value.get());
        assert!(binding_peak > 0);

        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(binding_peak)));
        V3_TEST_BINDING_SHADOW_SEAMS.with(|value| value.set(0));
        EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            &genesis,
            binding_prefix,
            &resolver,
            &roots,
            EventReplayLimits::new(binding_prefix.len() as u64, u64::MAX),
        )
        .unwrap();
        assert_eq!(V3_TEST_BINDING_SHADOW_SEAMS.with(|value| value.get()), 1);

        V3_TEST_WORKING_LIMIT.with(|value| value.set(Some(binding_peak - 1)));
        V3_TEST_BINDING_SHADOW_SEAMS.with(|value| value.set(0));
        V3_TEST_REPLAY_PAYLOAD_DECODE_COUNT.with(|value| value.set(0));
        let below = EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            &genesis,
            binding_prefix,
            &resolver,
            &roots,
            EventReplayLimits::new(binding_prefix.len() as u64, u64::MAX),
        );
        assert!(
            matches!(below, Err(DomainError::Incomplete { .. })),
            "unexpected binding exact-minus-one result: {below:?}"
        );
        assert_eq!(V3_TEST_BINDING_SHADOW_SEAMS.with(|value| value.get()), 0);
        assert_eq!(
            V3_TEST_REPLAY_PAYLOAD_DECODE_COUNT.with(|value| value.get()),
            binding_prefix.len() as u64
        );
        V3_TEST_WORKING_LIMIT.with(|value| value.set(None));
        V3_TEST_REPLAY_PAYLOAD_DECODE_COUNT.with(|value| value.set(0));
        let (replayed, mut replay_basis) = EventLog::replay_validated_v3_prefix(
            log.run_id().clone(),
            &genesis,
            &envelopes,
            &resolver,
            &roots,
            EventReplayLimits::new(
                u64::try_from(envelopes.len()).unwrap(),
                envelopes
                    .iter()
                    .map(|event| u64::try_from(event.canonical_bytes().unwrap().len()).unwrap())
                    .sum(),
            ),
        )
        .unwrap();
        assert_eq!(
            V3_TEST_REPLAY_PAYLOAD_DECODE_COUNT.with(|value| value.get()),
            u64::try_from(envelopes.len()).unwrap()
        );
        assert_eq!(basis.basis_digest(), replay_basis.basis_digest());
        assert_eq!(
            log.claim_assessment_v3(&claim_id)
                .unwrap()
                .canonical_bytes()
                .unwrap(),
            replayed
                .claim_assessment_v3(&claim_id)
                .unwrap()
                .canonical_bytes()
                .unwrap()
        );
        replay_basis.basis_digest = ContentHash::sha256(b"tampered authority basis");
        assert!(matches!(
            replayed.mint_finding_v3(&claim_id, crate::FINDING_PROJECTION_ID, &replay_basis,),
            Err(DomainError::AuthorityReplayBasisMismatch)
        ));

        let wrong_roots =
            authority_roots_for_claim(&log, claim_id.clone(), ContentHash::sha256(b"wrong policy"));
        assert!(matches!(
            log.prepare_static_verifier_artifact_registration_v3(
                claim_id.clone(),
                VerifierArtifactRoleV3::Input,
                input_hash.clone(),
                u64::try_from(input_bytes.len()).unwrap(),
                &resolver,
                &wrong_roots,
                &basis,
            ),
            Err(DomainError::AuthorityPolicyMismatch)
        ));

        let mut bad_resolver = AuthorityTestResolver::default();
        bad_resolver
            .objects
            .insert(input_hash.clone(), b"tampered static input".to_vec());
        assert!(matches!(
            log.prepare_static_verifier_artifact_registration_v3(
                claim_id.clone(),
                VerifierArtifactRoleV3::Input,
                input_hash,
                u64::try_from(input_bytes.len()).unwrap(),
                &bad_resolver,
                &roots,
                &basis,
            ),
            Err(DomainError::Validation(_))
        ));

        let roots_without_human = AuthorityTrustRootsV3::new(
            policy,
            log.aggregate().program().repository_id().clone(),
            log.aggregate()
                .program()
                .repository_source()
                .content_hash()
                .unwrap()
                .clone(),
            Vec::new(),
            Vec::new(),
        )
        .unwrap();
        assert!(matches!(
            EventLog::replay_validated_v3_prefix(
                log.run_id().clone(),
                &genesis,
                &envelopes,
                &resolver,
                &roots_without_human,
                EventReplayLimits::new(u64::try_from(envelopes.len()).unwrap(), u64::MAX),
            ),
            Err(DomainError::AuthorityReplayRefused { .. })
        ));

        let mut reordered = envelopes.clone();
        let last = reordered.len() - 1;
        reordered.swap(last - 1, last);
        assert!(
            EventLog::replay_validated_v3_prefix(
                log.run_id().clone(),
                &genesis,
                &reordered,
                &resolver,
                &roots,
                EventReplayLimits::new(u64::try_from(reordered.len()).unwrap(), u64::MAX),
            )
            .is_err()
        );

        let mut actor_tamper = serde_json::to_value(envelopes.last().unwrap()).unwrap();
        actor_tamper["actor"] = Value::String("human:attacker".to_owned());
        assert!(
            EventEnvelope::from_json_slice(&serde_json::to_vec(&actor_tamper).unwrap()).is_err()
        );
    }

